    // change event, update count, queue, loop queue, unit productions, status, settings
    public partial class TProductionControl : TEObject
    {

        // Structur.PAS:191
        public TProductionControl(TECustomNode owner) : base(owner)
        {
            FSettings = new TProductionSettings(null);
            FUnitProductions = new TUnitProductionList(null);
            FQueue = new TProductionQueue(null);
            FQueue.FProductionControl = this;
            FStatus = TProductionControlStatus.pcsIdle;
            Clear();
        }

        public TNotifyEvent<object> FOnChange;
        public int FUpdateCount;
        public TProductionQueue FQueue;
        public bool FLoopQueue;
        public TUnitProductionList FUnitProductions;
        public TProductionControlStatus FStatus;
        public TProductionSettings FSettings;

        // Structur.PAS:202
        public override void Dispose()
        {
            FSettings?.Dispose();
            FUnitProductions?.Dispose();
            FQueue?.Dispose();
            base.Dispose();
        }

        // Structur.PAS:783
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwEObject(FQueue, 20);
            Stream.rwEObject(FUnitProductions, 21);
            Stream.rwEObject(FSettings, 22);
            Stream.rwData(Bytes.Of(ref FStatus, 1), 1, 23);
            Stream.rwBool(ref FLoopQueue, 24);
        }

        // Structur.PAS:261
        public virtual int CancelProductionReturnGold()
        {
            int Result;
            if (FStatus == TProductionControlStatus.pcsProducing)
            {
                if (this.FSettings.FTurnsTotal != 0)
                {
                    Result = Round((double)(this.FSettings.FTurnsLeft * this.FSettings.FGold) / this.FSettings.FTurnsTotal);
                }
                else
                {
                    Result = 0;
                }
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // Structur.PAS:270
        public virtual int CancelProductionReturnMana()
        {
            int Result;
            if (FStatus == TProductionControlStatus.pcsProducing)
            {
                if (this.FSettings.FTurnsTotal != 0)
                {
                    Result = Round((double)(this.FSettings.FTurnsLeft * this.FSettings.FMana) / this.FSettings.FTurnsTotal);
                }
                else
                {
                    Result = 0;
                }
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // Structur.PAS:295
        public virtual void ExecuteCancelProduction()
        {
            sbyte Player;
            if (FStatus == TProductionControlStatus.pcsProducing)
            {
                FQueue.GetItem(0).Order.Cancel(this);
                if (FSettings.FGroupID != 0)
                {
                    UnregisterGroupProduction();
                }

                Player = GetPlayer();
                if (Player > -1)
                {
                    var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
                    var cancelProductionReturnGold = CancelProductionReturnGold();
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).SetGems(players.FGems + cancelProductionReturnGold);
                    var fPlayersPlayers = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
                    var cancelProductionReturnMana = CancelProductionReturnMana();
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FMagicControl.SetMana(fPlayersPlayers.FMagicControl.FMana + cancelProductionReturnMana);
                }

                FSettings.Clear();
                FStatus = TProductionControlStatus.pcsWaiting;
                Update();
            }
        }

        // Structur.PAS:483
        public virtual bool ExecuteAIProduction(int Index, int GroupID)
        {
            TProductionItem Item;
            ExecuteDeleteProductions();
            Item = new TProductionItem(null);
            Item.Order = new ProduceUnit(Index, GroupID);
            ExecuteAddProduction(Item);
            Item?.Dispose();
            return true;
        }

        // Structur.PAS:497
        public virtual bool ExecuteAIResearch(int Index)
        {
            bool Result;
            TProductionItem Item;
            if (!FUnitProductions.GetItem(Index).FResearched)
            {
                ExecuteDeleteProductions();
                Item = new TProductionItem(null);
                Item.Order = new ResearchSpell(Index);
                ExecuteAddProduction(Item);
                Item?.Dispose();
                Result = true;
            }
            else
            {
                Result = true;
            }

            return Result;
        }

        // Structur.PAS:392
        public virtual bool ExecuteProduction(TProductionItem Item)
        {
            bool Result;
            string Reason = "";
            if (CanExecuteProduction(Item, ref Reason))
            {
                BeginUpdate();
                ExecuteCancelProduction();
                FStatus = TProductionControlStatus.pcsWaiting;
                Item.Order.Execute(this);
                EndUpdate();
                Item.Order.Executed(this);
                Result = true;
            }
            else
            {
                FStatus = TProductionControlStatus.pcsWaiting;
                Result = false;
            }

            return Result;
        }

        // Structur.PAS:450
        public virtual void ExecuteAddProduction(TProductionItem Item)
        {
            TProductionItem NewItem;
            BeginUpdate();
            NewItem = (TProductionItem)Item.Copy(AoWEUnit.AoWEngine);
            NewItem.SetOwner(FQueue);
            if (FQueue.Count == 1)
            {
                ExecuteProduction(NewItem);
            }

            EndUpdate();
        }

        // Structur.PAS:461
        public virtual void ExecuteDeleteProduction(int Index)
        {
            BeginUpdate();
            if (Index == 0)
            {
                ExecuteCancelProduction();
                FQueue.GetItem(Index)?.Dispose();
                if (FQueue.Count != 0)
                {
                    ExecuteProduction(FQueue.GetItem(0));
                }
                else
                {
                    FStatus = TProductionControlStatus.pcsIdle;
                }
            }
            else
            {
                FQueue.GetItem(Index)?.Dispose();
            }

            EndUpdate();
        }

        // Structur.PAS:475
        public virtual void ExecuteDeleteProductions()
        {
            BeginUpdate();
            ExecuteCancelProduction();
            FQueue.Clear();
            EndUpdate();
        }

        // Structur.PAS:514
        public virtual TExecuteResult ExecuteProductionTE(TProductionTE Event)
        {
            TExecuteResult Result;
            switch (Event.FCommand)
            {
                case 0:
                    BeginUpdate();
                    if (!Event.FQueue)
                    {
                        ExecuteDeleteProductions();
                    }

                    ExecuteAddProduction(Event.FItem);
                    Result = TExecuteResult.erDone;
                    EndUpdate();
                    break;
                case 1:
                    ExecuteDeleteProduction(Event.FIndex);
                    Result = TExecuteResult.erDone;
                    break;
                case 2:
                    ExecuteDeleteProductions();
                    Result = TExecuteResult.erDone;
                    break;
                case 3:
                    if (FQueue.Count != 0 && FStatus == TProductionControlStatus.pcsWaiting)
                    {
                        ExecuteProduction(FQueue.GetItem(0));
                    }

                    Result = TExecuteResult.erDone;
                    break;
                case 4:
                    FLoopQueue = Event.FIndex == 1;
                    Update();
                    Result = TExecuteResult.erDone;
                    break;
                default:
                    Result = TExecuteResult.erDone;
                    break;
            }

            return Result;
        }

        // Structur.PAS:551
        public virtual TProductionTE CreateProductionTE()
        {
            TProductionTE Event;
            Event = new TProductionTE(null);
            GetLocation(ref Event.FX, ref Event.FY, ref Event.FL);
            Event.FPlayer = GetPlayer();
            return Event;
        }

