        }

        // Structur.PAS:279
        public virtual int GetQueueSizeMax() => 5;

        // Structur.PAS:282
        public virtual bool GetQueueLocked()
        {
            int I;
            I = FQueue.Count;
            bool Result = I >= GetQueueSizeMax();
            while (!Result && I != 0)
            {
                I -= 1;
                Result = LockQueueProduction(FQueue.GetItem(I));
            }

            return Result;
        }

        // Structur.PAS:837
        public virtual bool LoopableProduction(TProductionItem Item) => Item.Order.Loopable(this);

        // Structur.PAS:834
        public virtual bool LockQueueProduction(TProductionItem Item) => Item.Order.LocksQueue(this);

        // Structur.PAS:561
        public virtual bool UnitProduced() => false;

        // Structur.PAS:636
        public virtual void UnitResearched()
        {
            FUnitProductions.GetItem(FSettings.FUnitProductionIndex).FResearched = true;
        }

        // Structur.PAS:219
        public virtual void Update()
        {
            if (FUpdateCount == 0)
            {
                if (FOnChange != null)
                {
                    FOnChange(this);
                }
            }
        }

        // Structur.PAS:564
        public virtual TUnit CreateUnitProduction(int Index)
        {
            TUnit Result;
            TUnit AUnit;
            if (FUnitProductions.GetItem(Index) != null)
            {
                AUnit = new TUnit(null);
                var unitProduction = FUnitProductions.GetItem(Index);
                AUnit.SetUnitResource(AoWEUnit.AoWHSSet.FUnitResources.GetUnitResource(unitProduction.FUnitIndex));
                Result = AUnit;
            }
            else
            {
                Result = null;
            }

