        // Structur.PAS:225
        public virtual void Activate()
        {
            RegisterGroupProduction();
        }

        // Structur.PAS:228
        public virtual void Deactivate()
        {
            UnregisterGroupProduction();
        }

        // Structur.PAS:804
        public virtual void NewTurn(sbyte Player)
        {
            if (FStatus == TProductionControlStatus.pcsWaiting && Player == GetPlayer())
            {
                if (FQueue.Count != 0)
                {
                    ExecuteProduction(FQueue.GetItem(0));
                }
                else
                {
                    FStatus = TProductionControlStatus.pcsIdle;
                }
            }
            else
            {
                if (FStatus == TProductionControlStatus.pcsProducing && Player == FSettings.FPlayer)
                {
                    if (FSettings.FTurnsLeft > 0)
                    {
                        FSettings.FTurnsLeft = (sbyte)(FSettings.FTurnsLeft - 1);
