            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FDispelResistance), 10);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FSource), 11);
            Stream.rwInteger(ref FUpkeep, 12);
            Stream.rwInteger(ref FEnchantmentID, 13);
