        {
            if (Player != FSource)
            {
                if (FSource > -1)
                {
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FSource).FMagicControl.UnregisterEnchantment(this);
                }

                FSource = Player;
                if (FSource > -1)
