        {
            bool Result;
            sbyte X = default;
            sbyte Y = default;
            sbyte L = default;
            GetLocation(ref X, ref Y, ref L);
            if (X != -1)
            {
                if (AoWEUnit.AoWHSMap.Visible(X, Y, L, 0))
                {
                    AoWEUnit.AoWHSMap.CenterViewTo(X, Y, L);
                    AoWEUnit.AoWHSMap.PlayCenterAnimation(X, Y, L);
                }
                else
                {
                    var binding = GetBinding();
                    var format = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.XIsOutOfSightRStr), [binding]);
                    AoWEUnit.AoWHSMap.ShowMessage(format);
                }

