        public int DispelChance(int Mana)
        {
            int Result = Mana - FDispelResistance * 10 + 50;
            if (Result < 10)
            {
                Result = 10;
            }

            if (Result > 90)
            {
                Result = 90;
            }

            return Result;
        }

