    // (mode, player, values)
    public partial class TChangePlayerMagicTE : TTokenEvent
    {
        public TChangePlayerMagicTE(TECustomNode owner) : base(owner)
        { }

        public new const int ClassID = 135445;

        public TChangePlayerMagicMode FMode;
        public byte FPlayerIndex;
        public int FValue;
        public int FExtraValue;

        // Spells.PAS:2448
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwData(Bytes.Of(ref FMode, 1), 1, 20);
            Stream.rwByte(ref FPlayerIndex, 21);
            Stream.rwInteger(ref FValue, 22);
            Stream.rwInteger(ref FExtraValue, 23);
        }

        // Spells.PAS:2456
        public override TExecuteResult Execute(TTokenExecuter TE)
        {
            TExecuteResult Result;
            bool Success;
            TPlayerMagicControl Magic;
            base.Execute(TE);
            Success = false;
            Magic = AoWEUnit.AoWHSMap.FPlayers.GetPlayers((sbyte)FPlayerIndex).FMagicControl;
            switch (FMode)
            {
                case TChangePlayerMagicMode.cmmDispelEnchantment:
                    Success = Magic.ExecuteDispelEnchantment(FValue);
                    break;
                case TChangePlayerMagicMode.cmmChangePowerSettings:
                    Success = Magic.ExecuteChangePowerSettings(FValue);
                    break;
                case TChangePlayerMagicMode.cmmResearchSpell:
                    Success = Magic.ExecuteResearchSpell(FValue);
                    break;
            }

            if (Success)
            {
                Result = TExecuteResult.erDone;
            }
            else
            {
                Result = TExecuteResult.erDoneHalt;
            }

            return Result;
        }

        // NetworkE.pas:230

    }
}

namespace Aow.Game.Events
{

    // (mode, location, spell ID, value, enchantment name)
    public partial class TPlayerMagicEventLog : TEventLog
    {
        // Spells.PAS:1847
        // mode, location, spell ID, value, enchantment name
        public TPlayerMagicEventLog(TECustomNode owner) : base(owner)
        {
            FLocation.XYL = 16777215;
        }

        public new const int ClassID = 131824;

        public TPlayerMagicEventMode FMode;
        public TXYL FLocation;
        public int FSpellID;
        public int FValue;
        public string FEnchantmentName = "";

        // Spells.PAS:1854
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwData(Bytes.Of(ref FMode, 1), 1, 20);
            Stream.rwInteger(ref FSpellID, 21);
            Stream.rwInteger(ref FValue, 22);
            Stream.rwString(ref FEnchantmentName, 23);
            Stream.rwInteger(ref FLocation.XYL, 24);
        }

        // Spells.PAS:1892
        public override string GetText()
        {
            string Result = "";
            switch (FMode)
            {
                case TPlayerMagicEventMode.pmemSpellResearched:
                    var spell = AoWEUnit.AoWHSSet.FSpellControl.GetSpell(FSpellID);
                    Result = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.P4XResearchedRStr), [spell.FSpellName]);
                    break;
                case TPlayerMagicEventMode.pmemOutOfMana:
                    if (AoWEUnit.AoWHSMap.FSeatedPlayer == FPlayer)
                    {
                        Result = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.P4XRemovedOutOfManaRStr), [FEnchantmentName]);
                    }
                    else
                    {
                        Result = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.P4XRemovedRStr), [FEnchantmentName]);
                    }

                    break;
            }

            return Result;
        }

        // Spells.PAS:1874
        public override bool Execute(bool Mode, TExecuteTrigger Trigger, TExecuteDoneEvent Done)
        {
            bool Result = default;
            bool Show;
            switch (FMode)
            {
                case TPlayerMagicEventMode.pmemOutOfMana:
                    Show = Trigger == TExecuteTrigger.etUser;
                    break;
                case TPlayerMagicEventMode.pmemSpellResearched:
                    if (Trigger != TExecuteTrigger.etUser)
                    {
                        if (AoWEUnit.AoWHSMap.FPlayMode == TPlayMode.pmTurn)
                        {
                            Show = AoWEUnit.AoWEngine.FRegistry.GetClassicWindowPopupEvents().Contains(TWindowPopupEvent.wpSpellResearched);
                        }
                        else
                        {
                            Show = AoWEUnit.AoWEngine.FRegistry.GetSimultaneousWindowPopupEvents().Contains(TWindowPopupEvent.wpSpellResearched);
                        }
                    }
                    else
                    {
                        Show = true;
                    }

                    break;
                case TPlayerMagicEventMode.pmemStartResearch:
                    Show = true;
                    break;
                default:
                    Show = false;
                    break;
            }

            if (Show)
            {
                Result = base.Execute(Mode, Trigger, Done);
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Spells.PAS:1863
        public override void ViewLocation()
        {
            sbyte X;
            X = FLocation.X;
            if (X != -1)
            {
                AoWEUnit.AoWHSMap.CenterViewTo(X, FLocation.Y, FLocation.L);
                AoWEUnit.AoWHSMap.PlayCenterAnimation(FLocation.X, FLocation.Y, FLocation.L);
            }
        }

    }
}

