        // Spells.PAS:1976
        public void UpdateEnemyEnchantments()
        {
            TPlayerMagicControl Magic;
            FEnemyEnchantments = TSet<TPlayerEnchantmentType>.Of();
            for (int I = AoWEUnit.AoWHSMap.FPlayers.GetCount() - 1; I >= 1; I--)
            {
                if (I != FPlayer.FPlayerIndex)
                {
                    if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FDiplomaticRelations.GetDiplomaticRelation(FPlayer.FPlayerIndex) == TDiplomaticRelation.drWar)
                    {
                        Magic = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FMagicControl;
                        if (Magic.FActiveEnchantments.Contains(TPlayerEnchantmentType.petWaterMastery))
                        {
                            FEnemyEnchantments = FEnemyEnchantments + TSet<TPlayerEnchantmentType>.Of(TPlayerEnchantmentType.petWaterMastery);
                        }

                        if (Magic.FActiveEnchantments.Contains(TPlayerEnchantmentType.petLifeMastery))
                        {
                            FEnemyEnchantments = FEnemyEnchantments + TSet<TPlayerEnchantmentType>.Of(TPlayerEnchantmentType.petLifeMastery);
                        }

                        if (Magic.FActiveEnchantments.Contains(TPlayerEnchantmentType.petDeathMastery))
                        {
                            FEnemyEnchantments = FEnemyEnchantments + TSet<TPlayerEnchantmentType>.Of(TPlayerEnchantmentType.petDeathMastery);
                        }

                        if (Magic.FActiveEnchantments.Contains(TPlayerEnchantmentType.petAirMastery))
                        {
                            FEnemyEnchantments = FEnemyEnchantments + TSet<TPlayerEnchantmentType>.Of(TPlayerEnchantmentType.petAirMastery);
                        }
                    }
                }
            }
        }

