        // Spells.PAS:2316
        public bool DispelEnchantment(TEnchantment Enchantment)
        {
            bool Result;
            int Index;
            TChangePlayerMagicTE Event;
            Index = FEnchantments.FChildren.IndexOf(Enchantment);
            if (!FPlayer.GetBusy() && Index != -1)
            {
                Event = CreateChangeMagicTE();
                Event.FMode = TChangePlayerMagicMode.cmmDispelEnchantment;
                Event.FValue = Index;
                AoWEUnit.AoWHSMap.FTokenManager.GetTokenControl(FPlayer.FPlayerIndex).AddEvent(Event);
                Event.Release();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

