        // Spells.PAS:2563
        public virtual bool CanDeactivate(byte Player, ref string Reason) => true;

        // Spells.PAS:2565
        public virtual bool Deactivate(byte Player)
        {
            FEnchantmentStatus = FEnchantmentStatus - TSet<TGlobalEnchantmentStatusElement>.Of(TGlobalEnchantmentStatusElement.getActivated);
            if (FEnchantmentMode.Contains(TGlobalEnchantmentModeElement.gemOwned))
            {
                Owner = null;
            }
            else
            {
                AoWEUnit.AoWHSMap.FGlobalMagicControl.FEnchantments.RemoveChild(this);
            }

            AoWEUnit.AoWHSMap.FGlobalMagicControl.Update();
            if (FEnchantmentManaUpkeep != 0)
            {
                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayerIndex).FMagicControl.Update();
            }

            Release();
            return true;
        }

        // Spells.PAS:2536
        public virtual bool CanActivate(sbyte Player, ref string Reason)
        {
            bool Result;
            if (FEnchantmentType != TGlobalEnchantmentType.getNone && AoWEUnit.AoWHSMap.FGlobalMagicControl.FActiveEnchantments.Contains(FEnchantmentType))
            {
                Reason = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.XIsAlreadyActiveRStr), [FName]);
                Result = false;
            }
            else
            {
                Reason = "";
                Result = true;
            }

            return Result;
        }

        // Spells.PAS:2550
        public virtual bool Activate(sbyte Player)
        {
            FPlayerIndex = Player;
            FEnchantmentStatus = FEnchantmentStatus + TSet<TGlobalEnchantmentStatusElement>.Of(TGlobalEnchantmentStatusElement.getActivated);
            AoWEUnit.AoWHSMap.FGlobalMagicControl.ValidateEnchantmentID(this);
            if (FEnchantmentMode.Contains(TGlobalEnchantmentModeElement.gemOwned))
            {
                Owner = AoWEUnit.AoWHSMap.FGlobalMagicControl.FEnchantments;
            }
            else
            {
                AoWEUnit.AoWHSMap.FGlobalMagicControl.FEnchantments.AddChild(this);
            }

            AddRef();
            AoWEUnit.AoWHSMap.FGlobalMagicControl.Update();
            if (FEnchantmentManaUpkeep != 0)
            {
                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayerIndex).FMagicControl.Update();
            }

            return true;
        }

        // Spells.PAS:2575
        public virtual bool CanCast(sbyte Player, ref string Reason) => CanActivate(Player, ref Reason);

        // Spells.PAS:2577
        public virtual bool Cast(sbyte Player)
        {
            bool Result;
            string Reason = "";
            TGlobalEnchantmentEventLog Log;
            if (CanCast(Player, ref Reason))
            {
                Result = Activate(Player);
                if (Result)
                {
                    Log = new TGlobalEnchantmentEventLog(null);
                    Log.FEnchantmentPlayer = Player;
                    Log.FPlayer = Player;
                    Log.FText = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.XCastRStr), [FName]);
                    DistributeEventLog(Log, false);
                    Log.Release();
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Spells.PAS:2597
        public virtual bool CanDispel(sbyte Player, ref string Reason) => CanDeactivate((byte)Player, ref Reason);

        // Spells.PAS:2599
        public virtual bool Dispel(byte Player)
        {
            bool Result;
            string Reason = "";
            TXYL Location;
            TGlobalEnchantmentEventLog Log;
            if (CanDispel((sbyte)Player, ref Reason))
            {
                AddRef();
                Location = GetLocation();
                for (int I = 1, last = AoWEUnit.AoWHSMap.FPlayers.GetCount() - 1; I <= last; I++)
                {
                    if (VisibleForPlayer((sbyte)I))
                    {
                        Log = new TGlobalEnchantmentEventLog(null);
                        Log.FPlayer = (sbyte)Player;
                        Log.FEnchantmentPlayer = FPlayerIndex;
                        Log.SetLocation(Location.X, Location.Y, Location.L);
                        var name = GetName();
                        Log.FText = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.P4XDispelledRStr), [name]);
                        AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FEventLogbook.AddEvent(Log);
                        Log.Release();
                    }
                }

                Result = Deactivate(Player);
                Release();
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Spells.PAS:2626
        public virtual bool CanRemove(sbyte Player, ref string Reason)
        {
            bool Result;
            if (Player == FPlayerIndex)
            {
                Result = CanDeactivate((byte)FPlayerIndex, ref Reason);
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Spells.PAS:2631
        public virtual bool Remove(byte Player)
        {
