                    }
                }

                Result = Deactivate((byte)FPlayerIndex);
                Release();
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Spells.PAS:2507
        public virtual bool VisibleForPlayer(sbyte Player)
        {
            bool Result;
            TXYL Location;
            if (!FEnchantmentMode.Contains(TGlobalEnchantmentModeElement.gemTrueGlobal) && Player != FPlayerIndex)
