            PersistSupport.Int32Array(persister, "DoubleSphereManaCount", FDoubleSphereManaCount);
            UpdateActiveEnchantments();
        }

        // Spells.PAS:2690
        public override void MsgProc(ref TEMsg Msg, TEObject Sender)
        {
