            FEnchantments.MsgProc(ref Msg, Sender);
        }

        // Spells.PAS:2679
        public void IncDoubleSphereManaCount(TMagicSphere Sphere)
        {
            FDoubleSphereManaCount[(int)Sphere] += 1;
        }

        // Spells.PAS:2681
        public void DecDoubleSphereManaCount(TMagicSphere Sphere)
        {
            FDoubleSphereManaCount[(int)Sphere] -= 1;
        }

        // Spells.PAS:2683
        public bool GetSphereManaDoubled(TMagicSphere Sphere) => FDoubleSphereManaCount[(int)Sphere] != 0;

        // Spells.PAS:2685
        public void OutOfMana(sbyte Player, int Mana)
        {
            int Index;
            int I;
            TGlobalEnchantment Enchantment;
            TPlayerMagicEventLog Log;
            Index = 0;
            while (Index != -1 && Mana > 0 && FEnchantments.GetCount() != 0)
            {
                I = FEnchantments.GetCount();
                // { Original may select the last enchantment of another player. }
                Index = I - 1;
                while (I != 0)
                {
                    I -= 1;
                    if (FEnchantments.GetEnchantments(I).FPlayerIndex == Player && FEnchantments.GetEnchantments(I).GetUpkeep() < FEnchantments.GetEnchantments(Index).GetUpkeep())
                    {
                        Index = I;
                    }
                }

                if (Index != -1)
                {
                    Enchantment = FEnchantments.GetEnchantments(Index);
                    Mana -= Enchantment.GetUpkeep();
                    Log = new TPlayerMagicEventLog(null);
                    Log.FPlayer = Player;
                    Log.FMode = TPlayerMagicEventMode.pmemOutOfMana;
                    Log.FEnchantmentName = FEnchantments.GetEnchantments(Index).GetName();
                    DistributeEventLog(Log, false);
                    Log.Release();
                    Enchantment.AddRef();
                    Enchantment.Deactivate((byte)Player);
                    Enchantment.Release();
                }
            }
        }

        // Spells.PAS:2688
        public void RemovePlayerEnchantments(sbyte Player)
        {
            for (int I = FEnchantments.GetCount() - 1; I >= 0; I--)
            {
                if (Player == FEnchantments.GetEnchantments(I).FPlayerIndex)
                {
                    FEnchantments.GetEnchantments(I).Remove((byte)Player);
                }
            }
        }

        // Spells.PAS:2692
        public void BeginUpdate()
        {
            FUpdateCount += 1;
        }

        // Spells.PAS:2694
        public void EndUpdate()
        {
            FUpdateCount -= 1;
            if (FUpdateCount == 0)
            {
                Update();
            }
        }

        // Spells.PAS:2696
        public void TriggerChangedEvent()
        {
            if (FUpdateCount == 0)
            {
                FChangedEventsStore.Raise(this);
            }
        }

        // Spells.PAS:2698
        public void Update()
        {
            UpdateActiveEnchantments();
            FChangedEventsStore.Raise(this);
        }

        // Spells.PAS:2700
        public int GetEnchantmentUpkeep(sbyte Player)
        {
            int Result = 0;
            for (int I = FEnchantments.GetCount() - 1; I >= 0; I--)
            {
                if (Player == FEnchantments.GetEnchantments(I).FPlayerIndex)
                {
                    Result += FEnchantments.GetEnchantments(I).GetUpkeep();
                }
            }

            return Result;
        }

        // Spells.PAS:2702
        public void UpdateActiveEnchantments()
        {
            FActiveEnchantments = TSet<TGlobalEnchantmentType>.Of();
            for (int I = FEnchantments.GetCount() - 1; I >= 0; I--)
            {
                var enchantments = FEnchantments.GetEnchantments(I);
                FActiveEnchantments = FActiveEnchantments + TSet<TGlobalEnchantmentType>.Of(enchantments.FEnchantmentType);
            }
        }

        // Spells.PAS:2704
        public int IndexOfID(int ID)
        {
            int I;
            I = FEnchantments.GetCount();
            while (I != 0)
            {
                I -= 1;
                if (ID == FEnchantments.GetEnchantments(I).FEnchantmentID)
                {
                    return I;
                }
            }

            return -1;
        }

        // Spells.PAS:2706
        public bool ValidateEnchantmentID(TGlobalEnchantment Enchantment)
        {
            int ID;
            ID = Enchantment.FEnchantmentID;
            if (ID > 0)
            {
                Enchantment.FEnchantmentID = 0;
                if (IndexOfID(ID) != -1)
                {
                    ID = 0;
                }
            }

            if (ID <= 0)
            {
                ID = FNextEnchantmentID;
                FNextEnchantmentID += 1;
                if (FNextEnchantmentID > 268435455)
                {
                    FNextEnchantmentID = 1;
                }

                while (IndexOfID(ID) != -1)
                {
                    ID = FNextEnchantmentID;
                    FNextEnchantmentID += 1;
                    if (FNextEnchantmentID > 268435455)
                    {
                        FNextEnchantmentID = 1;
                    }
                }
            }

            Enchantment.FEnchantmentID = ID;
            return true;
        }

        // Spells.PAS:2708
        public TChangeGlobalMagicTE CreateChangeMagicTE() => new TChangeGlobalMagicTE(null);

        // Spells.PAS:2710
        public bool ExecuteDispelEnchantment(sbyte Player, int EnchantmentID)
        {
            bool Result;
            int Index;
            Index = IndexOfID(EnchantmentID);
            if (Index != -1)
            {
                Result = FEnchantments.GetEnchantments(Index).Dispel((byte)Player);
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Spells.PAS:2712
        public bool DispelEnchantment(sbyte Player, TGlobalEnchantment Enchantment)
        {
            bool Result;
            TChangeGlobalMagicTE Event;
            string Reason = "";
            if (!AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).GetBusy() && IndexOfID(Enchantment.FEnchantmentID) != -1)
            {
                if (Enchantment.CanDispel(Player, ref Reason))
                {
                    Event = CreateChangeMagicTE();
                    Event.FMode = TChangeGlobalMagicMode.cgmDispelEnchantment;
                    Event.FEnchantmentID = Enchantment.FEnchantmentID;
                    Event.FPlayerIndex = (byte)Player;
                    AoWEUnit.AoWHSMap.FTokenManager.GetTokenControl(Player).AddEvent(Event);
                    Event.Release();
                    Result = true;
                }
                else
                {
                    if (Player == AoWEUnit.AoWHSMap.FSeatedPlayer)
                    {
                        AoWEUnit.AoWHSMap.ShowWarning(Reason);
                    }

                    Result = false;
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Spells.PAS:2714
        public bool ExecuteRemoveEnchantment(sbyte Player, int EnchantmentID)
        {
            bool Result;
            int Index;
            Index = IndexOfID(EnchantmentID);
            if (Index != -1)
            {
                Result = FEnchantments.GetEnchantments(Index).Remove((byte)Player);
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Spells.PAS:2716
        public bool RemoveEnchantment(sbyte Player, TGlobalEnchantment Enchantment)
        {
            bool Result;
            TChangeGlobalMagicTE Event;
            string Reason = "";
            if (!AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).GetBusy() && IndexOfID(Enchantment.FEnchantmentID) != -1)
            {
                if (Enchantment.CanRemove(Player, ref Reason))
                {
                    Event = CreateChangeMagicTE();
                    Event.FMode = TChangeGlobalMagicMode.cgmRemoveEnchantment;
                    Event.FEnchantmentID = Enchantment.FEnchantmentID;
                    Event.FPlayerIndex = (byte)Player;
                    AoWEUnit.AoWHSMap.FTokenManager.GetTokenControl(Player).AddEvent(Event);
                    Event.Release();
                    Result = true;
                }
                else
                {
                    if (Player == AoWEUnit.AoWHSMap.FSeatedPlayer)
                    {
                        AoWEUnit.AoWHSMap.ShowWarning(Reason);
                    }

                    Result = false;
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // intf_P4_01.inc:258

    }
