            if (Player == -1)
            {
                Result = AoWEUnit.StatusToStatusValue((TStatus)FDefaultRelations[Race]);
            }
            else
            {
                Result = FPlayerRelations[Player - 1];
            }

            return Result + ((TRaceList)Owner).FRelationOffset;
