            if (Player == -1)
            {
                Result = AoWEUnit.StatusValueToStatus(AoWEUnit.StatusToStatusValue((TStatus)FDefaultRelations[Race]) + AoWEUnit.AoWHSMap.FRaces.FRelationOffset);
            }
            else
            {
