                FPlayerRelations[Player - 1] = Value - AoWEUnit.AoWHSMap.FRaces.FRelationOffset;
                if (AoWEUnit.AoWHSMap != null)
                {
                    AoWEUnit.AoWHSMap.TriggerRelationsChanged();
                }
