        // Ability.PAS:423
        public void Update()
        {
            TRace Race;
            for (int I = 0, last = AoWEUnit.AoWHSSet.FRaceResources.GetCount() - 1; I <= last; I++)
            {
                if (AoWEUnit.AoWHSSet.FRaceResources.GetRaceResource(I) != null)
                {
                    if (GetRace(I) == null)
                    {
                        Race = new TRace(null);
                        Race.FRace = (sbyte)I;
                        Race.SetArrayOwner(this, I);
                        Race.SetEnabled(true);
                    }
                }
                else
                {
                    GetRace(I)?.Dispose();
                }
            }
        }

