        {
            FRelations?.Dispose();
            FHistory?.Dispose();
            base.Dispose();
        }

        // Player.PAS:92
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwStreamProc(20, FRelations.LoadFromStream, FRelations.SaveToStream);
            Stream.rwEObject(FHistory, 21);
            if (Stream.StorageMode().Contains(TStorageModeElement.smRead))
            {
                FRelations.Default = (int)TDiplomaticRelation.drUnknown;
            }
