        {
            FRelations[Player] = (byte)Value;
            if (!AoWEUnit.AoWHSMap.Status.Contains(THSMapStatusElement.msEditting) && AoWEUnit.AoWHSMap.FDay > 0)
            {
                GetHistory(Player).Add(Value, AoWEUnit.AoWHSMap.FDay);
            }
        }

        // Player.PAS:114
        public TDiplomaticRelationHistoryList GetHistory(sbyte Player) => (TDiplomaticRelationHistoryList)FHistory.FChildren.List[Player - 1];

        // Player.PAS:119
        public void ValidateHistory()
        {
            while (FHistory.Count + 1 < AoWEUnit.AoWHSMap.FPlayers.Count)
            {
                new TDiplomaticRelationHistoryList(null).Owner = FHistory;
            }

            while (FHistory.Count + 1 > AoWEUnit.AoWHSMap.FPlayers.Count)
            {
                var count = FHistory.Count;
                FHistory.Children[count - 1]?.Dispose();
            }
        }

        // intf_P1_03.inc:79

    }
