        // Player.PAS:425
        public void SetGameOverStatus(TGameOverStatus Value)
        {
            TGameOverEventLog Event;
            TPlayerStructureList Structures;
            TArmyList Armies;
            TAoWCampaign Campaign;
            if (Value != FGameOverStatus && FGameOverStatus == TGameOverStatus.goNone)
            {
                FGameOverStatus = Value;
                AoWEUnit.AoWHSMap.FAIExecuter.DeactivatePlayer(FPlayerIndex);
                if (AoWEUnit.AoWHSMap.FGameType == TGameType.gtCampaign && FPlayerType == TPlayerType.ptHuman)
                {
                    if (FGameOverStatus == TGameOverStatus.goLost)
                    {
                        AoWEUnit.AoWHSMap.FGameResult = TGameResult.grFailed;
                        Campaign = AoWEUnit.AoWEngine.FCampaign;
                        if (Campaign != null)
                        {
                            Campaign.RestartScenario();
                        }
                    }
                    else
                    {
                        if (FGameOverStatus == TGameOverStatus.goWon)
                        {
                            AoWEUnit.AoWHSMap.FGameResult = TGameResult.grSucceeded;
                            Campaign = AoWEUnit.AoWEngine.FCampaign;
                            if (Campaign != null)
                            {
                                Campaign.FinishScenario();
                            }
                        }
                    }
                }

                if (FGameOverStatus == TGameOverStatus.goLost)
                {
                    BeginUpdate();
                    FMagicControl.RemoveEnchantments();
                    Structures = FStructures;
                    for (int I = Structures.Count - 1; I >= 0; I--)
                    {
                        FStructures.GetStructure(I).SetPlayer(0);
                    }

                    Armies = FArmies;
                    for (int I = Armies.Count - 1; I >= 0; I--)
                    {
                        FArmies.GetArmy(I).SetPlayer(0);
                    }

                    FMagicControl.SetMana(0);
                    FGems = 0;
                    EndUpdate();
                    AoWEUnit.AoWHSMap.FPlayers.Update();
                }

                Event = new TGameOverEventLog(null);
                Event.FPlayer = FPlayerIndex;
                if (Value == TGameOverStatus.goLost)
                {
                    var raceNamesPlural = AoWEUnit.TranslateRStr(AoWEUnit.RaceNamesPluralRStr[FPlayerRace]);
                    var name = GetName();
                    var format = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.GameOverDefeatMessageRStr), [IntToStr(AoWEUnit.AoWHSMap.FDay), raceNamesPlural, name]);
                    Event.FMessage.Text = format;
                }
                else
                {
                    var raceNamesPluralText = AoWEUnit.TranslateRStr(AoWEUnit.RaceNamesPluralRStr[FPlayerRace]);
                    var name = GetName();
                    var format = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.GameOverVictoryMessageRStr), [IntToStr(AoWEUnit.AoWHSMap.FDay), raceNamesPluralText, name]);
                    Event.FMessage.Text = format;
                }

                AoWEUnit.AoWHSMap.ExecuteGameOverEvent(Event);
                Event.Release();
                if (FGameOverStatus == TGameOverStatus.goLost)
                {
                    AoWEUnit.AoWHSMap.FGlobalMagicControl.RemovePlayerEnchantments(FPlayerIndex);
                }
            }
        }

        // Player.PAS:484
        public bool Surrender()
        {
            bool Result;
            TGameOverTE TE;
            if (!GetBusy() && FGameOverStatus == TGameOverStatus.goNone)
            {
                TE = new TGameOverTE(null);
                TE.FPlayer = FPlayerIndex;
                TE.FGameOverStatus = TGameOverStatus.goLost;
                AoWEUnit.AoWHSMap.FTokenManager.GetTokenControl(FPlayerIndex).AddEvent(TE);
                TE.Release();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Player.PAS:499
        public bool Win()
        {
            bool Result;
            TGameOverTE TE;
            if (!GetBusy() && FGameOverStatus == TGameOverStatus.goNone)
            {
                TE = new TGameOverTE(null);
                TE.FPlayer = FPlayerIndex;
                TE.FGameOverStatus = TGameOverStatus.goWon;
                AoWEUnit.AoWHSMap.FTokenManager.GetTokenControl(FPlayerIndex).AddEvent(TE);
                TE.Release();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Player.PAS:515
        public bool Validate(TStrings Errors)
        {
            bool Result;
            string S;
            string LeaderName;
            if (FPlayerIndex > 0)
            {
                Result = true;
                if (FLeader.GetSphereCount() != AoWEUnit.AoWHSMap.FSphereCount)
                {
                    var raceNames = AoWEUnit.TranslateRStr(AoWEUnit.RaceNamesRStr[FPlayerRace]);
                    LeaderName = AoWEUnit.Format(AoWEUnit.XLeaderRStr, [raceNames]);
                    S = LeaderName + ": " + AoWEUnit.TranslateRStr(AoWEUnit.NotAllSpheresAssignedRStr);
                    Errors.Add(S);
                    Result = false;
                }

                if (FLeader.Owner == null)
                {
                    var raceNamesText = AoWEUnit.TranslateRStr(AoWEUnit.RaceNamesRStr[FPlayerRace]);
                    LeaderName = AoWEUnit.Format(AoWEUnit.XLeaderRStr, [raceNamesText]);
                    S = LeaderName + ": " + AoWEUnit.TranslateRStr(AoWEUnit.NotPlacedOnMapRStr);
                    Errors.Add(S);
                    Result = false;
                }

                if (FLeader.GetSkillPoints() != 0)
                {
                    var translateRStr = AoWEUnit.TranslateRStr(AoWEUnit.RaceNamesRStr[FPlayerRace]);
                    LeaderName = AoWEUnit.Format(AoWEUnit.XLeaderRStr, [translateRStr]);
                    S = LeaderName + ": " + AoWEUnit.TranslateRStr(AoWEUnit.NotAllSkillPointsAssignedRStr);
                    Errors.Add(S);
                }
            }
            else
            {
                // { Original reports unassigned skill points without failing validation. }
                Result = true;
            }

            return Result;
        }

