        // Player.PAS:571
        public void EndUpdate()
        {
            FUpdateCount -= 1;
            if (FUpdateCount == 0)
            {
                FGemsChangedEventsStore.Raise(this);
                FUpkeepChangedEventsStore.Raise(this);
                UpdateIncome();
