        // Player.PAS:600
        public void UpdateIncome()
        {
            FIncome = FBaseIncome;
            for (int I = FIncomeSources.Count - 1; I >= 0; I--)
            {
                var income = ((TIncomeSource)FIncomeSources.FChildren.List[I]).Income();
                FIncome += income;
            }

            if (FPlayerType == TPlayerType.ptCPU2)
            {
                FIncome = Round((double)FIncome * 1);
            }
            else
            {
                if (FPlayerType == TPlayerType.ptCPU3)
                {
                    FIncome = Round((double)FIncome * 2);
                }
                else
                {
                    if (FPlayerType == TPlayerType.ptCPU4)
                    {
                        FIncome = Round((double)FIncome * 2.5) + 50;
                    }
                    else
                    {
                        if (FPlayerType == TPlayerType.ptCPU5)
                        {
                            FIncome = Round(FIncome * 3) + 100;
                        }
                    }
                }
            }

            if (FUpdateCount == 0)
            {
                FIncomeChangedEventsStore.Raise(this);
            }
        }

