        // Player.PAS:688
        public int GetHeroCountMax()
        {
            int Result;
            int Strength;
            int Maximum;
            var count = FStatistics.FTurnInfo.Count;
            Strength = FStatistics.FTurnInfo.GetTurnInfo(count - 1).FArmyStrength;
            if (Strength < 10)
            {
                Result = 1;
            }
            else
            {
                if (Strength < 40)
                {
                    Result = 2;
                }
                else
                {
                    if (Strength < 80)
                    {
                        Result = 3;
                    }
                    else
                    {
                        if (Strength < 120)
                        {
                            Result = 4;
                        }
                        else
                        {
                            if (Strength < 200)
                            {
                                Result = 5;
                            }
                            else
                            {
                                Result = (Strength - 200) / 100 + 5;
                            }
                        }
                    }
                }
            }

            Maximum = AoWEUnit.AoWHSMap.FHeroCountMax;
            if (Maximum < Result)
            {
                Result = Maximum;
            }

            return Result;
        }

