        // Player.PAS:738
        public void MakeHeroEmerge(THeroEmergeMode Mode)
        {
            int Chance = default;
            TDoubleItemList<THero> Heroes;
            THeroEmergeEventLog Log;
            TXYLList Locations;
            TStructure Structure;
            TDoubleItem<THero> Item;
            int I;
            THero Hero;
            Heroes = new TDoubleItemList<THero>();
            if (Mode == THeroEmergeMode.hemNormal)
            {
                I = AoWEUnit.AoWHSMap.FHeroControl.GetCount() - 1;
                for (; I >= 0; I -= 1)
                {
                    Hero = AoWEUnit.AoWHSMap.FHeroControl.GetHero(I);
                    if (!Hero.FHeroStatus.Contains(THeroStatusElement.hsDied) && Hero.FPlayer <= 0 && Hero.Owner == null && Hero.CanJoin(FPlayerIndex))
                    {
                        Chance = GetHeroJoinChance(Hero.GetLevel());
                        if (Chance > 0 && Hero.JoinAmount(FPlayerIndex) < FGems)
                        {
                            Heroes.AddAB(Hero, Chance * Chance);
                        }
                    }
                }
            }
            else
            {
                if (Mode == THeroEmergeMode.hemFirstHero)
                {
                    I = AoWEUnit.AoWHSMap.FHeroControl.GetCount() - 1;
                    for (; I >= 0; I -= 1)
                    {
                        Hero = AoWEUnit.AoWHSMap.FHeroControl.GetHero(I);
                        if (!Hero.FHeroStatus.Contains(THeroStatusElement.hsDied) && Hero.FPlayer <= 0 && Hero.Owner == null && Hero.GetAbilityEnabled(52) && Hero.GetLevel() >= 2 && Hero.GetLevel() <= 3)
                        {
                            var playerRelation = AoWEUnit.AoWHSMap.FRaces.GetRace(Hero.FRace).GetPlayerRelation(FPlayerIndex);
                            if (TSet<TStatus>.Of(TStatus.sPolite, TStatus.sFriendly).Contains(playerRelation) && Hero.JoinAmount(FPlayerIndex) < FGems)
                            {
                                var level = Hero.GetLevel();
                                Heroes.AddAB(Hero, (level - 2) * 1000 + 1);
                            }
                        }
                    }
                }
            }

            if (Heroes.Count != 0)
            {
                Locations = new TXYLList();
                I = FStructures.Count - 1;
                for (; I >= 0; I -= 1)
                {
                    Structure = FStructures.GetStructure(I);
                    if (Structure.EClass.ClassID == 131336)
                    {
                        var lhx = Structure.GetLhx();
                        var yhx = Structure.GetYhx();
                        Locations.AddXYL(Structure.GetXhx(), yhx, lhx);
                    }
                }

                if (Locations.Count != 0)
                {
                    FLastHeroEmergeDay = AoWEUnit.AoWHSMap.FDay;
                    RandSeed = AoWEUnit.AoWHSMap.Random(1048575);
                    I = Heroes.RandomChanceItemB(0);
                    Item = Heroes[I];
                    Hero = Item.A;
                    I = AoWEUnit.AoWHSMap.Random(Locations.Count);
                    FEmergingHeroID = Hero.FUnitID;
                    Hero.UpdateSettings();
                    var item = Locations[I];
                    var locationsItem = Locations[I];
                    Hero.Place(Locations[I].X, locationsItem.Y, item.L, 0, TSet<TUnitPlaceModeElement>.Of(TUnitPlaceModeElement.pmScanArea, TUnitPlaceModeElement.pmCreateNewArmy));
                    var item2 = Locations[I];
                    var item3 = Locations[I];
                    var item4 = Locations[I];
                    Structure = (TStructure)AoWEUnit.AoWHSMap.MapContainer.GetField(item4.X, item3.Y, item2.L).FindNoneTransparentHS(typeof(TStructure));
                    Log = new THeroEmergeEventLog(null);
                    Log.Setup(Hero, FPlayerIndex, THeroJoinMode.hjmEmerged);
                    if (Structure != null)
                    {
                        Log.FLocationName = Structure.GetName();
                    }
                    else
                    {
                        Log.FLocationName = AoWEUnit.TranslateRStr(AoWEUnit.UnknownRStr);
                    }

                    FEventLogbook.AddEvent(Log);
                    if (FPlayerIndex == AoWEUnit.AoWHSMap.FSeatedPlayer && AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayerIndex).FPlayerType == TPlayerType.ptHuman)
                    {
                        Log.Execute(false, TExecuteTrigger.etEvent, null);
                    }

                    Log.Release();
                }

                Locations?.Dispose();
            }

            Heroes?.Dispose();
        }

        // Player.PAS:812
        public void UpdateHeroJoin()
        {
            int Days;
            for (int I = FHeroes.Count - 1; I >= 0; I--)
            {
                if (FHeroes.GetHero(I).GetLevel() > FHighestHeroLevel)
                {
                    FHighestHeroLevel = FHeroes.GetHero(I).GetLevel();
                }
            }

            FBaseHeroJoinLevel = AoWEUnit.AoWHSMap.FPlayers.GetAverageHeroLevel();
            if (FBaseHeroJoinLevel == 0)
            {
                FBaseHeroJoinLevel = AoWEUnit.AoWHSMap.FHeroControl.GetMinFreeHeroLevel();
            }

            if (FHighestHeroLevel != 0)
            {
                FBaseHeroJoinLevel = (FBaseHeroJoinLevel + FHighestHeroLevel + 1) / 2;
            }

            if (FHeroes.Count == GetHeroCountMax())
            {
                ResetBaseHeroJoinDay();
            }

            FEmergingHeroID = 0;
            Days = GetIdealHeroEmergeDay() - AoWEUnit.AoWHSMap.FDay;
            if (AoWEUnit.AoWHSMap.FDay == 1 && FHeroes.Count == 1 && !AoWEUnit.AoWHSMap.FFixedLeaders)
            {
                MakeHeroEmerge(THeroEmergeMode.hemFirstHero);
                return;
            }

            if (Days <= 0)
            {
                if (AoWEUnit.AoWHSMap.Random(4) == 1)
                {
                    MakeHeroEmerge(THeroEmergeMode.hemNormal);
                }
            }
        }

        // Player.PAS:836
        public int GetHeroJoinChance(int Level)
        {
            int Result;
            int Maximum;
            Maximum = GetHeroJoinLevelMax();
            if (Level <= Maximum)
            {
                Result = Round((double)((double)(Maximum + 2) / (Level + 2)) * 20);
                if (Result > 40)
                {
                    Result = 40;
                }
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // Player.PAS:849
        public int GetHeroJoinLevelMax()
        {
            int Days;
            int Result = FBaseHeroJoinLevel;
            var idealHeroJoinDay = GetIdealHeroJoinDay();
            Days = AoWEUnit.AoWHSMap.FDay - idealHeroJoinDay;
            if (Days > 0)
            {
                Result += Days / 5;
            }

            if (Days < 0)
            {
                Result += Round((double)((double)(Result * Days) + 2.5) / 5);
                if (Result < 0)
                {
                    Result = 0;
                }
            }

            if (Result < 3 && !AoWEUnit.AoWHSMap.FFixedLeaders && AoWEUnit.AoWHSMap.FDay == 1)
            {
                Result = 3;
            }

            return Result;
        }

        // Player.PAS:865
        public void ValidateLeader()
        {
            int FaceIndex;
            int ResourceIndex;
            THeroType HeroType;
            string Name;
            if (AoWEUnit.AoWHSMap != null && FPlayerIndex != 0)
            {
                HeroType = THeroType.htHeroLeader;
                if (FLeader != null && FLeader.GetHeroType() != HeroType)
                {
                    Name = FLeader.FHeroName;
                    FaceIndex = FLeader.FFaceIndex;
                    FLeader.Deactivate();
                    ResourceIndex = AoWEUnit.AoWHSSet.FHeroResources.Find(FPlayerRace, HeroType);
                    FLeader.SetHeroResourceIndex(ResourceIndex);
                    FLeader.FHeroName = Name;
                    FLeader.SetFaceIndex(FaceIndex);
                    FLeader.Activate();
                }
                else
                {
                    if (FLeader == null)
                    {
                        ResourceIndex = AoWEUnit.AoWHSSet.FHeroResources.Find(FPlayerRace, HeroType);
                        if (ResourceIndex != -1)
                        {
                            FLeader = new TLeader(null);
                            FLeader.SetHeroResourceIndex(ResourceIndex);
                            FLeader.FPlayer = FPlayerIndex;
                            FLeader.Activate();
                        }
                    }
                    else
                    {
                        if (FLeader != null && !AoWEUnit.AoWHSMap.FFixedLeaders && AoWEUnit.AoWHSMap.FGameType != TGameType.gtCampaign && !AoWEUnit.AoWHSMap.Status.Contains(THSMapStatusElement.msEditting))
                        {
                            FLeader.Owner = null;
                        }
                    }
                }
            }
        }

