            if (((TPlayer)FChildren.List[Player]).FDiplomaticRelations.GetDiplomaticRelation(OtherPlayer) != Relation || ((TPlayer)FChildren.List[OtherPlayer]).FDiplomaticRelations.GetDiplomaticRelation(Player) != Relation)
            {
