        // Player.PAS:1636
        public void SetNumberOfPlayers(byte Value)
        {
            TPlayer Player;
            if (Value < 2)
            {
                Value = 2;
            }

            if (Value > 12)
            {
                Value = 12;
            }

            while (Count <= Value)
            {
                Player = new TPlayer(null);
                Player.SetPlayerIndex((sbyte)Count);
                if (Count == 0)
                {
                    Player.FPlayerType = TPlayerType.ptIndependent;
                }

                Player.FPlayerRace = (sbyte)(Count - 1);
                Player.SetArrayOwner(this, Count);
            }

            while (Count > Value + 1)
            {
                GetPlayers(Count - 1).Dispose();
                var count = Count;
                FChildren.Delete(count - 1);
            }
        }

        // Player.PAS:1657
        public void ValidateRaces(TRaceList Races)
        {
            TIntegerList Available;
            TIntegerList Invalid;
            int I;
            int Index;
            int DefaultRace;
            Available = new TIntegerList();
            Invalid = new TIntegerList();
            I = 0;
            int last = Races.Count - 1;
            for (; I <= last; I += 1)
            {
                if (Races.GetRace(I).FEnabled)
                {
                    Available.Add(I);
                }
            }

            I = 1;
            int limit = FChildren.Count - 1;
            for (; I <= limit; I += 1)
            {
                Index = Available.IndexOf(((TPlayer)FChildren.List[I]).FPlayerRace);
                if (Index == -1)
                {
                    Invalid.Add(I);
                }
                else
                {
                    Available.Delete(Index);
                }
            }

            I = 0;
            DefaultRace = -1;
            while (I != AoWEUnit.AoWHSSet.FRaceResources.Count && DefaultRace == -1)
            {
                if (AoWEUnit.AoWHSSet.FRaceResources.GetRaceResource(I) != null)
                {
                    if (Races == null || Races.GetRace(I).FEnabled)
                    {
                        DefaultRace = I;
                    }
                }

                I += 1;
            }

            I = 0;
            int last2 = Invalid.Count - 1;
            for (; I <= last2; I += 1)
            {
                if (Available.Count == 0)
                {
                    var item = Invalid[I];
                    ((TPlayer)FChildren.List[item]).SetRace((sbyte)DefaultRace);
                }
                else
                {
                    var item = Available[0];
                    var invalidItem = Invalid[I];
                    ((TPlayer)FChildren.List[invalidItem]).SetRace((sbyte)item);
                    Available.Delete(0);
                }
            }

            Invalid?.Dispose();
            Available?.Dispose();
        }

        // Player.PAS:1691
        public int VerifyRaces(TRaceList Races)
        {
            int Result;
            bool Valid;
            int I;
            int J;
            TPlayer Player;
            Valid = true;
            I = 1;
            while (Valid && I < FChildren.Count)
            {
                Player = (TPlayer)FChildren.List[I];
                Valid = Player.FPlayerRace != -1 && Races.GetRace(Player.FPlayerRace).FEnabled;
                if (Valid)
                {
                    J = 1;
                    while (Valid && J != FChildren.Count)
                    {
                        Valid = J == I || GetPlayers(J).FPlayerRace != Player.FPlayerRace;
                        J += 1;
                    }
                }

                if (Valid)
                {
                    I += 1;
                }
            }

            if (Valid)
            {
                Result = 0;
            }
            else
            {
                Result = I;
            }

            return Result;
        }

        // Player.PAS:1718
        public sbyte GetSuperiorPlayer()
        {
            int Maximum;
            int BestPlayer;
            int Value;
            Maximum = 0;
            BestPlayer = -1;
            for (int I = 1, last = Count - 1; I <= last; I++)
            {
                if (GetPlayers(I).FStatus == TPlayerStatus.psPlaying)
                {
                    Value = GetPlayers(I).GetSuperiority();
                    if (Value > Maximum)
