                if (Activate(Settings))
                {
                    Assert(AoWEUnit.AoWEngine.FDemo || Settings.FStatus != TMoveControlSettingsStatus.mcssProcessed, "", "MoveT.PAS", 1541);
                    do
                    {
                    }
                    while (!!Process());
                    if (FDestinationX != -1)
                    {
                        CalculatePathEx(Settings.FPath, (sbyte)FDestinationX, (sbyte)FDestinationY, (sbyte)FDestinationL);
                        if (Settings.FPath.Count == 0)
                        {
                            Settings.FStatus = TMoveControlSettingsStatus.mcssFailed;
