            }
            else
            {
                Settings.FPath.Clear();
                Settings.FPath.AddXYL((sbyte)Settings.FSourceX, (sbyte)Settings.FSourceY, (sbyte)Settings.FSourceL);
                Settings.FStatus = TMoveControlSettingsStatus.mcssProcessed;
            }
