        // MoveT.PAS:308
        public TAoWMapField FindSubMoveOrigin(TAoWMapField MapF)
        {
            int Best;
            int Points;
            int I;
            TSubMove SubMove;
            TMoveControlSettings Settings;
            Best = 16777215;
            TAoWMapField Result = null;
            I = 0;
            Settings = FSettings;
            while (I < Settings.FSubMoves.Count)
            {
                SubMove = Settings.FSubMoves.GetSubMove(I);
                if (MapF.Xhx == SubMove.FLocation.X && MapF.Yhx == SubMove.FLocation.Y && MapF.Lhx == SubMove.FLocation.L)
                {
                    Points = Settings.GetMovePoints(SubMove.FOrigin.X, SubMove.FOrigin.Y, SubMove.FOrigin.L);
                    if (Points <= Best)
                    {
                        // { After pushing L, the original stack slot holds Self, not Result. }
                        Result = (TAoWMapField)FMap.MapContainer.GetField(SubMove.FOrigin.X, SubMove.FOrigin.Y, SubMove.FOrigin.L);
                        Best = Points;
                    }
                }

                I += 1;
            }

