        // MoveT.PAS:1504
        public void Deactivate()
        {
            if (FStatus.Contains(TMoveControlStatusElement.mcsActivated))
            {
                FStatus = FStatus - TSet<TMoveControlStatusElement>.Of(TMoveControlStatusElement.mcsActivated);
                if (FSettings.FStatus == TMoveControlSettingsStatus.mcssProcessing)
                {
                    FSettings.FMovePointsLimit = FMovePointsLimit;
                }

                FSettings.Release();
                FSettings = null;
            }
        }

        // MoveT.PAS:1559
        public int CanMove(TMoveControlSettings Settings, TSet<TCanMoveModeElement> Mode)
        {
            int Points;
            if (Settings.FSourceX != Settings.FDestinationX || Settings.FSourceY != Settings.FDestinationY || Settings.FSourceL != Settings.FDestinationL)
            {
                Settings.ResetState();
                if (Activate(Settings))
                {
                    Points = -1;
                    if (FDestinationX == -1 || ValidLocation(FDestinationX, FDestinationY, FDestinationL))
                    {
                        if (FSourceL == FDestinationL && Mode.Contains(TCanMoveModeElement.mmFast))
                        {
                            Points = GetMovePointsCostFast(FSourceX, FSourceY, FDestinationX, FDestinationY);
                        }

                        if (Points == -1 && Mode.Contains(TCanMoveModeElement.mmExact))
                        {
                            do
                            {
                            }
                            while (!!Process());
                            Points = FSettings.GetMovePoints(FDestinationX, FDestinationY, FDestinationL);
                            if (Points == 16777215)
                            {
                                Points = -1;
                            }
                        }
                    }

                    Deactivate();
                }
                else
                {
                    Points = -1;
                }
            }
            else
            {
                Points = 0;
            }

            return Points;
        }

        // MoveT.PAS:1589
        public bool ValidPath(TMoveControlSettings Settings, TMovepath Path)
        {
            bool Valid;
            int I;
            int Points;
            Valid = true;
            I = Path.Count - 2;
            Points = 0;
            Settings.FMovePointsMax = Path.PosToMovePoints(0);
            ProcessMove(Settings);
            while (I > 0 && Valid)
            {
                Points += Path[I].Flag;
                var item = Path[I];
                var pathItem = Path[I];
                Valid = Points == Settings.GetMovePoints(Path[I].X, pathItem.Y, item.L);
                I -= 1;
            }

            return Valid;
        }

        // MoveT.PAS:1608
        public void CalculateGaps(int SourceX, int SourceY, int DestinationX, int DestinationY)
        {
            int X;
            int Y;
            int Direction;
            int OverCode;
            TAoWMapField Field;
            bool Clear;
            int Points = default;
            Clear = true;
            FGapStarts.Count = 0;
            FGapEnds.Count = 0;
            FDirectRoute.Count = 0;
            OverCode = 1;
            FDirectRoute.AddXYL((sbyte)SourceX, (sbyte)SourceY, 0);
            X = 0;
            Y = 0;
            Direction = 0;
            while (SourceX != DestinationX || SourceY != DestinationY)
            {
                if (SourceX == DestinationX)
                {
                    if (SourceY > DestinationY)
                    {
                        Direction = 1;
                        X = SourceX;
                        Y = SourceY - 1;
                    }
                    else
                    {
                        if (SourceY < DestinationY)
                        {
                            Direction = 4;
                            X = SourceX;
                            Y = SourceY + 1;
                        }
                    }
                }
                else
                {
                    if ((SourceX & 1) == 0)
                    {
                        if (SourceX > DestinationX)
                        {
                            if (SourceY > DestinationY)
                            {
                                Direction = 6;
                                X = SourceX - 1;
                                Y = SourceY - 1;
                            }
                            else
                            {
                                Direction = 5;
                                X = SourceX - 1;
                                Y = SourceY;
                            }
                        }
                        else
                        {
                            if (SourceY > DestinationY)
                            {
                                Direction = 2;
                                X = SourceX + 1;
                                Y = SourceY - 1;
                            }
                            else
                            {
                                Direction = 3;
                                X = SourceX + 1;
                                Y = SourceY;
                            }
                        }
                    }
                    else
                    {
                        if (SourceX > DestinationX)
                        {
                            if (SourceY < DestinationY)
                            {
                                Direction = 5;
                                X = SourceX - 1;
                                Y = SourceY + 1;
                            }
                            else
                            {
                                Direction = 6;
                                X = SourceX - 1;
                                Y = SourceY;
                            }
                        }
                        else
                        {
                            if (SourceY < DestinationY)
                            {
                                Direction = 3;
                                X = SourceX + 1;
                                Y = SourceY + 1;
                            }
                            else
                            {
                                Direction = 2;
                                X = SourceX + 1;
                                Y = SourceY;
                            }
                        }
                    }
                }

                Field = (TAoWMapField)FMapLevel.GetField(X, Y);
                Points = FOnMovePoint(Field, OverCode);
                if (Points >= 0)
                {
                    if ((Field.FFieldFlags & 8192) != 0 && (X != DestinationX || Y != DestinationY))
                    {
                        OverCode = Field.CanMoveOver(this);
                        if (OverCode == 0)
                        {
                            Points = -1;
                            OverCode = 1;
                        }
                    }
                    else
                    {
                        OverCode = 1;
                    }
                }

                if (Points < 0)
                {
                    if (Clear)
                    {
                        FGapStarts.AddXYL((sbyte)SourceX, (sbyte)SourceY, (sbyte)Direction);
                        Clear = false;
                        OverCode = 1;
                    }
                }
                else
                {
                    if (!Clear)
                    {
                        FGapEnds.AddXYL((sbyte)X, (sbyte)Y, -1);
                        Clear = true;
                    }
                }

                SourceX = X;
                SourceY = Y;
                FDirectRoute.AddXYL((sbyte)SourceX, (sbyte)SourceY, (sbyte)Points);
            }

            if (!Clear)
            {
                FGapEnds.AddXYL((sbyte)DestinationX, (sbyte)DestinationY, -1);
            }
        }

        // MoveT.PAS:1815
        public int GetMovePointsCostFast(int SourceX, int SourceY, int DestinationX, int DestinationY)
        {
            int I;
            int Points;
            int GapIndex;
            int Cost;
            I = 1;
            GapIndex = 0;
            Points = 0;
            CalculateGaps(SourceX, SourceY, DestinationX, DestinationY);
            while (I < FDirectRoute.Count && Points != -1)
            {
                Cost = FDirectRoute[I].L;
                if (Cost < 0)
                {
                    var item = FDirectRoute[I - 1];
                    var fDirectRouteItem = FDirectRoute[I - 1];
                    GapIndex = FGapStarts.IndexOfXY(fDirectRouteItem.X, item.Y);
                    Cost = CalculateTurnAroundMovePoints(ref GapIndex);
                    if (Cost != -1)
                    {
                        Points += Cost;
                        var fGapEndsItem = FGapEnds[GapIndex];
                        var item2 = FGapEnds[GapIndex];
                        I = FDirectRoute.IndexOfXY(item2.X, fGapEndsItem.Y);
                    }
                    else
                    {
                        Points = -1;
                    }
                }
                else
                {
                    Points += Cost;
                }

                I += 1;
            }

            return Points;
        }

        // intf_P5_01.inc:120

    }
}

