    // { Interface declaration run owned by P1. }
    // reason, disconnected player
    public partial class TPlayerConnectionEventLog : TMessageEventLog
    {
        public TPlayerConnectionEventLog(TECustomNode owner) : base(owner)
        { }

        public byte FReason;
        public sbyte FDisconnectedPlayer;

        // PlayerC.PAS:1714
        public override bool Yes()
        {
            TSaveGameEventLog Log = default;
            Log = new TSaveGameEventLog(null);
            Log.FDefaultName = "";
            Log.FDirectory = AoWEUnit.AoWEngine.StartupDirectory + "Save\\";
            AoWEUnit.AoWHSMap.TriggerExecuteEventLog(Log, false, ExitSaveGameCallBack);
            Log.Release();
            return true;
        }

        // PlayerC.PAS:1726
        public override bool No()
        {
            AoWEUnit.AoWHSMap.ExecuteExitGame();
            return true;
        }

        // PlayerC.PAS:1671
        public void Setup(sbyte Player, byte Reason)
        {
            FReason = Reason;
            FDisconnectedPlayer = Player;
            switch (FReason)
            {
                case 3:
                    FButtons = TMessageEventLogButtons.mebYesNo;
                    var outOfSync = AoWEUnit.TranslateRStr(AoWEUnit.OutOfSyncRStr);
                    FMessage.Text = outOfSync;
                    var aoWETranslateRStr = AoWEUnit.TranslateRStr(AoWEUnit.TerminateGameSaveRStr);
                    FMessage.Add(aoWETranslateRStr);
                    break;
                case 1:
                    FButtons = TMessageEventLogButtons.mebYesNo;
                    var name = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FDisconnectedPlayer).GetName();
                    var format = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.ConnectionXTimeOutRStr), [name]);
                    FMessage.Text = format;
                    FMessage.Add("");
                    var terminateGameSave = AoWEUnit.TranslateRStr(AoWEUnit.TerminateGameSaveRStr);
                    FMessage.Add(terminateGameSave);
                    break;
                case 2:
                    FButtons = TMessageEventLogButtons.mebYesNo;
                    if (FDisconnectedPlayer != -1)
                    {
                        var name2 = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FDisconnectedPlayer).GetName();
                        var aoWEFormat = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.ConnectionXLostRStr), [name2]);
                        FMessage.Text = aoWEFormat;
                    }
                    else
                    {
                        var connectionLost = AoWEUnit.TranslateRStr(AoWEUnit.ConnectionLostRStr);
                        FMessage.Text = connectionLost;
                    }

                    FMessage.Add("");
                    var terminateGameSaveText = AoWEUnit.TranslateRStr(AoWEUnit.TerminateGameSaveRStr);
                    FMessage.Add(terminateGameSaveText);
                    break;
            }
        }

        // PlayerC.PAS:1703
        public void ExitSaveGameCallBack(TEventLog Log)
        {
            if (!IsEmpty(((TSaveGameEventLog)Log).FFileName))
            {
                if (AoWEUnit.AoWEngine.FCampaign != null)
                {
                    AoWEUnit.AoWEngine.SaveCampaign(((TSaveGameEventLog)Log).FFileName);
                }
                else
                {
                    AoWEUnit.AoWEngine.SaveHSM(((TSaveGameEventLog)Log).FFileName, null, Aow.Formats.GameProfile.WorldMap);
                }
            }
            else
            {
                // { Original exits twice when the dialog is canceled. }
                AoWEUnit.AoWHSMap.ExecuteExitGame();
            }

            AoWEUnit.AoWHSMap.ExecuteExitGame();
        }

    }
}

