            AoWEUnit.AoWHSMap.FDay += 1;
            AoWEUnit.AoWHSMap.FPlayers.BeginUpdate();
            AoWEUnit.AoWHSMap.LockRelationsChanged();
            for (int I = 1, last = AoWEUnit.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
            {
                Log = new TNewDayEventLog(null);
                Log.FText = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.NewDayRStr), [AoWEUnit.AoWHSMap.FDay]);
                if (AoWEUnit.AoWHSMap.FDayLimit != 0 && AoWEUnit.AoWHSMap.FDayLimit - AoWEUnit.AoWHSMap.FDay <= 10)
                {
                    var fmtDaysLeftStr = AoWEUnit.FmtDaysLeftStr(AoWEUnit.AoWHSMap.FDayLimit - AoWEUnit.AoWHSMap.FDay);
                    Log.FText = Log.FText + " (" + fmtDaysLeftStr + ")";
                }

                Log.FPlayer = (sbyte)I;
                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FEventLogbook.AddEvent(Log);
                Log.Release();
            }

            if (AoWEUnit.AoWHSMap.FTurnOrderMode == TTurnOrderMode.toChanging)
            {
                AoWEUnit.AoWHSMap.GenerateNewTurnOrder();
            }

            if (AoWEUnit.AoWHSMap.FDay == 1)
            {
                AoWEUnit.AoWHSMap.FRaces.ResetPlayerRelations();
                if (AoWEUnit.AoWHSMap.FConnectionType == TPlayerConnectionType.pcLocal)
                {
                    Randomize();
                    AoWEUnit.AoWHSMap.FInitialRandomSeed = RandSeed;
                }

                AoWEUnit.AoWHSMap.FDefendersSeed = AoWEUnit.AoWHSMap.FInitialRandomSeed;
            }

            try
            {
                InitMsg(ref Msg, 537001985, this);
                AoWEUnit.AoWHSMap.SendMsg(ref Msg, this);
            }
            catch
            {
            }

            try
            {
                AoWEUnit.AoWHSMap.FNewDayEventsStore.Raise(this);
            }
            catch
            {
            }

            if (AoWEUnit.AoWHSMap.FDayLimit == AoWEUnit.AoWHSMap.FDay)
            {
                MessageLog = new TMessageEventLog(null);
                MessageLog.FTitle = AoWEUnit.TranslateRStr(AoWEUnit.InfoRStr);
                MessageLog.FButtons = TMessageEventLogButtons.mebOk;
                MessageLog.FLayout = TMessageEventLogLayout.melNormal;
                var turnLimitReached = AoWEUnit.TranslateRStr(AoWEUnit.TurnLimitReachedRStr);
                MessageLog.FMessage.Text = turnLimitReached;
                AoWEUnit.AoWHSMap.TriggerExecuteEventLog(MessageLog, false, null);
                MessageLog.Release();
                AoWEUnit.AoWHSMap.GameOver(AoWEUnit.AoWHSMap.FSeatedPlayer, TGameOverStatus.goLost);
                for (int I = 1, last = AoWEUnit.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
                {
                    AoWEUnit.AoWHSMap.GameOver((sbyte)I, TGameOverStatus.goLost);
                }
            }

            AoWEUnit.AoWHSMap.UnlockRelationsChanged();
            AoWEUnit.AoWHSMap.TriggerRelationsChanged();
            AoWEUnit.AoWHSMap.FPlayers.EndUpdate();
        }

        // PlayerC.PAS:177
        public virtual void NewTurn(sbyte Player)
        {
            TEMsg Msg = default;
            if (AoWEUnit.AoWHSMap.FDay != 1)
            {
                var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
                var fPlayersPlayers = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
                var upkeep = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).GetUpkeep();
                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).SetGems(players.FGems + fPlayersPlayers.FIncome - upkeep);
                if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FGems < 0)
                {
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).SetGems(0);
                    var players2 = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
                    players2.FMoraleValue = (sbyte)(players2.FMoraleValue - 5);
                    if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FMoraleValue < -50)
                    {
                        AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FMoraleValue = -50;
                    }
                }
                else
                {
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FMoraleValue = 0;
                }

                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).SetEndTurn(false);
            }

            var players3 = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
            players3.FDay += 1;
            AoWEUnit.AoWHSMap.LockUpdateVisibility();
            InitMsg(ref Msg, 537001986, this);
            Msg.Payload = Player;
            AoWEUnit.AoWHSMap.SendMsg(ref Msg, this);
            AoWEUnit.AoWHSMap.FNewTurnEventsStore.Raise(Player);
            InitMsg(ref Msg, 537001987, this);
            Msg.Payload = Player;
            AoWEUnit.AoWHSMap.SendMsg(ref Msg, this);
            AoWEUnit.AoWHSMap.UnLockUpdateVisibility();
            if (AoWEUnit.AoWHSMap.FDebugSave)
            {
                try
                {
                    if (AoWEUnit.AoWHSMap.FPlayMode == TPlayMode.pmSimultaneous)
                    {
                        if (Player == 0)
                        {
                            AoWEUnit.AoWEngine.SaveHSM(AoWEUnit.AoWEngine.StartupDirectory + "DEBUG\\" + AoWEUnit.AoWHSMap.FMapName + IntToStr(AoWEUnit.AoWHSMap.FDay) + "_p" + IntToStr(AoWEUnit.AoWHSMap.FSeatedPlayer) + FileBoundary.WriteExtension(Aow.Formats.DocumentKind.Save), null, Aow.Formats.GameProfile.WorldMap);
                        }
                    }
                    else
                    {
                        AoWEUnit.AoWEngine.SaveHSM(AoWEUnit.AoWEngine.StartupDirectory + "DEBUG\\" + AoWEUnit.AoWHSMap.FMapName + IntToStr(AoWEUnit.AoWHSMap.FDay) + "-" + IntToStr(Player) + "_p" + IntToStr(AoWEUnit.AoWHSMap.FSeatedPlayer) + FileBoundary.WriteExtension(Aow.Formats.DocumentKind.Save), null, Aow.Formats.GameProfile.WorldMap);
                    }
                }
                catch
                {
                }
            }
        }

