                if ((AoWEUnit.AoWHSMap.Status.Contains(THSMapStatusElement.msEditting) || TSet<TPlayerConnectionType>.Of(TPlayerConnectionType.pcLocal, TPlayerConnectionType.pcEmail).Contains(AoWEUnit.AoWHSMap.FConnectionType)) && AoWEUnit.AoWHSMap.FPlayerCommunicator.PCC == null)
                {
                    PCC = new TLocalPCC();
                    PCC.Setup(AoWEUnit.AoWHSMap.FPlayers.Count);
                    for (int I = 0, last = AoWEUnit.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
                    {
                        if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType == TPlayerType.ptHuman)
                        {
                            PCC.SetConnectionMode(I, TConnectionMode.cmLocal);
                        }
                        else
                        {
                            PCC.SetConnectionMode(I, TConnectionMode.cmGlobal);
                        }
                    }

                    AoWEUnit.AoWHSMap.FPlayerCommunicator.ActivatePCC(PCC);
                    PCC.Release();
                    AoWEUnit.AoWHSMap.FPlayers.Update();
                }
