        // PlayerC.PAS:241
        public virtual void GameOver(sbyte Player, TGameOverStatus Status)
        {
            if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FGameOverStatus != Status && AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FStatus != TPlayerStatus.psTerminated)
            {
                AoWEUnit.AoWHSMap.LockGameOverEvent();
                SetPlayerGameOverStatus(Player, Status);
                if (Status == TGameOverStatus.goLost)
                {
                    if (!AoWEUnit.AoWHSMap.FAlliedVictory)
                    {
                        if (AoWEUnit.AoWHSMap.FPlayers.FActivePlayers.Count == 1)
                        {
                            GameOver((sbyte)AoWEUnit.AoWHSMap.FPlayers.FActivePlayers[0], TGameOverStatus.goWon);
                        }
                    }
                    else
                    {
                        if (AoWEUnit.AoWHSMap.FPlayers.GetActivePlayersAllied())
                        {
                            for (int I = 1, last = AoWEUnit.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
                            {
                                if (I != Player && AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FStatus == TPlayerStatus.psPlaying && AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FGameOverStatus != TGameOverStatus.goLost)
                                {
                                    SetPlayerGameOverStatus((sbyte)I, TGameOverStatus.goWon);
                                }
                            }
                        }
                    }
                }
                else
                {
                    if (Status == TGameOverStatus.goWon)
                    {
                        for (int I = 1, last = AoWEUnit.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
                        {
                            if (I != Player && AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FStatus == TPlayerStatus.psPlaying && AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FGameOverStatus != TGameOverStatus.goLost)
                            {
                                if (AoWEUnit.AoWHSMap.FPlayers.GetDiplomaticRelation(Player, (sbyte)I) == TDiplomaticRelation.drAlliance && AoWEUnit.AoWHSMap.FAlliedVictory)
                                {
                                    SetPlayerGameOverStatus((sbyte)I, TGameOverStatus.goWon);
                                }
                                else
                                {
                                    SetPlayerGameOverStatus((sbyte)I, TGameOverStatus.goLost);
                                }
                            }
                        }
                    }
                }

                AoWEUnit.AoWHSMap.UnlockGameOverEvent();
            }
        }

        // PlayerC.PAS:274
        public virtual void GameOverEventHandled(sbyte Player)
        {
            AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FStatus = TPlayerStatus.psTerminated;
        }

        // PlayerC.PAS:388
        public virtual void ExitGame(TExitGameMode Mode, TExitGameCallBack Done)
        {
            TMessageEventLog Log = default;
            if (AoWEUnit.AoWHSMap.FCombat == null)
            {
                if (AoWEUnit.AoWHSMap.FConnectionType == TPlayerConnectionType.pcNetwork && AoWEUnit.AoWHSMap.FGameStatus != TGameStatus.gsTerminated && AoWEUnit.AoWHSMap.FGameType != TGameType.gtTutorial && AoWEUnit.AoWHSMap.FPlayers.FLocalPlayers.Count > 1)
                {
                    if (AoWEUnit.AoWHSMap.FPlayMode == TPlayMode.pmSimultaneous || AoWEUnit.AoWHSMap.FCurrentPlayer == AoWEUnit.AoWHSMap.FSeatedPlayer)
                    {
                        FExitMode = Mode;
                        FExitCallBack = Done;
                        Log = new TMessageEventLog(null);
                        Log.FTitle = AoWEUnit.TranslateRStr(AoWEUnit.ConfirmRStr);
                        Log.FButtons = TMessageEventLogButtons.mebYesNoCancel;
                        Log.FLayout = TMessageEventLogLayout.melNormal;
                        var yourAboutToExitAMultiPlayerGame = AoWEUnit.TranslateRStr(AoWEUnit.YourAboutToExitAMultiPlayerGameRStr);
                        Log.FMessage.Add(yourAboutToExitAMultiPlayerGame);
                        var aoWETranslateRStr = AoWEUnit.TranslateRStr(AoWEUnit.DoYouWantToContinueExitingRStr);
                        Log.FMessage.Add(aoWETranslateRStr);
                        AoWEUnit.AoWHSMap.TriggerExecuteEventLog(Log, false, ExitNetworkGameCallBack);
                        Log.Release();
                    }
                    else
                    {
                        Log = new TMessageEventLog(null);
                        Log.FTitle = AoWEUnit.TranslateRStr(AoWEUnit.MessageRStr);
                        Log.FButtons = TMessageEventLogButtons.mebOk;
                        Log.FLayout = TMessageEventLogLayout.melNormal;
                        var pleaseWaitTillItIsYourTurn = AoWEUnit.TranslateRStr(AoWEUnit.PleaseWaitTillItIsYourTurnRStr);
                        Log.FMessage.Add(pleaseWaitTillItIsYourTurn);
                        AoWEUnit.AoWHSMap.TriggerExecuteEventLog(Log, false, null);
                        Log.Release();
                    }
                }
                else
                {
                    if (AoWEUnit.AoWHSMap.Status.Contains(THSMapStatusElement.msModified) && AoWEUnit.AoWHSMap.FGameStatus != TGameStatus.gsTerminated && AoWEUnit.AoWHSMap.FGameType != TGameType.gtTutorial)
                    {
                        if (!(FExitCallBack != null))
                        {
                            if (Mode != TExitGameMode.egmReload)
                            {
                                FExitMode = Mode;
                                FExitCallBack = Done;
                                Log = new TMessageEventLog(null);
                                Log.FTitle = AoWEUnit.TranslateRStr(AoWEUnit.ConfirmRStr);
                                Log.FButtons = TMessageEventLogButtons.mebYesNoCancel;
                                if (AoWEUnit.AoWEngine.FCampaign == null && !IsEmpty(AoWEUnit.AoWHSMap.FileName) && !Aow.Formats.DocumentKind.Map.HasExtension(ExtractFileExt(AoWEUnit.AoWHSMap.FileName)))
                                {
                                    Log.FLayout = TMessageEventLogLayout.melNormal;
                                    // The message names the file the save writes (own-formats.md 4.2).
                                    var fileName = ExtractFileName(FileBoundary.WriteName(AoWEUnit.AoWHSMap.FileName));
                                    var format = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.SaveGameToXRStr), [fileName]);
                                    Log.FMessage.Add(format);
                                }
                                else
                                {
                                    if (AoWEUnit.AoWEngine.FCampaign != null && !IsEmpty(AoWEUnit.AoWEngine.FCampaign.FFileName) && !Aow.Formats.DocumentKind.CampaignMap.HasExtension(ExtractFileExt(AoWEUnit.AoWHSMap.FileName)))
                                    {
                                        // { Original tests the map extension when saving a campaign. }
                                        Log.FLayout = TMessageEventLogLayout.melNormal;
                                        var fileName = ExtractFileName(FileBoundary.WriteName(AoWEUnit.AoWEngine.FCampaign.FFileName));
                                        var format = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.SaveGameToXRStr), [fileName]);
                                        Log.FMessage.Add(format);
                                    }
                                    else
                                    {
                                        Log.FLayout = TMessageEventLogLayout.melNormal;
                                        var doYouWantToSaveThisGame = AoWEUnit.TranslateRStr(AoWEUnit.DoYouWantToSaveThisGameRStr);
                                        Log.FMessage.Add(doYouWantToSaveThisGame);
                                    }
                                }

                                AoWEUnit.AoWHSMap.TriggerExecuteEventLog(Log, false, SaveGameOnExitCallBack);
                                Log.Release();
                            }
                            else
                            {
                                Done(Mode, true);
                            }
                        }
                        else
                        {
                            FExitCallBack(FExitMode, false);
                        }
                    }
                    else
                    {
                        AoWEUnit.AoWHSMap.ExecuteExitGame();
                    }
                }
            }
            else
            {
                if (Done != null)
                {
                    Done(Mode, false);
                }
            }
        }

        // PlayerC.PAS:153
        public virtual void EndTurn(sbyte Player)
        {
            TEMsg Msg = default;
            int X = default;
            int Y = default;
            int L = default;
            TPlayer P;
            AoWEUnit.AoWHSMap.LockRelationsChanged();
            if (Player == AoWEUnit.AoWHSMap.FSeatedPlayer)
            {
                P = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
                P.SetEndTurn(true);
                if (P != null)
                {
                    AoWEUnit.AoWHSMap.GetViewCenter(ref X, ref Y, ref L);
                    P.FViewX = (byte)X;
                    P.FViewY = (byte)Y;
                    P.FViewL = (byte)L;
                }
            }

            InitMsg(ref Msg, 537001991, this);
            Msg.Payload = Player;
            AoWEUnit.AoWHSMap.SendMsg(ref Msg, this);
            AoWEUnit.AoWHSMap.UnlockRelationsChanged();
            AoWEUnit.AoWHSMap.TriggerRelationsChanged();
        }

