        // PlayerC.PAS:518
        public virtual void ValidateDisconnectedPlayers()
        {
            int Player;
            int Count;
            TPlayerConnectionEventLog Log;
            for (int I = FDisconnectedPlayers.Count - 1; I >= 0; I--)
            {
                Player = FDisconnectedPlayers[I].A;
                if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FGameOverStatus == TGameOverStatus.goNone)
                {
                    if (AoWEUnit.AoWHSMap.FTokenManager.PlayerReady(AoWEUnit.AoWHSMap.FCurrentPlayer) && AoWEUnit.AoWHSMap.FTokenManager.TokenExecuter.ActiveTC.Count == 0)
                    {
                        Count = FDisconnectedPlayers[I].B;
                        if (Count > 0)
                        {
                            Count -= 1;
                            FDisconnectedPlayers.List[I].B = Count;
                        }

                        if (Count == 0)
                        {
                            Log = new TPlayerConnectionEventLog(null);
                            Log.Setup((sbyte)Player, 2);
                            AoWEUnit.AoWHSMap.TriggerExecuteEventLog(Log, false, null);
                            Log.Release();
                            FDisconnectedPlayers.Delete(I);
                        }
                    }
                }
                else
                {
                    FDisconnectedPlayers.Delete(I);
                }
            }
        }

