        // PlayerC.PAS:54
        public void OutOfSync(object Sender)
        {
            TPlayerConnectionEventLog Log;
            if (AoWEUnit.AoWHSMap.FTokenManager.TokenExecuter.ActiveTC.Active)
            {
                if (!FOutOfSyncShown)
                {
                    Log = new TPlayerConnectionEventLog(null);
                    Log.Setup(-1, 3);
                    AoWEUnit.AoWHSMap.TriggerExecuteEventLog(Log, AoWEUnit.AoWHSMap.FCombat != null, null);
                    Log.Release();
                    FOutOfSyncShown = true;
                }
                else
                {
                    AoWEUnit.AoWHSMap.FTokenManager.TokenExecuter.Lock();
                }
            }
        }

        // PlayerC.PAS:295
        public void ListPlayerInfo(TStrings Strings)
        {
            int Race;
            string Text;
            TPlayerCommunicationControl PCC;
            PCC = AoWEUnit.AoWHSMap.FPlayerCommunicator.PCC;
            for (int I = 0, last = AoWEUnit.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
            {
                Text = "Player " + IntToStr(I);
                Race = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FPlayerRace;
                if (Race != -1)
                {
                    var raceNamesPlural = AoWEUnit.TranslateRStr(AoWEUnit.RaceNamesPluralRStr[Race]);
                    Text = Text + "(" + raceNamesPlural + ")";
                }

                Text = Text + " at system " + IntToStr(PCC.Players[I].SystemID);
                if (Strings != null)
                {
                    Strings.Add(Text);
                }

                AoWEUnit.AoWEngine.OutputDebugStr(Text);
            }
        }

        // PlayerC.PAS:313
        public void ExitSaveGameCallBack(TEventLog Log)
        {
            if (!IsEmpty(((TSaveGameEventLog)Log).FFileName))
            {
                if (AoWEUnit.AoWEngine.FCampaign != null)
                {
                    AoWEUnit.AoWEngine.SaveCampaign(((TSaveGameEventLog)Log).FFileName);
                }
                else
                {
                    AoWEUnit.AoWEngine.SaveHSM(((TSaveGameEventLog)Log).FFileName, null, Aow.Formats.GameProfile.WorldMap);
                }

                AoWEUnit.AoWHSMap.ExecuteExitGame();
                if (FExitCallBack != null)
                {
                    FExitCallBack(FExitMode, true);
                }
            }
            else
            {
                if (FExitCallBack != null)
                {
                    FExitCallBack(FExitMode, false);
                }
            }

            FExitCallBack = null;
        }

        // PlayerC.PAS:326
        public void SaveGameOnExitCallBack(TEventLog Log)
        {
            TSaveGameEventLog SaveLog = default;
            if (((TMessageEventLog)Log).FPressedButton == TPressedEventLogButton.pebYes)
            {
                if (AoWEUnit.AoWEngine.FCampaign == null && (IsEmpty(AoWEUnit.AoWHSMap.FileName) || Aow.Formats.DocumentKind.Map.HasExtension(ExtractFileExt(AoWEUnit.AoWHSMap.FileName))) || AoWEUnit.AoWEngine.FCampaign != null && (IsEmpty(AoWEUnit.AoWEngine.FCampaign.FFileName) || Aow.Formats.DocumentKind.CampaignMap.HasExtension(ExtractFileExt(AoWEUnit.AoWHSMap.FileName))))
                {
                    SaveLog = new TSaveGameEventLog(null);
                    if (!IsEmpty(AoWEUnit.AoWHSMap.FileName))
                    {
                        SaveLog.FDefaultName = ExtractFileName(AoWEUnit.AoWHSMap.FileName);
                        if (Pos(".", SaveLog.FDefaultName) != 0)
                        {
                            SaveLog.FDefaultName = RtlUnit.Copy(SaveLog.FDefaultName, 1, Pos(".", SaveLog.FDefaultName) - 1);
                        }
                    }
                    else
                    {
                        SaveLog.FDefaultName = AoWEUnit.AoWHSMap.FMapName;
                    }

                    SaveLog.FDirectory = AoWEUnit.AoWEngine.StartupDirectory + "Save\\";
                    AoWEUnit.AoWHSMap.TriggerExecuteEventLog(SaveLog, false, ExitSaveGameCallBack);
                    SaveLog.Release();
                }
                else
                {
                    var aoWEngine = AoWEUnit.AoWEngine;
                    // The save writes the own sibling of an original's name, which stays untouched
                    // (own-formats.md 4.2).
                    if (aoWEngine.FCampaign != null)
                    {
                        aoWEngine.SaveCampaign(FileBoundary.WriteName(aoWEngine.FCampaign.FFileName));
                    }
                    else
                    {
                        aoWEngine.SaveHSM(FileBoundary.WriteName(AoWEUnit.AoWHSMap.FileName), null, Aow.Formats.GameProfile.WorldMap);
                    }

                    AoWEUnit.AoWHSMap.ExecuteExitGame();
                    if (FExitCallBack != null)
                    {
                        FExitCallBack(FExitMode, true);
                    }

                    FExitCallBack = null;
                }
            }
            else
            {
                if (((TMessageEventLog)Log).FPressedButton == TPressedEventLogButton.pebNo)
                {
                    AoWEUnit.AoWHSMap.ExecuteExitGame();
                    if (FExitCallBack != null)
                    {
                        FExitCallBack(FExitMode, true);
                    }

                    FExitCallBack = null;
                }
                else
                {
                    if (((TMessageEventLog)Log).FPressedButton == TPressedEventLogButton.pebCancel)
                    {
                        if (FExitCallBack != null)
                        {
                            FExitCallBack(FExitMode, false);
                        }

                        FExitCallBack = null;
                    }
                }
            }
        }

        // PlayerC.PAS:372
        public void ExitNetworkGameCallBack(TEventLog Log)
        {
            TTerminatePlayerTE TE;
            if (((TMessageEventLog)Log).FPressedButton == TPressedEventLogButton.pebYes)
            {
                if (AoWEUnit.AoWHSMap.FPlayMode == TPlayMode.pmSimultaneous || AoWEUnit.AoWHSMap.FCurrentPlayer == AoWEUnit.AoWHSMap.FSeatedPlayer)
