namespace Aow.Game.Engine
{

    // inherits the children list
    public partial class TTextControl : TENode
    {
        public TTextControl(TECustomNode owner) : base(owner)
        { }

        // Structur.PAS:4419
        public TTextControlItem GetItem(int Index)
        {
            TTextControlItem Result;
            if (Index >= 0 && Index < FChildren.Count)
            {
                Result = (TTextControlItem)FChildren.List[Index];
            }
            else
            {
                Result = null;
            }

            return Result;
        }

        // Structur.PAS:4426
        public void Delete(int Index)
        {
            if (GetItem(Index) != null)
            {
                GetItem(Index)?.Dispose();
            }
        }

        // Structur.PAS:4431
        public TTextControlItem New() => new TTextControlItem(this);

        // Structur.PAS:4436
        public TTextControlItem FindID(int ID)
        {
            int I;
            I = Count;
            TTextControlItem Result = null;
            while (Result == null && I != 0)
            {
                I -= 1;
                if (((TTextControlItem)FChildren.List[I]).FID == ID)
                {
                    Result = (TTextControlItem)FChildren.List[I];
                }
            }

            return Result;
        }

        // Structur.PAS:4458
        public void Sort()
        {
            FChildren.SortStable(AoWEUnit.CompareTextControlItems);
        }

        // Structur.PAS:4463
        public int IndexOf(TTextControlItem Item) => FindChildIndex(Item);

        // Structur.PAS:4468
        public void RetrieveText(int ID, TStrings Text)
        {
            TTextControlItem Item;
            Text.Clear();
            Item = FindID(ID);
            if (Item != null)
            {
                Text.Text = Item.FText.Text;
            }
        }

        // Engine.pas:631

    }
}

