namespace Aow.Game.Session
{

    public partial class TTurnPlayerControl : TPlayerControl
    {
        public new const int ClassID = 131664;

        public TTurnPlayerControl(TECustomNode owner) : base(owner)
        { }

        // PlayerC.PAS:589
        public override void NewTurn(sbyte Player)
        {
            TNewTurnEventLog Log = default;
            TShowBookEventLog BookLog = default;
            TSpellList Spells = default;
            TPlayerMagicEventLog MagicLog = default;
            AoWEUnit.AoWHSMap.LockMapChangedEvent();
            AoWEUnit.AoWHSMap.FTokenManager.TokenExecuter.ActivateTC(Player);
            if (AoWEUnit.AoWHSMap.FRequestCombatType)
            {
                if (AoWEUnit.AoWHSMap.FSeatedPlayer != -1)
                {
                    AoWEUnit.AoWHSMap.SetSeatedPlayer(-1);
                }

                if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType == TPlayerType.ptHuman)
                {
                    Log = new TNewTurnEventLog(null);
                    Log.FTurnPlayer = AoWEUnit.AoWHSMap.FCurrentPlayer;
                    Log.FMode = TNewTurnEventLogMode.ntDialog;
                    Log.FDialogStyle = TSet<TNewTurnEventLogDialogStyleElement>.Of(TNewTurnEventLogDialogStyleElement.nsCloseable);
                    Log.FText = AoWEUnit.TranslateRStr(AoWEUnit.ItsYourTurnRStr);
                    AoWEUnit.AoWHSMap.TriggerExecuteEventLog(Log, false, ShowNewTurnCallBack);
                    Log.Release();
                }
                else
                {
                    Log = new TNewTurnEventLog(null);
                    Log.FTurnPlayer = AoWEUnit.AoWHSMap.FCurrentPlayer;
                    Log.FMode = TNewTurnEventLogMode.ntDialog;
                    Log.FDialogStyle = TSet<TNewTurnEventLogDialogStyleElement>.Of();
                    if (Player == 0)
                    {
                        Log.FText = AoWEUnit.TranslateRStr(AoWEUnit.IndependentsAreMovingRStr);
                    }
                    else
                    {
                        var name = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).GetName();
                        Log.FText = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.PlayerIsMovingRStr), [name]);
                    }

                    AoWEUnit.AoWHSMap.TriggerExecuteEventLog(Log, true, null);
                    Log.Release();
                }
            }
            else
            {
                if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType == TPlayerType.ptHuman && Player == AoWEUnit.AoWHSMap.FSeatedPlayer)
                {
                    if (AoWEUnit.AoWHSMap.FGameType != TGameType.gtTutorial || AoWEUnit.AoWHSMap.FDay != 1)
                    {
                        AoWEUnit.AoWHSMap.ResetTurnTimer();
                        AoWEUnit.AoWHSMap.EnableTurnTimer();
                        AoWEUnit.AoWHSMap.ResetSeatedPlayerView();
                        Log = new TNewTurnEventLog(null);
                        Log.FTurnPlayer = Player;
                        Log.FMode = TNewTurnEventLogMode.ntDialog;
                        Log.FDialogStyle = TSet<TNewTurnEventLogDialogStyleElement>.Of(TNewTurnEventLogDialogStyleElement.nsCloseable);
                        Log.FText = AoWEUnit.TranslateRStr(AoWEUnit.ItsYourTurnRStr);
                        AoWEUnit.AoWHSMap.TriggerExecuteEventLog(Log, false, null);
                        Log.Release();
                        ReplayLogbook();
                    }
                    else
                    {
                        AoWEUnit.AoWHSMap.FTutorialControl.ShowMessage(50, false, true);
                    }
                }
            }

            base.NewTurn(Player);
            if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType == TPlayerType.ptHuman && AoWEUnit.AoWHSMap.FConnectionType != TPlayerConnectionType.pcEmail && AoWEUnit.AoWEngine.FRegistry.GetAutoSave())
            {
                AutoSave();
            }

            AoWEUnit.AoWHSMap.UnlockMapChangedEvent();
            AoWEUnit.AoWHSMap.InvalidateMap();
            if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType != TPlayerType.ptHuman)
            {
                AoWEUnit.AoWHSMap.FAIExecuter.ActivatePlayer(Player);
                if (Player == 0)
                {
                    var independents = AoWEUnit.TranslateRStr(AoWEUnit.IndependentsRStr);
                    var format = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.AreMovingRStr), [independents]);
                    AoWEUnit.AoWHSMap.ShowMessage(format);
                }
                else
                {
                    var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
                    var raceNamesPlural = AoWEUnit.TranslateRStr(AoWEUnit.RaceNamesPluralRStr[players.FPlayerRace]);
                    var format = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.AreMovingRStr), [raceNamesPlural]);
                    AoWEUnit.AoWHSMap.ShowMessage(format);
                }
            }
            else
            {
                PlaySample("SFX\\EVENTS\\NEWTURN.WAV");
                if (AoWEUnit.AoWHSMap.FDay == 1 && (AoWEUnit.AoWHSMap.FRequestCombatType || Player == AoWEUnit.AoWHSMap.FSeatedPlayer))
                {
                    if (TSet<TGameType>.Of(TGameType.gtCustom, TGameType.gtTutorial).Contains(AoWEUnit.AoWHSMap.FGameType))
                    {
                        BookLog = new TShowBookEventLog(null);
                        AoWEUnit.AoWHSMap.TriggerExecuteEventLog(BookLog, false, null);
                        BookLog.Release();
                    }

                    if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FMagicControl.FResearchSpellID == 0)
                    {
                        Spells = new TSpellList();
                        AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FMagicControl.ListResearchSpells(ref Spells, TSet<TSpellType>.Of(TSpellType.stCombat, TSpellType.stUnit, TSpellType.stGlobal));
                        if (Spells.GetCount() > 0)
                        {
                            MagicLog = new TPlayerMagicEventLog(null);
                            MagicLog.FMode = TPlayerMagicEventMode.pmemStartResearch;
                            AoWEUnit.AoWHSMap.TriggerExecuteEventLog(MagicLog, false, null);
                            MagicLog.Release();
                        }

                        Spells?.Dispose();
                    }

                    AoWEUnit.AoWHSMap.FTutorialControl.ShowMessage(52, false, true);
                }
            }
        }

        // PlayerC.PAS:875
        public override void ValidateTurnTiming()
        {
            if (AoWEUnit.AoWHSMap.GetTurnTimerEnabled())
            {
                if (AoWEUnit.AoWHSMap.FCurrentPlayer == AoWEUnit.AoWHSMap.FSeatedPlayer)
                {
                    if (AoWEUnit.AoWHSMap.GetTurnTimeLeft() <= 0)
                    {
                        if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AoWEUnit.AoWHSMap.FSeatedPlayer).FGameOverStatus == TGameOverStatus.goNone && !AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AoWEUnit.AoWHSMap.FSeatedPlayer).FSingleProcessCycle)
                        {
                            if (AoWEUnit.AoWHSMap.FTokenManager.PlayerReady(AoWEUnit.AoWHSMap.FSeatedPlayer))
                            {
                                AoWEUnit.EndPlayerTurn(AoWEUnit.AoWHSMap.FSeatedPlayer);
                            }
                        }
                    }
                }
            }
        }

