        // PlayerC.PAS:854
        public override void SetPlayerGameOverStatus(sbyte Player, TGameOverStatus Status)
        {
            base.SetPlayerGameOverStatus(Player, Status);
            if (!AoWEUnit.AoWHSMap.FRequestCombatType || AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType != TPlayerType.ptHuman)
            {
                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FStatus = TPlayerStatus.psTerminated;
                AoWEUnit.AoWHSMap.FPlayers.Update();
                AoWEUnit.AoWHSMap.TriggerPlayerTerminatedEvent(Player);
                if (AoWEUnit.AoWHSMap.FCurrentPlayer == Player && AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).GetLocal())
                {
                    AoWEUnit.EndPlayerTurn(AoWEUnit.AoWHSMap.FCurrentPlayer);
                }

                if (AoWEUnit.AoWHSMap.FPlayers.FLocalHumanPlayers.Count == 0)
                {
                    AoWEUnit.AoWHSMap.TriggerGameTerminatedEvent();
                }
            }
        }

        // PlayerC.PAS:868
        public override void GameOver(sbyte Player, TGameOverStatus Status)
        {
            AoWEUnit.AoWHSMap.LockGameOverEvent();
            base.GameOver(Player, Status);
            AoWEUnit.AoWHSMap.UnlockGameOverEvent();
        }

        // PlayerC.PAS:842
        public override void GameOverEventHandled(sbyte Player)
        {
            if (AoWEUnit.AoWHSMap.FRequestCombatType)
            {
                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FStatus = TPlayerStatus.psTerminated;
                AoWEUnit.AoWHSMap.FPlayers.Update();
                AoWEUnit.AoWHSMap.TriggerPlayerTerminatedEvent(Player);
                if (AoWEUnit.AoWHSMap.FPlayers.FLocalHumanPlayers.Count == 0)
                {
                    AoWEUnit.AoWHSMap.TriggerGameTerminatedEvent();
                }
                else
                {
                    AoWEUnit.EndPlayerTurn(AoWEUnit.AoWHSMap.FCurrentPlayer);
                }
            }
        }

        // PlayerC.PAS:715
        public override void EndTurn(sbyte Player)
        {
            TEndTurnEventLog Log;
            int Index;
            bool Found;
            sbyte NextPlayer;
            base.EndTurn(Player);
            if (Player == AoWEUnit.AoWHSMap.FSeatedPlayer)
            {
                AoWEUnit.AoWHSMap.ZeroTurnTimer();
                if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FStatus == TPlayerStatus.psPlaying)
                {
                    AoWEUnit.AoWHSMap.ClearExecuteEventLogBuffer();
                }

                AoWEUnit.AoWHSMap.Selection.UnselectLocation();
            }

            if (Player == AoWEUnit.AoWHSMap.FCurrentPlayer)
            {
                if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType != TPlayerType.ptHuman)
                {
                    AoWEUnit.AoWHSMap.FAIExecuter.DeactivatePlayer(Player);
                }

                Log = new TEndTurnEventLog(null);
                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AoWEUnit.AoWHSMap.FCurrentPlayer).FEventLogbook.AddEvent(Log);
                Log.Release();
                Index = AoWEUnit.AoWHSMap.FTurnOrder.IndexOf((byte)AoWEUnit.AoWHSMap.FCurrentPlayer);
                Found = false;
                while (!Found)
                {
                    Index += 1;
                    if (Index == AoWEUnit.AoWHSMap.FTurnOrder.Count)
                    {
                        NewDay();
                        Index = 0;
                    }

                    NextPlayer = (sbyte)AoWEUnit.AoWHSMap.FTurnOrder[Index];
                    Found = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(NextPlayer).FStatus == TPlayerStatus.psPlaying;
                    if (!Found)
                    {
                        base.NewTurn(NextPlayer);
                        base.EndTurn(NextPlayer);
                    }
                }

                if (AoWEUnit.AoWHSMap.FTurnOrder.Count != 0)
                {
                    NewTurn((sbyte)AoWEUnit.AoWHSMap.FTurnOrder[Index]);
                }
                else
                {
                    NewTurn(0);
                }
            }
        }

        // PlayerC.PAS:693
        public override void SetSeatedPlayer(sbyte Player)
        {
            AoWEUnit.AoWHSMap.LockMapChangedEvent();
            base.SetSeatedPlayer(Player);
            AoWEUnit.AoWHSMap.UnlockMapChangedEvent();
            AoWEUnit.AoWHSMap.InvalidateMap();
        }

        // PlayerC.PAS:779
        public virtual void StartLoadedMapEx()
        {
            TNewTurnEventLog Log = default;
            DefaultStartMap();
            AoWEUnit.AoWHSMap.FTokenManager.TokenExecuter.ActivateTC(AoWEUnit.AoWHSMap.FCurrentPlayer);
            if (AoWEUnit.AoWHSMap.FRequestCombatType)
            {
                AoWEUnit.AoWHSMap.SetSeatedPlayer(-1);
                if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AoWEUnit.AoWHSMap.FCurrentPlayer).FPlayerType == TPlayerType.ptHuman)
                {
                    Log = new TNewTurnEventLog(null);
                    Log.FTurnPlayer = AoWEUnit.AoWHSMap.FCurrentPlayer;
                    Log.FMode = TNewTurnEventLogMode.ntDialog;
                    Log.FDialogStyle = TSet<TNewTurnEventLogDialogStyleElement>.Of(TNewTurnEventLogDialogStyleElement.nsCloseable);
                    Log.FText = AoWEUnit.TranslateRStr(AoWEUnit.YourTurnContinuesRStr);
                    AoWEUnit.AoWHSMap.TriggerExecuteEventLog(Log, false, StartGameCallBack);
                    Log.Release();
                }
                else
                {
                    Log = new TNewTurnEventLog(null);
                    Log.FTurnPlayer = AoWEUnit.AoWHSMap.FCurrentPlayer;
                    Log.FMode = TNewTurnEventLogMode.ntDialog;
                    Log.FDialogStyle = TSet<TNewTurnEventLogDialogStyleElement>.Of();
                    if (AoWEUnit.AoWHSMap.FCurrentPlayer == 0)
                    {
                        Log.FText = AoWEUnit.TranslateRStr(AoWEUnit.IndependentsAreMovingRStr);
                    }
                    else
                    {
                        var name = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AoWEUnit.AoWHSMap.FCurrentPlayer).GetName();
                        Log.FText = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.PlayerIsMovingRStr), [name]);
                    }

                    AoWEUnit.AoWHSMap.TriggerExecuteEventLog(Log, true, null);
                    Log.Release();
                }
            }
            else
            {
                var item = AoWEUnit.AoWHSMap.FPlayers.FLocalHumanPlayers[0];
                AoWEUnit.AoWHSMap.SetSeatedPlayer((sbyte)item);
                AoWEUnit.AoWHSMap.ResetSeatedPlayerView();
                if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AoWEUnit.AoWHSMap.FCurrentPlayer).FPlayerType == TPlayerType.ptHuman && AoWEUnit.AoWHSMap.FCurrentPlayer == AoWEUnit.AoWHSMap.FSeatedPlayer)
                {
                    Log = new TNewTurnEventLog(null);
                    Log.FTurnPlayer = AoWEUnit.AoWHSMap.FSeatedPlayer;
                    Log.FMode = TNewTurnEventLogMode.ntDialog;
                    Log.FDialogStyle = TSet<TNewTurnEventLogDialogStyleElement>.Of(TNewTurnEventLogDialogStyleElement.nsCloseable);
                    Log.FText = AoWEUnit.TranslateRStr(AoWEUnit.YourTurnContinuesRStr);
                    AoWEUnit.AoWHSMap.TriggerExecuteEventLog(Log, false, StartGameCallBack);
                    Log.Release();
                }
            }

            if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AoWEUnit.AoWHSMap.FCurrentPlayer).FPlayerType != TPlayerType.ptHuman)
            {
                AoWEUnit.AoWHSMap.FAIExecuter.ActivatePlayer(AoWEUnit.AoWHSMap.FCurrentPlayer);
            }

            AoWEUnit.AoWEngine.OutputDebugStr("Random Seed: " + IntToStr(AoWEUnit.AoWHSMap.FDefendersSeed));
        }

        // PlayerC.PAS:683
        public void ReplayLogbook()
        {
            TEventLogbook Book;
            int Index;
            Book = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AoWEUnit.AoWHSMap.FCurrentPlayer).FEventLogbook;
            Index = Book.FindFirstLogEx(131811, AoWEUnit.AoWHSMap.FCurrentPlayer, AoWEUnit.AoWHSMap.FDay - 1);
            for (int I = Index + 1, last = Book.GetCount() - 1; I <= last; I++)
            {
                Book.GetLogs(I).Execute(false, TExecuteTrigger.etNewTurn, null);
            }
        }

        // PlayerC.PAS:701
        public void ShowNewTurnCallBack(TEventLog Log)
        {
            SetSeatedPlayer(AoWEUnit.AoWHSMap.FCurrentPlayer);
            AoWEUnit.AoWHSMap.ResetTurnTimer();
            AoWEUnit.AoWHSMap.EnableTurnTimer();
            if (AoWEUnit.AoWHSMap.FCurrentPlayer != -1)
            {
                ReplayLogbook();
            }
        }

        // PlayerC.PAS:709
        public void StartGameCallBack(TEventLog Log)
        {
            if (AoWEUnit.AoWHSMap.FSeatedPlayer == -1)
            {
                SetSeatedPlayer(AoWEUnit.AoWHSMap.FCurrentPlayer);
            }

            AoWEUnit.AoWHSMap.EnableTurnTimer();
        }

        // PlayerC.PAS:758
        public void DefaultStartMap()
        {
            AoWEUnit.AoWHSMap.FPlayers.Update();
            AoWEUnit.AoWHSMap.FRequestCombatType = AoWEUnit.AoWHSMap.FConnectionType == TPlayerConnectionType.pcEmail || (AoWEUnit.AoWHSMap.FConnectionType == TPlayerConnectionType.pcLocal && AoWEUnit.AoWHSMap.FPlayers.FLocalHumanPlayers.Count > 1);
            AoWEUnit.AoWHSMap.FShowIndependentMoves = !AoWEUnit.AoWHSMap.FRequestCombatType;
        }

