namespace Aow.Game.Session
{

    // local player
    public partial class TPBEMPlayerControl : TTurnPlayerControl
    {
        public new const int ClassID = 131667;

        public TPBEMPlayerControl(TECustomNode owner) : base(owner)
        { }

        public sbyte FLocalPlayer;

        // PlayerC.PAS:984
        public override void NewTurn(sbyte Player)
        {
            TSendEmailGameEventLog Log = default;
            if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPBEMSettings.FStatus.Contains(TPBEMPlayerStatusElement.pbsNewTurn) || AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType != TPlayerType.ptHuman || AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FStatus == TPlayerStatus.psTerminated)
            {
                base.NewTurn(Player);
                var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPBEMSettings.FStatus = players.FPBEMSettings.FStatus - TSet<TPBEMPlayerStatusElement>.Of(TPBEMPlayerStatusElement.pbsNewTurn, TPBEMPlayerStatusElement.pbsTurnDone) + TSet<TPBEMPlayerStatusElement>.Of(TPBEMPlayerStatusElement.pbsPlaying);
            }
            else
            {
                if (AoWEUnit.AoWHSMap.FPlayers.FLocalPlayers.Count > 1 || Player != FLocalPlayer)
                {
                    AoWEUnit.AoWHSMap.SetCurrentPlayer(Player);
                    var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPBEMSettings.FStatus = players.FPBEMSettings.FStatus + TSet<TPBEMPlayerStatusElement>.Of(TPBEMPlayerStatusElement.pbsNewTurn);
                    Log = new TSendEmailGameEventLog(null);
                    Log.FMode = 2;
                    Log.FSendPlayer = Player;
                    AoWEUnit.AoWHSMap.TriggerExecuteEventLog(Log, false, SendEmailGameCallBack);
                    Log.Release();
                }
                else
                {
                    base.NewTurn(Player);
                    var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPBEMSettings.FStatus = players.FPBEMSettings.FStatus - TSet<TPBEMPlayerStatusElement>.Of(TPBEMPlayerStatusElement.pbsNewTurn, TPBEMPlayerStatusElement.pbsTurnDone) + TSet<TPBEMPlayerStatusElement>.Of(TPBEMPlayerStatusElement.pbsPlaying);
                }
            }
        }

        // PlayerC.PAS:1194
        public override void StartNewMap()
        {
            int I;
            int Player;
            DefaultStartMap();
            NewDay();
            I = 0;
            int last = AoWEUnit.AoWHSMap.FPlayers.Count - 1;
            for (; I <= last; I += 1)
            {
                if (I == 0 || AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType != TPlayerType.ptIndependent)
                {
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FStatus = TPlayerStatus.psPlaying;
                }
            }

            I = 0;
            while (true)
            {
                bool condition = I < AoWEUnit.AoWHSMap.FTurnOrder.Count;
                if (condition)
                {
                    var item = AoWEUnit.AoWHSMap.FTurnOrder[I];
                    condition = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(item).FPlayerType != TPlayerType.ptHuman;
                }

                if (!condition)
                    break;
                I += 1;
            }

            Player = AoWEUnit.AoWHSMap.FTurnOrder[I];
            var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
            bool test = AoWEUnit.AoWEngine.FEmailGames.FindEmailGame(players.FPBEMSettings.FEmailGame) != null;
            if (test)
            {
                var localEmailAddress = AoWEUnit.AoWEngine.FRegistry.GetLocalEmailAddress();
                test = CompareText(AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPBEMSettings.FEmailGame.FEmailAddress, localEmailAddress) == 0;
            }

            if (test)
            {
                FLocalPlayer = (sbyte)Player;
                var fPlayersPlayers = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPBEMSettings.FStatus = fPlayersPlayers.FPBEMSettings.FStatus + TSet<TPBEMPlayerStatusElement>.Of(TPBEMPlayerStatusElement.pbsNewTurn);
            }
            else
            {
                AoWEUnit.AoWHSMap.SetSeatedPlayer(-1);
            }

            NewTurn((sbyte)AoWEUnit.AoWHSMap.FTurnOrder[1]);
        }

        // PlayerC.PAS:1187
        public override void StartLoadedMap()
        {
            if (!IsEmpty(AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AoWEUnit.AoWHSMap.FCurrentPlayer).FSettings))
            {
                ValidatePassword(AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AoWEUnit.AoWHSMap.FCurrentPlayer).FSettings);
            }
            else
            {
                ValidateLoadedMap();
            }
        }

        // PlayerC.PAS:1184
        public override void PasswordValidated()
        {
            ValidateLoadedMap();
        }

        // PlayerC.PAS:1230
        public override void ExitGame(TExitGameMode Mode, TExitGameCallBack Done)
        {
            TSaveGameEventLog Log = default;
            if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AoWEUnit.AoWHSMap.FCurrentPlayer).FPBEMSettings.FStatus.Contains(TPBEMPlayerStatusElement.pbsPlaying))
            {
                if (Aow.Formats.DocumentKind.Map.HasExtension(ExtractFileExt(AoWEUnit.AoWHSMap.FileName)))
                {
                    Log = new TSaveGameEventLog(null);
                    Log.FTitle = AoWEUnit.TranslateRStr(AoWEUnit.SaveEmailGameRStr);
                    if (!IsEmpty(AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AoWEUnit.AoWHSMap.FCurrentPlayer).FPBEMSettings.FEmailGame.FName))
                    {
                        Log.FDefaultName = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AoWEUnit.AoWHSMap.FCurrentPlayer).FPBEMSettings.FEmailGame.FName + ".asg";
                    }

                    Log.FDirectory = AoWEUnit.AoWEngine.StartupDirectory + "EmailIn\\";
                    AoWEUnit.AoWHSMap.TriggerExecuteEventLog(Log, false, ExitGameSaveAsCallBack);
                    Log.Release();
                }
                else
                {
                    // A game file outside EmailIn takes the name the host writes (own-formats.md 4.2).
                    AoWEUnit.AoWHSMap.FileName = FileBoundary.WriteName(AoWEUnit.AoWHSMap.FileName);
                    AoWEUnit.AoWEngine.SaveHSM(AoWEUnit.AoWHSMap.FileName, null, Aow.Formats.GameProfile.WorldMap);
                    AoWEUnit.AoWHSMap.ExecuteExitGame();
                }
            }
            else
            {
                AoWEUnit.AoWHSMap.ExecuteExitGame();
            }
        }

        // PlayerC.PAS:1053
        public override void EndTurn(sbyte Player)
        {
            TSaveGameEventLog SaveLog = default;
            TMessageEventLog MessageLog = default;
            bool Saved = default;
            if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType == TPlayerType.ptHuman && AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FStatus == TPlayerStatus.psPlaying)
            {
                if (Aow.Formats.DocumentKind.Map.HasExtension(ExtractFileExt(AoWEUnit.AoWHSMap.FileName)))
                {
                    SaveLog = new TSaveGameEventLog(null);
                    SaveLog.FTitle = AoWEUnit.TranslateRStr(AoWEUnit.SaveEmailGameRStr);
                    if (!IsEmpty(AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPBEMSettings.FEmailGame.FName))
                    {
                        SaveLog.FDefaultName = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPBEMSettings.FEmailGame.FName + ".asg";
                    }

                    SaveLog.FDirectory = AoWEUnit.AoWEngine.StartupDirectory + "EmailIn\\";
                    AoWEUnit.AoWHSMap.TriggerExecuteEventLog(SaveLog, false, EndTurnGameSavedCallBack);
                    SaveLog.Release();
                }
                else
                {
                    var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPBEMSettings.FStatus = players.FPBEMSettings.FStatus + TSet<TPBEMPlayerStatusElement>.Of(TPBEMPlayerStatusElement.pbsTurnDone) - TSet<TPBEMPlayerStatusElement>.Of(TPBEMPlayerStatusElement.pbsPlaying);
                    // A game file outside EmailIn takes the name the host writes (own-formats.md 4.2).
                    AoWEUnit.AoWHSMap.FileName = FileBoundary.WriteName(AoWEUnit.AoWHSMap.FileName);
                    try
                    {
                        AoWEUnit.AoWEngine.SaveHSM(AoWEUnit.AoWHSMap.FileName, null, Aow.Formats.GameProfile.WorldMap);
                        Saved = true;
                    }
                    catch
                    {
                        Saved = false;
                    }

                    if (Saved)
                    {
                        base.EndTurn(AoWEUnit.AoWHSMap.FCurrentPlayer);
                    }
                    else
                    {
                        MessageLog = new TMessageEventLog(null);
                        var format = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.CouldNotSaveXRStr) + ".", [AoWEUnit.AoWHSMap.FileName]);
                        MessageLog.FMessage.Text = format;
                        AoWEUnit.AoWHSMap.TriggerExecuteEventLog(MessageLog, false, TerminateEmailGameCallBack);
                        MessageLog.Release();
                    }
                }
            }
            else
            {
                // { Original uses current player, ignoring Player here. }
                base.EndTurn(AoWEUnit.AoWHSMap.FCurrentPlayer);
            }
        }

