        // PlayerC.PAS:893
        public void SendEmailGameAutomatedCallBack(TEventLog Log)
        {
            TSendEmailGameEventLog SendLog = default;
            DeleteFile(((TSMTPEventLog)Log).FFileName);
            if (!((TSMTPEventLog)Log).FSuccess)
            {
                SendLog = new TSendEmailGameEventLog(null);
                SendLog.FMode = 1;
                SendLog.FSendPlayer = AoWEUnit.AoWHSMap.FCurrentPlayer;
                AoWEUnit.AoWHSMap.TriggerExecuteEventLog(SendLog, false, SendEmailGameCallBack);
