            }
        }

        // PlayerC.PAS:909
        public void SendEmailGameManualCallBack(TEventLog Log)
        {
            bool Failed = default;
            TMessageEventLog MessageLog = default;
            if (!IsEmpty(((TSaveGameEventLog)Log).FFileName))
            {
                try
                {
                    AoWEUnit.AoWEngine.SaveHSM(((TSaveGameEventLog)Log).FFileName, null, Aow.Formats.GameProfile.WorldMap);
                    var format = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.GameSavedRStr), [((TSaveGameEventLog)Log).FFileName]);
                    AoWEUnit.AoWHSMap.ShowMessage(format);
                    Failed = false;
                }
                catch
                {
                    Failed = true;
                }
            }
            else
            {
                Failed = true;
            }

            if (Failed)
            {
                MessageLog = new TMessageEventLog(null);
                var format = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.CouldNotSaveXRStr) + ".", [((TSaveGameEventLog)Log).FFileName]);
                MessageLog.FMessage.Text = format;
                AoWEUnit.AoWHSMap.TriggerExecuteEventLog(MessageLog, false, TerminateEmailGameCallBack);
                MessageLog.Release();
            }
            else
            {
                MessageLog = new TMessageEventLog(null);
                var format = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.GameSuccessfullySavedRStr) + ".", [((TSaveGameEventLog)Log).FFileName]);
                MessageLog.FMessage.Text = format;
                AoWEUnit.AoWHSMap.TriggerExecuteEventLog(MessageLog, false, TerminateEmailGameCallBack);
                MessageLog.Release();
            }
        }

