            if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AoWEUnit.AoWHSMap.FCurrentPlayer).FPBEMSettings.FStatus.Contains(TPBEMPlayerStatusElement.pbsNewTurn))
            {
                AoWEUnit.AoWHSMap.SynchroniseBegin();
