        // PlayerC.PAS:1136
        public void ValidateLoadedMap()
        {
            bool Restarted = default;
            TMessageEventLog Log = default;
            FLocalPlayer = AoWEUnit.AoWHSMap.FCurrentPlayer;
            var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AoWEUnit.AoWHSMap.FCurrentPlayer);
            if (AoWEUnit.AoWEngine.FEmailGames.FindEmailGame(players.FPBEMSettings.FEmailGame) == null)
            {
                var fPlayersPlayers = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AoWEUnit.AoWHSMap.FCurrentPlayer);
                Restarted = AoWEUnit.AoWEngine.FEmailGames.EmailGameRestarted(fPlayersPlayers.FPBEMSettings.FEmailGame);
                var players2 = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AoWEUnit.AoWHSMap.FCurrentPlayer);
                var players3 = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AoWEUnit.AoWHSMap.FCurrentPlayer);
                var emailGame = AoWEUnit.AoWEngine.FEmailGames.CreateEmailGame(players3.FPBEMSettings.FEmailGame.FName, players2.FPBEMSettings.FEmailGame.FEmailAddress);
                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AoWEUnit.AoWHSMap.FCurrentPlayer).FPBEMSettings.SetGame(emailGame);
                if (Restarted)
                {
                    TriggerGameRestartedEvents(AoWEUnit.AoWHSMap.FCurrentPlayer);
                }

                StartLoadedEmailGame();
            }
            else
            {
                var fPlayersPlayers = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AoWEUnit.AoWHSMap.FCurrentPlayer);
                if (AoWEUnit.AoWEngine.FEmailGames.EmailGameRestarted(fPlayersPlayers.FPBEMSettings.FEmailGame))
                {
                    SetSeatedPlayer(-1);
                    Log = new TMessageEventLog(null);
                    Log.FButtons = TMessageEventLogButtons.mebYesNo;
                    Log.FTitle = AoWEUnit.TranslateRStr(AoWEUnit.WarningRStr);
                    var pbemRestartCheat = AoWEUnit.TranslateRStr(AoWEUnit.PBEMRestartCheatRStr);
                    Log.FMessage.Text = pbemRestartCheat;
                    Log.FMessage.Add("");
                    var aoWETranslateRStr = AoWEUnit.TranslateRStr(AoWEUnit.DoYouWantToContinueRStr);
                    Log.FMessage.Add(aoWETranslateRStr);
                    AoWEUnit.AoWHSMap.TriggerExecuteEventLog(Log, false, ContinueRestartedGameCallBack);
                    Log.Release();
                }
                else
                {
                    SetSeatedPlayer(-1);
                    if ((AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AoWEUnit.AoWHSMap.FCurrentPlayer).FPBEMSettings.FStatus & TSet<TPBEMPlayerStatusElement>.Of(TPBEMPlayerStatusElement.pbsNewTurn, TPBEMPlayerStatusElement.pbsTurnDone)) == TSet<TPBEMPlayerStatusElement>.Of(TPBEMPlayerStatusElement.pbsTurnDone))
                    {
                        Log = new TMessageEventLog(null);
                        Log.FTitle = AoWEUnit.TranslateRStr(AoWEUnit.WarningRStr);
                        Log.FButtons = TMessageEventLogButtons.mebYesNo;
                        var pbemGameEnded = AoWEUnit.TranslateRStr(AoWEUnit.PBEMGameEndedRStr);
                        Log.FMessage.Text = pbemGameEnded;
                        Log.FMessage.Add("");
                        var aoWETranslateRStr = AoWEUnit.TranslateRStr(AoWEUnit.DoYouWantToContinueRStr);
                        Log.FMessage.Add(aoWETranslateRStr);
                        AoWEUnit.AoWHSMap.TriggerExecuteEventLog(Log, false, ContinueTurnDoneGameCallBack);
                        Log.Release();
                    }
                    else
                    {
                        StartLoadedEmailGame();
                    }
                }
            }
        }

