    public partial class TSimultaniousPlayerControl : TPlayerControl
    {
        public new const int ClassID = 131665;

        public TSimultaniousPlayerControl(TECustomNode owner) : base(owner)
        { }

        // PlayerC.PAS:1343
        public override void NewDay()
        {
            AoWEUnit.AoWHSMap.Selection.UnselectLocation();
            base.NewDay();
            for (int I = 0, last = AoWEUnit.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
            {
                NewTurn((sbyte)I);
            }

            PlaySample("SFX\\EVENTS\\NEWTURN.WAV");
            if (AoWEUnit.AoWEngine.FRegistry.GetAutoSave())
            {
                AutoSave();
            }
        }

        // PlayerC.PAS:1258
        public override void NewTurn(sbyte Player)
        {
            TEventLog Log;
            TSpellList Spells = default;
            if (Player == AoWEUnit.AoWHSMap.FSeatedPlayer)
            {
                if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType == TPlayerType.ptHuman)
                {
                    if (AoWEUnit.AoWHSMap.FDay == 1)
                    {
                        if (AoWEUnit.AoWHSMap.FGameType == TGameType.gtCustom)
                        {
                            Log = new TShowBookEventLog(null);
                            AoWEUnit.AoWHSMap.TriggerExecuteEventLog(Log, false, null);
                            Log.Release();
                        }

                        if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FMagicControl.FResearchSpellID == 0)
                        {
                            Spells = new TSpellList();
                            AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FMagicControl.ListResearchSpells(ref Spells, TSet<TSpellType>.Of(TSpellType.stCombat, TSpellType.stUnit, TSpellType.stGlobal));
                            if (Spells.GetCount() > 0)
                            {
                                Log = new TPlayerMagicEventLog(null);
                                ((TPlayerMagicEventLog)Log).FMode = TPlayerMagicEventMode.pmemStartResearch;
                                AoWEUnit.AoWHSMap.TriggerExecuteEventLog(Log, false, null);
                                Log.Release();
                            }

                            Spells?.Dispose();
                        }
                    }
                    else
                    {
                        AoWEUnit.AoWHSMap.ResetTurnTimer();
                        AoWEUnit.AoWHSMap.EnableTurnTimer();
                    }
                }
            }

            base.NewTurn(Player);
            if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType != TPlayerType.ptHuman)
            {
                if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FStatus == TPlayerStatus.psPlaying)
                {
                    AoWEUnit.AoWHSMap.FAIExecuter.ActivatePlayer(Player);
                }
            }
        }

        // PlayerC.PAS:1663
