        // PlayerC.PAS:1364
        public override void StartNewMap()
        {
            TNewTurnEventLog Log = default;
            base.StartNewMap();
            AoWEUnit.AoWHSMap.FShowIndependentMoves = false;
            for (int I = 0, last = AoWEUnit.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
            {
                if (I == 0 || AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType != TPlayerType.ptIndependent)
                {
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FStatus = TPlayerStatus.psPlaying;
                }
            }

            AoWEUnit.AoWHSMap.FPlayers.Update();
            AoWEUnit.AoWHSMap.FCurrentPlayer = 0;
            var item = AoWEUnit.AoWHSMap.FPlayers.FLocalHumanPlayers[0];
            AoWEUnit.AoWHSMap.SetSeatedPlayer((sbyte)item);
            AoWEUnit.AoWHSMap.SeatedPlayerChanged();
            Assert(AoWEUnit.AoWHSMap.FSeatedPlayer != 0, "", "PlayerC.PAS", 1584);
            AoWEUnit.AoWHSMap.ResetSeatedPlayerView();
            AoWEUnit.AoWHSMap.FTokenManager.TokenExecuter.ActivateTC(AoWEUnit.AoWHSMap.FCurrentPlayer);
            Log = new TNewTurnEventLog(null);
            Log.FTurnPlayer = AoWEUnit.AoWHSMap.FSeatedPlayer;
