            Log.FDialogStyle = TSet<TNewTurnEventLogDialogStyleElement>.Of(TNewTurnEventLogDialogStyleElement.nsCloseable);
            Log.FText = AoWEUnit.TranslateRStr(AoWEUnit.LetTheGameBeginRStr);
            AoWEUnit.AoWHSMap.TriggerExecuteEventLog(Log, false, StartGameCallBack);
            Log.Release();
            if (AoWEUnit.AoWHSMap.FConnectionType == TPlayerConnectionType.pcNetwork)
            {
                AoWEUnit.AoWHSMap.ResetTurnTimer();
                AoWEUnit.AoWHSMap.EnableTurnTimer();
            }
            else
            {
                AoWEUnit.AoWHSMap.FAIExecuter.Lock();
            }

            NewDay();
        }

