        // PlayerC.PAS:1652
        public override void SetPlayerGameOverStatus(sbyte Player, TGameOverStatus Status)
        {
            base.SetPlayerGameOverStatus(Player, Status);
            AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FStatus = TPlayerStatus.psTerminated;
            AoWEUnit.AoWHSMap.FTokenManager.TokenExecuter.GetTC(Player).Active = false;
            AoWEUnit.AoWHSMap.FPlayers.Update();
            AoWEUnit.AoWHSMap.TriggerPlayerTerminatedEvent(Player);
            if (AoWEUnit.AoWHSMap.FPlayers.FLocalHumanPlayers.Count == 0)
            {
                AoWEUnit.AoWHSMap.TriggerGameTerminatedEvent();
            }
            else
            {
                EndTurn(Player);
            }
        }

        // PlayerC.PAS:1646
        public override void GameOverEventHandled(sbyte Player)
        {
            AoWEUnit.AoWHSMap.SetSeatedPlayer(-1);
            AoWEUnit.AoWHSMap.TriggerGameTerminatedEvent();
        }

        // PlayerC.PAS:1305
        public override void EndTurn(sbyte Player)
        {
            int I;
            bool AllDone;
            TEndTurnEventLog Log;
            TEMsg Msg = default;
            AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).SetEndTurn(true);
            AllDone = true;
            I = 1;
            while (AllDone && I != AoWEUnit.AoWHSMap.FPlayers.Count)
            {
                AllDone = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FStatus != TPlayerStatus.psPlaying || AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FSingleProcessCycle;
                I += 1;
            }

            if (AllDone)
            {
                if (AoWEUnit.AoWHSMap.FSeatedPlayer == Player)
                {
                    AoWEUnit.AoWHSMap.ClearExecuteEventLogBuffer();
                }

                AoWEUnit.AoWHSMap.LockRelationsChanged();
                I = 0;
                int last = AoWEUnit.AoWHSMap.FPlayers.Count - 1;
                for (; I <= last; I += 1)
                {
                    if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FStatus == TPlayerStatus.psPlaying)
                    {
                        if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType != TPlayerType.ptHuman)
                        {
                            AoWEUnit.AoWHSMap.FAIExecuter.DeactivatePlayer((sbyte)I);
                        }

                        Log = new TEndTurnEventLog(null);
                        AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FEventLogbook.AddEvent(Log);
                        Log.Release();
                    }

                    InitMsg(ref Msg, 537001991, this);
                    Msg.Payload = I;
                    AoWEUnit.AoWHSMap.SendMsg(ref Msg, this);
                }

                AoWEUnit.AoWHSMap.UnlockRelationsChanged();
                NewDay();
            }
        }

        // PlayerC.PAS:1354
        public void StartGameCallBack(TEventLog Log)
        {
            if (AoWEUnit.AoWHSMap.FConnectionType != TPlayerConnectionType.pcNetwork)
            {
                AoWEUnit.AoWHSMap.FAIExecuter.Unlock();
                AoWEUnit.AoWHSMap.ResetTurnTimer();
                AoWEUnit.AoWHSMap.EnableTurnTimer();
            }
        }

