                    AoWEUnit.AoWHSMap.FTokenManager.TokenControls[I].Active = false;
                }
            }

            AoWEUnit.AoWHSMap.FTokenManager.TokenExecuter.ActivateTC(AoWEUnit.AoWHSMap.FCurrentPlayer);
            Log = new TNewTurnEventLog(null);
