            {
                Deactivate();
            }

            FMap = Map;
            FMap.Mouse.SetCapture(this);
            FMap.Mouse.OnDown += MouseDownEvent;
            FMap.Mouse.OnMove += MouseMoveEvent;
            FMap.Mouse.OnCaptureChanged += MouseDownEvent;
            FMap.Mouse.CursorMode = 256;
            UpdateMoveCursor();
