                                        }
                                    }
                                }
                                else
                                {
                                    if (FCurrentMove == I)
                                    {
                                        if (PointsLeft <= Settings.FMovePoints)
                                        {
                                            ImageIndex = 41;
                                        }
                                        else
                                        {
                                            ImageIndex = 48;
