                                        HXtoHP(X1, Y1, ref Xhp, ref Yhp);
                                        AoWEUnit.AoWHSSet.FCursorImages[ImageIndex].Show(Xhp - FMap.ViewXhp - 8, Yhp - FMap.ViewYhp - 8, Surface);
                                        if (PointsLeft - Settings.FPath[J].Flag != 0 && Settings.FPath[J + 1].L == FMap.ViewL)
                                        {
                                            if (PointsLeft - Settings.FPath[J].Flag <= Settings.FMovePoints)
                                            {
                                                ImageIndex = 41;
                                            }
                                            else
                                            {
                                                ImageIndex = 48;
                                            }

                                            HXtoHP(X2, Y2, ref Xhp, ref Yhp);
                                            AoWEUnit.AoWHSSet.FCursorImages[ImageIndex].Show(Xhp - FMap.ViewXhp - 8, Yhp - FMap.ViewYhp - 8, Surface);
                                        }
                                    }
                                    else
                                    {
                                        if (PointsLeft <= Settings.FMovePoints)
                                        {
                                            ImageIndex = 41;
                                        }
                                        else
                                        {
                                            ImageIndex = 48;
                                        }

                                        HXtoHP(X1, Y1, ref Xhp, ref Yhp);
                                        AoWEUnit.AoWHSSet.FCursorImages[ImageIndex].ShowTransparent(Xhp - FMap.ViewXhp - 8, Yhp - FMap.ViewYhp - 8, Surface);
                                        if (PointsLeft - Settings.FPath[J].Flag <= Settings.FMovePoints)
