                        if (Settings.FPath[0].X >= FMap.ViewXhx && Settings.FPath[0].X <= MaxX && Settings.FPath[0].Y >= FMap.ViewYhx && Settings.FPath[0].Y <= MaxY && Settings.FPath[0].L == FMap.ViewL)
