            base.Dispose();
        }

        // Army.PAS:3837
        public override void MouseDownEvent(object Sender)
        {
            TArmyHS ArmyHS;
            int Index;
            if (!FIgnoreMouseDown)
            {
                if (AoWEUnit.AoWHSMap.Mouse.Shift.Contains(TShiftState.ssShift))
                {
                    if (FMoveSettingsList.Count == 1 && FMoveSettingsList.GetMoveSettings(0).FPath.Count != 0)
                    {
                        var item = FMoveSettingsList.GetMoveSettings(0).FPath[0];
                        var fPathItem = FMoveSettingsList.GetMoveSettings(0).FPath[0];
                        var item2 = FMoveSettingsList.GetMoveSettings(0).FPath[0];
                        if (!ValidMultiMoveSelection((TAoWMapField)FMap.MapContainer.GetField(item2.X, fPathItem.Y, item.L)))
                        {
                            return;
                        }
                    }

                    if (AoWEUnit.AoWHSMap.Mouse.Xhx != -1)
                    {
                        var yhx = AoWEUnit.AoWHSMap.Mouse.Yhx;
                        var xhx = AoWEUnit.AoWHSMap.Mouse.Xhx;
                        ArmyHS = (TArmyHS)AoWEUnit.AoWHSMap.MapContainer.GetField(xhx, yhx, AoWEUnit.AoWHSMap.ViewL).FindOwnedChild(131607);
                        if (ArmyHS != null && ArmyHS.FArmy.FPlayer == AoWEUnit.AoWHSMap.FSeatedPlayer)
                        {
                            Index = FMoveSettingsList.IndexOfMoveObject(ArmyHS);
                            if (Index == -1)
                            {
                                AddMoveArmy(ArmyHS, 255);
                                Update();
                                AoWEUnit.AoWHSMap.Selection.SelectLocationHS(ArmyHS);
                                SetCurrentMove(-1);
                            }
                            else
                            {
                                ArmyHS.Unselect();
                                DeleteMoveObject(Index);
                                if (FMoveSettingsList.Count == 1)
                                {
                                    SetCurrentMove(0);
                                }
                            }
                        }
                    }
                }
                else
                {
                    if (AoWEUnit.AoWHSMap.Mouse.Shift.Contains(TShiftState.ssCtrl))
                    {
                        if (FMoveSettingsList.Count > 1 && AoWEUnit.AoWHSMap.Mouse.Xhx != -1)
                        {
                            var yhx = AoWEUnit.AoWHSMap.Mouse.Yhx;
                            var xhx = AoWEUnit.AoWHSMap.Mouse.Xhx;
                            ArmyHS = (TArmyHS)AoWEUnit.AoWHSMap.MapContainer.GetField(xhx, yhx, AoWEUnit.AoWHSMap.ViewL).FindOwnedChild(131607);
                            if (ArmyHS != null && ArmyHS.FArmy.FPlayer == AoWEUnit.AoWHSMap.FSeatedPlayer)
                            {
                                Index = FMoveSettingsList.IndexOfMoveObject(ArmyHS);
                                if (Index != -1)
                                {
                                    if (Index != FCurrentMove)
                                    {
                                        SetCurrentMove(Index);
                                        Update();
                                    }
                                    else
                                    {
                                        SetCurrentMove(-1);
                                    }
                                }
                            }
                        }
                    }
                    else
                    {
                        if (AoWEUnit.AoWHSMap.Mouse.Capture != AoWEUnit.AoWHSMap.FTargetSelection && (AoWEUnit.AoWHSMap.Mouse.Capture != this || FMap.Mouse.Button == TMouseButton.mbRight))
                        {
                            Unselect();
                        }
                        else
                        {
                            if (AoWEUnit.AoWHSMap.Mouse.Capture == this && AoWEUnit.AoWHSMap.Mouse.Button == TMouseButton.mbLeft)
                            {
                                var yhx = FMap.Mouse.Yhx;
                                SelectPath((sbyte)FMap.Mouse.Xhx, (sbyte)yhx, (sbyte)FMap.ViewL);
                            }
                        }
                    }
                }
            }
            else
            {
                FIgnoreMouseDown = false;
            }
        }

        // Army.PAS:3751
        public override void CalculateMovePath(int Index, sbyte X, sbyte Y, sbyte L)
        {
            TMoveSettings Settings;
            TArmyHS ArmyHS;
            if (X != -1)
            {
                Settings = FMoveSettingsList.GetMoveSettings(Index);
                ArmyHS = (TArmyHS)Settings.FMoveObject;
                Settings.FPathMovePoints = 0;
                FMoveControlSettings.Reset();
                var lhx = ArmyHS.GetLhx();
                var yhx = ArmyHS.GetYhx();
                var xhx = ArmyHS.GetXhx();
                FMoveControlSettings.SetSourcePos(xhx, yhx, lhx);
                FMoveControlSettings.FPlayer = ArmyHS.FArmy.FPlayer;
                FMoveControlSettings.FArmyHS = ArmyHS;
                FMoveControlSettings.SetDestinationPos(X, Y, L);
                FMoveControlSettings.FUnits.AddUnitsEx(ArmyHS.FArmy, (byte)Settings.FSelection);
                if (AoWEUnit.AoWHSMap.FExplorationEnabled)
                {
                    FMoveControlSettings.FMode = FMoveControlSettings.FMode + TSet<TMoveModeElement>.Of(TMoveModeElement.mmExploredTerrainOnly);
                }

                ArmyHS.FArmy.CreateMovePointTable((byte)Settings.FSelection, Bytes.Of(ref FMoveControlSettings.FMovePointTable));
                AoWEUnit.AoWHSMap.FMoveControl.ProcessMove(FMoveControlSettings);
                if (FMoveControlSettings.FPath.Count != 0)
                {
                    Settings.FPath.Assign(FMoveControlSettings.FPath);
                    Settings.FPathMovePoints = Settings.FPath.PosToMovePoints(0);
                    var item = Settings.FPath[0];
                    var fPathItem = Settings.FPath[0];
                    var item2 = Settings.FPath[0];
                    ArmyHS.FArmy.SetDestinationPos(item2.X, fPathItem.Y, item.L);
                    FMoveControlSettings.FPath.Clear();
                    if (FMode == TSelectedArmyMode.samBuildRoads)
                    {
                        if (Settings.FMovePoints < Settings.FPathMovePoints)
                        {
                            Settings.FPath.Clear();
                            var armyNotEnoughMovePoints = AoWEUnit.TranslateRStr(AoWEUnit.ArmyNotEnoughMovePointsRStr);
                            AoWEUnit.AoWHSMap.ShowMessage(armyNotEnoughMovePoints);
                        }
                        else
                        {
                            if (Settings.FPath.Count != 0)
                            {
                                var roadConstructionCost = AoWEUnit.RoadConstructionCost(GetArmyHS().FArmy.FPlayer, Settings.FPath, Settings.FMovePoints);
                                var format = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.ArmyRoadConstructionCostRStr), [IntToStr(roadConstructionCost)]);
                                AoWEUnit.AoWHSMap.ShowMessage(format);
                            }
                        }
                    }
                }
                else
                {
                    FMoveSettingsList.GetMoveSettings(Index).FPath.Clear();
                    ArmyHS.FArmy.ResetDestinationPos();
                }
            }
        }

        // Army.PAS:3580
        public override void SetCurrentMove(int Value)
        {
            if (FCurrentMove != -1 && GetArmyHS() != null)
            {
                var armyHS = GetArmyHS();
                AoWEUnit.AoWHSMap.Selection.TriggerDeselectEvent(armyHS);
            }

            FCurrentMove = Value;
            if (FCurrentMove != -1 && GetArmyHS() != null)
            {
                var armyHS = GetArmyHS();
                AoWEUnit.AoWHSMap.Selection.TriggerSelectEvent(armyHS);
            }

            UpdateSelectedUnitGFX();
        }

        // Army.PAS:3795
        public override void SelectPath(sbyte X, sbyte Y, sbyte L)
        {
            bool Valid;
            int I;
            TMoveSettings Settings;
            if (GetArmyHS() != null && GetArmyHS().GetXhx() == AoWEUnit.AoWHSMap.Mouse.Xhx && GetArmyHS().GetYhx() == AoWEUnit.AoWHSMap.Mouse.Yhx && GetArmyHS().GetLhx() == AoWEUnit.AoWHSMap.ViewL)
            {
                var lhx = GetArmyHS().GetLhx();
                var yhx = GetArmyHS().GetYhx();
                var xhx = GetArmyHS().GetXhx();
                AoWEUnit.AoWHSMap.Selection.SelectLocationHX(xhx, yhx, lhx);
            }
            else
            {
                if (FMoveSettingsList.Count > 1 && FCurrentMove == -1)
                {
                    Valid = true;
                    I = FMoveSettingsList.Count;
                    while (Valid && I != 0)
                    {
                        I -= 1;
                        Settings = FMoveSettingsList.GetMoveSettings(I);
                        Valid = Settings.FPath.Count != 0 && Settings.FPath[0].X == X && Settings.FPath[0].Y == Y && Settings.FPath[0].L == L;
                    }

                    if (!Valid)
                    {
                        if (ValidateSelection((TAoWMapField)FMap.MapContainer.GetField(X, Y, L)))
                        {
                            I = 0;
                            int last = FMoveSettingsList.Count - 1;
                            for (; I <= last; I += 1)
                            {
                                CalculateMovePath(I, X, Y, L);
                            }
                        }
                        else
                        {
                            I = 0;
                            int last = FMoveSettingsList.Count - 1;
                            for (; I <= last; I += 1)
                            {
                                FMoveSettingsList.GetMoveSettings(I).FPath.Clear();
                            }
                        }
                    }
                    else
                    {
                        ExecuteMove();
                    }
                }
                else
                {
                    base.SelectPath(X, Y, L);
                }
            }
        }

        // Army.PAS:3831
        public override void Unselect()
        {
            base.Unselect();
            Select(null);
        }

        // Army.PAS:3742
        public override bool ValidateSelection(TAoWMapField Field)
        {
            bool Result;
            if (FMoveSettingsList.Count > 1)
            {
                Result = ValidMultiMoveSelection(Field);
            }
            else
            {
                Result = base.ValidateSelection(Field);
            }

            if (FMode == TSelectedArmyMode.samBuildRoads)
            {
                if (Field.GetPlayer() != -1 && Field.GetPlayer() != GetArmyHS().FArmy.FPlayer)
                {
                    Result = false;
                }
            }

            return Result;
        }

        // Army.PAS:3904
        public override void ExecuteMove()
        {
            TArmyHS ArmyHS;
            TAoWMapField Field;
            int Cost;
            if (FMoveSettingsList.Count == 1)
            {
                var moveSettings = FMoveSettingsList.GetMoveSettings(FCurrentMove);
                if (moveSettings.FPath.Count > 1 && GetArmyHS() != null)
                {
                    ArmyHS = GetArmyHS();
                    var item = moveSettings.FPath[0];
                    var fPathItem = moveSettings.FPath[0];
                    var item2 = moveSettings.FPath[0];
                    Field = (TAoWMapField)AoWEUnit.AoWHSMap.MapContainer.GetField(item2.X, fPathItem.Y, item.L);
                    bool condition = Field.GetMoveAction(ArmyHS.FArmy.FPlayer) != TMoveAction.maAttack || Field.GetPlayer() <= 0;
                    if (!condition)
                    {
                        var player = Field.GetPlayer();
                        var diplomaticRelation = AoWEUnit.AoWHSMap.FPlayers.GetDiplomaticRelation(ArmyHS.FArmy.FPlayer, player);
                        condition = TSet<TDiplomaticRelation>.Of(TDiplomaticRelation.drWar, TDiplomaticRelation.drUnknown).Contains(diplomaticRelation);
                    }

                    if (condition)
                    {
                        if (FMode == TSelectedArmyMode.samBuildRoads)
                        {
                            Cost = AoWEUnit.RoadConstructionCost(ArmyHS.FArmy.FPlayer, moveSettings.FPath, moveSettings.FMovePoints);
                            if (Cost <= AoWEUnit.AoWHSMap.FPlayers.GetPlayers(ArmyHS.FArmy.FPlayer).FGems)
                            {
                                if (AoWEUnit.MoveArmyEx(ArmyHS, GetSelection(), moveSettings.FPath, TSet<TArmyMoveModeElement>.Of(TArmyMoveModeElement.mmSelectEndLocation, TArmyMoveModeElement.mmBuildRoads), false))
                                {
                                    moveSettings.FPath.Clear();
                                    if (AoWEUnit.AoWHSMap.Status.Contains(THSMapStatusElement.msEditting))
                                    {
                                        AoWEUnit.AoWHSMap.Selection.UnselectLocation();
                                    }

                                    DeactivateMoveSelection();
                                }
                            }
                            else
                            {
                                var notEnoughGold = AoWEUnit.TranslateRStr(AoWEUnit.NotEnoughGoldRStr);
                                AoWEUnit.AoWHSMap.ShowWarning(notEnoughGold);
                            }
                        }
                        else
                        {
                            var item3 = moveSettings.FPath[0];
                            var item4 = moveSettings.FPath[0];
                            var item5 = moveSettings.FPath[0];
                            ArmyHS.FArmy.SetDestinationPos(item5.X, item4.Y, item3.L);
                            if (AoWEUnit.MoveArmy(ArmyHS, GetSelection(), moveSettings.FPath))
                            {
                                var movePoints = ArmyHS.FArmy.MovePoints(255);
                                if (moveSettings.FPath.MovePointsToPos(movePoints) > 0)
                                {
                                    var army = ArmyHS.FArmy;
                                    army.FUserMode = army.FUserMode + TSet<TArmyUserModeElement>.Of(TArmyUserModeElement.aumTurnDone);
                                }

                                moveSettings.FPath.Clear();
                                if (AoWEUnit.AoWHSMap.Status.Contains(THSMapStatusElement.msEditting))
                                {
                                    AoWEUnit.AoWHSMap.Selection.UnselectLocation();
                                }

                                DeactivateMoveSelection();
                            }
                        }
                    }
                    else
                    {
                        if (((Field.FFieldFlags >> 16) & 255) != 0 || !AoWEUnit.AoWHSMap.FFogEnabled)
                        {
                            var player = Field.GetPlayer();
                            var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(player);
                            var raceNamesPlural = AoWEUnit.TranslateRStr(AoWEUnit.RaceNamesPluralRStr[players.FPlayerRace]);
                            var format = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.ArmyNotAtWarRStr), [raceNamesPlural]);
                            AoWEUnit.AoWHSMap.ShowMessage(format);
                        }
                    }
                }
            }
            else
            {
                if (FMoveSettingsList.Count > 1 && AoWEUnit.ExecuteMultiArmyMove(FMoveSettingsList))
                {
                    for (int I = 0, last = FMoveSettingsList.Count - 1; I <= last; I++)
                    {
                        var moveSettings = FMoveSettingsList.GetMoveSettings(I);
                        var item = moveSettings.FPath[0];
                        var fPathItem = moveSettings.FPath[0];
                        var item2 = moveSettings.FPath[0];
                        ((TArmyHS)moveSettings.FMoveObject).FArmy.SetDestinationPos(item2.X, fPathItem.Y, item.L);
                        moveSettings.FPath.Clear();
                    }

                    Deactivate();
                    AoWEUnit.AoWHSMap.Selection.UnselectLocation();
                    Clear();
                }
            }
        }

