        // Army.PAS:3647
        public void ResetSelectedUnitGFX()
        {
            for (int I = FSelectedUnitGFX.Count - 1; I >= 0; I--)
            {
                var item = FSelectedUnitGFX[I];
                AoWEUnit.AoWHSSet.FUnitGFXResources.GetUnitGFXResource(item).Release();
                FSelectedUnitGFX.Delete(I);
            }
        }

        // Army.PAS:3657
        public void UpdateSelectedUnitGFX()
        {
            int Index;
            TIntegerList List;
            List = new TIntegerList();
            if (GetArmyHS() != null)
            {
                for (int I = 0, last = GetArmyHS().FArmy.Count - 1; I <= last; I++)
                {
                    Index = GetArmyHS().FArmy.GetUnit(I).GetUnitGFXResourceIndex();
                    List.Add(Index);
                    AoWEUnit.AoWHSSet.FUnitGFXResources.GetUnitGFXResource(Index).AddRef();
                }
            }

            ResetSelectedUnitGFX();
            FSelectedUnitGFX.Assign(List);
            List?.Dispose();
        }

        // Army.PAS:3673
        public void OnDestroyArmy(TArmy Sender)
        {
            int Index;
            if (FStatus.Contains(TMoveSelectorStatusElement.mssActivated))
            {
                if (Sender != null)
                {
                    var armyHS = Sender.GetArmyHS();
                    Index = FMoveSettingsList.IndexOfMoveObject(armyHS);
                    if (Index != -1)
                    {
                        DeleteMoveObject(Index);
                    }
                }
                else
                {
                    Deactivate();
                }
            }
        }

        // Army.PAS:3685
        public void RectangleSelectEvent(TAbstractAoWHSMapMouse Sender)
        {
            int X1 = default;
            int Y1 = default;
            int X2 = default;
            int Y2 = default;
            int Xhp = default;
            int Yhp = default;
            TArmyHSList Armies;
            TRect R;
            TMapLevel Level;
            TArmyHS ArmyHS;
            Armies = new TArmyHSList(null);
            R = Sender.FSelectionRectangle;
            Level = AoWEUnit.AoWHSMap.MapContainer.GetMapLevel(AoWEUnit.AoWHSMap.ViewL);
            HPtoHX(R.Left, R.Top, ref X1, ref Y1);
            HPtoHX(R.Right, R.Bottom, ref X2, ref Y2);
            for (int X = X1 - 1, last = X2 + 1; X <= last; X++)
            {
                for (int Y = Y1 - 1, lastY = Y2 + 1; Y <= lastY; Y++)
                {
                    HXtoHP(X, Y, ref Xhp, ref Yhp);
                    Xhp += 16;
                    Yhp += 16;
                    if (X >= 0 && X < Level.Width && Y > 0 && Y < Level.Height && Xhp >= R.Left && Xhp < R.Right && Yhp >= R.Top && Yhp < R.Bottom)
                    {
                        ArmyHS = ((TAoWMapField)Level.GetField(X, Y)).GetArmyHS();
                        if (ArmyHS != null && ArmyHS.FArmy.FPlayer == AoWEUnit.AoWHSMap.FSeatedPlayer)
                        {
                            Armies.AddChild(ArmyHS);
                        }
                    }
                }
            }

            if (Armies.Count != 0)
            {
                Clear();
                AoWEUnit.AoWHSMap.Selection.UnselectLocation();
                for (int I = 0, last = Armies.Count - 1; I <= last; I++)
                {
                    AddMoveArmy(Armies.GetArmyHS(I), 255);
                    var armyHS = Armies.GetArmyHS(I);
                    AoWEUnit.AoWHSMap.Selection.SelectLocationHS(armyHS);
                }

                if (Armies.Count == 1)
                {
                    SetCurrentMove(0);
                }
                else
                {
                    SetCurrentMove(-1);
                }

                Update();
            }

            Armies?.Dispose();
        }

        // Army.PAS:3731
        public bool ValidMultiMoveSelection(TAoWMapField Field)
        {
            sbyte Player;
            bool Valid;
            TArmyHS ArmyHS;
            Player = Field.GetPlayer();
            Valid = Player == -1 || Player == AoWEUnit.AoWHSMap.FSeatedPlayer;
            ArmyHS = Field.GetArmyHS();
            if (ArmyHS != null)
            {
                Valid = Valid && ArmyHS.FArmy.Transporter(255) == null;
            }

            return Valid && FMode != TSelectedArmyMode.samBuildRoads;
        }

        // Army.PAS:4002
        public void ActivateMoveSelection()
        {
            Activate(AoWEUnit.AoWHSMap);
        }

        // Army.PAS:4013
        public void DeactivateMoveSelection()
        {
            Deactivate();
        }

        // Army.PAS:4018
        public void Update()
        {
            byte Selection;
            TMapField Field;
            TArmyHS ArmyHS;
            UpdateSelectedUnitGFX();
            if (GetArmyHS() != null)
            {
                var selection = GetSelection();
                GetArmyHS().FArmy.CreateMovePointTable(selection, Bytes.Of(ref FMoveControlSettings.FMovePointTable));
            }

            for (int I = 0, last = FMoveSettingsList.Count - 1; I <= last; I++)
            {
                Selection = (byte)FMoveSettingsList.GetMoveSettings(I).FSelection;
                ArmyHS = (TArmyHS)FMoveSettingsList.GetMoveSettings(I).FMoveObject;
                var movePoints = ArmyHS.FArmy.MovePoints(Selection);
                FMoveSettingsList.GetMoveSettings(I).FMovePoints = movePoints;
                var moves = ArmyHS.FArmy.Moves(Selection);
                FMoveSettingsList.GetMoveSettings(I).FMoves = moves;
            }

            if (FStatus.Contains(TMoveSelectorStatusElement.mssActivated))
            {
                for (int I = 0, last = FMoveSettingsList.Count - 1; I <= last; I++)
                {
                    ArmyHS = (TArmyHS)FMoveSettingsList.GetMoveSettings(I).FMoveObject;
                    if (ArmyHS.FArmy.FPlayer == AoWEUnit.AoWHSMap.FSeatedPlayer)
                    {
                        if (ArmyHS.FArmy.FDestinationX != -1 && ArmyHS.FArmy.FDestinationX != 0)
                        {
                            var army = ArmyHS.FArmy;
                            Field = AoWEUnit.AoWHSMap.MapContainer.GetField(army.FDestinationX, army.FDestinationY, army.FDestinationL);
                            if (this.ValidateSelection((TAoWMapField)Field))
                            {
                                CalculateMovePath(I, army.FDestinationX, army.FDestinationY, army.FDestinationL);
                            }
                            else
                            {
                                ArmyHS.FArmy.ResetDestinationPos();
                            }
                        }
                        else
                        {
                            if (FMoveSettingsList.GetMoveSettings(I).FPath.Count != 0)
                            {
                                var location = FMoveSettingsList.GetMoveSettings(I).FPath[0];
                                CalculateMovePath(I, location.X, location.Y, location.L);
                            }
                        }
                    }
                }
            }

            UpdateMoveCursor();
        }

        // Army.PAS:4063
        public void OutputGroupInfo()
        {
            string Text;
            TAIGroup Group;
            for (int I = 0, last = GetArmyHS().FArmy.Count - 1; I <= last; I++)
            {
                Text = GetArmyHS().FArmy.GetUnit(I).GetName() + "(ID:" + IntToStr(GetArmyHS().FArmy.GetUnit(I).FUnitID) + ")";
                Group = GetArmyHS().FArmy.GetUnit(I).FGroup;
                if (Group != null)
                {
                    var behavior = Group.GroupClass.Behavior;
                    Text = Text + AoWEUnit.TGroupBehaviorStr[(int)behavior] + "(GID:" + IntToStr(Group.FGroupID) + "/Target:" + IntToStr(Group.FTargetXYL.X) + "," + IntToStr(Group.FTargetXYL.Y) + "," + IntToStr(Group.FTargetXYL.L) + "/Budget:" + IntToStr(Group.FGoldBudget) + "/MP:" + IntToStr(Group.FTargetMovePoints) + ")";
                    if (Group.FTargetType == TAIGroupTargetStatus.gtsSetup)
                    {
                        Text = Text + "-setup";
                    }
                    else
                    {
                        if (Group.FTargetType == TAIGroupTargetStatus.gtsExecute)
                        {
                            Text = Text + "-execute";
                        }
                    }

                    var unit = GetArmyHS().FArmy.GetUnit(I);
                    if (Group.FLeader == unit)
                    {
                        Text = Text + "/Leader";
                    }
                }

                AoWEUnit.AoWEngine.OutputDebugStr(Text);
            }

            var strengthMax = GetArmyHS().FArmy.GetStrengthMax(AoWEUnit.dtAll - TSet<TDamageType>.Of(TDamageType.dtNone));
            AoWEUnit.AoWEngine.OutputDebugStr("Army strength: " + IntToStr(strengthMax));
        }

        // Army.PAS:4090
        public void SetArmyHS(TArmyHS ArmyHS)
        {
            if (ArmyHS != GetArmyHS() && !AoWEUnit.AoWHSMap.Status.Contains(THSMapStatusElement.msEditting) && FMoveSettingsList.Count <= 1)
            {
                Clear();
                FIgnoreMouseDown = false;
                FMode = TSelectedArmyMode.samDefault;
                if (ArmyHS != null)
                {
                    if (ArmyHS.FArmy.FPlayer == AoWEUnit.AoWHSMap.FSeatedPlayer)
                    {
                        ActivateMoveSelection();
                    }

                    AddMoveArmy(ArmyHS, 255);
                    FCurrentMove = 0;
                    Update();
                }
                else
                {
                    DeactivateMoveSelection();
                    ResetSelectedUnitGFX();
                }

                if (GetArmyHS() != null && AoWEUnit.AoWEngine.FRegistry.GetDebugMode())
                {
                    OutputGroupInfo();
                }
            }
        }

        // Army.PAS:4114
        public void Select(TArmyHS ArmyHS)
        {
            AoWEUnit.AoWHSMap.Selection.UnselectLocation();
            if (ArmyHS != null)
            {
                AoWEUnit.AoWHSMap.Selection.SelectLocationHS(ArmyHS);
            }
        }

        // Army.PAS:4120
        public void SelectBuildRoad(TAbstractUnit AUnit)
        {
            TECustomNode Army;
            TArmyHS ArmyHS;
            Army = AUnit.Owner;
            if (Army is TArmy)
            {
                ArmyHS = ((TArmy)Army).GetArmyHS();
                ArmyHS.FArmy.ResetDestinationPos();
                if (ArmyHS != GetArmyHS())
                {
                    AoWEUnit.AoWHSMap.Selection.UnselectLocation();
                    AoWEUnit.AoWHSMap.Selection.SelectLocationHS(ArmyHS);
                    SetSelection(255);
                }
                else
                {
                    DeleteMoves();
                    AddMoveArmy(ArmyHS, 255);
                    FCurrentMove = 0;
                }

                var selectRoadConstructionPath = AoWEUnit.TranslateRStr(AoWEUnit.SelectRoadConstructionPathRStr);
                AoWEUnit.AoWHSMap.ShowMessage(selectRoadConstructionPath);
                FRoadBuilderID = AUnit.FUnitID;
                FMode = TSelectedArmyMode.samBuildRoads;
            }
        }

        // Army.PAS:4146
        public void Center()
        {
            if (GetArmyHS() != null)
            {
                var aoWHSMap = AoWEUnit.AoWHSMap;
                var lhx = GetArmyHS().GetLhx();
                var yhx = GetArmyHS().GetYhx();
                aoWHSMap.CenterViewTo(GetArmyHS().GetXhx(), yhx, lhx);
