        // Army.PAS:4153
        public void TurnDone()
        {
            if (GetArmyHS() != null && GetArmyHS().FArmy.FPlayer == AoWEUnit.AoWHSMap.FSeatedPlayer)
            {
                var armyHS = GetArmyHS();
                GetArmyHS().FArmy.FUserMode = armyHS.FArmy.FUserMode + TSet<TArmyUserModeElement>.Of(TArmyUserModeElement.aumTurnDone);
                AoWEUnit.AoWHSMap.SelectNextArmy();
            }
