        // Structur.PAS:3816
        public void DeselectHS(object Sender)
        {
            if (FStatus.Contains(TTargetSelectionStatusElement.tsActivated))
            {
                Deactivate();
            }
        }

        // Structur.PAS:3821
        public void MouseDownEvent(object Sender)
        {
            THSMapMouse Mouse;
            if (FStatus.Contains(TTargetSelectionStatusElement.tsActivated))
            {
                if (AoWEUnit.AoWHSMap.Mouse.Capture != this || AoWEUnit.AoWHSMap.Mouse.Button == TMouseButton.mbRight)
                {
                    Deactivate();
                    AoWEUnit.AoWHSMap.FSelectedArmy.FIgnoreMouseDown = true;
                }
                else
                {
                    Mouse = AoWEUnit.AoWHSMap.Mouse;
                    if (Mouse.Capture == this && Mouse.Button == TMouseButton.mbLeft)
                    {
                        if (ValidTarget(FTargetX, FTargetY, FTargetL))
                        {
                            TriggerOnChangeEvent(TTargetSelectionChange.tscSelected);
                            if (!FStatus.Contains(TTargetSelectionStatusElement.tsActivated))
                            {
                                AoWEUnit.AoWHSMap.FSelectedArmy.FIgnoreMouseDown = true;
                            }
                        }
                    }
                }
            }
        }

        // Structur.PAS:3845
        public bool ValidTarget(sbyte X, sbyte Y, sbyte L)
        {
            bool Result = default;
            TMapField MapField;
            if (X != -1 && Y != -1)
            {
                if (FTargetMode.Contains(TTargetSelectionModeElement.tmValidateDistance))
                {
                    Result = dHXtoRad(FSourceX, FSourceY, X, Y) <= FRange;
                }
                else
                {
                    Result = true;
                }

                if (FTargetMode.Contains(TTargetSelectionModeElement.tmFixedLevel))
                {
                    Result = Result && L == FSourceL;
                }

                MapField = AoWEUnit.AoWHSMap.MapContainer.GetField(X, Y, L);
                Result = Result && MapField.TerrainType != 15;
                if (Result && FOnValidateTarget != null)
                {
                    FOnValidateTarget(this, X, Y, L, ref Result);
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Structur.PAS:3862
        public void NewFrameEvent(object Sender)
        {
            if (FStatus.Contains(TTargetSelectionStatusElement.tsActivated))
            {
                if (FStatus.Contains(TTargetSelectionStatusElement.tsVisible))
                {
                    AoWEUnit.AoWHSMap.Mouse.SetCursor(110 + (int)(((uint)AoWEUnit.AoWHSMap.Frame) >> 2) % 10);
                    AoWEUnit.AoWHSMap.Mouse.CursorVisible = true;
                }
                else
                {
                    AoWEUnit.AoWHSMap.Mouse.SetCursor(120);
                    AoWEUnit.AoWHSMap.Mouse.CursorVisible = false;
                }
            }
        }

        // Structur.PAS:3877
        public void MouseMoveEvent(object Sender)
        {
            if (FStatus.Contains(TTargetSelectionStatusElement.tsActivated))
            {
                FTargetX = (sbyte)AoWEUnit.AoWHSMap.Mouse.GetXhx();
                FTargetY = (sbyte)AoWEUnit.AoWHSMap.Mouse.GetYhx();
                FTargetL = (sbyte)AoWEUnit.AoWHSMap.ViewL;
                bool condition = AoWEUnit.AoWHSMap.Mouse.GetXhx() != -1 && AoWEUnit.AoWHSMap.Mouse.GetYhx() != -1;
                if (condition)
                {
                    var yhx = AoWEUnit.AoWHSMap.Mouse.GetYhx();
                    condition = ValidTarget((sbyte)AoWEUnit.AoWHSMap.Mouse.GetXhx(), (sbyte)yhx, (sbyte)AoWEUnit.AoWHSMap.ViewL);
                }

                if (condition)
                {
                    FStatus = FStatus + TSet<TTargetSelectionStatusElement>.Of(TTargetSelectionStatusElement.tsVisible);
                }
                else
                {
                    FStatus = FStatus - TSet<TTargetSelectionStatusElement>.Of(TTargetSelectionStatusElement.tsVisible);
                }
            }
        }

        // Structur.PAS:3891
        public void ShowSelection(int XhpSurf, int YhpSurf, in TSurfaceDesc SurfaceDesc)
        {
            int DX = default;
            int DY = default;
            int X = default;
            int Y = default;
            int XS;
            int YS;
            if (FStatus.Contains(TTargetSelectionStatusElement.tsActivated) && FTargetX != -1 && FStatus.Contains(TTargetSelectionStatusElement.tsVisible))
            {
                HXtoHP(FTargetX, FTargetY, ref X, ref Y);
                X -= XhpSurf;
                Y -= YhpSurf;
                for (int I = 0, last = FHNs.Count - 1; I <= last; I++)
                {
                    if (FHNs[I] >= 0)
                    {
                        HNtoHP(I, ref DX, ref DY);
                        XS = X + DX;
                        YS = Y + DY;
                        if (FTargetMode.Contains(TTargetSelectionModeElement.tmOwnerDraw))
                        {
                            if (FOnShow != null)
                            {
                                FOnShow(this, I, XS, YS, SurfaceDesc);
                            }
                        }
                        else
                        {
                            var item = FHNs[I];
                            FImageLibrary.Get(item).Show(XS - 8, YS, SurfaceDesc);
                        }
                    }
                }
            }
        }

        // Structur.PAS:3915
        public void Initialize(object Source)
        {
            if (FImageLibrary == null)
            {
                FImageLibrary = AoWEUnit.AoWHSSet.ImageLibraryManager.LinkToIL(TSet<TILManagerCategoryElement>.Of(TILManagerCategoryElement.icDisk), "TARGHEX.ILB");
            }

            if (!FStatus.Contains(TTargetSelectionStatusElement.tsActivated))
            {
                FHNs.Clear();
                FSource = Source;
                FTargetMode = TSet<TTargetSelectionModeElement>.Of(TTargetSelectionModeElement.tmFixedLevel);
            }
            else
            {
                throw new InvalidOperationException("please deactivate before initializing (TTargetSelectionControl)");
            }
        }

        // Structur.PAS:3928
        public void Activate()
        {
            if (!FStatus.Contains(TTargetSelectionStatusElement.tsActivated))
            {
                FStatus = FStatus + TSet<TTargetSelectionStatusElement>.Of(TTargetSelectionStatusElement.tsActivated);
                AoWEUnit.AoWHSMap.Mouse.SetCapture(this);
                AoWEUnit.AoWHSMap.Mouse.OnDown += MouseDownEvent;
                AoWEUnit.AoWHSMap.Mouse.OnMove += MouseMoveEvent;
                AoWEUnit.AoWHSMap.NewFrameEvents += NewFrameEvent;
                AoWEUnit.AoWHSMap.Selection.OnDeselect += DeselectHS;
                AoWEUnit.AoWHSMap.Mouse.CursorMode = 256;
                AoWEUnit.AoWHSMap.FKeyboard.Lock();
                TriggerOnChangeEvent(TTargetSelectionChange.tscActivated);
                MouseMoveEvent(this);
            }
            else
            {
                throw new InvalidOperationException("Already activated");
            }
        }

        // Structur.PAS:3946
        public void Deactivate()
        {
            TArmyHS ArmyHS = default;
            if (FStatus.Contains(TTargetSelectionStatusElement.tsActivated))
            {
                FStatus = FStatus - TSet<TTargetSelectionStatusElement>.Of(TTargetSelectionStatusElement.tsActivated);
                AoWEUnit.AoWHSMap.Mouse.OnDown -= MouseDownEvent;
                AoWEUnit.AoWHSMap.Mouse.OnMove -= MouseMoveEvent;
                AoWEUnit.AoWHSMap.NewFrameEvents -= NewFrameEvent;
                AoWEUnit.AoWHSMap.Selection.OnDeselect -= DeselectHS;
                if (AoWEUnit.AoWHSMap.Mouse.Capture == this)
                {
                    if (AoWEUnit.AoWHSMap.FSelectedArmy.GetArmyHS() != null)
                    {
                        ArmyHS = AoWEUnit.AoWHSMap.FSelectedArmy.GetArmyHS();
                        AoWEUnit.AoWHSMap.Mouse.SetCapture(null);
                        AoWEUnit.AoWHSMap.Selection.UnselectLocation();
                        AoWEUnit.AoWHSMap.Selection.SelectLocationHS(ArmyHS);
                    }
                    else
                    {
                        AoWEUnit.AoWHSMap.Mouse.SetCapture(null);
                    }
                }

                AoWEUnit.AoWHSMap.FKeyboard.Unlock();
                TriggerOnChangeEvent(TTargetSelectionChange.tscDeactivated);
                FSource = null;
                FOnShow = null;
                FOnValidateTarget = null;
            }
        }

        // Structur.PAS:3974
        public void UnitChanged(object AUnit)
        {
            if (FStatus.Contains(TTargetSelectionStatusElement.tsActivated) && FSource != null && AUnit == FSource && ((TAbstractUnit)AUnit).FUnitStatus.Contains(TUnitStatusElement.usKilled))
            {
                Deactivate();
            }
        }

        // intf_P1_05.inc:31

    }
}

namespace Aow.Game.World.Map
{

    // TNotifyEvent target passed directly
    // cheat text, mode, lock count
    public partial class TAoWHSMapKeyboard : TEObject
    {
        public TAoWHSMapKeyboard(TECustomNode owner) : base(owner)
        { }

        public string FCheatText = "";
        public TAoWHSMapKeyboardMode FMode;
        public int FLockCount;

        // AoWHSMap.PAS:946
        public virtual void KeyDown(ref ushort Key, TSet<TShiftState> Shift)
        {
            ushort TranslatedKey;
            int I;
            bool Prefix;
            bool Complete;
            TCheatTE Cheat;
            if (FLockCount != 0)
            {
                return;
            }

            // { Original uses OR between the digit bounds, admitting every key. }
            if ((Key >= 65 && Key <= 90) || Key >= 48 || Key <= 57 || Key == 188 || Key == 190 || Key == 13)
            {
                switch (FMode)
                {
                    case TAoWHSMapKeyboardMode.kmDefault:
                        TranslatedKey = Key;
                        switch (AoWEUnit.AoWEngine.FLanguage)
                        {
                            case 3:
                                switch (Key)
                                {
                                    case 83:
                                        TranslatedKey = 78;
                                        break;
                                    case 67:
                                        TranslatedKey = 76;
                                        break;
                                    case 84:
                                        TranslatedKey = 68;
                                        break;
                                    case 86:
                                        TranslatedKey = 67;
                                        break;
                                    case 68:
                                        TranslatedKey = 77;
                                        break;
                                }

                                break;
                            case 5:
                                switch (Key)
                                {
                                    case 86:
                                        TranslatedKey = 78;
                                        break;
                                    case 69:
                                        TranslatedKey = 72;
                                        break;
                                    case 67:
                                        TranslatedKey = 76;
                                        break;
                                    case 70:
                                        TranslatedKey = 68;
                                        break;
                                    case 83:
                                        TranslatedKey = 71;
                                        break;
                                    case 84:
                                        TranslatedKey = 67;
                                        break;
                                }

                                break;
                            case 4:
                                switch (Key)
                                {
                                    case 65:
                                        TranslatedKey = 68;
                                        break;
                                }

                                break;
                        }

                        if (!Shift.Contains(TShiftState.ssCtrl))
                        {
                            switch (TranslatedKey)
                            {
                                case 79:
                                    AoWEUnit.AoWHSMap.FShowIndependentMoves = !AoWEUnit.AoWHSMap.FShowIndependentMoves;
                                    if (AoWEUnit.AoWHSMap.FShowIndependentMoves)
                                    {
                                        var observeEnabled = AoWEUnit.TranslateRStr(AoWEUnit.ObserveEnabledRStr);
                                        AoWEUnit.AoWHSMap.ShowMessage(observeEnabled);
                                    }
                                    else
                                    {
                                        var observeDisabled = AoWEUnit.TranslateRStr(AoWEUnit.ObserveDisabledRStr);
                                        AoWEUnit.AoWHSMap.ShowMessage(observeDisabled);
                                    }

                                    break;
                                case 78:
                                case 188:
                                    AoWEUnit.AoWHSMap.SelectNextArmy();
                                    break;
                                case 80:
                                case 190:
                                    AoWEUnit.AoWHSMap.SelectPrevArmy();
                                    break;
                                case 72:
                                    AoWEUnit.AoWHSMap.SelectNextHero();
                                    break;
                                case 77:
                                    AoWEUnit.AoWHSMap.FSelectedArmy.ExecuteMove();
                                    break;
                                case 68:
                                    AoWEUnit.AoWHSMap.FSelectedArmy.TurnDone();
                                    break;
                                case 71:
                                    AoWEUnit.AoWHSMap.FSelectedArmy.ToggleGuard();
                                    break;
                                case 76:
                                    AoWEUnit.AoWHSMap.CenterOnLeader(AoWEUnit.AoWHSMap.FSeatedPlayer, true, false);
                                    break;
                                case 67:
                                    if (!Shift.Contains(TShiftState.ssCtrl))
                                    {
                                        AoWEUnit.AoWHSMap.FSelectedArmy.Center();
                                    }

                                    break;
                                case 82:
                                    if (AoWEUnit.AoWEngine.FDebug)
                                    {
                                        AoWEUnit.AoWEngine.OutputDebugStr("Random Seed: " + IntToStr(AoWEUnit.AoWHSMap.FDefendersSeed));
                                    }

                                    break;
                                case 83:
                                    if (!Shift.Contains(TShiftState.ssCtrl) && AoWEUnit.AoWEngine.FRegistry.GetDebugMode())
                                    {
                                        RunDefaultTest();
                                    }

                                    break;
                                case 65:
                                    if (AoWEUnit.AoWEngine.FRegistry.GetDeveloper() && AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AoWEUnit.AoWHSMap.FSeatedPlayer).FPlayerType != TPlayerType.ptHuman)
                                    {
                                        AoWEUnit.AoWHSMap.FAIExecuter.ActivatePlayer(AoWEUnit.AoWHSMap.FSeatedPlayer);
                                    }

                                    break;
                                case 73:
                                    if (AoWEUnit.AoWEngine.FDebug)
                                    {
                                        var heapStatus = GetHeapStatus();
                                        AoWEUnit.AoWHSMap.ShowMessage("Allocated Memory: " + IntToStr(heapStatus.TotalAllocated));
                                    }

                                    break;
                            }
                        }

                        // AoWHSMap.PAS:1004 called AoWHSMap.EndTurn for Ctrl+E and Ctrl+Enter.
                        // The port presses the end-turn button from the map window instead.
                        // A port addition the original does not have.

                        break;
                    case TAoWHSMapKeyboardMode.kmCheat:
                        FCheatText = FCheatText + Cp1252.Text((byte)Key);
                        I = 10;
                        Complete = false;
                        Prefix = false;
                        while (I != 0 && !Complete)
                        {
                            I -= 1;
                            Prefix = Prefix || CompareText(FCheatText, RtlUnit.Copy(AoWEUnit.CheatNames[I], 1, FCheatText.Length)) == 0;
                            Complete = CompareText(FCheatText, AoWEUnit.CheatNames[I]) == 0;
                        }

                        if (Complete && AoWEUnit.AoWHSMap.FSeatedPlayer != -1 && !AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AoWEUnit.AoWHSMap.FSeatedPlayer).GetBusy())
                        {
                            Cheat = new TCheatTE(null);
                            Cheat.FPlayer = AoWEUnit.AoWHSMap.FSeatedPlayer;
                            Cheat.FCheatID = I;
                            AoWEUnit.AoWHSMap.FTokenManager.GetTokenControl(AoWEUnit.AoWHSMap.FSeatedPlayer).AddEvent(Cheat);
                            Cheat.Release();
                            FCheatText = "";
                            FMode = TAoWHSMapKeyboardMode.kmDefault;
                        }
                        else
                        {
                            if (!Prefix)
                            {
                                FMode = TAoWHSMapKeyboardMode.kmDefault;
                                FCheatText = "";
                            }
                        }

                        break;
                }
            }

            if (Key == 67 && (TSet<TShiftState>.Of(TShiftState.ssShift, TShiftState.ssCtrl) & Shift) == TSet<TShiftState>.Of(TShiftState.ssShift, TShiftState.ssCtrl) && CompareText(ParamStr(1), "beatrix") == 0 && AoWEUnit.AoWHSMap.FConnectionType != TPlayerConnectionType.pcNetwork && AoWEUnit.AoWHSMap.FConnectionType != TPlayerConnectionType.pcEmail && !AoWEUnit.AoWEngine.FDemo)
            {
                PlaySample("SFX\\ATTACK\\MAGICB02.WAV");
                FMode = TAoWHSMapKeyboardMode.kmCheat;
                FCheatText = "";
            }
        }

        // AoWHSMap.PAS:928
        public void Lock()
        {
            FLockCount += 1;
        }

        // AoWHSMap.PAS:933
        public void Unlock()
        {
            FLockCount -= 1;
        }

        // AoWHSMap.PAS:938
        public void RunDefaultTest()
        {
            string FileName;
            FileName = "autosave" + FileBoundary.WriteExtension(Aow.Formats.DocumentKind.Save);
            // { Original saves the autosave file. }
            AoWEUnit.AoWEngine.SaveHSM(AoWEUnit.AoWEngine.StartupDirectory + "Save\\" + FileName, null, Aow.Formats.GameProfile.WorldMap);
        }

        // Engine.pas:524

    }

    // selection rectangle, events
    public partial class TAbstractAoWHSMapMouse : THSMapMouse
    {
        public TAbstractAoWHSMapMouse() : base()
        {
            ResetRectangleSelection();
            FRectangleSelectEventsStore = new();
        }

        public TRect FSelectionRectangle;

        internal EventStore<TAbstractAoWHSMapMouse> FRectangleSelectEventsStore;

        public event TNotifyEvent<TAbstractAoWHSMapMouse> FRectangleSelectEvents
        {
            add => FRectangleSelectEventsStore.Add(value);
            remove => FRectangleSelectEventsStore.Remove(value);
        }

        // AoWHSMap.PAS:1057
        public override void Dispose()
        {
            base.Dispose();
            FRectangleSelectEventsStore.Clear();
        }

        // AoWHSMap.PAS:1123
        public override void Down(TMouseButton Button, TSet<TShiftState> Shift, int X, int Y)
        {
            base.Down(Button, Shift, X, Y);
            if (Capture == null && !HSMap.Status.Contains(THSMapStatusElement.msEditting))
            {
                StartRectangleSelection(HSMap.ViewXhp + X - 2, HSMap.ViewYhp + Y - 3);
            }
        }

        // AoWHSMap.PAS:1130
        public override void Up(TMouseButton Button, TSet<TShiftState> Shift, int X, int Y)
        {
            base.Up(Button, Shift, X, Y);
            if (Capture == null && FSelectionRectangle.Left != -1)
            {
                if (X != -1 && Y != -1)
                {
                    StopRectangleSelection(HSMap.ViewXhp + X - 2, HSMap.ViewYhp + Y - 3);
                }
                else
                {
                    ResetRectangleSelection();
                }
            }
        }

        // AoWHSMap.PAS:1141
        public override void Move(TSet<TShiftState> Shift, int X, int Y)
        {
            base.Move(Shift, X, Y);
            if (Capture == null)
            {
                UpdateRectangleSelection(HSMap.ViewXhp + X - 2, HSMap.ViewYhp + Y - 3);
            }
        }

        // AoWHSMap.PAS:1063
        public void ResetRectangleSelection()
        {
            FSelectionRectangle.Left = -1;
            FSelectionRectangle.Top = -1;
            FSelectionRectangle.Right = -1;
            FSelectionRectangle.Bottom = -1;
        }

        // AoWHSMap.PAS:1071
        public bool GetSelectingRectangle()
        {
            bool Result;
            if (FSelectionRectangle.Left == -1 || (FSelectionRectangle.Left == FSelectionRectangle.Right && FSelectionRectangle.Top == FSelectionRectangle.Bottom))
            {
                Result = false;
            }
            else
            {
                Result = true;
            }

            return Result;
        }

        // AoWHSMap.PAS:1079
        public void StartRectangleSelection(int Xhp, int Yhp)
        {
            FSelectionRectangle.Left = Xhp;
            FSelectionRectangle.Top = Yhp;
            FSelectionRectangle.Right = Xhp;
            FSelectionRectangle.Bottom = Yhp;
        }

        // AoWHSMap.PAS:1087
        public void UpdateRectangleSelection(int Xhp, int Yhp)
        {
            if (Button == TMouseButton.mbLeft)
            {
                if (Xhp > 0 && Yhp > 0)
                {
                    if (Xhp < FSelectionRectangle.Left - 800)
                    {
                        Xhp = FSelectionRectangle.Left - 800;
                    }

                    if (Xhp > FSelectionRectangle.Left + 800)
                    {
                        Xhp = FSelectionRectangle.Left + 800;
                    }

                    if (Yhp < FSelectionRectangle.Top - 600)
                    {
                        Yhp = FSelectionRectangle.Top - 600;
                    }

                    if (Yhp > FSelectionRectangle.Top + 600)
                    {
                        Yhp = FSelectionRectangle.Top + 600;
                    }

                    FSelectionRectangle.Right = Xhp;
                    FSelectionRectangle.Bottom = Yhp;
                }
            }
            else
            {
                ResetRectangleSelection();
            }
        }

        // AoWHSMap.PAS:1104
        public void StopRectangleSelection(int Xhp, int Yhp)
        {
            TRect R = default;
            FSelectionRectangle.Right = Xhp;
            FSelectionRectangle.Bottom = Yhp;
            if (FSelectionRectangle.Left < FSelectionRectangle.Right)
            {
                R.Left = FSelectionRectangle.Left;
            }
            else
            {
                R.Left = FSelectionRectangle.Right;
            }

            if (FSelectionRectangle.Right > FSelectionRectangle.Left)
            {
                R.Right = FSelectionRectangle.Right;
            }
            else
            {
                R.Right = FSelectionRectangle.Left;
            }

            if (FSelectionRectangle.Top < FSelectionRectangle.Bottom)
            {
                R.Top = FSelectionRectangle.Top;
            }
            else
            {
                R.Top = FSelectionRectangle.Bottom;
            }

            if (FSelectionRectangle.Bottom > FSelectionRectangle.Top)
            {
                R.Bottom = FSelectionRectangle.Bottom;
            }
            else
            {
                R.Bottom = FSelectionRectangle.Top;
            }

            FSelectionRectangle = R;
            FRectangleSelectEventsStore.Raise(this);
            ResetRectangleSelection();
        }

        // intf_P1_05.inc:68

    }

