        // AoWHSMap.PAS:1184
        public override void DblClick()
        {
            TAbstractAoWCombatMap CombatMap;
            bool SelectStructure;
            TStructure Structure;
            CombatMap = AoWEUnit.AoWHSMap.FCombatMap;
            if (CombatMap != null)
            {
                CombatMap.Mouse.DblClick();
                return;
            }

            SelectStructure = Capture == null;
            if (Capture == AoWEUnit.AoWHSMap.FSelectedArmy)
            {
                SelectStructure = AoWEUnit.AoWHSMap.FSelectedArmy.GetArmyHS() != null && AoWEUnit.AoWHSMap.FSelectedArmy.FMoveSettingsList.Count == 1 && AoWEUnit.AoWHSMap.FSelectedArmy.GetArmyHS().Xhx == Xhx && AoWEUnit.AoWHSMap.FSelectedArmy.GetArmyHS().Yhx == Yhx && AoWEUnit.AoWHSMap.FSelectedArmy.GetArmyHS().Lhx == AoWEUnit.AoWHSMap.ViewL;
            }

            if (SelectStructure && Xhx != -1)
            {
                var yhx = Yhx;
                var xhx = Xhx;
                Structure = (TStructure)AoWEUnit.AoWHSMap.MapContainer.GetField(xhx, yhx, AoWEUnit.AoWHSMap.ViewL).FindNoneTransparentHS(typeof(TStructure));
                if (Structure != null && Structure.CanDblClick())
                {
                    AoWEUnit.AoWHSMap.Selection.UnselectLocation();
                    AoWEUnit.AoWHSMap.Selection.SelectLocationHS(Structure);
                }
            }

            base.DblClick();
        }

        // intf_P1_05.inc:68

    }

    public partial class TAbstractAoWHSMap : THSMap
    {

        public TAbstractAoWHSMap(TECustomNode owner) : base(owner)
        {
            FShowMessageEventsStore = new();
            FMapChangedEventsStore = new();
            FScannerIconsChangedEventsStore = new();
            FBackHexagonSelector = new TCustomFixedVisibleHS(null);
            FBackHexagonSelector.OnShow = ShowBackHexagonSelector;
            FFrontHexagonSelector = new TCustomFixedVisibleHS(null);
            FFrontHexagonSelector.OnShow = ShowFrontHexagonSelector;
            FHexagonSelectorVisible = false;
            FExplorationEnabled = true;
            FFogEnabled = true;
            FSeatedPlayer = 1;
