        public override void Dispose()
        {
            FShownMessages?.Dispose();
            base.Dispose();
        }

        // AoWHSMap.PAS:11
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwStreamProc(20, FShownMessages.LoadFromStream, FShownMessages.SaveToStream);
        }

        // AoWHSMap.PAS:16
        public void ShowMessage(int ID, bool Immediate, bool OnceOnly)
        {
            TTutorialMessageEventLog Log;
            if (AoWEUnit.AoWHSMap.FGameType == TGameType.gtTutorial && AoWEUnit.AoWHSMap.FTextControl.FindID(ID) != null)
            {
                if (OnceOnly && FShownMessages.IndexOf(ID) != -1)
                {
                    return;
                }

                Log = new TTutorialMessageEventLog(null);
                var id = AoWEUnit.AoWHSMap.FTextControl.FindID(ID);
                Log.FMessage.Assign(id.FText);
                AoWEUnit.AoWHSMap.TriggerExecuteEventLog(Log, Immediate, null);
                Log.Release();
                FShownMessages.Add(ID);
            }
        }

        // intf_P1_05.inc:187

    }
}

