        // AoWHSMap.PAS:1215
        public TStartupSongList(TECustomNode owner) : base(owner)
        {
            Songs.OnChange = OriginalSongsChanged;
        }

        // AoWHSMap.PAS:1221
        public void OriginalSongsChanged(object Sender)
        {
            string Name;
            SongNames.Clear();
            for (int I = Songs.Count - 1; I >= 0; I--)
            {
                try
                {
                    Name = GetSongName(Songs[I]);
                }
                catch
                {
                    Name = AoWEUnit.TranslateRStr(AoWEUnit.FileNotFoundRStr);
                }

                SongNames.Insert(0, Name);
            }
        }

        // intf_P1_05.inc:194

    }
}

