        // AoWHSMap.PAS:2116
        public override void NotifyProgress(in TMapProgress Progress)
        {
            string DefaultText;
            string Text = "";
            int Percent = default;
            int Total = default;
            if (OnProgress != null)
            {
                DefaultText = AoWEUnit.TranslateRStr(OneMomentPleaseStr);
                switch (Progress.ProgressType)
                {
                    case TMapProgressType.ptLoading:
                        Total = Progress.Percent + Progress.Level * 100;
                        Percent = Round((double)((double)Total / 3) / MapContainer.LevelCount);
                        if (AoWEUnit.AoWEngine.FDebug)
                        {
                            Text = AoWEUnit.TranslateRStr(AoWEUnit.LoadingLevelRStr) + IntToStr(Progress.Level);
                        }
                        else
                        {
                            Text = DefaultText;
                        }

                        OnProgress(this, Text, Percent);
                        break;
                    case TMapProgressType.ptInitializing:
                        Total = Progress.Percent + Progress.Level * 100;
                        Percent = Round((double)((double)((double)Total / 4.5) / MapContainer.LevelCount) + (double)100 / 3);
                        if (AoWEUnit.AoWEngine.FDebug)
                        {
                            Text = AoWEUnit.TranslateRStr(AoWEUnit.InitializingLevelRStr) + IntToStr(Progress.Level);
                        }
                        else
                        {
                            Text = DefaultText;
                        }

                        OnProgress(this, Text, Percent);
                        break;
                    case TMapProgressType.ptUpdatingTerrain:
                        Total = Progress.Percent + Progress.Level * 100;
                        Percent = Round((double)((double)((double)Total / 4.5) / MapContainer.LevelCount) + (double)500 / 9);
                        if (AoWEUnit.AoWEngine.FDebug)
                        {
                            Text = AoWEUnit.TranslateRStr(AoWEUnit.UpdatingTerrainLevelRStr) + IntToStr(Progress.Level);
                        }
                        else
                        {
                            Text = DefaultText;
                        }

                        OnProgress(this, Text, Percent);
                        break;
                    case TMapProgressType.ptActivating:
                        Total = Progress.Percent + Progress.Level * 100;
                        Percent = Round((double)((double)((double)Total / 4.5) / MapContainer.LevelCount) + (double)700 / 9);
                        if (AoWEUnit.AoWEngine.FDebug)
                        {
                            Text = AoWEUnit.TranslateRStr(AoWEUnit.ActivatingLevelRStr) + IntToStr(Progress.Level);
                        }
                        else
                        {
                            Text = DefaultText;
                        }

                        OnProgress(this, Text, Percent);
                        break;
                    case TMapProgressType.ptSaving:
                        var savingLevel = AoWEUnit.TranslateRStr(AoWEUnit.SavingLevelRStr);
                        OnProgress(this, savingLevel + IntToStr(Progress.Level), Progress.Percent);
                        break;
                    case TMapProgressType.ptDestroying:
                        var aoWETranslateRStr = AoWEUnit.TranslateRStr(AoWEUnit.DestroyingLevelRStr);
                        OnProgress(this, aoWETranslateRStr + IntToStr(Progress.Level), Progress.Percent);
                        break;
                }
            }
        }

        // AoWHSMap.PAS:2290
        public override void InitializeNewMap()
        {
            TEObject Obj;
            FRaces.Update();
            FPlayers.SetNumberOfPlayers(2);
            FPlayers.ValidateRaces(FRaces);
            for (int L = 0, last = MapContainer.LevelCount - 1; L <= last; L++)
            {
                InitializeMapLevel((sbyte)L);
            }

            for (int I = 0, last = AoWEUnit.AoWHSSet.FItemLibraries.FSystemLibrary.Count - 1; I <= last; I++)
            {
                Obj = AoWEUnit.AoWHSSet.FItemLibraries.FSystemLibrary.GetItem(I).Copy(AoWEUnit.AoWEngine);
                FItemControl.RegisterItem((TItem)Obj);
                Obj.Release();
            }

            for (int I = 0, last = AoWEUnit.AoWHSSet.FHeroLibraries.FSystemLibrary.Count - 1; I <= last; I++)
            {
                Obj = AoWEUnit.AoWHSSet.FHeroLibraries.FSystemLibrary.GetHero(I).Copy(AoWEUnit.AoWEngine);
                FHeroControl.RegisterHero((THero)Obj);
                Obj.Release();
            }
        }

