        // AoWHSMap.PAS:2654
        public override void Activate()
        {
            SynchroniseBegin();
            if (FDay == 0 || FGameSongs.Songs.Count == 0)
            {
                FGameSongs.Songs.Clear();
                for (int I = 0, last = AoWEUnit.AoWHSMap.FStartupSongs.Songs.Count - 1; I <= last; I++)
                {
                    var fileNotFound = AoWEUnit.TranslateRStr(AoWEUnit.FileNotFoundRStr);
                    if (CompareText(AoWEUnit.AoWHSMap.FStartupSongs.SongNames[I], fileNotFound) != 0)
                    {
                        var item = AoWEUnit.AoWHSMap.FStartupSongs.Songs[I];
                        FGameSongs.Songs.Add(item);
                    }
                }
            }

            FGameStatus = TGameStatus.gsPlaying;
            FDebugSave = AoWEUnit.AoWEngine.FRegistry.GetAutoDebugSave();
            FGlobalMagicControl.Update();
            FPlayers.BeginUpdate();
            FPlayers.EndUpdate();
            for (int I = 0, last = FPlayers.Count - 1; I <= last; I++)
            {
                if (FPlayers.GetPlayers(I).FBehavior == TPlayerBehavior.pbRandom)
                {
                    var random = AoWEUnit.AoWHSMap.Random(5);
                    FPlayers.GetPlayers(I).FBehavior = (TPlayerBehavior)random;
                }
            }

            if (FPlayerControl == null)
            {
                if (FPlayMode == TPlayMode.pmNone)
                {
                    FPlayMode = TPlayMode.pmTurn;
                }

                if (FPlayers.FLocalHumanPlayers.Count > 1)
                {
                    FPlayMode = TPlayMode.pmTurn;
                }

                SetupPlayerControl(FPlayMode, FConnectionType);
            }

            FTokenManager.Initialize(FPlayerCommunicator);
            base.Activate();
            if (!Status.Contains(THSMapStatusElement.msEditting))
            {
                if (FDay == 0)
                {
                    StartNewMap();
                }
                else
                {
                    StartLoadedMap();
                }

                ShowMessage("");
            }

            if (AoWEUnit.AoWEngine.FRegistry.GetLogTokenEvents())
            {
                StartTokenEventLogging();
            }

            SynchroniseEnd();
        }

