        // AoWHSMap.PAS:1996
        public virtual void TriggerExecuteEventLog(TEventLog Log, bool Immediate, TExecuteDoneEvent Done)
        {
            var notification = new ExecuteEventLogNotification();
            ref var Info = ref notification.Info;
            Info.Log = Log;
            Info.Done = Done;
            Info.Immediate = Immediate;
            if (!Immediate)
            {
                Log.AddRef();
                FExecuteEventLogCallBacks.Add(Info);
                if (FAILockCount == 0)
                {
                    ExecuteNextEventLog();
                }
            }
            else
            {
                FExecuteEventLogEventsStore.Raise(notification);
            }
        }

