        // AoWHSMap.PAS:1559
        public bool TerrainVisible(sbyte X, sbyte Y, sbyte L, int Radius)
        {
            TMapLevel MapLevel;
            TAoWMapField Field;
            THNWalkData Walk = default;
            // { Original returns true immediately when exploration is enabled. }
            bool Result = AoWEUnit.AoWHSMap.FExplorationEnabled;
            MapLevel = MapContainer.GetMapLevel(L);
            InitHNWalk(ref Walk, X, Y, 0);
            while (Walk.Radius <= Radius && !Result)
            {
                if (Walk.X >= 0 && Walk.Y >= 0 && Walk.X < MapLevel.Width && Walk.Y < MapLevel.Height)
                {
                    Field = (TAoWMapField)MapLevel.GetField(Walk.X, Walk.Y);
                    Result = Field.GetExplored(AoWEUnit.AoWHSMap.FSeatedPlayer);
                }

                if (!Result)
                {
                    WalkToNextHN(ref Walk);
                }
            }

            return Result;
        }

