        // AoWHSMap.PAS:1647
        public bool ValidateTerrainObservation(sbyte Player, sbyte X, sbyte Y, sbyte L, int Radius)
        {
            bool Result;
            TMapLevel MapLevel;
            TAoWMapField Field;
            THNWalkData Walk = default;
            int WX;
            if (FShowIndependentMoves && Player != AoWEUnit.AoWHSMap.FSeatedPlayer)
            {
                Result = false;
                MapLevel = MapContainer.GetMapLevel(L);
                InitHNWalk(ref Walk, X, Y, 0);
                while (Walk.Radius <= Radius && !Result)
                {
                    WX = Walk.X;
                    if (WX >= 0 && Walk.Y >= 0 && WX < MapLevel.Width && Walk.Y < MapLevel.Height)
                    {
                        Field = (TAoWMapField)MapLevel.GetField(WX, Walk.Y);
                        Result = Field.GetExplored(AoWEUnit.AoWHSMap.FSeatedPlayer) || !AoWEUnit.AoWHSMap.FExplorationEnabled;
                    }

                    if (!Result)
                    {
                        WalkToNextHN(ref Walk);
                    }
                }

                if (Result)
                {
                    MakeVisible(Walk.X, Walk.Y, L, 3);
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

