        // AoWHSMap.PAS:1709
        public bool SelectNextHero()
        {
            TPlayer Player;
            int I;
            int Left;
            TArmy Army;
            int Xhp = default;
            int Yhp = default;
            Player = FPlayers.GetPlayers(FSeatedPlayer);
            if (Player.FArmies.Count != 0)
            {
                Left = Player.FArmies.Count;
                I = Player.FHeroJoinDay;
                if (I < 0 || I >= Player.FArmies.Count)
                {
                    I = 0;
                }

                while (true)
                {
                    I += 1;
                    Left -= 1;
                    if (I == Player.FArmies.Count)
                    {
                        I = 0;
                    }

                    if (Left == 0 || Player.FArmies.GetArmy(I).Hero(255, TSet<THeroType>.Of(THeroType.htHero, THeroType.htLeader, THeroType.htHeroLeader, THeroType.htMerchant)) != null)
                        break;
                }

                if (Player.FArmies.GetArmy(I).Hero(255, TSet<THeroType>.Of(THeroType.htHero, THeroType.htLeader, THeroType.htHeroLeader, THeroType.htMerchant)) != null)
                {
                    Army = FPlayers.GetPlayers(FSeatedPlayer).FArmies.GetArmy(I);
                    CenterViewTo(Army.FX, Army.FY, Army.FL);
                    Selection.UnselectLocation();
                    HXtoHP(Army.FX, Army.FY, ref Xhp, ref Yhp);
                    Selection.SelectLocation(Xhp, Yhp, Army.FL);
                    Player.FHeroJoinDay = I;
                }
                else
                {
                    Selection.UnselectLocation();
                }
            }

            return true;
        }

