        // AoWHSMap.PAS:2024
        public void ExecuteGameOverEvent(TGameOverEventLog Event)
        {
            TPlayer Player;
            TGameOverEventLog Log;
            for (int I = 1, last = AoWEUnit.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
            {
                Player = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I);
                if (I == Event.FPlayer || Player.FGameOverStatus == TGameOverStatus.goNone)
                {
                    Log = (TGameOverEventLog)Event.Copy(AoWEUnit.AoWEngine);
                    if (FGameOverLockCount == 0)
                    {
                        Player.FEventLogbook.AddEvent(Log);
                        if (I == AoWEUnit.AoWHSMap.FSeatedPlayer)
                        {
                            Log.Execute(false, TExecuteTrigger.etEvent, null);
                        }
                    }
                    else
                    {
                        Log.FTargetPlayer = (sbyte)I;
                        FExecuteEventLogBuffer.AddEvent(Log);
                    }

                    Log.Release();
                }
            }
        }

        // AoWHSMap.PAS:2052
        public void UnlockGameOverEvent()
        {
            sbyte Player;
            TEventLog Log;
            FGameOverLockCount -= 1;
            if (FGameOverLockCount == 0)
            {
                while (FExecuteEventLogBuffer.Count != 0)
                {
                    Player = ((TGameOverEventLog)FExecuteEventLogBuffer.GetEvents(0)).FTargetPlayer;
                    Log = (TEventLog)FExecuteEventLogBuffer.GetEvents(0).Copy(AoWEUnit.AoWEngine);
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FEventLogbook.AddEvent(Log);
                    if (Player == AoWEUnit.AoWHSMap.FSeatedPlayer)
                    {
                        Log.Execute(false, TExecuteTrigger.etEvent, null);
                    }

                    Log.Release();
                    var events = FExecuteEventLogBuffer.GetEvents(0);
                    FExecuteEventLogBuffer.RemoveEvent(events);
                }
            }
        }

