        // AoWHSMap.PAS:2088
        public bool ValidateMap(TStrings Messages)
        {
            TEMsg Msg = default;
            InitMsg(ref Msg, 537002243, this);
            Msg.Payload = Messages;
            Msg.Data[0] = 0;
            AoWEUnit.AoWHSMap.SendMsg(ref Msg, this);
            bool Result = Msg.Data[0] == 0;
            if (Result)
            {
                Messages.Add(AoWEUnit.TranslateRStr(AoWEUnit.MapSuccessfullyValidatedRStr));
