        // AoWHSMap.PAS:2703
        public int Random(int Range)
        {
            int Result;
            if (!AoWEUnit.AoWHSMap.Status.Contains(THSMapStatusElement.msDestroying))
            {
                if (GetSynchronised())
                {
                    RandSeed = FDefendersSeed;
                    Result = RtlUnit.Random(Range);
                    FDefendersSeed = RandSeed;
                }
                else
                {
                    RtlUnit.ShowMessage("Invalid AoWHSMap.Random use");
                    Result = 0;
                }
            }
            else
            {
                Result = RtlUnit.Random(Range);
            }

            return Result;
        }

        // AoWHSMap.PAS:2723
        public void GenerateNewTurnOrder()
        {
            int Index;
