            {
                FTurnTimerStart = GetElapsedMilliSeconds();
            }
        }

        // AoWHSMap.PAS:3114
        public void DisableTurnTimer()
        {
            int Time;
            Time = GetElapsedMilliSeconds() - FTurnTimerStart;
            if (Time > 0)
            {
                FTurnTimeElapsed -= Time;
            }

            FTurnTimerStart = -1;
        }

