            if (this.GetAttack(null) != 0)
            {
                Text.Add("Attack modifier: " + IntToStr(this.GetAttack(null)));
            }

            if (this.GetDefense(null) != 0)
            {
                Text.Add("Defense modifier: " + IntToStr(this.GetDefense(null)));
            }

            if (this.GetDamage(null) != 0)
            {
                Text.Add("Damage modifier: " + IntToStr(this.GetDamage(null)));
            }

            if (this.GetResistance(null) != 0)
            {
                Text.Add("Resistance modifier: " + IntToStr(this.GetResistance(null)));
            }

            if (Mode.Contains(TAbilityInfoModeElement.aimDescription))
            {
                Text.Add("Description: ");
                Text.AddStrings(FDescription);
            }

            if (this.GetCombatMode(null) != TCombatMode.cmNone)
            {
                var combatMode = this.GetCombatMode(null);
                Text.Add("Combat mode: " + AoWEUnit.TranslateRStr(AoWEUnit.TCombatModeRStr[(int)combatMode]));
            }

            if (Mode.Contains(TAbilityInfoModeElement.aimStatistics))
            {
                this.GetCombatInfo(null, ref Info);
                if (Info.Attack != -1)
                {
                    Text.Add("Attack: " + IntToStr(Info.Attack));
                }

                if (Info.Damage != -1)
                {
                    Text.Add("Damage: " + IntToStr(Info.Damage));
                }

                if (Info.RepeatCount != -1)
                {
                    Text.Add("Repeat: " + IntToStr(Info.RepeatCount));
                }

                if (Info.DamageTypes != TSet<TDamageType>.Of())
                {
                    DamageNames = "";
                    for (int damageTypeOrdinal = (int)(TDamageType)0; damageTypeOrdinal <= (int)(TDamageType)9; damageTypeOrdinal++)
                    {
                        DamageType_ = (TDamageType)damageTypeOrdinal;
                        if (Info.DamageTypes.Contains(DamageType_))
                        {
                            if (!IsEmpty(DamageNames))
                            {
                                DamageNames = DamageNames + ",";
                            }

                            DamageNames = DamageNames + AoWEUnit.TranslateRStr(AoWEUnit.TDamageTypeRStr[(int)DamageType_]);
                        }
                    }

                    Text.Add("Damage Types: " + DamageNames);
                }
            }

            if (Mode.Contains(TAbilityInfoModeElement.aimStrength))
            {
                this.GetOffensiveStrength(null, ref Strength, ref Types);
                if (Strength != 0)
                {
                    Text.Add("Strength: " + IntToStr(Strength));
                }
            }
        }

        // Ability.PAS:1331
        public virtual void GetCombatInfo(TAbilityOwner Owner, ref TAbilityCombatInfo Info)
        {
            ref var abilityCombatInfo = ref Info;
            abilityCombatInfo.Attack = -1;
            abilityCombatInfo.Damage = -1;
            abilityCombatInfo.DamageTypes = TSet<TDamageType>.Of();
            abilityCombatInfo.RepeatCount = -1;
        }

        // Ability.PAS:1252
        // class receiver
        public void ShowInfo(TAbilityOwner Owner, TImageLibraryFont Font, int X, int Y, in TSurfaceDesc Surface)
        {
            Font.SetText(X, Y, this.GetName(Owner), Surface);
        }

        // Ability.PAS:1260
        public void SetAb(TAbilityOwner Owner, int Index, byte Value)
        {
            Owner.SetAbSet(Index, Value);
        }

        // Ability.PAS:1445
        public virtual EClass AbilityDataClass() => default;

        public virtual bool CanExpand(TAbilityOwner owner) => !owner.GetAbSet(FAbilityID) && (owner.GetAbilitySelectionTypes() & FSelectionTypes) != default(TSet<TAbilitySelectionType>);
        public virtual int ExpandCost(TAbilityOwner owner) => FSkillPointCost;

        public virtual bool Remove(TAbilityOwner owner)
        {
            if (!owner.GetAbSet(FAbilityID)) return false;
            owner.SetAbSet(FAbilityID, 0);
            return true;
        }

        public virtual bool GetInherent(TAbilityOwner owner) => owner.GetAbSet(FAbilityID);
        public virtual int GetSkillPoints(TAbilityOwner owner) => owner.GetAbSet(FAbilityID) ? FSkillPointCost : 0;
        public virtual bool GetEnabled(TAbilityOwner owner) => owner.GetAbSet(FAbilityID);
    }

