            base.ReadWrite(Stream);
            if ((Stream.StorageMode() & TSet<TStorageModeElement>.Of(TStorageModeElement.smRead, TStorageModeElement.smCompare)) == TSet<TStorageModeElement>.Of(TStorageModeElement.smRead))
            {
                // The original tests property 3 before reading the data-ID list.
                if (Stream.PropertyTable.PropertyExist(3))
                {
