                            FAbilityData = Data;
                        }
                    }

                    IDs?.Dispose();
                }
            }
            else
            {
                if ((Stream.StorageMode() & TSet<TStorageModeElement>.Of(TStorageModeElement.smWrite)) == TSet<TStorageModeElement>.Of(TStorageModeElement.smWrite))
                {
