                    if ((Stream.StorageMode() & TSet<TStorageModeElement>.Of(TStorageModeElement.smCompare)) == TSet<TStorageModeElement>.Of(TStorageModeElement.smCompare))
                    {
                        Data = FAbilityData;
                        while (Data != null)
                        {
                            var abilityID = Data.GetAbilityID();
