        public void RemoveAbilityData(TAbilityData Data)
        {
            TAbilityData Current;
            TAbilityData Previous;
            Current = FAbilityData;
            Previous = null;
            while (Current != null && Current != Data)
            {
                Previous = Current;
                Current = Current.FNext;
            }

            if (Current == Data)
            {
                // { Original dereferences nil when Data is nil. }
                if (Previous != null)
                {
                    Previous.FNext = Current.FNext;
                }
                else
                {
                    FAbilityData = Current.FNext;
                }

                Current?.Dispose();
            }
        }

