            while (Current != null && Current.GetAbilityID() != AbilityID)
            {
                Previous = Current;
                Current = Current.FNext;
            }

            if (Current != null && Current.GetAbilityID() == AbilityID)
            {
                if (Previous != null)
                {
                    Previous.FNext = Current.FNext;
                }
                else
                {
                    FAbilityData = Current.FNext;
