    // (FAbilities, FAbilitiesByType,)
    public partial class TAbilityControl : TEObject
    {
        // Ability.PAS:2035
        public TAbilityControl(TECustomNode owner) : base(owner)
        {
            TAbilityType Kind;

            FAbilities = new TList();
            for (int kindOrdinal = (int)(TAbilityType)0; kindOrdinal <= (int)(TAbilityType)4; kindOrdinal++)
            {
                Kind = (TAbilityType)kindOrdinal;
                var abilityTypeList = new TAbilityTypeList();
                FAbilitiesByType[(int)Kind] = abilityTypeList;
            }
        }

        public TList FAbilities;
        public FixedArray_Aow_Units_AoWE_TAbilityTypeList_5 FAbilitiesByType;

        // Ability.PAS:2044
        public override void Dispose()
        {
            TAbilityType Kind;
            UnregisterAll();
            for (int kindOrdinal = (int)(TAbilityType)0; kindOrdinal <= (int)(TAbilityType)4; kindOrdinal++)
            {
                Kind = (TAbilityType)kindOrdinal;
                FAbilitiesByType[(int)Kind]?.Dispose();
            }

            FAbilities?.Dispose();
            base.Dispose();
        }

        // Ability.PAS:2053
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            for (int I = 0, last = FAbilities.Count - 1; I <= last; I++)
            {
                if (FAbilities[I] != null)
                {
                    Stream.rwEObject((TEObject)FAbilities[I], I + 10);
                }
            }
        }

        // Ability.PAS:2061
        public int GetCount() => FAbilities.Count;

        // Ability.PAS:2078
        public void RegisterAbility(TAbility Ability)
        {
            int ID;
            ID = Ability.FAbilityID;
            if (ID != -1)
            {
                if (ID < this.FAbilities.Count && this.FAbilities[ID] != null)
                {
                    throw new InvalidOperationException("Ability already registered (" + IntToStr(ID) + ")");
                }

                while (ID >= FAbilities.Count)
                {
                    FAbilities.Add(null);
                }

                FAbilities.List[ID] = Ability;
                var abilityType = Ability.GetAbilityType();
                FAbilitiesByType[(int)abilityType].Add(Ability);
                Ability.FImageSequences.LinkToIL();
            }
            else
            {
                throw new ArgumentException("Invalid AbilityID (" + Ability.GetType().Name + ")");
            }
        }

        // Ability.PAS:2096
        public void UnregisterAbility(TAbility Ability)
        {
            int ID;
            ID = Ability.FAbilityID;
            if (ID != -1)
            {
                if (ID < 0 || ID >= FAbilities.Count || FAbilities[ID] != Ability)
                {
                    throw new InvalidOperationException("Cannot Unregister Ability (" + IntToStr(ID) + ")");
                }

                if (FAbilities.List[ID] != null)
                {
                    var abilityType = Ability.GetAbilityType();
                    FAbilitiesByType[(int)abilityType].Remove(Ability);
                    ((TAbility)FAbilities.List[ID]).FImageSequences.ReleaseIL();
                    (FAbilities.List[ID] as IDisposable)?.Dispose();
                    FAbilities.List[ID] = null;
                }
            }
            else
            {
                throw new ArgumentException("Invalid AbilityID (" + Ability.GetType().Name + ")");
            }
        }

        // Ability.PAS:2116
        public void UnregisterAll()
        {
            for (int I = FAbilities.Count - 1; I >= 0; I--)
            {
                if (FAbilities[I] != null)
                {
                    UnregisterAbility((TAbility)FAbilities[I]);
                }
            }
        }

        // Ability.PAS:2129
        public void ListAbilities(TStrings Text, TSet<TAbilitySelectionType> Types)
        {
            Text.Clear();
            for (int I = 0, last = this.FAbilities.Count - 1; I <= last; I++)
            {
                if (this.FAbilities.List[I] != null)
                {
                    if ((((TAbility)this.FAbilities.List[I]).FSelectionTypes & Types) != TSet<TAbilitySelectionType>.Of() || (Types == TSet<TAbilitySelectionType>.Of().WithRange(0, (TAbilitySelectionType)9) && ((TAbility)this.FAbilities.List[I]).FSelectionTypes == TSet<TAbilitySelectionType>.Of()))
                    {
                        Text.AddObject(((TAbility)this.FAbilities.List[I]).GetName(null), IntToObject(I));
                    }
                }
            }
        }

        // Ability.PAS:2148
        public void ListAbilityInfo(TStrings Text, bool SortByName, TSet<TAbilityInfoModeElement> Mode)
        {
            TList List = default;
            List = new TList();
            for (int I = 0, last = FAbilities.Count - 1; I <= last; I++)
            {
                if (FAbilities.List[I] != null)
                {
                    List.Add(FAbilities.List[I]);
                }
            }

            if (SortByName)
            {
                List.Sort(AoWEUnit.CompareAbilityNames);
            }

            // { Original frees the temporary list only after all ability callbacks succeed. }
            for (int I = 0, last = List.Count - 1; I <= last; I++)
            {
                ((TAbility)List[I]).ListInfo(Text, Mode);
                Text.Add("-------------------------------------------------");
                Text.Add("");
            }

            List?.Dispose();
        }

        // intf_P1_06.inc:178
        public void UnregisterAbilityID(int id)
        {
            if (FAbilities[id] is TAbility ability) UnregisterAbility(ability);
        }

        public TAbility GetAbility(int index)
        {
            Assert(index >= 0, "Invalid AbilityID", "Ability.PAS", 2069);
            return index < FAbilities.Count ? (TAbility)FAbilities[index] : null;
        }
    }
}

