        public void LinkToIL()
        {
            ReleaseIL();
            if (!IsEmpty(FImageLibraryName))
            {
                FImageLibrary = AoWEUnit.AoWHSSet.ImageLibraryManager.LinkToIL(TSet<TILManagerCategoryElement>.Of(TILManagerCategoryElement.icDisk), FImageLibraryName);
            }
            else
            {
                FImageLibrary = null;
            }
        }

        // Army.PAS:5116
        public void ReleaseIL()
        {
            if (FImageLibrary != null)
            {
                if (!IsEmpty(FImageLibraryName))
                {
                    AoWEUnit.AoWHSSet.ImageLibraryManager.ReleaseIL(TSet<TILManagerCategoryElement>.Of(TILManagerCategoryElement.icDisk), FImageLibraryName);
                }

                FImageLibrary = null;
            }
        }

        // Army.PAS:5126
