    // item ID, action, hero ID
    public partial class TItemTE : TTokenEvent
    {
        public TItemTE(TECustomNode owner) : base(owner)
        { }

        public new const int ClassID = 131698;

        public int FItemID;
        public byte FAction;
        // 0 = use
        public int FHeroID;

        // Army.PAS:4185
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwInteger(ref FItemID, 20);
            Stream.rwData(Bytes.Of(ref FAction, 1), 1, 21);
            Stream.rwInteger(ref FHeroID, 22);
        }

        // Army.PAS:4193
        public override TExecuteResult Execute(TTokenExecuter TE)
        {
            TExecuteResult Result;
            bool Done;
            TItem Item;
            THero Hero;
            base.Execute(TE);
            Done = false;
            Item = AoWEUnit.AoWHSMap.FItemControl.FindItem(FItemID);
            if (Item != null)
            {
                switch (FAction)
                {
                    case 0:
                        Hero = AoWEUnit.AoWHSMap.FHeroControl.FindID(FHeroID);
                        if (Hero != null)
                        {
                            Done = Item.ExecuteUse(Hero);
                        }
                        else
                        {
                            Done = false;
                        }

                        break;
                }
            }

            if (Done)
            {
                Result = TExecuteResult.erDone;
            }
            else
            {
                Result = TExecuteResult.erDoneHalt;
            }

            return Result;
        }

        // NetworkE.pas:230

    }
}

