                {
                    Result = true;
                }
                else
                {
                    Result = false;
                    var spell = AoWEUnit.AoWHSSet.FSpellControl.GetSpell(FSpellID);
                    Reason = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.ItemSpellAlreadyResearchedRStr), [spell.FSpellName]);
                }
            }
            else
            {
                Result = false;
                Reason = AoWEUnit.TranslateRStr(AoWEUnit.ItemNotUseableRStr);
            }

            return Result;
