            if (CanUse(Hero, ref Reason) && !AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Hero.FPlayer).GetBusy())
            {
                Event = new TItemTE(null);
                Event.FItemID = FItemID;
                Event.FHeroID = Hero.FUnitID;
                AoWEUnit.AoWHSMap.FTokenManager.GetTokenControl(Hero.FPlayer).AddEvent(Event);
                Event.Release();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Army.PAS:4255
        public virtual bool ExecuteUse(THero Hero)
        {
            string Reason = "";
            // { Original reports success even when CanUse rejects the item. }
            bool Result = true;
            if (CanUse(Hero, ref Reason))
            {
                switch (FItemType)
                {
                    case TItemType.itScroll:
                        AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Hero.FPlayer).FMagicControl.ExecuteSpellResearched(FSpellID);
                        if (AoWEUnit.AoWHSMap.FSeatedPlayer == Hero.FPlayer)
                        {
                            PlaySample("SFX\\ATTACK\\MAGICB01.WAV");
                            var spell = AoWEUnit.AoWHSSet.FSpellControl.GetSpell(FSpellID);
                            var format = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.ItemSpellResearchedRStr), [spell.FSpellName]);
                            AoWEUnit.AoWHSMap.ShowMessage(format);
                        }

                        Dispose();
                        Hero.Changed();
                        break;
                }
            }

            return Result;
        }

        // Army.PAS:4418
