        {
            if (!FStatus.Contains(TItemStatusElement.isActivated))
            {
                if (AoWEUnit.AoWHSMap.Status.Contains(THSMapStatusElement.msEditting) || AoWEUnit.AoWHSMap.FDay == 0)
                {
