            if (FLibraryID != -1)
            {
                Item = AoWEUnit.AoWHSSet.FItemLibraries.FindItem(FLibraryName, FLibraryID);
                if (Item != null)
                {
                    ID = FItemID;
                    Assign(Item, AoWEUnit.AoWEngine);
                    FItemID = ID;
                    Changed();
                }
                else
                {
