            return Result;
        }

        // Army.PAS:4474
        public bool PlaceOnMap(TAbstractAoWHSMap Map, sbyte X, sbyte Y, sbyte L)
        {
            bool Result;
            TItemHS HS;
            if (X >= 0 && Y >= 0 && L >= 0 && X < Map.MapContainer.Width && Y < Map.MapContainer.Height && L < Map.MapContainer.LevelCount && Map.MapContainer.GetField(X, Y, L).TerrainType != 15)
            {
                HS = (TItemHS)Map.MapContainer.GetField(X, Y, L).FindOwnedChild(131697);
                if (HS == null)
                {
                    HS = new TItemHS(null);
                    if (!Map.PlaceHX(HS, X, Y, L))
                    {
                        HS?.Dispose();
                        HS = null;
                    }
                }

                if (HS != null)
                {
                    SetOwner(HS.FItems);
                    Result = true;
                }
                else
                {
                    Result = false;
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Army.PAS:4501
        public void EditDropMsg(ref TItemDropMsg Msg)
        {
            int X = default;
            int Y = default;
            int L;
            L = Msg.Lhp;
            HPtoHX(Msg.Xhp, Msg.Yhp, ref X, ref Y);
            if (!PlaceOnMap(AoWEUnit.AoWHSMap, (sbyte)X, (sbyte)Y, (sbyte)L))
            {
                Msg.Result = -1;
            }
            else
            {
                Msg.Result = 0;
            }
        }

