    // system library, libraries
    public partial class TItemLibraryManager : TEObject
    {
        // Army.PAS:4967
        public TItemLibraryManager(TECustomNode owner) : base(owner)
        {
            FSystemLibrary = new TItemLibrary(null);
            FLibraries = new TENode(null);
        }

        public TItemLibrary FSystemLibrary;
        public TENode FLibraries;

        // Army.PAS:4974
        public override void Dispose()
        {
            FLibraries?.Dispose();
            FSystemLibrary?.Dispose();
            base.Dispose();
        }

        // Army.PAS:4981
        public override void ReadWrite(TEStorageStream Stream)
        {
            string Directory;
            base.ReadWrite(Stream);
            if ((Stream.StorageMode() & TSet<TStorageModeElement>.Of(TStorageModeElement.smTextOnly, TStorageModeElement.smCompare)) == TSet<TStorageModeElement>.Of())
            {
                Directory = ExtractFilePath(AoWEUnit.AoWEngine.HSSFileName);
                if (Stream.StorageMode().Contains(TStorageModeElement.smRead))
                {
                    ReadUserLibraries();
                    AoWEUnit.AoWEngine.ReadFromFile(Directory + "ITEMS.PFS", FSystemLibrary, null);
                }
                else
                {
                    AoWEUnit.AoWEngine.WriteToFile(Directory + "ITEMS.PFS", FSystemLibrary, null);
                    WriteUserLibraries();
                }
            }
            else
            {
                Stream.rwEObject(FSystemLibrary, 20);
            }
        }

        // Army.PAS:5002
        public TItemLibrary GetLibrary(int Index) => (TItemLibrary)FLibraries.FChildren.EObjects[Index];

        // Army.PAS:5007
        public int GetCount() => FLibraries.Count;

        // Army.PAS:5012
        public void ReadUserLibraries()
        {
            TItemLibrary ItemLibrary;
            FLibraries.Clear();
            FLibraries.AddChild(FSystemLibrary);
            // Both extensions list, and a list present in both forms loads its own document once
            // (own-formats.md 4.2).
            foreach (var Listed in FileBoundary.FindDocuments(AoWEUnit.AoWEngine.StartupDirectory + "User\\", Aow.Formats.DocumentKind.ItemList))
            {
                ItemLibrary = new TItemLibrary(null);
                try
                {
                    ItemLibrary.LoadFromFile(AoWEUnit.AoWEngine.StartupDirectory + "User\\" + Listed);
                    ItemLibrary.SetOwner(FLibraries);
                }
                catch
                {
                    ItemLibrary?.Dispose();
                }
            }
        }

        // Army.PAS:5033
        public void WriteUserLibraries()
        {
            TItemLibrary ItemLibrary;
            for (int I = 1, last = FLibraries.Count - 1; I <= last; I++)
            {
                ItemLibrary = GetLibrary(I);
                var name = ItemLibrary.GetName();
                ItemLibrary.SaveToFile(AoWEUnit.AoWEngine.StartupDirectory + "User\\" + name + FileBoundary.WriteExtension(Aow.Formats.DocumentKind.ItemList));
            }
        }

        // Army.PAS:5043
        public int IndexOfLibraryName(string Name)
        {
            int Result = FLibraries.Count;
            while (Result != 0)
            {
                Result -= 1;
                if (CompareText(Name, ((TItemLibrary)FLibraries.FChildren.List[Result]).FName) == 0)
                {
                    return Result;
                }
            }

            return -1;
        }

        // Army.PAS:5054
        public int IndexOfLibrary(TItemLibrary ItemLibrary) => FLibraries.FChildren.IndexOf(ItemLibrary);

        // Army.PAS:5059
        public TItem FindItem(string LibraryName, int LibraryID)
        {
            TItem Result;
            int Index;
            Index = IndexOfLibraryName(LibraryName);
            if (Index != -1)
            {
                Result = ((TItemLibrary)FLibraries.FChildren.List[Index]).FindLibraryID(LibraryID);
            }
            else
            {
                Result = null;
            }

            return Result;
        }

        // Army.PAS:5068
        public TItemLibrary CreateLibrary(string Name)
        {
            TItemLibrary Result;
            string LibraryName;
            LibraryName = Name;
            // { Original retains the period when stripping the extension. }
            if (Pos(".", LibraryName) != 0)
            {
                LibraryName = RtlUnit.Copy(LibraryName, 1, Pos(".", LibraryName));
            }

            if (!IsEmpty(LibraryName) && IndexOfLibraryName(LibraryName) == -1)
            {
                Result = new TItemLibrary(FLibraries);
                Result.FName = LibraryName;
                // { Original creates in Release while reading and deleting from User. }
                Result.SaveToFile(AoWEUnit.AoWEngine.StartupDirectory + "Release\\" + LibraryName + FileBoundary.WriteExtension(Aow.Formats.DocumentKind.ItemList));
            }
            else
            {
                Result = null;
            }

            return Result;
        }

        // Army.PAS:5084
        public void DeleteLibrary(int Index)
        {
            if (Index < FLibraries.Count && Index > 0)
            {
                var name = GetLibrary(Index).GetName();
                // The list goes in both forms, so an original of the same name does not return.
                DeleteFile(AoWEUnit.AoWEngine.StartupDirectory + "User\\" + name + Aow.Formats.DocumentKind.ItemList.OriginalExtension);
                DeleteFile(AoWEUnit.AoWEngine.StartupDirectory + "User\\" + name + Aow.Formats.DocumentKind.ItemList.OwnExtension);
                GetLibrary(Index)?.Dispose();
            }
        }

        // intf_P2_04.inc:157

    }

