        // Unit.PAS:1796
        public virtual bool CanJoin(sbyte Player)
        {
            bool Result;
            TAlignment Alignment;
            TDiplomaticRelation Relation;
            int I;
            bool condition = FGroup == null;
            if (!condition)
            {
                var behavior = FGroup.GroupClass.Behavior;
                condition = !TSet<TGroupBehavior>.Of(TGroupBehavior.gbGuard, TGroupBehavior.gbGuardArea).Contains(behavior);
            }

            if (condition)
            {
                if (GetRace() == -1)
                {
                    var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
                    Alignment = AoWEUnit.AoWHSSet.FRaceResources.GetRaceResource(players.FPlayerRace).GetAlignment();
                    if (GetAlignment() != TAlignment.alNone)
                    {
                        Relation = AoWEUnit.dAlignmentToDiplomaticRelation(GetAlignment(), Alignment);
                        if (Relation == TDiplomaticRelation.drUnknown && this is TUnit)
                        {
                            Result = false;
                            I = AoWEUnit.AoWHSMap.FRaces.Count;
                            while (!Result && I != 0)
                            {
                                I -= 1;
                                bool test = AoWEUnit.AoWHSMap.FRaces.GetRace(I).GetPlayerRelation(Player) >= TStatus.sPolite;
                                if (test)
                                {
                                    var unitResourceIndex = ((TUnit)this).FUnitResource.UnitResourceIndex();
                                    test = AoWEUnit.AoWHSSet.FRaceResources.GetRaceResource(I).FUnitIndexes.IndexOf(unitResourceIndex) != -1;
                                }

                                Result = test;
                            }
                        }
                        else
                        {
                            Result = Relation == TDiplomaticRelation.drPeace;
                        }
                    }
                    else
                    {
                        Result = true;
                    }
                }
                else
                {
                    var race = GetRace();
                    Result = AoWEUnit.AoWHSMap.FRaces.GetRace(race).GetPlayerRelation(Player) >= TStatus.sPolite;
                }

                if (Result && FGroup != null && FGroup.GroupClass.Behavior == TGroupBehavior.gbHunt && ((THuntAG)FGroup).HuntingPlayer(Player))
                {
                    Result = false;
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

