        // Unit.PAS:1843
        public virtual bool OfferToJoin(sbyte Player)
        {
            bool Result;
            TUnitUserList Group;
            TAlignment Alignment;
            if (CanJoin(Player))
            {
                if (GetRace() != -1)
                {
                    var race = GetRace();
                    Result = AoWEUnit.AoWHSMap.FRaces.GetRace(race).GetPlayerRelation(Player) >= TStatus.sPolite;
                }
                else
                {
                    Group = FGroup;
                    if (Group != null && ((TAIGroup)(object)Group).GroupClass.Behavior == TGroupBehavior.gbRefuge)
                    {
                        var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
                        Alignment = AoWEUnit.AoWHSSet.FRaceResources.GetRaceResource(players.FPlayerRace).GetAlignment();
                        if ((GetAlignment() != TAlignment.alNone || GetUnitType() == TUnitType.utMachine) && AoWEUnit.dAlignmentToDiplomaticRelation(GetAlignment(), Alignment) != TDiplomaticRelation.drPeace)
                        {
                            Result = false;
                        }
                        else
                        {
                            Result = true;
                        }
                    }
                    else
                    {
                        Result = false;
                    }
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

