        // Unit.PAS:152
        // { A stack-argument assembler routine gets an EBP frame; remove it before jumping. }
        public void RetrieveDamageInfo(sbyte Attack, sbyte Damage, TSet<TDamageType> DamageTypes, ref int DamageValue, ref int ObtainValue)
        {
            int MaxDamage;
            MaxDamage = GetHitPoints() * 100;
            DamageValue = AoWEUnit.StatisticsToDV(Attack, Damage, DamageTypes, GetDefense(), GetResistance(), GetImmunityTypes(), GetProtectionTypes());
            if (MaxDamage < DamageValue)
            {
                DamageValue = MaxDamage;
            }

            if (DamageValue > 0 && GetHitPoints() > 0)
            {
                if (MaxDamage > DamageValue)
                {
                    ObtainValue = Round((double)GetObtainValue() * ((double)((double)DamageValue * 0.75) / MaxDamage));
                }
                else
                {
                    ObtainValue = GetObtainValue();
                }
            }
            else
            {
                ObtainValue = 0;
            }
        }

