            if (Player != 0)
            {
                if (Race != -1 && !GetAbilityEnabled(107))
                {
                    Result = AoWEUnit.AoWHSMap.FRaces.GetRace(Race).GetPlayerRelationValue(Player);
                }
                else
                {
                    var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
                    var playerAlignment = AoWEUnit.AoWHSSet.FRaceResources.GetRaceResource(players.FPlayerRace).GetAlignment();
                    var unitAlignment = GetAlignment();
                    Result = AoWEUnit.P2AlignmentToStatusValue[(int)unitAlignment][(int)playerAlignment];
                }
            }
            else
            {
                var iRtoAlignment = AoWEUnit.IRtoAlignment(IndependentRelation);
                var alignment = GetAlignment();
                Result = AoWEUnit.P2AlignmentToStatusValue[(int)alignment][(int)iRtoAlignment];
            }

            return Result;
        }

