        // Unit.PAS:312
        public sbyte UpdateMoraleValue()
        {
            int Player;
            int Value;
            TAbstractUnit AUnit;
            Player = FPlayer;
            Value = GetUnitMoraleValue((sbyte)Player, GetIndependentRelation());
            if (!AoWEUnit.AoWHSMap.Status.Contains(THSMapStatusElement.msEditting) && GetUnitType() != TUnitType.utMachine && !(this is TLeader) && Owner is TArmy)
            {
                if (GetUpkeep() != 0 && Player > 0 && !GetAbilityEnabled(155))
                {
                    Value += AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FMoraleValue;
                }

                for (int I = Owner.Count - 1; I >= 0; I--)
                {
                    AUnit = (TAbstractUnit)((TEChangeNotifyNode)(object)Owner).FChildren.List[I];
                    if (AUnit.GetAbilityEnabled(37) && AUnit != this)
                    {
                        Value += 30;
                    }
                    else
                    {
                        if (TSet<TStatus>.Of(TStatus.sHostile, TStatus.sWary).Contains(UnitRelation(AUnit)))
                        {
                            Value -= 10;
                        }
                    }
                }
            }

            if (Value > 125)
            {
                FMoraleValue = 125;
            }
            else
            {
                if (Value < -25)
                {
                    FMoraleValue = -25;
                }
                else
                {
                    FMoraleValue = (sbyte)Value;
                }
            }

            return FMoraleValue;
        }

