        // Unit.PAS:358
        public void UpdateEnchanted()
        {
            int I;
            TAbilityTypeList List;
            bool Enchanted;
            List = AoWEUnit.AoWHSSet.FAbilityControl.FAbilitiesByType[4];
            Enchanted = false;
            I = List.Count;
            while (!Enchanted && I != 0)
            {
                I -= 1;
                Enchanted = GetAbilityEnabled(List.GetAbility(I).FAbilityID);
            }

            if (Enchanted)
            {
                FUnitStatus = FUnitStatus + TSet<TUnitStatusElement>.Of(TUnitStatusElement.usEnchanted);
            }
            else
            {
                FUnitStatus = FUnitStatus - TSet<TUnitStatusElement>.Of(TUnitStatusElement.usEnchanted);
            }
        }

        // Unit.PAS:375
        public void RemoveEnchantments()
        {
            TAbility Ability;
            TAbilityTypeList List;
            AddRef();
            List = AoWEUnit.AoWHSSet.FAbilityControl.FAbilitiesByType[4];
            for (int I = List.Count - 1; I >= 0; I--)
            {
                Ability = List.GetAbility(I);
                if (Ability is TUnitEnchantmentAbility && GetAbilityEnabled(Ability.FAbilityID))
                {
                    RemoveAbility(Ability.FAbilityID);
                }
            }

            Release();
        }

