            }
        }

        // Unit.PAS:657
        public int GetStrength(TDamageType DamageType)
        {
            if (!FUnitStatus.Contains(TUnitStatusElement.usActivated))
            {
                UpdateDefensiveStrength();
                UpdateOffensiveStrength();
            }

            int Result = FOffensiveStrength[(int)DamageType];
            if (Result != 0)
            {
                Result = (Result + 10) * FDefensiveStrength;
            }

            return Result;
        }

        // Unit.PAS:664
        public int GetStrengthMax(TSet<TDamageType> DamageTypes)
        {
            int Result;
            TDamageType DamageType;
            if (!FUnitStatus.Contains(TUnitStatusElement.usActivated))
            {
                UpdateDefensiveStrength();
                UpdateOffensiveStrength();
            }

            if (DamageTypes != AoWEUnit.TAbstractUnit_GetStrengthMax__AllDamageTypes)
            {
                Result = 0;
                for (int damageTypeOrdinal = (int)(TDamageType)0; damageTypeOrdinal <= (int)(TDamageType)9; damageTypeOrdinal++)
                {
                    DamageType = (TDamageType)damageTypeOrdinal;
                    if (DamageTypes.Contains(DamageType))
                    {
                        if (Result < FOffensiveStrength[(int)DamageType])
                        {
                            Result = FOffensiveStrength[(int)DamageType];
                        }
                    }
                }

                if (Result != 0)
                {
                    Result = (Result + 10) * FDefensiveStrength;
                }
            }
            else
            {
                if (FMaxOffensiveStrength != 0)
                {
                    Result = (FMaxOffensiveStrength + 10) * FDefensiveStrength;
                }
                else
                {
                    Result = 0;
                }
            }

            return Result;
        }

        // Unit.PAS:688
        public int GetCombatValue(TAbstractUnit Target, byte Mode)
        {
            int Value;
            TAbilityTypeList Abilities;
            TAbility Ability;
            TAbilityDamageValues Info = default;
            int Result = 0;
            Abilities = AoWEUnit.AoWHSSet.FAbilityControl.FAbilitiesByType[(int)TAbilityType.atCombat];
            for (int I = Abilities.Count - 1; I >= 0; I--)
            {
                Ability = Abilities.GetAbility(I);
                if (GetAbilityEnabled(Ability.FAbilityID))
                {
                    Ability.GetDamageValueEx(this, Target, (TWallSituation)Mode, ref Info);
                    if (Info.SourceDamage > 0)
                    {
                        Value = Info.SourceDamage * Info.SourceDamage / (Info.TargetDamage + Info.SourceDamage);
                        if (Value <= 0)
                        {
                            Value = 1;
                        }

                        if (Value > Result)
                        {
                            Result = Value;
                        }
                    }
                }
            }

            return Result;
        }

