        // Unit.PAS:922
        public void CreateMovePointTable(ref FixedArray_Aow_Units_FixedArray_sbyte_16_16 Table)
        {
            TSet<TMoveType> Moves;
            int Points;
            sbyte Value;
            bool Faster;
            bool Slower;
            Moves = GetMoveTypes();
            if (AoWEUnit.AoWHSMap.FCombat != null)
            {
                Moves = Moves - TSet<TMoveType>.Of(TMoveType.mtTunneling);
            }

            var moveTypesToInt = AoWEUnit.MoveTypesToInt(Moves);
            Table = AoWEUnit.MovePointTables[moveTypesToInt];
            if (FPlayer > 0)
            {
                if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.FActiveEnchantments.Contains(TPlayerEnchantmentType.petEnchantedRoads))
                {
                    for (int Terrain = 0; Terrain <= 15; Terrain++)
                    {
                        if (Table[Terrain][4 - -1] != -1)
                        {
                            Table[Terrain][4 - -1] = 2;
                        }
                    }
                }

                if (GetAbilityEnabled(23) || GetAbilityEnabled(1) || GetAbilityEnabled(165))
                {
                    Faster = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.FActiveEnchantments.Contains(TPlayerEnchantmentType.petAirMastery);
                    Slower = (((byte)AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.FEnemyEnchantments.Image) & 4) != 0;
                    if (Faster && !Slower)
                    {
                        for (int Overlay = -1; Overlay <= 11; Overlay++)
                        {
                            for (int Terrain = 0; Terrain <= 15; Terrain++)
                            {
                                Value = Table[Terrain][Overlay - -1];
                                if (Value > 2)
                                {
                                    Table[Terrain][Overlay - -1] = (sbyte)(int)(((uint)(Value + 1)) >> 1);
                                }
                            }
                        }
                    }
                    else
                    {
                        if (!Faster && Slower)
                        {
                            for (int Overlay = -1; Overlay <= 11; Overlay++)
                            {
                                for (int Terrain = 0; Terrain <= 15; Terrain++)
                                {
                                    if (Table[Terrain][Overlay - -1] >= 1)
                                    {
                                        Table[Terrain][Overlay - -1] = (sbyte)(Table[Terrain][Overlay - -1] * 2);
                                    }
                                }
                            }
                        }
                    }
                }

                if (GetAbilityEnabled(152))
                {
                    for (int Overlay = -1; Overlay <= 11; Overlay++)
                    {
                        for (int Terrain = 0; Terrain <= 15; Terrain++)
                        {
                            Points = Table[Terrain][Overlay - -1];
                            if (Points > 2)
                            {
                                Points -= 1;
                                // { Original retains this redundant lower bound after Points > 2. }
                                if (Points < 2)
                                {
                                    Points = 2;
                                }
                            }

                            Table[Terrain][Overlay - -1] = (sbyte)Points;
                        }
                    }
                }

                if (GetAbilityEnabled(132))
                {
                    for (int Overlay = -1; Overlay <= 11; Overlay++)
                    {
                        for (int Terrain = 0; Terrain <= 15; Terrain++)
                        {
                            Points = Table[Terrain][Overlay - -1];
                            if (Points > 0)
                            {
                                Table[Terrain][Overlay - -1] = (sbyte)(Points + 2);
                            }
                        }
                    }
                }
            }
        }

        // Unit.PAS:993
        public bool ValidTerrain(sbyte TerrainType, sbyte OverlayType)
        {
            bool Result;
            sbyte Cost;
            // { Original retrieves the movement set twice and retains the first dead store. }
            GetMoveTypes();
            var moveTypesToInt = AoWEUnit.MoveTypesToInt(GetMoveTypes());
            Cost = AoWEUnit.MovePointTables[moveTypesToInt][TerrainType][OverlayType - -1];
            if (Cost == -1 || Cost > GetMoves())
            {
                Result = false;
            }
            else
            {
                Result = true;
            }

            return Result;
        }

        // Unit.PAS:1011
        public void ExecuteTrailOfDarkness(TMapField MapField)
        {
            TMapLevel Level;
            THNWalkData Walk = default;
            TAoWMapField Field;
            Level = (TMapLevel)MapField.Owner;
            InitHNWalk(ref Walk, MapField.Xhx, MapField.Yhx, 0);
            while (Walk.Radius <= 1)
            {
                if (Walk.X >= 0 && Walk.X < Level.Width && Walk.Y >= 0 && Walk.Y < Level.Height)
                {
                    Field = (TAoWMapField)Level.GetField(Walk.X, Walk.Y);
                    if (Field.TerrainType != (int)TAoWTerrainType.ttBorder)
                    {
                        for (int Player = 1, last = AoWEUnit.AoWHSMap.FPlayers.Count - 1; Player <= last; Player++)
                        {
                            if (Player != FPlayer && AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FDiplomaticRelations.GetDiplomaticRelation((sbyte)Player) == TDiplomaticRelation.drWar && Field.GetExplored(Player) && !AoWEUnit.AoWHSMap.VisibleForPlayer(Walk.X, Walk.Y, MapField.Lhx, (sbyte)Player))
                            {
                                Field.SetExplored(Player, false);
                            }
                        }
                    }
                }

                WalkToNextHN(ref Walk);
            }

            AoWEUnit.AoWHSMap.MapChangedRad(MapField.Xhx, MapField.Yhx, MapField.Lhx, 1);
        }

