            Active = DamageTypes - GetImmunityTypes();
            if (Active != TSet<TDamageType>.Of())
            {
                DC = Attack - GetDefense();
                Result = AoWEUnit.ExecuteDamageRole(Damage, DC);
                if (Active - GetProtectionTypes() == TSet<TDamageType>.Of())
                {
                    Result = (Result + 1) / 2;
                }
            }

            return Result;
        }

        // Unit.PAS:1635
