                {
                    Attack -= 2;
                }

                Result = AoWEUnit.HitRole(Attack - GetResistance());
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Unit.PAS:1644
        public TSet<TDamageType> ExecuteDamageEffectsRole(TSet<TDamageType> DamageTypes)
        {
            TSet<TDamageType> Active;
            TSet<TDamageType> Protection;
            int Resistance;
            int EffectiveResistance;
            TSet<TDamageType> Result = TSet<TDamageType>.Of();
            Active = DamageTypes - GetImmunityTypes();
            if (Active != TSet<TDamageType>.Of())
            {
                Resistance = GetResistance();
                Protection = GetProtectionTypes();
                if (Active.Contains(TDamageType.dtFire) && !GetAbilityEnabled(7))
                {
                    if (Protection.Contains(TDamageType.dtFire))
                    {
                        EffectiveResistance = Resistance + 2;
                    }
                    else
                    {
                        EffectiveResistance = GetResistance();
                    }

                    if (AoWEUnit.HitRole(4 - EffectiveResistance))
                    {
                        Result = Result + TSet<TDamageType>.Of(TDamageType.dtFire);
                    }
                }

                if (Active.Contains(TDamageType.dtLightning) && GetUnitType() != TUnitType.utMachine && !GetAbilityEnabled(9))
                {
                    if (Protection.Contains(TDamageType.dtLightning))
                    {
                        EffectiveResistance = Resistance + 2;
                    }
                    else
                    {
                        EffectiveResistance = GetResistance();
                    }

                    if (AoWEUnit.HitRole(6 - EffectiveResistance))
                    {
                        Result = Result + TSet<TDamageType>.Of(TDamageType.dtLightning);
                    }
                }

                if (Active.Contains(TDamageType.dtPoison) && !GetAbilityEnabled(10))
                {
                    if (Protection.Contains(TDamageType.dtPoison))
                    {
                        EffectiveResistance = Resistance + 2;
                    }
                    else
                    {
                        EffectiveResistance = GetResistance();
                    }

                    if (AoWEUnit.HitRole(3 - EffectiveResistance))
                    {
                        Result = Result + TSet<TDamageType>.Of(TDamageType.dtPoison);
                    }
                }

                if (Active.Contains(TDamageType.dtDeath) && !GetAbilityEnabled(11))
                {
                    if (Protection.Contains(TDamageType.dtDeath))
                    {
                        EffectiveResistance = Resistance + 2;
                    }
                    else
                    {
                        EffectiveResistance = GetResistance();
                    }

                    if (AoWEUnit.HitRole(4 - EffectiveResistance))
                    {
                        Result = Result + TSet<TDamageType>.Of(TDamageType.dtDeath);
                    }
                }

                if (Active.Contains(TDamageType.dtHoly) && !GetAbilityEnabled(12))
                {
                    if (Protection.Contains(TDamageType.dtHoly))
                    {
                        EffectiveResistance = Resistance + 2;
                    }
                    else
                    {
                        EffectiveResistance = GetResistance();
                    }

                    if (AoWEUnit.HitRole(3 - EffectiveResistance) && GetUnitType() != TUnitType.utMachine)
                    {
                        Result = Result + TSet<TDamageType>.Of(TDamageType.dtHoly);
                    }
                }

                if (Active.Contains(TDamageType.dtCold) && !GetAbilityEnabled(8))
                {
                    if (Protection.Contains(TDamageType.dtCold))
                    {
                        EffectiveResistance = Resistance + 2;
                    }
                    else
                    {
                        EffectiveResistance = GetResistance();
                    }

                    if (AoWEUnit.HitRole(2 - EffectiveResistance))
                    {
                        Result = Result + TSet<TDamageType>.Of(TDamageType.dtCold);
                    }
                }
            }

            return Result;
        }

        // Unit.PAS:1699
        public TSet<TDamageType> ExecuteDamageEffects(TSet<TDamageType> DamageTypes)
        {
            TSet<TDamageType> Active;
            TSet<TDamageType> Result = TSet<TDamageType>.Of();
            Active = DamageTypes - GetImmunityTypes();
            // { Preserve EBX allocation and byte membership tests. }
            if (Active != TSet<TDamageType>.Of())
            {
                if (Active.Contains(TDamageType.dtPoison) && this.ExpandAbility(96))
                {
                    Result = Result + TSet<TDamageType>.Of(TDamageType.dtPoison);
                }

                if (Active.Contains(TDamageType.dtDeath) && this.ExpandAbility(93))
