        // Unit.PAS:1747
        public TDamageType OptimalDamageType(TSet<TDamageType> DamageTypes)
        {
            TSet<TDamageType> Active;
            TSet<TDamageType> Protection;
            TDamageType Result = TDamageType.dtNone;
            Active = DamageTypes - GetImmunityTypes();
            if (Active != TSet<TDamageType>.Of())
            {
                Protection = GetProtectionTypes();
                if (Protection == TSet<TDamageType>.Of() || Active - Protection == TSet<TDamageType>.Of())
                {
                    while (!Active.Contains(Result))
                    {
                        Result = (TDamageType)((int)Result - 1);
                    }
                }
                else
                {
                    while (!Active.Contains(Result) || Protection.Contains(Result))
                    {
                        Result = (TDamageType)((int)Result - 1);
                    }
                }
            }

            return Result;
        }

