        public virtual bool GetAbilitySet(int index) => (uint)index < (uint)FAbilityCount && (FAbilityBits[index >> 3] & (1 << (index & 7))) != 0;

        public override bool RemoveAbility(int ability)
        {
            AddRef();
            bool result = base.RemoveAbility(ability);
            Release();
            return result;
        }

        // Unit.PAS:713. TP2AbilityCalls is a layout view, not an instance type.
        public void ListAbilityInfo(TStrings names, TStrings types, TStrings sources)
        {
            names.Clear();
            sources?.Clear();
            for (int i = 0; i < GetAbilityCount(); i++)
            {
                if (!GetAbilitySet(i)) continue;
                var owner = GetAbilityOwner(i);
                var ability = AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(i);
                var name = ability.GetName(owner);
                if (!IsEmpty(name)) names.AddObject(name, IntToObject(i));
                types?.AddObject(AoWEUnit.TranslateRStr(AoWEUnit.TAbilityTypeRStr[(int)ability.GetAbilityType()]), IntToObject(i));
                var source = ability.GetSourceName(owner);
                sources?.AddObject(source, IntToObject(i));
            }
        }

        // Unit.PAS:1715. Native hard casts retain identity across the intermediate local type.
        public TSet<TDamageType> ExecuteCombatDamageEffects(TCombat combat, TSet<TDamageType> damageTypes)
        {
            TSet<TDamageType> result = default;
            var active = damageTypes - GetImmunityTypes();
            if (active == default(TSet<TDamageType>)) return result;
            if (active.Contains(TDamageType.dtFire) && ExpandAbility(127))
            {
                RemoveAbility(95);
                result += TSet<TDamageType>.Of(TDamageType.dtFire);
            }
            if (active.Contains(TDamageType.dtCold) && ExpandAbility(95))
            {
                var data = (TUnitEnchantmentAbilityData)GetAbilityData(95);
                if (data != null) data.FEnchantmentPlayerIndex = (sbyte)combat.FCombatData.FCurrentPlayer;
                RemoveAbility(127);
                result += TSet<TDamageType>.Of(TDamageType.dtCold);
            }
            if (active.Contains(TDamageType.dtLightning) && ExpandAbility(92))
            {
                var data = (TDurationAbilityData)GetAbilityData(92);
                if (data != null) data.FPlayerIndex = combat.FCombatData.FCurrentPlayer;
                result += TSet<TDamageType>.Of(TDamageType.dtLightning);
            }
            if (active.Contains(TDamageType.dtPoison) && ExpandAbility(96))
                result += TSet<TDamageType>.Of(TDamageType.dtPoison);
            if (active.Contains(TDamageType.dtDeath) && ExpandAbility(93))
                result += TSet<TDamageType>.Of(TDamageType.dtDeath);
            if (active.Contains(TDamageType.dtHoly) && ExpandAbility(98))
                result += TSet<TDamageType>.Of(TDamageType.dtHoly);
            return result;
        }

        public void UpdateOffensiveStrength()
        {
            var abilities = AoWEUnit.AoWHSSet.FAbilityControl.FAbilitiesByType[(int)TAbilityType.atCombat];
            FMaxOffensiveStrength = 0;
            FOffensiveStrength = default;
            for (int i = abilities.Count - 1; i >= 0; i--)
            {
                var ability = abilities.GetAbility(i);
                if (!GetAbilityEnabled(ability.FAbilityID)) continue;
                int strength = 0;
                TSet<TDamageType> types = default;
                ability.GetOffensiveStrength(this, ref strength, ref types);
                if (strength > 255) strength = 255;
                if (types == default)
                    Assert(false, $"Ability: {ability.GetName(null)}", @"D:\AoWDev\AoWE\inc\Unit.PAS", 0xE2B4);
                if (types == default) continue;
                if (FMaxOffensiveStrength < strength) FMaxOffensiveStrength = (byte)strength;
                for (int kind = (int)TDamageType.dtFire; kind <= (int)TDamageType.dtNone; kind++)
                    if (types.Contains((TDamageType)kind) && FOffensiveStrength[kind] < strength)
                        FOffensiveStrength[kind] = (byte)strength;
            }
        }
    }
}

