        // UnitRes.PAS:188
        public override bool DropUnit(int Xhx, int Yhx, int Lhx)
        {
            sbyte Player;
            TUnit AUnit;
            if (AoWEUnit.AoWHSMap.Status.Contains(THSMapStatusElement.msEditting))
            {
                Player = ((TAoWMapField)AoWEUnit.AoWHSMap.MapContainer.GetField(Xhx, Yhx, Lhx)).GetPlayer();
