        public override void SetExperience(int Value)
        {
            TUnitRank OldRank;
            TUnitRank NewRank;
            TUnitRank Rank;
            OldRank = GetRank();
            if (Value > 255)
            {
                Value = 255;
            }

            FExperience = (byte)Value;
            NewRank = GetRank();
            if (OldRank != NewRank)
            {
                for (int rankOrdinal = (int)(TUnitRank)((int)OldRank + 1); rankOrdinal <= (int)NewRank; rankOrdinal++)
                {
                    Rank = (TUnitRank)rankOrdinal;
                    UpdateDefaultAbilities(FUnitResource.FAbilities[(int)Rank]);
                }
            }

            Changed();
        }

        // Unit.PAS:2002
        public override int GetNextLevelExperience()
        {
            int Result;
            int Level;
            Level = FUnitResource.FLevel;
            if (FExperience >= Level * 2)
            {
                if (FExperience >= Level * 6)
                {
                    Result = 0;
                }
                else
                {
                    return Level * 6;
                }
            }
            else
            {
                Result = Level * 2;
            }

            return Result;
        }

