            AddRef();
            AddRef();
            AddRef();
            Dispose();
        }

        // Unit.PAS:1919
        public override int ShowEx(int X, int Y, in TSurfaceDesc SD, in TP2UnitShowInfo Info)
        {
            int Result = base.ShowEx(X, Y, SD, Info);
            if (Info.Overlays.Contains(TUnitOverlayModesElement.uoRank))
            {
                switch (GetRank())
                {
                    case TUnitRank.urSilver:
                        AoWEUnit.AoWHSSet.FCombatImages[5].Show(X + 33, Y + 12, SD);
                        break;
                    case TUnitRank.urGold:
                        AoWEUnit.AoWHSSet.FCombatImages[6].Show(X + 33, Y + 12, SD);
                        break;
                }
            }

            return Result;
        }

        // Unit.PAS:1966
        public override void UnitKilled()
        {
        }

        // Unit.PAS:1960
        public override void Killed()
        {
            base.Killed();
            Deactivate();
            SetOwner(null);
        }

        // Unit.PAS:2009
        public TUnitRank GetRank()
        {
            TUnitRank Result;
            if (FExperience >= FUnitResource.FLevel * 2)
            {
                if (FExperience >= FUnitResource.FLevel * 6)
                {
                    Result = TUnitRank.urGold;
                }
                else
                {
                    return TUnitRank.urSilver;
                }
            }
            else
            {
                Result = TUnitRank.urNone;
            }

            return Result;
        }

        // Unit.PAS:2016
        public void SetRank(TUnitRank Value)
        {
            if (Value != GetRank())
            {
                switch (Value)
                {
                    case TUnitRank.urNone:
                        FExperience = 0;
                        break;
                    case TUnitRank.urSilver:
                        SetExperience(FUnitResource.FLevel * 2);
                        break;
                    case TUnitRank.urGold:
                        SetExperience(FUnitResource.FLevel * 6);
                        break;
                }
            }
        }

        // Unit.PAS:2090
        public void SetUnitResource(TUnitResource Resource)
        {
            TUnitRank Rank;
            if (Resource != FUnitResource)
            {
                base.Clear();
                FUnitResource = Resource;
                if (FUnitResource != null)
                {
                    UpdateMoraleValue();
                    for (int rankOrdinal = (int)TUnitRank.urNone, last = (int)GetRank(); rankOrdinal <= last; rankOrdinal++)
                    {
                        Rank = (TUnitRank)rankOrdinal;
                        UpdateDefaultAbilities(FUnitResource.FAbilities[(int)Rank]);
                    }

                    FHitPoints = GetHits();
                    FMovePoints = GetMoves();
                }
            }
        }

    }
