    // FUnitID. FMode. FItemID (also spell ID). FParameter
    public partial class THeroUpdateTE : TTokenEvent
    {
        public THeroUpdateTE(TECustomNode owner) : base(owner)
        { }

        public new const int ClassID = 135429;

        public int FUnitID;
        public THeroUpdateMode FMode;
        public int FItemID;
        public int FParameter;

        // Hero.PAS:2279
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwInteger(ref FUnitID, 20);
            Stream.rwData(Bytes.Of(ref FMode, 1), 1, 21);
            Stream.rwInteger(ref FItemID, 22);
            Stream.rwInteger(ref FParameter, 23);
        }

        // Hero.PAS:2291
        public override TExecuteResult Execute(TTokenExecuter TE)
        {
            TExecuteResult Result;
            bool Success;
            Success = false;
            TAbstractUnit unit = AoWEUnit.AoWHSMap.FUnitControl.FindUnit(FUnitID);
            if (unit == null)
            {
                // A missing id is a nil hero. The original reads FPlayer and faults.
                // ExecuteTokenEvent catches the fault, shows the message and returns erDone.
                // Returning erDoneHalt stops the rest of Process.
                _ = unit.FPlayer;
            }

            if (unit is THero Hero && ((AoWEUnit.AoWHSMap.FCombat == null && AoWEUnit.AoWHSMap.FCurrentPlayer == Hero.FPlayer) || (AoWEUnit.AoWHSMap.FCombat != null && AoWEUnit.AoWHSMap.FCombat.FCombatData.FPlayers.GetPlayers((sbyte)AoWEUnit.AoWHSMap.FCombat.FCombatData.FCurrentPlayer).FPlayer == Hero.FPlayer)))
            {
                switch (FMode)
                {
                    case THeroUpdateMode.hmPlaceItem:
                        Success = Hero.ExecutePlaceItem(FItemID, (THeroItemPosition)FParameter);
                        break;
                    case THeroUpdateMode.hmSwapItem:
                        Success = Hero.ExecuteSwapItem(FItemID, FParameter);
                        break;
                    case THeroUpdateMode.hmStartCasting:
                        Success = Hero.ExecuteStartCasting(FItemID);
                        break;
                    case THeroUpdateMode.hmCancelCasting:
                        Success = Hero.ExecuteCancelCasting();
                        break;
                }
            }

            if (Success)
            {
                Result = TExecuteResult.erDone;
            }
            else
            {
                Result = TExecuteResult.erDoneHalt;
            }

            return Result;
        }

        // NetworkE.pas:230

    }
}

