    // FUnitID. FOldLevel. FNewLevel. FDay
    public partial class THeroUpgradeEventLog : TEventLog
    {
        public THeroUpgradeEventLog(TECustomNode owner) : base(owner)
        { }

        public new const int ClassID = 131825;

        public int FUnitID;
        public byte FOldLevel;
        public byte FNewLevel;
        public new int FDay;

        // Hero.PAS:57
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwInteger(ref FUnitID, 25);
            Stream.rwByte(ref FOldLevel, 26);
            Stream.rwByte(ref FNewLevel, 27);
            Stream.rwInteger(ref FDay, 28);
        }

        // Hero.PAS:66
        public override string GetText()
        {
            string Result = "";
            THero Hero;
            Hero = AoWEUnit.AoWHSMap.FUnitControl.FindUnit<THero>(FUnitID);
            if (Hero != null)
            {
                if (FNewLevel - FOldLevel == 1)
                {
                    var name = Hero.GetName();
                    Result = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.XMadeALevelRStr), [name]);
                }
                else
                {
                    var name = Hero.GetName();
                    Result = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.XMadeYLevelsRStr), [name, (FNewLevel - FOldLevel)]);
                }
            }

            return Result;
        }

        // Hero.PAS:76
        public override bool Execute(bool Mode, TExecuteTrigger Trigger, TExecuteDoneEvent Done)
        {
            bool Result = default;
            THero Hero;
            TAbstractUnit UnitItem;
            bool ExecuteNow;
            var unitControl = AoWEUnit.AoWHSMap.FUnitControl;
            UnitItem = unitControl.FindUnit(FUnitID);

            Hero = (THero)UnitItem;
            if (Hero != null && AoWEUnit.AoWHSMap.FSeatedPlayer == Hero.FPlayer)
            {
                if (Hero.FUpgradePending)
                {
                    ExecuteNow = Trigger == TExecuteTrigger.etUser;
                    ExecuteNow = ExecuteNow || AoWEUnit.AoWHSMap.FPlayMode == TPlayMode.pmTurn && AoWEUnit.AoWEngine.FRegistry.GetClassicWindowPopupEvents().Contains(TWindowPopupEvent.wpHeroUpgrade);
                    ExecuteNow = ExecuteNow || AoWEUnit.AoWHSMap.FPlayMode == TPlayMode.pmSimultaneous && AoWEUnit.AoWEngine.FRegistry.GetSimultaneousWindowPopupEvents().Contains(TWindowPopupEvent.wpHeroUpgrade);
                    if (ExecuteNow)
                    {
                        Result = base.Execute(Mode, Trigger, Done);
                    }
                    else
                    {
                        Result = false;
                    }
                }
                else
                {
                    if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Hero.FPlayer).FDay == FDay)
                    {
                        var canOnlyUpgradeHeroOnce = AoWEUnit.TranslateRStr(AoWEUnit.CanOnlyUpgradeHeroOnceRStr);
                        AoWEUnit.AoWHSMap.ShowWarning(canOnlyUpgradeHeroOnce);
                    }
                    else
                    {
                        var canOnlyUpgradeOnTheDayALevelIsMade = AoWEUnit.TranslateRStr(AoWEUnit.CanOnlyUpgradeOnTheDayALevelIsMadeRStr);
                        AoWEUnit.AoWHSMap.ShowWarning(canOnlyUpgradeOnTheDayALevelIsMade);
                    }

                    Result = false;
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

