                ExecuteNow = ExecuteNow || AoWEUnit.AoWHSMap.FPlayMode == TPlayMode.pmSimultaneous && AoWEUnit.AoWEngine.FRegistry.GetSimultaneousWindowPopupEvents().Contains(TWindowPopupEvent.wpHeroJoin);
