        // Hero.PAS:148
        public override bool Accept(ref string ErrorText)
        {
            TNegotiateTE TE;
            TAbstractUnit U;
            TXYL Location = default;
            bool Result = base.Accept(ref ErrorText);
            if (Result && !AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).GetBusy())
            {
                U = AoWEUnit.AoWHSMap.FUnitControl.FindUnit(FFirstUnitID);
                U.GetLocation(ref Location.X, ref Location.Y, ref Location.L);
                TE = new TNegotiateTE(null);
                TE.FPlayer = FPlayer;
                TE.FObject = TNegotiateObject.noArmy;
                TE.FGold = FGold;
                TE.FOffer = TNegotiateOffer.noOfferBribe;
                TE.FX = (byte)Location.X;
                TE.FY = (byte)Location.Y;
                TE.FL = (byte)Location.L;
                TE.FMode = TSet<TNegotiateModeElement>.Of();
                TE.FResult = TNegotiateResult.nrAccept;
                TE.FEventLogID = FJoinIndex;
                AoWEUnit.AoWHSMap.FTokenManager.GetTokenControl(FPlayer).AddEvent(TE);
                TE.Release();
            }

            return Result;
        }

        // Hero.PAS:132
        // The AI reaches this through THeroEmergeEventLog.ExecuteAI(), not through the virtual
        // ExecuteAI(sbyte) of 9.6-3, which this class leaves as the no-op (AI.pas:1626 never
        // dispatched on it).
        public bool ExecuteAI()
        {
            THero Hero;
            string ErrorText = "";
            bool Result = false;
            Hero = AoWEUnit.AoWHSMap.FUnitControl.FindUnit<THero>(FFirstUnitID);
            if (Hero != null && Hero.FPlayer == 0 && Hero.OfferToJoin(FPlayer))
            {
                var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer);
                if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FAIBudget.RequestBudgetExpense(FGold, 0, players.FAIBudget.FDefaultBudget, true))
                {
                    if (Accept(ref ErrorText))
                    {
                        var fPlayersPlayers = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer);
                        AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FAIBudget.BudgetExpenseMade(FGold, 0, fPlayersPlayers.FAIBudget.FDefaultBudget, TBudgetExpenseMode.bemBudgetThenPool);
                    }

                    Result = true;
                }
            }

            return Result;
        }

    }

