        // Hero.PAS:214
        public THeroJoinEventLog CreateHeroJoinEventLog()
        {
            THeroJoinEventLog Result;
            THero Hero;
            Hero = AoWEUnit.AoWHSMap.FUnitControl.FindUnit<THero>(FUnitID);
            if (Hero != null && Hero.FPlayer == 0 && Hero.OfferToJoin(FPlayer))
            {
                Result = new THeroJoinEventLog(null);
                Result.FJoinIndex = FID;
                switch (FMode)
                {
                    case THeroJoinMode.hjmEmerged:
                        Result.SetupJoinArmy((TArmy)Hero.Owner, FPlayer, Result.FJoinMode);
                        Result.FFirstUnitID = Hero.FUnitID;
                        var format = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.XEmergedAtYAndOffersToJoinYouForZgpRStr), [Hero.FHeroName, FLocationName, Result.FGold]);
                        Result.FJoinMessage.Text = format;
                        break;
                    case THeroJoinMode.hjmResurrected:
                        Result.SetupJoinArmy((TArmy)Hero.Owner, FPlayer, Result.FJoinMode);
                        Result.FFirstUnitID = Hero.FUnitID;
                        var aoWEFormat = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.XwasResurrectedAndOffersToJoinYouForZgpRStr), [Hero.FHeroName, Result.FGold]);
                        Result.FJoinMessage.Text = aoWEFormat;
                        break;
                }
            }
            else
            {
                Result = null;
            }

            return Result;
        }

