        // Hero.PAS:933
        public override void SetPlayer(sbyte Player)
        {
            if (Player != FPlayer)
            {
                bool condition = FPlayer != -1;
                if (condition)
                {
                    var count = AoWEUnit.AoWHSMap.FPlayers.Count;
                    condition = FPlayer < count;
                }

                if (condition)
                {
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.UnregisterPowerSource(FPowerSource);
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FHeroes.RemoveChild(this);
                }

                base.SetPlayer(Player);
                if (FPlayer != -1)
                {
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FHeroes.AddChild(this);
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.RegisterPowerSource(FPowerSource);
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).ResetBaseHeroJoinDay();
                }
            }
        }

