        // Hero.PAS:914
        public override bool CanActivate()
        {
            THero Hero;
            bool Result = base.CanActivate();
            if (Result && !FRegistered && FUnitID != -1)
            {
                Hero = AoWEUnit.AoWHSMap.FHeroControl.FindID(FUnitID);
                if (Hero == null || Hero == this)
                {
                    Result = true;
                }
                else
                {
                    if (Hero.Owner == null && CompatibleHero(Hero))
                    {
                        Result = true;
                    }
                    else
                    {
                        Result = false;
                    }
                }
            }

            return Result;
        }

        // Hero.PAS:964
        public override void Activate()
        {
            THero Hero;
            if (FUnitID != -1)
            {
                Hero = AoWEUnit.AoWHSMap.FHeroControl.FindID(FUnitID);
                if (Hero != null && Hero != this && Hero.Owner == null && CompatibleHero(Hero))
                {
                    AoWEUnit.AoWHSMap.FHeroControl.UnRegisterHero(Hero);
                }
            }

            if (AoWEUnit.AoWHSMap.Status.Contains(THSMapStatusElement.msEditting))
            {
                FLevel = (byte)GetLevel();
            }

            if (FHeroResourceIndex == -1)
            {
                SetHeroResourceIndex(0);
            }

            if (FPlayer > 0 && AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer) == null && Owner == null)
            {
                FPlayer = -1;
            }

            if (Owner == null && FGroupID != 0)
            {
                FGroupID = 0;
            }

            base.Activate();
            if (AoWEUnit.AoWHSMap != null)
            {
                if (!FMode.Contains(THeroModeElement.hmSkipLibraryUpdate) && (AoWEUnit.AoWHSMap.Status.Contains(THSMapStatusElement.msEditting) || AoWEUnit.AoWHSMap.FDay == 0))
                {
                    UpdateFromLibrary();
                }

                if (!FRegistered)
                {
                    AoWEUnit.AoWHSMap.FHeroControl.RegisterHero(this);
                }

                if (FPlayer != -1 && Owner != null)
                {
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.RegisterPowerSource(FPowerSource);
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FHeroes.AddChild(this);
                }

                FInventory.RegisterItems();
                FHeroItems.RegisterItems();
            }
        }

        // Hero.PAS:993
        public override void Deactivate()
        {
            bool condition = FPlayer != -1;
            if (condition)
            {
                var count = AoWEUnit.AoWHSMap.FPlayers.Count;
                condition = FPlayer < count;
            }

            if (condition)
            {
                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.UnregisterPowerSource(FPowerSource);
                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FHeroes.RemoveChild(this);
            }

            base.Deactivate();
        }

        // Hero.PAS:765
        public override bool CanJoin(sbyte Player)
        {
            bool Result;
            TPlayer APlayer;
            if (FRace != -1)
            {
                APlayer = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
                var playerRelation = AoWEUnit.AoWHSMap.FRaces.GetRace(FRace).GetPlayerRelation(Player);
                Result = TSet<TStatus>.Of(TStatus.sPolite, TStatus.sFriendly).Contains(playerRelation);
                if (Result)
                {
                    bool condition = FGroup == null || FGroup.GroupClass.Behavior != TGroupBehavior.gbRefuge;
                    if (condition)
                    {
                        bool test = !GetAbilityEnabled(128) || Player != FDeathPlayer;
                        if (!test)
                        {
                            var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
                            test = FDeathDay + 2 < players.FDay;
                        }

                        condition = test;
                    }

                    if (condition)
                    {
                        Result = Result && APlayer.FHeroes.Count < APlayer.GetHeroCountMax() && GetLevel() <= APlayer.GetHeroJoinLevelMax();
                    }
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Hero.PAS:794
        public override bool OfferToJoin(sbyte Player)
        {
            bool Result;
            TPlayer APlayer;
            int Seed;
            int Chance;
            if (CanJoin(Player))
            {
                APlayer = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
                if (EmergedToPlayer() == -1)
                {
                    if ((!GetAbilityEnabled(128) || Player != FDeathPlayer) && (FGroup == null || FGroup.GroupClass.Behavior != TGroupBehavior.gbRefuge))
                    {
                        Chance = APlayer.GetHeroJoinChance(GetLevel());
                        Seed = RandSeed;
                        RandSeed = (AoWEUnit.AoWHSMap.FInitialRandomSeed + AoWEUnit.AoWHSMap.FDay + FUnitID * 16) & 4088;
                        Result = Random(100) < Chance;
                        RandSeed = Seed;
                    }
                    else
                    {
                        Result = true;
                    }
                }
                else
                {
                    Result = Player == EmergedToPlayer();
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

