        // Hero.PAS:1674
        public virtual void EditDropMsg(ref TEMsg Msg)
        {
            TMapLevel Level;
            int L;
            int X = default;
            int Y = default;
            int Player;
            bool Placed;
            Level = Msg.Param[0].As<TMapLevel>();
            L = Msg.Data[1];
            HPtoHX(Msg.Payload.Int, Msg.Data[0], ref X, ref Y);
            if (X >= 0 && Y >= 0 && X < Level.Width && Y < Level.Height)
            {
                if (AoWEUnit.AoWHSMap.Status.Contains(THSMapStatusElement.msEditting))
                {
                    Player = ((TAoWMapField)AoWEUnit.AoWHSMap.MapContainer.GetField(X, Y, L)).GetPlayer();
                    if (Player == -1)
                    {
                        Player = AoWEUnit.AoWHSMap.FEditorPlayer;
                    }
                }
                else
                {
                    Player = -1;
                }

                Placed = Place(X, Y, L, (sbyte)Player, TSet<TUnitPlaceModeElement>.Of()) != null;
            }
            else
            {
                Placed = false;
            }

            if (Placed)
            {
                Msg.Result = 0;
            }
            else
            {
                Msg.Result = -1;
            }
        }

