        // Hero.PAS:751
        public int UsedSkillPoints()
        {
            int Result = FUnitAttack * 5 + FUnitDefense * 5 + FUnitDamage * 10 + FUnitResistance * 5 + FUnitHits * 5 + FUnitMoves * 2;
            for (int I = GetAbCount() - 1; I >= 0; I--)
            {
                if (GetAbSet(I))
                {
                    Result += AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(I).GetSkillPoints(this);
                    if (FHeroResource.FAbilities.GetAbSet(I))
                    {
                        Result -= AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(I).GetSkillPoints(FHeroResource.FAbilities);
                    }
                }
            }

            return Result;
        }

        // Hero.PAS:782
        public sbyte EmergedToPlayer()
        {
            int I;
            I = AoWEUnit.AoWHSMap.FPlayers.Count;
            sbyte Result = -1;
            while (I != 1 && Result == -1)
            {
                I -= 1;
                if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FEmergingHeroID == FUnitID)
                {
                    Result = (sbyte)I;
                }
            }

            return Result;
        }

