        // Hero.PAS:1040
        public int LevelToExperience(int Level)
        {
            int Total;
            int Quotient;
            Total = 0;
            for (int I = 1; I <= Level - 1; I++)
            {
                Quotient = I / 5;
                if (Quotient <= 5)
                {
                    Total += AoWEUnit.HeroExperienceTable[Quotient].Experience;
                }
            }

            return Total;
        }

        // Hero.PAS:1049
        public sbyte ExperienceToLevel(int Experience)
        {
            int Level;
            int Total;
            int Maximum;
            Level = 1;
            Total = 0;
            Maximum = GetLevelMax();
            do
            {
                Total += AoWEUnit.HeroExperienceTable[Level / 5].Experience;
                if (Experience < Total)
                {
                    break;
                }

                Level += 1;
            }
            while (!(Level >= Maximum));
            return (sbyte)Level;
        }

        // Hero.PAS:1071
        public sbyte GetLevel() => this.ExperienceToLevel(this.FExperience);

        // Hero.PAS:1076
        public void SetLevel(sbyte Value)
        {
            int Maximum;
            int Level;
            int Points;
            Maximum = GetLevelMax();
            if (Value < 1)
            {
                Value = 1;
            }

            if (Maximum < Value)
            {
                Value = (sbyte)Maximum;
            }

            Level = GetLevel();
            if (Level > Value)
            {
                Points = GetSkillPoints();
                while (Points >= 10 && Level != Value)
                {
                    Level -= 1;
                    Points -= 10;
                }

                Value = (sbyte)Level;
            }

            FExperience = LevelToExperience(Value);
            FLevel = (byte)Value;
        }

