            base.SetHeroResourceIndex(Value);
            if (FHeroResource != null && AoWEUnit.AoWHSMap != null && AoWEUnit.AoWHSMap.Status.Contains(THSMapStatusElement.msEditting))
            {
                FHeroName = FHeroResource.FName;
