        // Hero.PAS:2960
        public override void EditDropMsg(ref TEMsg Msg)
        {
            TMapLevel Level;
            int L;
            int X = default;
            int Y = default;
            bool Placed;
            Level = Msg.Param[0].As<TMapLevel>();
            L = Msg.Data[1];
            HPtoHX(Msg.Payload.Int, Msg.Data[0], ref X, ref Y);
            if (X >= 0 && Y >= 0 && X < Level.Width && Y < Level.Height)
            {
                Placed = Place(X, Y, L, FPlayer, TSet<TUnitPlaceModeElement>.Of()) != null;
            }
            else
            {
                Placed = false;
            }

            if (Placed)
            {
                Msg.Result = 0;
            }
            else
            {
                Msg.Result = -1;
            }
        }

        // Hero.PAS:2800
        public byte GetSpherePicks(Aow.Game.Magic.TMagicSphere Sphere)
        {
            byte Result;
            if (Sphere != Aow.Game.Magic.TMagicSphere.msCosmos)
            {
                Result = 0;
                for (int I = FSpheres.Count - 1; I >= 0; I--)
                {
                    if (FSpheres.List[I] == (byte)Sphere)
                    {
                        Result = (byte)(Result + 1);
                    }
                }
            }
            else
            {
                Result = 4;
            }

            return Result;
        }

        // Hero.PAS:2812
        public Aow.Game.Magic.TMagicSphere GetSpheres(int Index) => (Aow.Game.Magic.TMagicSphere)FSpheres.List[Index];

        // Hero.PAS:2815
        public int GetSphereCount() => FSpheres.Count;

        // Hero.PAS:2818
        public void SetSpherePicksMax(byte Value)
        {
            FSpherePicksMax = Value;
            while (FSpheres.Count > FSpherePicksMax)
            {
                FSpheres.Delete(FSpheres.Count - 1);
            }
        }

        // Hero.PAS:2824
        public bool CanAddSphere(Aow.Game.Magic.TMagicSphere Sphere)
        {
            bool Result;
            if (FSpheres.Count < FSpherePicksMax)
            {
                if (Sphere == Aow.Game.Magic.TMagicSphere.msCosmos)
                {
                    Result = false;
                }
                else
                {
                    if (AoWEUnit.AoWEngine.FDemo && GetSpherePicks(Sphere) >= 2)
                    {
                        Result = false;
                    }
                    else
                    {
                        if (GetSpherePicks(Sphere) == 4)
                        {
                            Result = false;
                        }
                        else
                        {
                            if (Sphere == Aow.Game.Magic.TMagicSphere.msFire && GetSpherePicks(Aow.Game.Magic.TMagicSphere.msWater) != 0)
                            {
                                Result = false;
                            }
                            else
                            {
                                if (Sphere == Aow.Game.Magic.TMagicSphere.msWater && GetSpherePicks(Aow.Game.Magic.TMagicSphere.msFire) != 0)
                                {
                                    Result = false;
                                }
                                else
                                {
                                    if (Sphere == Aow.Game.Magic.TMagicSphere.msLife && GetSpherePicks(Aow.Game.Magic.TMagicSphere.msDeath) != 0)
                                    {
                                        Result = false;
                                    }
                                    else
                                    {
                                        if (Sphere == Aow.Game.Magic.TMagicSphere.msDeath && GetSpherePicks(Aow.Game.Magic.TMagicSphere.msLife) != 0)
                                        {
                                            Result = false;
                                        }
                                        else
                                        {
                                            if (Sphere == Aow.Game.Magic.TMagicSphere.msEarth && GetSpherePicks(Aow.Game.Magic.TMagicSphere.msAir) != 0)
                                            {
                                                Result = false;
                                            }
                                            else
                                            {
                                                if (Sphere == Aow.Game.Magic.TMagicSphere.msAir && GetSpherePicks(Aow.Game.Magic.TMagicSphere.msEarth) != 0)
                                                {
                                                    Result = false;
                                                }
                                                else
                                                {
                                                    Result = true;
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Hero.PAS:2842
        public bool AddSphere(Aow.Game.Magic.TMagicSphere Sphere)
        {
            bool Result = CanAddSphere(Sphere);
            if (Result)
            {
                FSpheres.Add((byte)Sphere);
            }

            return Result;
        }

        // Hero.PAS:2863
        public bool DeleteSphereIndex(int Index)
        {
            bool Result;
            if (Index >= 0 && Index < FSpheres.Count)
            {
                FSpheres.Delete(Index);
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Hero.PAS:2870
        public bool DeleteSphere(Aow.Game.Magic.TMagicSphere Sphere)
        {
            int I;
            I = FSpheres.Count;
            bool Result = false;
            while (!Result && I != 0)
            {
                I -= 1;
                Result = FSpheres[I] == (byte)Sphere;
            }

            if (Result)
            {
                FSpheres.Delete(I);
            }

            return Result;
        }

        // Hero.PAS:2883
        public void ClearSpheres()
        {
            FSpheres.Clear();
        }

    }
}

