            for (int I = FHeroes.FChildren.Count - 1; I >= 0; I--)
            {
                Hero = (THero)FHeroes.FChildren.List[I];
                if (!Hero.FHeroStatus.Contains(THeroStatusElement.hsDied) && Hero.FPlayer <= 0 && Result > Hero.GetLevel())
                {
                    Result = Hero.GetLevel();
                }
            }

            return Result;
        }

