    // FSystemLibrary. FLibraries
    public partial class THeroLibraryManager : TEObject
    {
        // Hero.PAS:2646
        public THeroLibraryManager(TECustomNode owner) : base(owner)
        {
            FSystemLibrary = new THeroLibrary(null);
            FLibraries = new TENode(null);
        }

        public THeroLibrary FSystemLibrary;
        public TENode FLibraries;

        // Hero.PAS:2653
        public override void Dispose()
        {
            FLibraries?.Dispose();
            FSystemLibrary?.Dispose();
            base.Dispose();
        }

        // Hero.PAS:2656
        public override void ReadWrite(TEStorageStream Stream)
        {
            string Directory;
            base.ReadWrite(Stream);
            if ((Stream.StorageMode() & TSet<TStorageModeElement>.Of(TStorageModeElement.smTextOnly, TStorageModeElement.smCompare)) == TSet<TStorageModeElement>.Of())
            {
                Directory = ExtractFilePath(AoWEUnit.AoWEngine.HSSFileName);
                if (Stream.StorageMode().Contains(TStorageModeElement.smRead))
                {
                    ReadUserLibraries();
                    AoWEUnit.AoWEngine.ReadFromFile(Directory + "Heroes.PFS", FSystemLibrary, null);
                }
                else
                {
                    AoWEUnit.AoWEngine.WriteToFile(Directory + "Heroes.PFS", FSystemLibrary, null);
                    WriteUserLibraries();
                }
            }
            else
            {
                Stream.rwEObject(FSystemLibrary, 20);
            }
        }

        // Hero.PAS:2677
        public THeroLibrary GetLibrary(int Index) => (THeroLibrary)FLibraries.FChildren.EObjects[Index];

        // Hero.PAS:2680
        public int GetCount() => FLibraries.GetCount();

        // Hero.PAS:2683
        public void ReadUserLibraries()
        {
            THeroLibrary Lib;
            FLibraries.Clear();
            FLibraries.AddChild(FSystemLibrary);
            // Both extensions list, and a list present in both forms loads its own document once
            // (own-formats.md 4.2).
            foreach (var Listed in FileBoundary.FindDocuments(AoWEUnit.AoWEngine.StartupDirectory + "User\\", Aow.Formats.DocumentKind.HeroList))
            {
                Lib = new THeroLibrary(null);
                try
                {
                    Lib.LoadFromFile(AoWEUnit.AoWEngine.StartupDirectory + "User\\" + Listed);
                    Lib.SetOwner(FLibraries);
                }
                catch
                {
                    Lib?.Dispose();
                }
            }
        }

        // Hero.PAS:2703
        public void WriteUserLibraries()
        {
            THeroLibrary Lib;
            for (int I = 1, last = FLibraries.GetCount() - 1; I <= last; I++)
            {
                Lib = GetLibrary(I);
                var name = Lib.GetName();
                Lib.SaveToFile(AoWEUnit.AoWEngine.StartupDirectory + "User\\" + name + FileBoundary.WriteExtension(Aow.Formats.DocumentKind.HeroList));
            }
        }

        // Hero.PAS:2713
        public int IndexOfLibraryName(string Name)
        {
            int Result = FLibraries.GetCount();
            while (Result != 0)
            {
                Result -= 1;
                if (CompareText(Name, ((THeroLibrary)FLibraries.FChildren.List[Result]).FLibraryName) == 0)
                {
                    return Result;
                }
            }

            return -1;
        }

        // Hero.PAS:2724
        public int IndexOfLibrary(THeroLibrary Lib) => FLibraries.FChildren.IndexOf(Lib);

        // Hero.PAS:2727
        public THero FindHero(string LibraryName, int LibraryID)
        {
            THero Result;
            int Index;
            Index = IndexOfLibraryName(LibraryName);
            if (Index != -1)
            {
                Result = ((THeroLibrary)FLibraries.FChildren.List[Index]).FindLibraryID(LibraryID);
            }
            else
            {
                Result = null;
            }

            return Result;
        }

        // Hero.PAS:2735
        public THeroLibrary CreateLibrary(string Name)
        {
            THeroLibrary Result;
            string LibraryName;
            LibraryName = Name;
            // { Original retains the period when stripping the extension. }
            if (Pos(".", LibraryName) != 0)
            {
                LibraryName = RtlUnit.Copy(LibraryName, 1, Pos(".", LibraryName));
            }

            if (!IsEmpty(LibraryName) && IndexOfLibraryName(LibraryName) == -1)
            {
                Result = new THeroLibrary(FLibraries);
                Result.FLibraryName = LibraryName;
                Result.SaveToFile(AoWEUnit.AoWEngine.StartupDirectory + "Release\\" + LibraryName + FileBoundary.WriteExtension(Aow.Formats.DocumentKind.HeroList));
            }
            else
            {
                Result = null;
            }

            return Result;
        }

        // Hero.PAS:2750
        public void DeleteLibrary(int Index)
        {
            if (Index < FLibraries.GetCount() && Index > 0)
            {
                var name = GetLibrary(Index).GetName();
                // The list goes in both forms, so an original of the same name does not return.
                DeleteFile(AoWEUnit.AoWEngine.StartupDirectory + "User\\" + name + Aow.Formats.DocumentKind.HeroList.OriginalExtension);
                DeleteFile(AoWEUnit.AoWEngine.StartupDirectory + "User\\" + name + Aow.Formats.DocumentKind.HeroList.OwnExtension);
                GetLibrary(Index)?.Dispose();
            }
        }

        // intf_P2_07.inc:311

    }

