        // Unit.PAS:2607
        public override TSet<TDamageType> GetProtectionTypes() => FProtectionTypes;

        // Unit.PAS:2539
        public void MakeDefaultLevelUnit(sbyte Level)
        {
            // { Original retains protection from an earlier, higher-level setup. }
            switch (Level)
            {
                case 1:
                    FAttack = 4;
                    FDefense = 2;
                    FResistance = 3;
                    FDamage = 3;
                    FHits = 5;
                    SetAbSet(21, 1);
                    SetAbSet(0, 1);
                    FImmunityTypes = TSet<TDamageType>.Of(TDamageType.dtWall);
                    break;
                case 2:
                    FAttack = 5;
                    FDefense = 3;
                    FResistance = 3;
                    FDamage = 3;
                    FHits = 8;
                    SetAbSet(21, 1);
                    SetAbSet(0, 1);
                    FImmunityTypes = TSet<TDamageType>.Of(TDamageType.dtWall);
                    break;
                case 3:
                    FAttack = 6;
                    FDefense = 3;
                    FResistance = 4;
                    FDamage = 7;
                    FHits = 15;
                    SetAbSet(21, 1);
                    SetAbSet(0, 1);
                    FImmunityTypes = TSet<TDamageType>.Of(TDamageType.dtWall);
                    FProtectionTypes = TSet<TDamageType>.Of(TDamageType.dtPhysical);
                    break;
                default:
                    {
                        FAttack = 6;
                        FDefense = 3;
                        FResistance = 4;
                        FDamage = 7;
                        FHits = 20;
                        FImmunityTypes = TSet<TDamageType>.Of(TDamageType.dtPhysical, TDamageType.dtWall);
                        SetAbSet(21, 1);
                        SetAbSet(0, 1);
                    }

                    break;
            }

            FHitPoints = FHits;
        }

    }

