        public bool RetrieveArmy(ref TArmyHS ArmyHS, ref byte Selection)
        {
            bool Result;
            int I;
            int Index;
            if (FX != -1)
            {
                Selection = 0;
                ArmyHS = ((TAoWMapField)AoWEUnit.AoWHSMap.MapContainer.GetField(FX, FY, FL)).GetArmyHS();
                if (ArmyHS != null && ArmyHS.FArmy.FPlayer == FPlayer)
                {
                    I = FUnitIDs.Count;
                    Result = true;
                    while (Result && I != 0)
                    {
                        I -= 1;
                        var item = FUnitIDs[I];
                        Index = ArmyHS.FArmy.IndexOfID(item);
                        // { Original shifts by the missing unit index before reporting failure. }
                        Selection = (byte)(Selection | (1 << Index));
                        Result = Index != -1;
                    }
                }
                else
                {
                    Result = false;
                }
            }
            else
            {
