        // Army.PAS:500
        public void InitializeGroupBehavior()
        {
            byte Selection;
            int Index;
            TGroupBehavior Behavior;
            THero AHero;
            Selection = 255;
            AHero = Hero(Selection, TSet<THeroType>.Of(THeroType.htLeader, THeroType.htHeroLeader));
            if (AHero != null)
            {
                Index = IndexOf(AHero);
                if (Index != -1)
                {
                    SetBehavior((byte)(1 << Index), TGroupBehavior.gbFortify);
                    Selection = (byte)(Selection & ~(1 << Index));
                }
            }

            Index = IndexOfTransporter(Selection);
            if (Index != -1 && FOldAIBehavior == TGroupBehavior.gbNone)
            {
                Selection = (byte)(Selection & ~(1 << Index));
            }

            if (Selection != 0)
            {
                Behavior = FOldAIBehavior;
                if (Behavior == TGroupBehavior.gbNone)
                {
                    if (FPlayer == 0 && AoWEUnit.AoWHSMap.GetIndependentAIMode() != TIndependentAIMode.iaOff)
                    {
                        if (FX != -1 && AoWEUnit.AoWHSMap.MapContainer.GetField(FX, FY, FL).FindNoneTransparentHS(typeof(TPlayerStructure)) == null)
                        {
                            if (FIndependentRelation >= 0)
                            {
                                Behavior = TGroupBehavior.gbPatrol;
                            }
                            else
                            {
                                Behavior = TGroupBehavior.gbGuardArea;
                            }
                        }
                        else
                        {
                            Behavior = TGroupBehavior.gbPassive;
                        }
                    }
                    else
                    {
                        Behavior = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FAIControl.GetRandomGroupBehavior();
                    }
                }

                SetBehavior(Selection, Behavior);
            }
        }

        // Army.PAS:533
        public void UpdateGroupBehavior()
        {
            byte Selection;
            int Index;
            TGroupBehavior Behavior;
            Selection = GetGroupSelection(0);
            if (Selection != 0)
            {
                Index = IndexOfTransporter(Selection);
                if (Index != -1)
                {
                    Selection = (byte)(Selection & ~(1 << Index));
                    if (((TAbstractUnit)FChildren.List[Index]).FGroupID == 0)
                    {
                        SetBehavior((byte)(1 << Index), TGroupBehavior.gbTransport);
                    }
                }

                Behavior = TGroupBehavior.gbPassive;
                if (FPlayer == 0 && Hero(Selection, TSet<THeroType>.Of(THeroType.htHero)) != null)
                {
                    Behavior = TGroupBehavior.gbScout;
                }
                else
                {
                    if (FPlayer == 0 && AoWEUnit.AoWHSMap.GetIndependentAIMode() != TIndependentAIMode.iaOff && FX != -1)
                    {
                        if (AoWEUnit.AoWHSMap.MapContainer.GetField(FX, FY, FL).FindNoneTransparentHS(typeof(TPlayerStructure)) == null)
                        {
                            if (FIndependentRelation >= 0)
                            {
                                Behavior = TGroupBehavior.gbPatrol;
                            }
                            else
                            {
                                Behavior = TGroupBehavior.gbGuardArea;
                            }
                        }
                    }
                }

                if (Selection != 0)
                {
                    Index = IndexOfBehavior(Behavior);
                    if (Index == -1)
                    {
                        SetBehavior(Selection, Behavior);
                    }
                    else
                    {
                        SetGroup(Selection, ((TAbstractUnit)FChildren.List[Index]).FGroup);
                    }
                }
            }
        }

