        {
            ValidateTerrainEx(TerrainType, OverlayType, FPlayer);
        }

        // Army.PAS:790
        public void Validate()
        {
            TAbstractUnit AUnit;
            TUnit NewUnit;
            AoWEUnit.AoWHSMap.LockGameOverEvent();
            BeginUpdate();
            for (int I = FChildren.Count - 1; I >= 0; I--)
            {
                AUnit = (TAbstractUnit)FChildren.List[I];
                if (AUnit.GetHitPoints() == 0)
                {
                    if (AUnit.GetAbilityEnabled(107))
                    {
                        NewUnit = new TUnit(null);
                        NewUnit.SetUnitResource(AoWEUnit.AoWHSSet.FUnitResources.GetUnitResource(152));
                        AUnit.Killed();
                        AddUnit(NewUnit);
                    }
                    else
                    {
                        AUnit.Killed();
                    }
                }
            }

            EndUpdate();
            AoWEUnit.AoWHSMap.UnlockGameOverEvent();
        }

        // Army.PAS:812
        public void UpdateFormation()
        {
            int Level;
            int UnitLevel;
            TAbstractUnit AUnit;
            string SourceName = "";
            Level = 0;
            for (int I = FChildren.Count - 1; I >= 0; I--)
            {
                AUnit = (TAbstractUnit)FChildren.List[I];
                AUnit.UpdateMoraleValue();
                if (AUnit.GetAbilityEnabled(46) || AUnit.GetAbilityLevel(46) > 0)
                {
                    ((TLeadershipAbility)AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(46)).ResetExternalSource(AUnit);
                    UnitLevel = AUnit.GetAbilityLevel(46);
                    if (UnitLevel > Level)
                    {
                        Level = UnitLevel;
                        SourceName = AUnit.GetAbilityOwner(46).GetOwnerName();
                        if (SourceName == AoWEUnit.TranslateRStr(AoWEUnit.ArmyInherentRStr))
                        {
                            SourceName = AUnit.GetName();
                        }
                    }
                }
            }

            if (Level > 0)
            {
                for (int I = FChildren.Count - 1; I >= 0; I--)
                {
                    AUnit = (TAbstractUnit)FChildren.List[I];
                    if (AUnit.GetAbilityLevel(46) < Level)
                    {
                        ((TLeadershipAbility)AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(46)).SetExternalSource(AUnit, (byte)Level, SourceName);
                    }
                }
            }
        }

        // Army.PAS:841
        public void Update()
        {
            if (UpdateCount == 0 && FStatus.Contains(TArmyStatusElement.asActivated))
            {
                LockChanged();
                SortUnits();
                UpdateVisibilityRanges();
                UpdateUnfog();
                UpdateUpkeep();
                UpdateConcealedUnits();
                UpdateConcealment();
                UpdateFormation();
                UpdateIndependentRelation();
                if (AoWEUnit.AoWHSMap.Status.Contains(THSMapStatusElement.msEditting) && FX != -1)
                {
                    AoWEUnit.AoWHSMap.ScannerIconsChangedRad(FX, FY, FL, 0);
                }

                UnlockChanged();
                TriggerOnUpdateEvent();
            }
        }

        // Army.PAS:861
        public void TriggerOnUpdateEvent()
        {
            if (UpdateCount == 0 && FStatus.Contains(TArmyStatusElement.asActivated))
            {
                AoWEUnit.AoWHSMap.ArmyChanged(this);
                if (FOnUpdate != null)
                {
                    FOnUpdate(this);
                }
            }
        }

        // Army.PAS:870
        public void Activate()
        {
            TAbstractUnit AUnit;
            Assert(!FStatus.Contains(TArmyStatusElement.asActivated), "Army already activated", "Army.PAS", 1171);
            if (FOldAIBehavior == TGroupBehavior.gbNone)
            {
                FOldAIBehavior = GetOldAIBehavior();
            }

            for (int I = FChildren.Count - 1; I >= 0; I--)
            {
                AUnit = (TAbstractUnit)FChildren.List[I];
                if (!AUnit.FUnitStatus.Contains(TUnitStatusElement.usActivated))
                {
                    AUnit.Activate();
                }
            }

            FStatus = FStatus + TSet<TArmyStatusElement>.Of(TArmyStatusElement.asActivated);
            FUpkeep = 0;
            if (FPlayer != -1)
            {
                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FArmies.AddChild(this);
            }

            // { Original treats X = 0 as an unset location. }
            if (FX == 0)
            {
                FX = -1;
                FY = -1;
                FL = -1;
            }

            Update();
        }

        // Army.PAS:1186
        public void Deactivate()
        {
            TAbstractUnit AUnit;
            if (FStatus.Contains(TArmyStatusElement.asActivated))
            {
                if (FUnfogRange != 0)
                {
                    AoWEUnit.AoWHSMap.FogArea(FX, FY, FL, FUnfogRange);
                    FUnfogRange = 0;
                }

                for (int I = FChildren.Count - 1; I >= 0; I--)
                {
                    AUnit = (TAbstractUnit)FChildren.List[I];
                    if (AUnit.FUnitStatus.Contains(TUnitStatusElement.usActivated))
                    {
                        AUnit.Deactivate();
                    }
                }

                if (FPlayer != -1)
                {
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FArmies.RemoveChild(this);
                    var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer);
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).SetArmyUpkeep(players.FArmyUpkeep - FUpkeep);
                }

                FStatus = FStatus - TSet<TArmyStatusElement>.Of(TArmyStatusElement.asActivated);
            }
        }

        // Army.PAS:1211
