        // Army.PAS:1298
        public void SetPlayer(sbyte Player)
        {
            if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player) == null)
            {
                Player = 0;
            }

            if (Player != FPlayer)
            {
                BeginUpdate();
                if (FStatus.Contains(TArmyStatusElement.asActivated))
                {
                    if (FPlayer != -1)
                    {
                        var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer);
                        AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).SetArmyUpkeep(players.FArmyUpkeep - FUpkeep);
                        AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FArmies.RemoveChild(this);
                    }

                    FPlayer = Player;
                    if (FPlayer != -1)
                    {
                        var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer);
                        AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).SetArmyUpkeep(players.FArmyUpkeep + FUpkeep);
                        AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FArmies.AddChild(this);
                    }

                    for (int I = FChildren.Count - 1; I >= 0; I--)
                    {
                        ((TAbstractUnit)FChildren.List[I]).SetPlayer(FPlayer);
                    }

                    if (FX != -1)
                    {
                        AoWEUnit.AoWHSMap.ScannerIconsChangedRad(FX, FY, FL, 0);
                    }

                    if (FPlayer > 0 && AoWEUnit.AoWHSMap.FDay > 0)
                    {
                        if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType != TPlayerType.ptHuman)
                        {
                            SetBehavior(255, TGroupBehavior.gbPassive);
                        }
                    }

                    UpdateUnfog();
                    UpdateExploration();
                }
                else
                {
                    FPlayer = Player;
                }

                EndUpdate();
            }
        }

