        // Army.PAS:1416
        public TSet<TMoveType> GetPartyMoves(byte Selection)
        {
            TSet<TMoveType> Result = default;
            TAbstractUnit Transport;
            TSet<TMoveType> Common;
            TSet<TMoveType> Moves;
            int MoveType;
            Transport = Transporter(Selection);
            if (Transport == null)
            {
                Common = TSet<TMoveType>.Of().WithRange(TMoveType.mtWalking, TMoveType.mtTunneling);
                MoveType = (int)TMoveType.mtFlying;
                for (int I = 0, last = GetCount() - 1; I <= last; I++)
                {
                    if (((1 << I) & Selection) != 0)
                    {
                        Moves = ((TAbstractUnit)FChildren.List[I]).GetMoveTypes();
                        Common = Common & Moves;
                        if (MoveType != -1)
                        {
                            if ((TMoveType)MoveType == TMoveType.mtFlying)
                            {
                                if (!Moves.Contains(TMoveType.mtFlying))
                                {
                                    if (Moves.Contains(TMoveType.mtSwimming))
                                    {
                                        MoveType = (int)TMoveType.mtSwimming;
                                    }
                                    else
                                    {
                                        MoveType = (int)TMoveType.mtWalking;
                                    }
                                }
                            }
                            else
                            {
                                if ((TMoveType)MoveType == TMoveType.mtSwimming)
                                {
                                    if ((TSet<TMoveType>.Of(TMoveType.mtFlying, TMoveType.mtSwimming) & Moves) == TSet<TMoveType>.Of())
                                    {
                                        MoveType = (int)TMoveType.mtWalking;
                                    }
                                }
                                else
                                {
                                    if ((TMoveType)MoveType == TMoveType.mtWalking)
                                    {
                                        if ((TSet<TMoveType>.Of(TMoveType.mtWalking, TMoveType.mtFlying).WithRange(TMoveType.mtForestry, TMoveType.mtLavaCrossing) & Moves) == TSet<TMoveType>.Of())
                                        {
                                            MoveType = -1;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }

                // { Original leaves Result uninitialized when the units share no movement mode. }
                if (MoveType != -1)
                {
                    Result = TSet<TMoveType>.Of((TMoveType)MoveType);
                }

                Result = Result + Common;
            }
            else
            {
                Result = Transport.GetMoveTypes();
            }

            return Result;
        }

