                    if (((1 << I) & Selection) != 0)
                    {
                        if (!Units.GetUnit(I).GetTransporter())
                        {
                            List.AddUnit(Units.GetUnit(I));
                        }
                        else
                        {
                            AddUnit(Units.GetUnit(I));
                        }
                    }
                }

                for (int I = List.GetCount() - 1; I >= 0; I--)
                {
                    AddUnit(List.GetUnit(I));
                }

                Units.EndUpdate();
                List?.Dispose();
            }

            return Result;
        }

        // Army.PAS:1881
        public TAbstractUnit SelectionUnit(byte Selection, int Index)
        {
            int I;
            TAbstractUnit Result = null;
            I = 0;
            while (I != FChildren.Count && Result == null)
            {
                if ((Selection & 1) != 0)
                {
                    if (Index == 0)
                    {
                        Result = (TAbstractUnit)FChildren.List[I];
                    }

                    Index -= 1;
                }

                Selection = (byte)(int)(((uint)Selection) >> 1);
                I += 1;
            }

            return Result;
        }

        // Army.PAS:1919
        public void MakeIndependent(byte Selection, ref TArmyHSList Armies)
        {
            sbyte X;
            sbyte Y;
            sbyte L;
            TArmy GoodArmy;
            TArmy EvilArmy;
            TList Races;
            TList Units;
            int Race;
            TAbstractUnit AUnit;
            TAlignment Alignment;
            TArmyHS ArmyHS;
            TArmyHS PlaceIndependentArmy(sbyte AX, sbyte AY, sbyte AL, TArmy Army)
            {
                TArmyHS Result;
                try
                {
                    if (Army.GetCount() != 0)
                    {
                        Result = new TArmyHS(null);
                        Result.FArmy.BeginUpdate();
                        Result.FArmy.AddUnits(Army);
                        if (Result.PlaceEx(X, Y, L, TSet<TArmyPlaceModeElement>.Of(TArmyPlaceModeElement.apSafe, TArmyPlaceModeElement.apScanArea)))
                        {
                            Result.Activate();
                            Result.FArmy.EndUpdate();
                        }
                        else
                        {
                            Result.FArmy.Kill(255);
                            Result?.Dispose();
                            Result = null;
                        }
                    }
                    else
                    {
                        Result = null;
                    }
                }
                catch
                {
                    // { Original suppresses placement failures without releasing a partly built army. }
                    Result = null;
                }

                return Result;
            }

            BeginUpdate();
            GoodArmy = null;
            EvilArmy = null;
            Races = new TList();
            Units = new TList();
            for (int I = 0, last = FChildren.Count - 1; I <= last; I++)
            {
                if ((Selection & 1) != 0)
                {
                    Units.Add(FChildren.List[I]);
                }

                Selection = (byte)(int)(((uint)Selection) >> 1);
            }

            for (int I = Units.Count - 1; I >= 0; I--)
            {
                AUnit = (TAbstractUnit)Units.List[I];
                if (AUnit.GetRace() != -1 && !AUnit.GetAbilityEnabled(107))
                {
                    if (AUnit.GetRace() >= Races.Count)
                    {
                        Races.Count = AUnit.GetRace() + 1;
                    }

                    var race = AUnit.GetRace();
                    if (Races.List[race] == null)
                    {
                        var army = new TArmy(null);
                        var aUnitRace = AUnit.GetRace();
                        Races.List[aUnitRace] = army;
                    }

                    var race2 = AUnit.GetRace();
                    ((TUnitList)Races.List[race2]).AddUnit(AUnit);
                    Units.Delete(I);
                }
            }

            for (int I = Units.Count - 1; I >= 0; I--)
            {
                AUnit = (TAbstractUnit)Units.List[I];
                Alignment = AUnit.GetAlignment();
                Race = -1;
                for (int J = Races.Count - 1; J >= 0; J--)
                {
                    if (Races.List[J] != null && AoWEUnit.AoWHSSet.FRaceResources.GetRaceResource(J).FAlignments.Contains(Alignment))
                    {
                        // { Original chooses the largest compatible race group. }
                        if (Race == -1 || ((TECustomNode)Races.List[Race]).GetCount() <= ((TECustomNode)Races.List[J]).GetCount())
                        {
                            Race = J;
                        }
                    }
                }

                if (Race != -1)
                {
                    ((TUnitList)Races.List[Race]).AddUnit(AUnit);
                    Units.Delete(I);
                }
                else
                {
                    if (AoWEUnit.alsGood.Contains(Alignment) && (!AoWEUnit.alsEvil.Contains(Alignment) || (GoodArmy != null && EvilArmy == null) || (GoodArmy == null && EvilArmy == null) || GoodArmy != null && EvilArmy != null && GoodArmy.GetCount() >= EvilArmy.GetCount()))
                    {
                        if (GoodArmy == null)
                        {
                            GoodArmy = new TArmy(null);
                        }

                        GoodArmy.AddUnit(AUnit);
                        Units.Delete(I);
                    }
                    else
                    {
                        if (EvilArmy == null)
                        {
                            EvilArmy = new TArmy(null);
                        }

                        EvilArmy.AddUnit(AUnit);
                        Units.Delete(I);
                    }
                }
            }

            X = FX;
            Y = FY;
            L = FL;
            EndUpdate();
            for (int I = 0, last = Races.Count - 1; I <= last; I++)
            {
                if (Races.List[I] != null)
                {
                    ArmyHS = PlaceIndependentArmy(X, Y, L, (TArmy)Races.List[I]);
                    if (Armies != null && ArmyHS != null)
                    {
                        Armies.AddChild(ArmyHS);
                    }

                    ((TArmy)Races.List[I])?.Dispose();
                    Races.List[I] = null;
                }
            }

            if (GoodArmy != null)
            {
                ArmyHS = PlaceIndependentArmy(X, Y, L, GoodArmy);
                if (Armies != null && ArmyHS != null)
                {
                    Armies.AddChild(ArmyHS);
                }

                GoodArmy?.Dispose();
            }

            if (EvilArmy != null)
            {
                ArmyHS = PlaceIndependentArmy(X, Y, L, EvilArmy);
                if (Armies != null && ArmyHS != null)
                {
                    Armies.AddChild(ArmyHS);
                }

                EvilArmy?.Dispose();
            }

            Units?.Dispose();
            Races?.Dispose();
        }

        // Army.PAS:2029
        public void UpdateIndependentRelation()
        {
            sbyte Race;
            bool Valid;
            bool Evil;
            bool Good;
            bool Neutral;
            int I;
            int UnitRace;
            TAbstractUnit AUnit;
            TAlignment Alignment;
            if (FPlayer == 0)
            {
                Race = -1;
                Valid = true;
                I = FChildren.Count;
                while (Valid && I != 0)
                {
                    I -= 1;
                    if (!((TAbstractUnit)FChildren.List[I]).GetAbilityEnabled(107))
                    {
                        UnitRace = ((TAbstractUnit)FChildren.List[I]).GetRace();
                    }
                    else
                    {
                        UnitRace = -1;
                    }

                    if (UnitRace != -1 && UnitRace != Race)
                    {
                        if (Race == -1)
                        {
                            Race = (sbyte)UnitRace;
                        }
                        else
                        {
                            Valid = false;
                        }
                    }
                }

                if (Valid && Race == -1)
                {
                    if (FX != -1)
                    {
                        Race = FIndependentRelation;
                        FIndependentRelation = -1;
                        FIndependentRelation = (sbyte)((TAoWMapField)AoWEUnit.AoWHSMap.MapContainer.GetField(FX, FY, FL)).GetIndependentRelation();
                        if (FIndependentRelation >= 0)
                        {
                            Race = FIndependentRelation;
                        }
                        else
                        {
                            FIndependentRelation = Race;
                            Race = -1;
                        }
                    }

                    if (Race == -1)
                    {
                        if (FIndependentRelation >= 0)
                        {
                            Race = FIndependentRelation;
                        }
                        else
                        {
                            Valid = false;
                        }
                    }
                }

                I = FChildren.Count;
                while (Valid && I != 0)
                {
                    I -= 1;
                    bool condition = Race == ((TAbstractUnit)FChildren.List[I]).GetRace();
                    if (!condition)
                    {
                        var alignment = ((TAbstractUnit)FChildren.List[I]).GetAlignment();
                        condition = AoWEUnit.AoWHSSet.FRaceResources.GetRaceResource(Race).FAlignments.Contains(alignment);
                    }

                    Valid = condition;
                }

                if (!Valid)
                {
                    Evil = true;
                    Good = true;
                    Neutral = true;
                    I = 0;
                    int last = FChildren.Count - 1;
                    for (; I <= last; I += 1)
                    {
                        AUnit = (TAbstractUnit)FChildren.List[I];
                        Alignment = AUnit.GetAlignment();
                        Evil = Evil && AoWEUnit.alsEvil.Contains(Alignment) && (AUnit.GetRace() == -1 || TSet<TAlignment>.Of(TAlignment.alEvil, TAlignment.alPureEvil).Contains(Alignment));
                        Good = Good && AoWEUnit.alsGood.Contains(Alignment) && (AUnit.GetRace() == -1 || TSet<TAlignment>.Of(TAlignment.alPureGood, TAlignment.alGood).Contains(Alignment));
                        Neutral = Neutral && AoWEUnit.alsNeutral.Contains(Alignment);
                    }

                    if (Good && !Evil)
                    {
                        FIndependentRelation = -2;
                    }
                    else
                    {
                        if (Evil && !Good)
                        {
                            FIndependentRelation = -4;
                        }
                        else
                        {
                            FIndependentRelation = -3;
                        }
                    }
                }
                else
                {
                    FIndependentRelation = Race;
                }
            }
            else
            {
                FIndependentRelation = -1;
            }
        }

        // Army.PAS:2091
        public void Desert(byte Selection)
        {
            TList Units;
            sbyte Player;
            TArmyHSList Armies;
            int Count;
            int Bit;
            TArmyInfoEventLog Log;
            TAbstractUnit AUnit;
            AoWEUnit.AoWHSMap.LockGameOverEvent();
            Units = new TList();
            Count = SelectionCount(Selection);
            Log = new TArmyInfoEventLog(null);
            Log.FArmyView.Setup(this, 255);
            Log.FSelection = Selection;
            Log.FPlayer = FPlayer;
            Log.FTitle = AoWEUnit.TranslateRStr(AoWEUnit.DesertionRStr);
            Log.FTriggers = TSet<TExecuteTrigger>.Of(TExecuteTrigger.etUser);
            if (AoWEUnit.AoWHSMap.FPlayMode == TPlayMode.pmTurn && AoWEUnit.AoWEngine.FRegistry.GetClassicWindowPopupEvents().Contains(TWindowPopupEvent.wpRebellion))
            {
                Log.FTriggers = Log.FTriggers + TSet<TExecuteTrigger>.Of(TExecuteTrigger.etEvent);
                if (AoWEUnit.AoWHSMap.FRequestCombatType)
                {
                    Log.FTriggers = Log.FTriggers + TSet<TExecuteTrigger>.Of(TExecuteTrigger.etNewTurn);
                }
            }

            if (AoWEUnit.AoWHSMap.FPlayMode == TPlayMode.pmSimultaneous && AoWEUnit.AoWEngine.FRegistry.GetSimultaneousWindowPopupEvents().Contains(TWindowPopupEvent.wpRebellion))
            {
                Log.FTriggers = Log.FTriggers + TSet<TExecuteTrigger>.Of(TExecuteTrigger.etEvent, TExecuteTrigger.etNewTurn);
            }

            Log.FDescription = AoWEUnit.TranslateRStr(AoWEUnit.TheLeaderOfThePartyStepsForwardRStr);
            if (Count == 1)
            {
                Log.FText = AoWEUnit.TranslateRStr(AoWEUnit.OneUnitDesertedRStr);
            }
            else
            {
                Log.FText = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.XUnitsDesertedRStr), [IntToStr(Count)]);
            }

            if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FGems == 0 && AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).GetUpkeep() > AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FIncome)
            {
                if (Count == 1)
                {
                    var desertUnitNoUpkeep = AoWEUnit.TranslateRStr(AoWEUnit.DesertUnitNoUpkeepRStr);
                    Log.FMessages.Text = desertUnitNoUpkeep;
                }
                else
                {
                    var desertUnitsNoUpkeep = AoWEUnit.TranslateRStr(AoWEUnit.DesertUnitsNoUpkeepRStr);
                    Log.FMessages.Text = desertUnitsNoUpkeep;
                }
            }
            else
            {
                if (ValidateSelection(255) == Selection)
                {
                    if (Count == 1)
                    {
                        var desertUnitLowMorale = AoWEUnit.TranslateRStr(AoWEUnit.DesertUnitLowMoraleRStr);
                        Log.FMessages.Text = desertUnitLowMorale;
                    }
                    else
                    {
                        var desertUnitsLowMorale = AoWEUnit.TranslateRStr(AoWEUnit.DesertUnitsLowMoraleRStr);
                        Log.FMessages.Text = desertUnitsLowMorale;
                    }
                }
                else
                {
                    if (Count == 1)
                    {
                        var desertUnitLowMoraleSplit = AoWEUnit.TranslateRStr(AoWEUnit.DesertUnitLowMoraleSplitRStr);
                        Log.FMessages.Text = desertUnitLowMoraleSplit;
                    }
                    else
                    {
                        var desertUnitsLowMoraleSplit = AoWEUnit.TranslateRStr(AoWEUnit.DesertUnitsLowMoraleSplitRStr);
                        Log.FMessages.Text = desertUnitsLowMoraleSplit;
                    }
                }
            }

            DistributeLocationEventLog(Log, -1, FX, FY, FL, true);
            Log.Release();
            for (int I = GetCount() - 1; I >= 0; I--)
            {
                Bit = 1 << I;
                if ((Bit & Selection) != 0 && GetUnit(I).GetAbilityEnabled(155))
                {
                    Units.Add(GetUnit(I));
                    Selection = (byte)(Selection & ~(byte)Bit);
                }
            }

            Armies = new TArmyHSList(null);
            Player = FPlayer;
            MakeIndependent(Selection, ref Armies);
            while (Units.Count != 0)
            {
                AUnit = (TAbstractUnit)Units[0];
                AUnit.AddRef();
                AUnit.Killed();
                AUnit.SetOwner(null);
                AUnit.Release();
                Units.Delete(0);
            }

            for (int I = 0, last = Armies.GetCount() - 1; I <= last; I++)
            {
                if (AoWEUnit.DiplomaticRelation(0, Armies.GetArmyHS(I).FArmy.FIndependentRelation, Player, 0) == TDiplomaticRelation.drWar)
                {
                    Armies.GetArmyHS(I).FArmy.SetBehavior(255, TGroupBehavior.gbRaid);
                }
                else
                {
                    Armies.GetArmyHS(I).FArmy.SetBehavior(255, TGroupBehavior.gbScout);
                }
            }

            Armies?.Dispose();
            Units?.Dispose();
            AoWEUnit.AoWHSMap.UnlockGameOverEvent();
        }

        // Army.PAS:2155
        public TPartyStatus GetPartyStatus(byte Selection)
        {
            TPartyStatus Result;
            int Morale;
            int Count;
            TCombatPredictor Predictor;
            int UnitMorale;
            TAbstractUnit AUnit;
            Morale = 100;
            Count = 0;
            Predictor = new TCombatPredictor();
            for (int I = 0, last = FChildren.Count - 1; I <= last; I++)
            {
                if ((Selection & 1) != 0)
                {
                    AUnit = (TAbstractUnit)FChildren.List[I];
                    UnitMorale = AUnit.FMoraleValue;
                    if (AUnit.GetUnitType() != TUnitType.utMachine)
                    {
                        if (UnitMorale < Morale)
                        {
                            Morale = UnitMorale;
                        }

                        Count += 1;
                    }

                    if (UnitMorale <= 40)
                    {
                        Predictor.AddOpponent(AUnit, 0);
                    }
                    else
                    {
                        Predictor.AddUnit(AUnit);
                    }
                }

                Selection = (byte)(int)(((uint)Selection) >> 1);
            }

            if (Predictor.Execute() == TCombatResult.crDefeat)
            {
                if (Predictor.GetSuperiority() < 50)
                {
                    Result = TPartyStatus.psUnruly;
                }
                else
                {
                    Result = TPartyStatus.psUnrest;
                }
            }
            else
            {
                if (Count == 0 || Morale <= 60)
                {
                    Result = TPartyStatus.psStable;
                }
                else
                {
                    if (Morale <= 80)
                    {
                        Result = TPartyStatus.psContent;
                    }
                    else
                    {
                        Result = TPartyStatus.psCheerful;
                    }
                }
            }

            Predictor?.Dispose();
            return Result;
        }

        // Army.PAS:2185
        public void UpdateDesertion()
        {
            TPartyStatus Status;
            int Chance;
            byte Selection;
            if (FX != -1 && FPlayer != 0)
            {
                Status = GetPartyStatus(255);
                if (TSet<TPartyStatus>.Of(TPartyStatus.psUnruly, TPartyStatus.psUnrest).Contains(Status))
                {
                    if (Status == TPartyStatus.psUnrest)
                    {
                        Chance = 10;
                    }
                    else
                    {
                        Chance = 50;
                    }

                    if (Chance > AoWEUnit.AoWHSMap.Random(100))
                    {
                        Selection = 0;
                        for (int I = FChildren.Count - 1; I >= 0; I--)
                        {
                            Selection = (byte)(Selection << 1);
                            if (((TAbstractUnit)FChildren.List[I]).FMoraleValue <= 40)
                            {
                                Selection = (byte)(Selection | 1);
                            }
                        }

                        if (Selection != 0)
                        {
                            Desert(Selection);
                        }
                    }
                }
            }
        }

        // Army.PAS:2208
        public bool ValidateCrusaders()
        {
            int I;
            I = GetCount();
            bool Result = false;
            while (I != 0 && !Result)
            {
                I -= 1;
                if (((TAbstractUnit)FChildren.List[I]).GetAbilityEnabled(101))
                {
                    Result = true;
                }
            }

            if (Result)
            {
                BeginUpdate();
                I = GetCount() - 1;
                for (; I >= 0; I -= 1)
                {
                    if (((TAbstractUnit)FChildren.List[I]).GetAbilityEnabled(101))
                    {
                        ((TAbstractUnit)FChildren.List[I]).ValidateCrusader();
                    }
                }

                Result = GetCount() != 0;
                EndUpdate();
            }
            else
            {
                Result = true;
            }

            return Result;
        }

