        // Army.PAS:2288
        public TMoveAction GetMoveAction(sbyte Player)
        {
            TMoveAction Result = TMoveAction.maNormal;
            if (Player != FPlayer)
            {
                if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType == TPlayerType.ptHuman)
                {
                    if (!FStatus.Contains(TArmyStatusElement.asFullyConcealed))
                    {
                        if (FPlayer == 0 && GetJoinSelection(Player) != 0)
                        {
                            Result = TMoveAction.maNegotiate;
                        }
                        else
                        {
                            Result = TMoveAction.maAttack;
                        }
                    }
                }
                else
                {
                    if (FPlayer == 0 && GetJoinSelection(Player) != 0)
                    {
                        Result = TMoveAction.maNegotiate;
                    }
                    else
                    {
                        Result = TMoveAction.maAttack;
                    }
                }
            }
            else
            {
                Result = TMoveAction.maCombine;
            }

            return Result;
        }

        // Army.PAS:2306
        public byte GetCanJoinSelection(sbyte Player)
        {
            byte Result;
            TAbstractUnit AUnit;
            if (Player > 0)
            {
                Result = 0;
                for (int I = Count - 1; I >= 0; I--)
                {
                    Result = (byte)(Result << 1);
                    AUnit = (TAbstractUnit)FChildren.List[I];
                    if (AUnit.CanJoin(Player))
                    {
                        Result = (byte)(Result | 1);
                    }
                }

                if (IndexOfTransporter(255) != -1)
                {
                    if (Result != ValidateSelection(255))
                    {
                        Result = 0;
                    }
                }
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // Army.PAS:2324
        public byte GetJoinSelection(sbyte Player)
        {
            bool WantsJoin;
            int I;
            byte Result = 0;
            if (Player > 0)
            {
                WantsJoin = false;
                I = Count;
                while (!WantsJoin && I != 0)
                {
                    I -= 1;
                    WantsJoin = ((TAbstractUnit)FChildren.List[I]).OfferToJoin(Player);
                }

                if (WantsJoin)
                {
                    Result = GetCanJoinSelection(Player);
                }
            }

            return Result;
        }

