            TMapFieldMsg Msg = default;
            FArmy.BeginUpdate();
            OldField = (TMapField)Owner;
            if (OldField != null)
            {
                Msg.MsgID = 4416;
                Msg.Param[0] = this;
                Msg.Param[1] = Field;
                Msg.Result = 0;
                OldField.SendMapFieldMsg(ref Msg);
            }

            if (OldField == null || Msg.Result.Int == 0)
            {
                Msg.MsgID = 4417;
                Msg.Param[0] = this;
                Msg.Param[1] = OldField;
                Msg.Result = 0;
                Field.SendMapFieldMsg(ref Msg);
                if (Msg.Result.Int == 0)
                {
                    base.MoveTo(Field, MoveCost);
                    if (OldField != null && (Field.Lhx != OldField.Lhx || !ConnectingHX(OldField.Xhx, OldField.Yhx, Field.Xhx, Field.Yhx)))
                    {
                        AoWEUnit.AoWHSMap.NotifyPlayerChanged(OldField.Xhx, OldField.Yhx, OldField.Lhx);
                        AoWEUnit.AoWHSMap.NotifyPlayerChanged(Field.Xhx, Field.Yhx, Field.Lhx);
                    }
                    else
                    {
                        AoWEUnit.AoWHSMap.NotifyPlayerChangedEx(Field.Xhx, Field.Yhx, Field.Lhx, 13);
                    }

                    FArmy.Validate();
                    FArmy.MovedTo(OldField, Field, MoveCost);
                    Msg.MsgID = 4418;
                    Msg.Param[0] = this;
                    Msg.Param[1] = OldField;
                    Msg.Result = 0;
                    Field.SendMapFieldMsg(ref Msg);
                    if (FArmy.FPlayer > 0)
                    {
                        var visibilityRange = FArmy.VisibilityRange();
                        var trueVisionRange = FArmy.TrueVisionRange();
                        AoWEUnit.AoWHSMap.UpdatePlayerSeen(FArmy.FPlayer, Field.Xhx, Field.Yhx, Field.Lhx, visibilityRange, trueVisionRange);
                    }

                    Result = true;
                }
                else
