            else
            {
                I = 0;
            }

            FUnitIndex = (byte)I;
            SetUnitGFXResourceIndex(FArmy.GetUnit(I).GetUnitGFXResourceIndex());
            if (FArmy.GetUnit(I).GetMoveTypes().Contains(TMoveType.mtFlying))
            {
                FUnitYOffset = -8;
