        // Army.PAS:3490
        public bool PlaceEx(sbyte X, sbyte Y, sbyte L, TSet<TArmyPlaceModeElement> Mode)
        {
            TMapLevel Level;
            TAoWMapField Field;
            TMapFieldMsg Msg = default;
            THNWalkData Walk = default;
            int Player;
            bool Result = false;
            Level = AoWEUnit.AoWHSMap.MapContainer.GetMapLevel(L);
            InitHNWalk(ref Walk, X, Y, 0);
            while (!Result && (Walk.Radius == 0 || Mode.Contains(TArmyPlaceModeElement.apScanArea)) && Walk.Radius < 30)
            {
                if (Walk.X >= 0 && Walk.Y >= 0 && Walk.X < Level.Width && Walk.Y < Level.Height)
                {
                    Field = (TAoWMapField)Level.GetField(Walk.X, Walk.Y);
                    if (Field.FindOwnedChild(131607) == null)
                    {
                        Player = Field.GetPlayer();
                        if (Player == -1 || (Player == FArmy.FPlayer && Mode.Contains(TArmyPlaceModeElement.apEnableOwnPlayerLocation)))
                        {
                            Msg.MsgID = 4384;
                            Msg.Param[0] = this;
                            Msg.Result = 0;
                            Field.SendMapFieldMsg(ref Msg);
                            if (Msg.Result.Int == 0)
                            {
                                if (FArmy.CanPlace((sbyte)Walk.X, (sbyte)Walk.Y, L))
                                {
                                    MoveTo(Field, 0);
                                    Result = true;
                                }
                            }
                        }
                    }
                }

                WalkToNextHN(ref Walk);
            }

            return Result;
        }

