                        ShowEvent = ShowEvent || AoWEUnit.AoWHSMap.FPlayMode == TPlayMode.pmSimultaneous && AoWEUnit.AoWEngine.FRegistry.GetSimultaneousWindowPopupEvents().Contains(TWindowPopupEvent.wpPartyDamage);
                    }

                    ShowEvent = ShowEvent || FGameOver;
                    if (ShowEvent)
