        public override void Dispose()
        {
            FMessages?.Dispose();
            FArmyView?.Dispose();
            base.Dispose();
        }

        // Army.PAS:273
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwEObject(FArmyView, 15);
            Stream.rwStrings(FMessages, 16);
            Stream.rwData(Bytes.Of(ref FSelection, 1), 1, 17);
            Stream.rwString(ref FTitle, 18);
            Stream.rwString(ref FText, 19);
            Stream.rwString(ref FDescription, 20);
        }

        // Army.PAS:287
        public override string GetText() => FText;

        // Army.PAS:297
        public override bool Execute(bool Mode, TExecuteTrigger Trigger, TExecuteDoneEvent Done)
        {
            bool Result = false;
            if (FTriggers.Contains(Trigger))
            {
                switch (Trigger)
                {
                    case TExecuteTrigger.etUser:
                        AoWEUnit.AoWHSMap.TriggerExecuteEventLog(this, false, Done);
                        Result = true;
                        break;
                    case TExecuteTrigger.etNewTurn:
                        if (AoWEUnit.AoWHSMap.FSeatedPlayer == FPlayer || AoWEUnit.AoWHSMap.FSeatedPlayer == FArmyView.FPlayer)
                        {
                            AoWEUnit.AoWHSMap.TriggerExecuteEventLog(this, false, Done);
                            Result = true;
                        }

                        break;
                    case TExecuteTrigger.etEvent:
                        if (AoWEUnit.AoWHSMap.FConnectionType == TPlayerConnectionType.pcLocal && (AoWEUnit.AoWHSMap.FSeatedPlayer == FPlayer || AoWEUnit.AoWHSMap.FSeatedPlayer == FArmyView.FPlayer))
                        {
                            AoWEUnit.AoWHSMap.TriggerExecuteEventLog(this, false, Done);
                            Result = true;
                        }
                        else
                        {
                            PlaySample("SFX\\EVENTS\\NEWEVENT.WAV");
                        }

                        break;
                }
            }

            return Result;
        }

        // Army.PAS:290
        public override void ViewLocation()
        {
            TArmyView Army;
            Army = FArmyView;
            if (Army != null && Army.FX != -1)
            {
                CenterViewTo(Army.FX, Army.FY, Army.FL);
            }
        }

        // Army.PAS:284
        public void SetArmyView(TArmyView Value)
        {
            FArmyView.Assign(Value, AoWEUnit.AoWEngine);
        }

    }
}

