        // PlayerC.PAS:1839
        public Aow.Game.Draw.Images.TLibraryImage GetCityImage(int Size, int Terrain, int Level)
        {
            Aow.Game.Draw.Images.TLibraryImage Result;
            int Index;
            if (Terrain == 5)
            {
                Index = Size + 60 - 1;
            }
            else
            {
                Index = Terrain * 10 + 70 + (Size - 1);
            }

            if (FImageLibrary.ImageExist(Index))
            {
                Result = FImageLibrary[Index];
            }
            else
            {
                Result = null;
            }

            if (Result == null)
            {
                if (Level == 0)
                {
                    Index = Size + 50 - 1;
                }
                else
                {
                    Index = Size + 60 - 1;
                }

                if (FImageLibrary.ImageExist(Index))
                {
                    Result = FImageLibrary[Index];
                }
            }

            return Result;
        }

        // PlayerC.PAS:1875
        public TAlignment GetAlignment()
        {
            TAlignment Result;
            if (FAlignments == AoWEUnit.alsPureGood)
            {
                return TAlignment.alPureGood;
            }

            if (FAlignments == AoWEUnit.alsGood)
            {
                Result = TAlignment.alGood;
            }
            else
            {
                if (FAlignments == AoWEUnit.alsNeutral)
                {
                    Result = TAlignment.alNeutral;
                }
                else
                {
                    if (FAlignments == AoWEUnit.alsEvil)
                    {
                        Result = TAlignment.alEvil;
                    }
                    else
                    {
                        if (FAlignments == AoWEUnit.alsPureEvil)
                        {
                            Result = TAlignment.alPureEvil;
                        }
                        else
                        {
                            if (FAlignments == AoWEUnit.alsPureNeutral)
                            {
                                Result = TAlignment.alPureNeutral;
                            }
                            else
                            {
                                Result = TAlignment.alNone;
                            }
                        }
                    }
                }
            }

            return Result;
        }

