    // connected/visible flags, structure
    public partial class TStructureShadow : THexagonSprite
    {
        public TStructureShadow(TECustomNode owner) : base(owner)
        { }

        public TSet<TStructureShadowStatusElement> FShadowStatus;
        public TStructure FStructure;

        // Structur.PAS:934
        public override void Dispose()
        {
            if (FShadowStatus.Contains(TStructureShadowStatusElement.sssVisible))
            {
                AoWEUnit.AoWHSMap.StaticVisibleHS.RemoveChild(this);
            }

            base.Dispose();
        }

        // Structur.PAS:940
        public override void SetVisible(bool Value)
        {
            if (Value)
            {
                FShadowStatus = FShadowStatus + TSet<TStructureShadowStatusElement>.Of(TStructureShadowStatusElement.sssVisible);
            }
            else
            {
                FShadowStatus = FShadowStatus - TSet<TStructureShadowStatusElement>.Of(TStructureShadowStatusElement.sssVisible);
            }
        }

        // Structur.PAS:946
        public override bool GetVisible() => FShadowStatus.Contains(TStructureShadowStatusElement.sssVisible);

        // Structur.PAS:995
        public override int GetShowPriority() => (FStructure.GetShowPriority() & 67108863) + 805306368;

        // Structur.PAS:951
        public override void Connect()
        {
            THNWalkData Walk = default;
            int Count;
            TMapLevel Level;
            if (!FShadowStatus.Contains(TStructureShadowStatusElement.sssConnected))
            {
                FShadowStatus = FShadowStatus + TSet<TStructureShadowStatusElement>.Of(TStructureShadowStatusElement.sssConnected);
                Count = FStructure.GetTerrainCount();
                Level = (TMapLevel)FStructure.Owner.Owner;
                InitHNWalk(ref Walk, FStructure.FXhx, FStructure.FYhx, 0);
                while (Walk.HN < Count)
                {
                    if ((FStructure.GetTerrain(Walk.HN) >= -1 || FStructure.GetOverlay(Walk.HN) >= -1) && Walk.X >= 0 && Walk.Y >= 0 && Walk.X < Level.Width && Walk.Y < Level.Height)
                    {
                        Level.GetField(Walk.X, Walk.Y).AddHS(this, Walk.HN);
                    }

                    WalkToNextHN(ref Walk);
                }
            }
        }

        // Structur.PAS:973
        public override void Disconnect()
        {
            THNWalkData Walk = default;
            int Count;
            TMapLevel Level;
            if (FShadowStatus.Contains(TStructureShadowStatusElement.sssConnected))
            {
                Count = FStructure.GetTerrainCount();
                FShadowStatus = FShadowStatus - TSet<TStructureShadowStatusElement>.Of(TStructureShadowStatusElement.sssConnected);
                Level = (TMapLevel)FStructure.Owner.Owner;
                InitHNWalk(ref Walk, FStructure.FXhx, FStructure.FYhx, 0);
                while (Walk.HN < Count)
                {
                    if ((FStructure.GetTerrain(Walk.HN) >= -1 || FStructure.GetOverlay(Walk.HN) >= -1) && Walk.X >= 0 && Walk.Y >= 0 && Walk.X < Level.Width && Walk.Y < Level.Height)
                    {
                        Level.GetField(Walk.X, Walk.Y).RemoveHS(this);
                    }

                    WalkToNextHN(ref Walk);
                }
            }
        }

        // Structur.PAS:1000
        public override void Show(int XhpSurf, int YhpSurf, in TSurfaceDesc SurfaceDesc)
        {
            FStructure.ShowShadow(XhpSurf, YhpSurf, SurfaceDesc);
        }

        // Engine.pas:524

    }
