        // Structur.PAS:1734
        public virtual bool GenerateRazeDefenders(sbyte Player, TUnitList Units)
        {
            int Collection;
            TUnitIndexList Indexes;
            var xhx = GetXhx();
            var yhx = GetYhx();
            RandSeed = xhx + AoWEUnit.AoWHSMap.FInitialRandomSeed + yhx;
            Collection = ((TStructureResource)FResource).FDefenders.GetRndCollection();
            if (Collection != -1)
            {
                Indexes = new TUnitIndexList();
                var unitIndexListCollection = ((TStructureResource)FResource).FDefenders;
                for (int I = unitIndexListCollection.GetCollectionCount(Collection) - 1; I >= 0; I--)
                {
                    Indexes.Add(unitIndexListCollection.GetU(Collection, I));
                }

                AoWEUnit.FillWithRandomUnits(Indexes, Units, 4, ((TStructureResource)FResource).FRazeDefenderBudget, TSet<TUnitType>.Of(TUnitType.utHumanoid, TUnitType.utCreature, TUnitType.utMachine));
                while (Units.Count > 8)
                {
                    Units.DeleteUnit(Units.GetUnit(Units.Count - 1));
                }

                Indexes?.Dispose();
            }

            return true;
        }

        // Structur.PAS:1767
        public virtual bool PlaceRazeDefenders(sbyte Player)
        {
            bool Result;
            TUnitList Defenders;
            TUnitList Placed;
            TUnitList Attackers;
            TAbstractUnit AUnit;
            Defenders = new TUnitList(null);
            Placed = new TUnitUserList(null);
            Attackers = new TUnitUserList(null);
            GenerateRazeDefenders(Player, Defenders);
            if (Defenders.Count != 0)
            {
                for (int I = Defenders.Count - 1; I >= 0; I--)
                {
                    AUnit = Defenders.GetUnit(I);
                    Placed.AddUnit(AUnit);
                    var lhx = GetLhx();
                    var yhx = GetYhx();
                    AUnit.Place(GetXhx(), yhx, lhx, 0, TSet<TUnitPlaceModeElement>.Of(TUnitPlaceModeElement.pmScanArea));
                }

                ListUnits(Attackers);
                SetupRazeDefenderAG(Attackers, Placed);
                Result = true;
            }
            else
            {
                Result = false;
            }

            Attackers?.Dispose();
            Placed?.Dispose();
            Defenders?.Dispose();
            return Result;
        }

        // Structur.PAS:1801
        public virtual bool ExecuteRaze(sbyte Player)
        {
            bool Result = default;
            string Reason = "";
            TLocationTextEventLog Log = default;
            TImageSequenceAnimation Animation = default;
            if (CanRaze(Player, ref Reason))
            {
                BeginUpdate();
                Log = new TLocationTextEventLog(null);
                Log.FPlayer = Player;
                var editName = EditName();
                Log.FText = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.StructureRazedRStr), [editName]);
                var lhx = GetLhx();
                var yhx = GetYhx();
                Log.SetLocation(GetXhx(), yhx, lhx);
                var yhx2 = GetYhx();
                var lhx2 = GetLhx();
                DistributeLocationEventLog(Log, Player, GetXhx(), yhx2, lhx2, false);
                Log.Release();
                if (FResource.ImageSequenceList.GetImageSequence(20) != null)
                {
                    Animation = new TImageSequenceAnimation(null);
                    Animation.SetImageSequence(FResource.ImageSequenceList.GetImageSequence(20));
                    Animation.SetXhpOffset(Animation.FXhpOffset - 16);
                    Animation.SetYhpOffset(Animation.FYhpOffset - 16);
                    Animation.FOnShow = ShowRazeAnimation;
                    var lhx3 = GetLhx();
                    var yhx3 = GetYhx();
                    var xhx = GetXhx();
                    AoWEUnit.AoWHSMap.PlaceHX(Animation, xhx, yhx3, lhx3);
                }

                if (FResource.ImageSequenceList.GetImageSequence(21) != null)
                {
                    Animation = new TImageSequenceAnimation(null);
                    Animation.SetImageSequence(FResource.ImageSequenceList.GetImageSequence(21));
                    Animation.FFrameCount = 300;
                    Animation.SetXhpOffset(Animation.FXhpOffset - 16);
                    Animation.SetYhpOffset(Animation.FYhpOffset - 16);
                    Animation.FLooped = true;
                    var lhx3 = GetLhx();
                    var yhx3 = GetYhx();
                    var xhx = GetXhx();
                    AoWEUnit.AoWHSMap.PlaceHX(Animation, xhx, yhx3, lhx3);
                }

                ValidateObservation(Player);
                SetRazed(true);
                PlaceRazeDefenders(Player);
                EndUpdate();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

