        public virtual bool VisibleForPlayer(sbyte Player)
        {
            THNWalkData Walk = default;
            bool Result = false;
            if (Player >= 0)
            {
                InitHNWalk(ref Walk, FXhx, FYhx, 0);
                while (true)
                {
                    var terrainCount = GetTerrainCount();
                    if (!(Walk.HN < terrainCount && !Result))
                        break;
                    if (FResource.TerrainList.Used[Walk.HN])
                    {
                        var lhx = GetLhx();
                        Result = AoWEUnit.AoWHSMap.VisibleForPlayer(Walk.X, Walk.Y, lhx, Player);
                    }

                    WalkToNextHN(ref Walk);
                }
            }

            return Result;
        }

