        // Structur.PAS:1508
        public virtual int ListUnits(TUnitList List)
        {
            THNWalkData Walk = default;
            int Count;
            TMapLevel Level;
            TArmyHS Army;
            int Result = 0;
            Count = GetTerrainCount();
            Level = (TMapLevel)Owner.Owner;
            InitHNWalk(ref Walk, FXhx, FYhx, 0);
            while (Walk.HN < Count)
            {
                if (FResource.TerrainList.Terrain[Walk.HN] >= 0 && Walk.X >= 0 && Walk.Y >= 0 && Walk.X < Level.Width && Walk.Y < Level.Height)
                {
                    Army = ((TAoWMapField)Level.GetField(Walk.X, Walk.Y)).GetArmyHS();
                    if (Army != null)
                    {
                        List.AddUnits(Army.FArmy);
                        Result += Army.FArmy.Count;
                    }
                }

                WalkToNextHN(ref Walk);
            }

            return Result;
        }

