        // Structur.PAS:1708
        public virtual bool CanRaze(sbyte Player, ref string Reason)
        {
            bool Result;
            TCombatPredictor Predictor;
            TUnitList Defenders;
            TUnitList Units;
            if (!GetRazed() && GetRazeable())
            {
                Predictor = new TCombatPredictor();
                Defenders = new TUnitList(null);
                Units = new TUnitUserList(null);
                ListUnits(Units);
                for (int I = 0, last = Units.Count - 1; I <= last; I++)
                {
                    if (Units.GetUnit(I).FPlayer == Player)
                    {
                        Predictor.AddUnit(Units.GetUnit(I));
                    }
                }

                Units?.Dispose();
                GenerateRazeDefenders(Player, Defenders);
                for (int I = 0, last = Defenders.Count - 1; I <= last; I++)
                {
                    Predictor.AddOpponent(Defenders.GetUnit(I), 0);
                }

                Predictor.Execute();
                Result = TSet<byte>.WithBounds(0, 255).With(3).With(4).With(6).Contains(Predictor.FResult) && Predictor.GetSuperiority() > 50;
                if (!Result)
                {
                    Reason = AoWEUnit.TranslateRStr(AoWEUnit.NotEnoughForcesRStr);
                }

                Defenders?.Dispose();
                Predictor?.Dispose();
            }
            else
            {
                Result = false;
            }

            return Result;
        }

