            int X = default;
            int Y = default;
            TAbstractRoad Road;
            Level = (TMapLevel)MapField.Owner;
            Table = FResource.TerrainList.CreateSurroundingHNTable();
            for (int I = 0, last = Table.Count - 1; I <= last; I++)
            {
                var item = Table[I];
                CenterHNtoHX(MapField.Xhx, MapField.Yhx, item, ref X, ref Y);
                if (X >= 0 && Y >= 0 && X < Level.Width && Y < Level.Height)
                {
                    Road = (TAbstractRoad)Level.GetField(X, Y).FindHS(typeof(TAbstractRoad));
                    if (Road != null)
                    {
                        Road.UpdateTransitions();
                    }
                }
            }

            Table?.Dispose();
        }

