        {
            TDIB16Surface Surface;
            int Width;
            int Height;
            TSurfaceDesc SurfaceDesc = default;
            TRect BorderRect;
            bool Result = false;
            if (GetBottomBorderImage() != null)
            {
                Width = R.Right - R.Left;
                Height = R.Bottom - R.Top;
                Surface = new TDIB16Surface(Width, Height, pfRGB565);
                try
                {
                    BorderRect = Rect(0, 0, Width, Height);
                    Surface.Lock(ref SurfaceDesc);
                    Result = ShowBorderImage(SurfaceDesc, BorderRect);
                    Surface.Unlock();
                    /* TODO: Implement cell or array backing for this address. */
                    throw new NotImplementedException();
                }
                finally
                {
                    Surface?.Dispose();
                }
            }

            return Result;
        }

