                        }

                        Sequence = Sequence.Next;
                    }
                }
                else
                {
                    FImageLibrary[Index].ShowTransparent(X + FdXImage, Y + FdYImage, SurfaceDesc);
                }
            }
            else
            {
                if (FImageSequenceList == null)
                {
                    FImageLibrary[Structure.ImageIndex].Show(X, Y, SurfaceDesc);
