        // Structur.PAS:2030
        public override bool CanRebuild(TAbstractUnit AUnit, ref string Reason) => base.CanRebuild(AUnit, ref Reason);

        // Structur.PAS:2130
        public virtual void SetPlayer(sbyte Player)
        {
            if (Player != FPlayer)
            {
                if (GetRazed() && !GetBuilding())
                {
                    return;
                }

                FProductionPriority = 0;
                if (FPlayer != -1)
                {
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FStructures.RemoveChild(this);
                }

                if (AoWEUnit.AoWHSMap.FDay > 0)
                {
                    StructureCaptured(FPlayer, Player);
                }

                FPlayer = Player;
                UpdateUnfog();
                UpdatePlayerSeen();
                UpdateExploration();
                var hNtoRad = HNtoRad(FResource.TerrainList.Count);
                var lhx = GetLhx();
                var yhx = GetYhx();
                var xhx = GetXhx();
                AoWEUnit.AoWHSMap.ScannerIconsChangedRad(xhx, yhx, lhx, hNtoRad);
                UpdateFlagID();
                FogChanged();
                var lhx2 = GetLhx();
                var yhx2 = GetYhx();
                var xhx2 = GetXhx();
                AoWEUnit.AoWHSMap.NotifyPlayerChanged(xhx2, yhx2, lhx2);
                if (FPlayer != -1)
                {
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FStructures.AddChild(this);
                }

                if (FPlayer > 0 && AoWEUnit.AoWHSMap.FVictoryCondition == TVictoryCondition.vcCaptureLocations)
                {
                    for (int I = 1, last = AoWEUnit.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
                    {
                        if (FVictoryLocations[I])
                        {
                            if (I == FPlayer || AoWEUnit.AoWHSMap.FAlliedVictory && AoWEUnit.AoWHSMap.FPlayers.GetDiplomaticRelation(FPlayer, (sbyte)I) == TDiplomaticRelation.drAlliance)
                            {
                                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).CheckCaptureLocations();
                            }
                        }
                    }
                }

                Update();
            }
        }

