            {
                Result = 6;
                if (GetLhx() != 0 || FPlayer > 0 && (((byte)AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.FEnemyEnchantments.Image) & 8) != 0)
                {
                    Result = (int)(((uint)(Result + 1)) >> 1);
