        // Structur.PAS:2249
        public virtual void UpdateUnfog()
        {
            int Range;
            int X = default;
            int Y = default;
            if (!FStatus.Contains(Aow.Game.World.TMapObjectStatusElement.moPlacedOnMap))
            {
                return;
            }

            if (FStatus.Contains(Aow.Game.World.TMapObjectStatusElement.moActivated) && FPlayer != -1 && AoWEUnit.AoWHSMap.FSeatedPlayer != -1 && (AoWEUnit.AoWHSMap.FSeatedPlayer == FPlayer || AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FDiplomaticRelations.GetDiplomaticRelation(AoWEUnit.AoWHSMap.FSeatedPlayer) == TDiplomaticRelation.drAlliance))
            {
                Range = VisibilityRange();
            }
            else
            {
                Range = 0;
            }

            if (Range != FUnfogRange)
            {
                if (FUnfogRange != 0)
                {
                    for (int I = 0, last = FResource.TerrainList.Count - 1; I <= last; I++)
                    {
                        if (FResource.TerrainList.Terrain[I] >= 0)
                        {
                            CenterHNtoHX(FXhx, FYhx, I, ref X, ref Y);
                            AoWEUnit.AoWHSMap.FogArea(X, Y, ((TMapField)Owner).Lhx, FUnfogRange);
                        }
                    }
                }

                FUnfogRange = (byte)Range;
                if (FUnfogRange != 0)
                {
                    for (int I = 0, last = FResource.TerrainList.Count - 1; I <= last; I++)
                    {
                        if (FResource.TerrainList.Terrain[I] >= 0)
                        {
                            CenterHNtoHX(FXhx, FYhx, I, ref X, ref Y);
                            AoWEUnit.AoWHSMap.UnFogArea(X, Y, ((TMapField)Owner).Lhx, FUnfogRange);
                        }
                    }
                }
            }
        }

        // Structur.PAS:2233
        public virtual void UpdateExploration()
        {
            int X = default;
            int Y = default;
            if (FStatus.Contains(Aow.Game.World.TMapObjectStatusElement.moPlacedOnMap) && FPlayer > 0)
            {
                for (int Player = 1, last = AoWEUnit.AoWHSMap.FPlayers.Count - 1; Player <= last; Player++)
                {
                    if (Player == FPlayer || AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FDiplomaticRelations.GetDiplomaticRelation((sbyte)Player) == TDiplomaticRelation.drAlliance)
                    {
                        for (int I = 0, lastI = FResource.TerrainList.Count - 1; I <= lastI; I++)
                        {
                            if (FResource.TerrainList.Terrain[I] >= 0)
                            {
                                CenterHNtoHX(FXhx, FYhx, I, ref X, ref Y);
                                var visibilityRange = VisibilityRange();
                                AoWEUnit.AoWHSMap.ExploreArea(X, Y, ((TMapField)Owner).Lhx, (sbyte)Player, visibilityRange);
                            }
                        }
                    }
                }
            }
        }

