            FFlags = gameSet.ImageLibraryManager.LinkToIL(TSet<TILManagerCategoryElement>.Of(TILManagerCategoryElement.icDisk), "Flags.ILB");
            this.FRaceResources = gameSet.FRaceResources;

            SetControlStyle(TSet<TEControlStyleElement>.Of(TEControlStyleElement.csFixedChild));
        }

        // PlayerC.PAS:1927
        public void ShowFlag(int X, int Y, int FrameOffset, byte FlagID, in TSurfaceDesc SurfaceDesc)
        {
            FFlags[4].Show(X, Y, SurfaceDesc);
            FrameOffset = (int)(((uint)FrameOffset) >> 2) % 12;
            if ((FlagID & 32) != 0)
            {
                FFlags[FrameOffset + 22].Show(X - 21, Y - 16, SurfaceDesc);
            }
            else
            {
                FRaceResources.GetRaceResource(FlagID & 31).FImageLibrary[FrameOffset + 12].Show(X - 21, Y - 16, SurfaceDesc);
            }
        }

        // PlayerC.PAS:1937
        public void ShowFlagEx(int X, int Y, int FrameOffset, byte FlagID, in TSurfaceDesc SurfaceDesc, bool ShowBase)
        {
            if (ShowBase)
            {
                FFlags[4].Show(X, Y, SurfaceDesc);
            }

            FrameOffset = (int)(((uint)FrameOffset) >> 2) % 12;
            if ((FlagID & 32) != 0)
            {
                FFlags[FrameOffset + 22].Show(X - 21, Y - 16, SurfaceDesc);
            }
            else
            {
                FRaceResources.GetRaceResource(FlagID & 31).FImageLibrary[FrameOffset + 12].Show(X - 21, Y - 16, SurfaceDesc);
            }
        }

        // PlayerC.PAS:1947
        public void ShowStructureFlag(int X, int Y, int FrameOffset, byte FlagID, in TSurfaceDesc SurfaceDesc)
        {
            FFlags[(int)(((uint)FlagID) >> 6)].Show(X, Y, SurfaceDesc);
            FrameOffset = (int)(((uint)FrameOffset) >> 1) % 12;
            if ((FlagID & 32) != 0)
            {
                FFlags[FrameOffset + 10].Show(X - 21, Y - 16, SurfaceDesc);
            }
            else
            {
                FRaceResources.GetRaceResource(FlagID & 31).FImageLibrary[FrameOffset].Show(X - 21, Y - 16, SurfaceDesc);
            }
        }

        // PlayerC.PAS:1957
        public void ShowStructureFlagEx(int X, int Y, int FrameOffset, byte FlagID, in TSurfaceDesc SurfaceDesc, bool ShowBase)
        {
            if (ShowBase)
            {
                FFlags[(int)(((uint)FlagID) >> 6)].Show(X, Y, SurfaceDesc);
            }

            FrameOffset = (int)(((uint)FrameOffset) >> 1) % 12;
            if ((FlagID & 32) != 0)
            {
                FFlags[FrameOffset + 10].Show(X - 21, Y - 16, SurfaceDesc);
            }
            else
            {
                FRaceResources.GetRaceResource(FlagID & 31).FImageLibrary[FrameOffset].Show(X - 21, Y - 16, SurfaceDesc);
            }
        }

        // PlayerC.PAS:1909
        public static TFlagControl Create(TECustomNode owner) =>
            ConstructionContext.Create(owner, static (context, owner) => new TFlagControl(context, owner ?? throw new NullReferenceException()));
    }
