        // Ability.PAS:131
        public override void ReadWrite(TEStorageStream Stream)
        {
            string Path = "";
            bool Loaded = default;
            if (Stream.StorageMode().Contains(TStorageModeElement.smRead))
            {
                Stream.ShowProgress(this, AoWEUnit.TranslateRStr(AoWEUnit.LoadingGamePackRStr), 0);
            }

            base.ReadWrite(Stream);
            Stream.rwEObject(FRaceResources, 10);
            Stream.rwEObject(FItemLibraries, 11);
            if (!Stream.StorageMode().Contains(TStorageModeElement.smTextOnly))
            {
                Path = ExtractFilePath(AoWEUnit.AoWEngine.HSSFileName);
                if (Stream.StorageMode().Contains(TStorageModeElement.smRead))
                {
                    Loaded = AoWEUnit.AoWEngine.ReadFromFileCRC(Path + "ABILITY.PFS", FAbilityControl, null);
                    Stream.ShowProgress(this, AoWEUnit.TranslateRStr(AoWEUnit.LoadingUnitsRStr), 70);
                    Loaded = Loaded && AoWEUnit.AoWEngine.ReadFromFileCRC(Path + "UNITRES.PFS", FUnitResources, null);
                    Loaded = Loaded && AoWEUnit.AoWEngine.ReadFromFileCRC(Path + "UNITGFX.PFS", FUnitGFXResources, null);
                    Stream.ShowProgress(this, AoWEUnit.TranslateRStr(AoWEUnit.LoadingHeroesRStr), 80);
                    Loaded = Loaded && AoWEUnit.AoWEngine.ReadFromFileCRC(Path + "HERORES.PFS", FHeroResources, null);
                    Stream.ShowProgress(this, AoWEUnit.TranslateRStr(AoWEUnit.LoadingItemsRStr), 90);
                    Loaded = Loaded && AoWEUnit.AoWEngine.ReadFromFileCRC(Path + "ITEMGFX.PFS", FItemGFXResources, null);
                    Loaded = Loaded && AoWEUnit.AoWEngine.ReadFromFileCRC(Path + "FACERES.PFS", FFaceResources, null);
                    Loaded = Loaded && AoWEUnit.AoWEngine.ReadFromFileCRC(Path + "COMB_RES.PFS", FCombatResources, null);
                    Loaded = Loaded && AoWEUnit.AoWEngine.ReadFromFileCRC(Path + "SPELLS.PFS", FSpellControl, null);
                    Loaded = Loaded && AoWEUnit.AoWEngine.ReadFromFileCRC(Path + "TEXT.PFS", FTextControl, null);
                    if (!Loaded)
                    {
                        throw new InvalidOperationException("CRC-CHECK FAILED");
                    }

                    Stream.ShowProgress(this, AoWEUnit.TranslateRStr(AoWEUnit.GamePackLoadedRStr), 100);
                }
                else
                {
                    AoWEUnit.AoWEngine.WriteToFileCRC(Path + "ABILITY.PFS", FAbilityControl, null);
                    AoWEUnit.AoWEngine.WriteToFileCRC(Path + "UNITRES.PFS", FUnitResources, null);
                    AoWEUnit.AoWEngine.WriteToFileCRC(Path + "UNITGFX.PFS", FUnitGFXResources, null);
                    AoWEUnit.AoWEngine.WriteToFileCRC(Path + "HERORES.PFS", FHeroResources, null);
                    AoWEUnit.AoWEngine.WriteToFileCRC(Path + "ITEMGFX.PFS", FItemGFXResources, null);
                    AoWEUnit.AoWEngine.WriteToFileCRC(Path + "FACERES.PFS", FFaceResources, null);
                    AoWEUnit.AoWEngine.WriteToFileCRC(Path + "COMB_RES.PFS", FCombatResources, null);
                    AoWEUnit.AoWEngine.WriteToFileCRC(Path + "SPELLS.PFS", FSpellControl, null);
                    AoWEUnit.AoWEngine.WriteToFileCRC(Path + "TEXT.PFS", FTextControl, null);
                }
            }
            else
            {
                Stream.rwEObject(FUnitResources, 111);
                Stream.rwEObject(FUnitGFXResources, 112);
                Stream.rwEObject(FHeroResources, 113);
                Stream.rwEObject(FItemGFXResources, 114);
                Stream.rwEObject(FFaceResources, 115);
                Stream.rwEObject(FSpellControl, 117);
                Stream.rwEObject(FAbilityControl, 118);
                Stream.rwEObject(FTextControl, 119);
            }

            Stream.rwEObject(FHeroLibraries, 17);
            Stream.rwStreamProc(18, FImageSequences.LoadFromStream, FImageSequences.SaveToStream);
            if (Stream.StorageMode().Contains(TStorageModeElement.smRead))
            {
                FImageSequences.LinkToIL();
                FHSSCRC = RetrieveHSSCRC();
            }
        }

