    public partial class TEmailGameList : TENode
    {
        public TEmailGameList(TECustomNode owner) : base(owner)
        { }

        // Diplomacy.pas:2475
        public TEmailGame GetEmailGames(int Index) => (TEmailGame)FChildren.List[Index];

        // Diplomacy.pas:2478
        public int IndexOfUniqueLocalID(int ID)
        {
            int Result = Count;
            while (Result != 0)
            {
                Result -= 1;
                if (((TEmailGame)FChildren.List[Result]).FUniqueLocalID == ID)
                {
                    return Result;
                }
            }

            return -1;
        }

        // Engine.pas:631

    }

    // games
    public partial class TEmailGameControl : TEObject
    {
        // Diplomacy.pas:2489
        public TEmailGameControl(TECustomNode owner) : base(owner)
        {
            FGames = new TEmailGameList(null);
        }

        public TEmailGameList FGames;

        // Diplomacy.pas:2495
        public override void Dispose()
        {
            FGames?.Dispose();
            base.Dispose();
        }

        // Diplomacy.pas:2498
        public int CreateUniqueLocalID()
        {
            int Result = 1;
            while (FGames.IndexOfUniqueLocalID(Result) != -1)
            {
                Result += 1;
            }

            return Result;
        }

        // Diplomacy.pas:2504
        public void Load()
        {
            string FileName;
            FGames.Clear();
            FileName = AoWEUnit.AoWEngine.StartupDirectory + "EmailIn\\" + "egames.pfs";
            if (FileExists(FileName))
            {
                if (GetFileCRC32(FileName) == AoWEUnit.AoWEngine.FRegistry.GetEmailGamesCRC())
                {
                    AoWEUnit.AoWEngine.ReadFromFile(FileName, FGames, null);
                }
            }
        }

        // Diplomacy.pas:2514
        public void Save()
        {
            string FileName;
            try
            {
                FileName = AoWEUnit.AoWEngine.StartupDirectory + "EmailIn\\" + "egames.pfs";
                AoWEUnit.AoWEngine.WriteToFile(AoWEUnit.AoWEngine.StartupDirectory + "EmailIn\\" + "egames.pfs", FGames, null);
                var fileCRC = GetFileCRC32(FileName);
                AoWEUnit.AoWEngine.FRegistry.SetEmailGamesCRC(fileCRC);
            }
            catch
            {
            }
        }

        // Diplomacy.pas:2525
        public TEmailGame FindEmailGame(TEmailGame Game)
        {
            TEmailGame Result;
            int Index;
            Index = FGames.IndexOfUniqueLocalID(Game.FUniqueLocalID);
            if (Index != -1 && Game.FUniqueID != 0 && FGames.GetEmailGames(Index).FUniqueID == Game.FUniqueID)
            {
                Result = FGames.GetEmailGames(Index);
            }
            else
            {
                Result = null;
            }

            return Result;
        }

        // Diplomacy.pas:2535
        public bool EmailGameRestarted(TEmailGame Game)
        {
            bool Result;
            TEmailGame LocalGame;
            if (Game.FSecurityID != 0)
            {
                LocalGame = FindEmailGame(Game);
                Result = LocalGame == null || Game.FSecurityID != LocalGame.FSecurityID;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Diplomacy.pas:2546
        public int GenerateSecurityID() => Random(GetElapsedMilliSeconds() & 16777215) + 1;

        // Diplomacy.pas:2549
        public bool UpdateGame(TEmailGame Game)
        {
            bool Result;
            TEmailGame LocalGame;
            LocalGame = FindEmailGame(Game);
            if (LocalGame != null)
            {
                LocalGame.FLastDay = Game.FLastDay;
                LocalGame.FSecurityID = GenerateSecurityID();
                Game.FSecurityID = LocalGame.FSecurityID;
                Save();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Diplomacy.pas:2564
        public TEmailGame CreateEmailGame(string Name, string EmailAddress)
        {
            TEmailGame Result = new TEmailGame(null);
            Result.FEmailAddress = EmailAddress;
            Result.FUniqueLocalID = CreateUniqueLocalID();
            Result.FUniqueID = Random(GetElapsedMilliSeconds() & 16777215) + 1;
            Result.FSecurityID = GenerateSecurityID();
            Result.FName = Name;
            Result.SetOwner(FGames);
            Save();
            return Result;
        }

        // Diplomacy.pas:2576
        public void ValidateIncommingGame(string FileName, ref string Destination)
        {
            TAoWHSMap Map;
            TAoWHSMap PreviousMap;
            TEmailGame LocalGame;
            bool Overwrite;
            int I;
            string Name = "";
            // { Addressability survives elimination of this assignment. }
            try
            {
                Destination = "";
                Overwrite = false;
                Map = (TAoWHSMap)AoWEUnit.AoWEngine.CreatePreviewHSM(FileName, Aow.Formats.GameProfile.WorldMap);
                bool condition = Map != null && Map.FConnectionType == TPlayerConnectionType.pcEmail && Map.FCurrentPlayer > 0;
                if (condition)
                {
                    var count = Map.FPlayers.Count;
                    condition = Map.FCurrentPlayer < count;
                }

                if (condition && Map.FPlayers.GetPlayers(Map.FCurrentPlayer).FPBEMSettings.FStatus.Contains(TPBEMPlayerStatusElement.pbsNewTurn))
                {
                    var localEmailAddress = AoWEUnit.AoWEngine.FRegistry.GetLocalEmailAddress();
                    if (CompareText(Map.FPlayers.GetPlayers(Map.FCurrentPlayer).FPBEMSettings.FEmailGame.FEmailAddress, localEmailAddress) == 0)
                    {
                        LocalGame = FindEmailGame(Map.FPlayers.GetPlayers(Map.FCurrentPlayer).FPBEMSettings.FEmailGame);
                        if (LocalGame != null)
                        {
                            if (Map.FDay > LocalGame.FLastDay)
                            {
                                Name = Map.FPlayers.GetPlayers(Map.FCurrentPlayer).FPBEMSettings.FEmailGame.FName;
                                if (FileExists(AoWEUnit.AoWEngine.StartupDirectory + "EmailIn\\" + Name + ".asg"))
                                {
                                    PreviousMap = (TAoWHSMap)AoWEUnit.AoWEngine.CreatePreviewHSM(AoWEUnit.AoWEngine.StartupDirectory + "EmailIn\\" + Name + ".asg", Aow.Formats.GameProfile.WorldMap);
                                    if (PreviousMap != null)
                                    {
                                        // { Original bug: the previous map's player is checked against the new map's count. }
                                        bool test = PreviousMap.FCurrentPlayer > 0;
                                        if (test)
                                        {
                                            var count = Map.FPlayers.Count;
                                            test = PreviousMap.FCurrentPlayer < count;
                                        }

                                        if (test)
                                        {
                                            var players = PreviousMap.FPlayers.GetPlayers(PreviousMap.FCurrentPlayer);
                                            var fPlayersPlayers = Map.FPlayers.GetPlayers(Map.FCurrentPlayer);
                                            bool passed = players.FPBEMSettings.FEmailGame.FUniqueLocalID == fPlayersPlayers.FPBEMSettings.FEmailGame.FUniqueLocalID;
                                            if (passed)
                                            {
                                                var players2 = PreviousMap.FPlayers.GetPlayers(PreviousMap.FCurrentPlayer);
                                                var players3 = Map.FPlayers.GetPlayers(Map.FCurrentPlayer);
                                                passed = players2.FPBEMSettings.FEmailGame.FUniqueID == players3.FPBEMSettings.FEmailGame.FUniqueID;
                                            }

                                            if (passed)
                                            {
                                                Overwrite = true;
                                            }
                                        }

                                        PreviousMap?.Dispose();
                                    }
                                }
                            }
                        }
                        else
                        {
                            Name = Map.FPlayers.GetPlayers(Map.FCurrentPlayer).FPBEMSettings.FEmailGame.FName;
                        }

                        if (!IsEmpty(Name))
                        {
                            I = 0;
                            Destination = AoWEUnit.AoWEngine.StartupDirectory + "EmailIn\\" + Name + ".asg";
                            while (!Overwrite && FileExists(Destination))
                            {
                                I += 1;
                                Destination = AoWEUnit.AoWEngine.StartupDirectory + "EmailIn\\" + Name + IntToStr(I) + ".asg";
                            }
                        }
                    }
                }

                Map?.Dispose();
            }
            catch
            {
            }
        }

