        // CombatPredictor.pas:739
        public void InitAdjacentArmies(TArmyHS Army, sbyte X, sbyte Y, sbyte L)
        {
            TMapLevel Level;
            TArmyHS ArmyHS;
            TAbstractUnit U;
            byte Defender;
            byte Player;
            byte Relation;
            byte DefenderRelation;
            TCombatSideIndex Side;
            TMapField Field;
            TMapFieldMsg Msg = default;
            THNWalkData Walk = default;
            AddUnits(Army.FArmy);
            Level = AoWEUnit.AoWHSMap.MapContainer.GetMapLevel(L);
            var army = Army.FArmy;
            Player = (byte)army.FPlayer;
            Relation = (byte)army.FIndependentRelation;

            Defender = (byte)((TAoWMapField)Level.GetField(X, Y)).GetPlayer();
            DefenderRelation = ((TAoWMapField)Level.GetField(X, Y)).GetIndependentRelation();
            if (Defender != 255)
            {
                Msg.MsgID = 4387;
                var fieldValue = Level.GetField(X, Y);
                Msg.Param[0] = fieldValue;
                Msg.Result = 0;
                Level.GetField(X, Y).SendMapFieldMsg(ref Msg);
                if ((TWallType)Msg.Result.Int != TWallType.wtNone)
                {
                    AddWall((TWallType)Msg.Result.Int);
                }

                InitHNWalk(ref Walk, X, Y, 0);
                while (Walk.Radius <= 1)
                {
                    if (Walk.X >= 0 && Walk.Y >= 0 && Walk.X < Level.Width && Walk.Y < Level.Height)
                    {
                        ArmyHS = (TArmyHS)Level.GetField(Walk.X, Walk.Y).FindOwnedChild(131607);
                        if (ArmyHS != null && ArmyHS != Army)
                        {
                            Side = AoWEUnit.GetCombatSide((sbyte)Player, (sbyte)Relation, (sbyte)Defender, (sbyte)DefenderRelation, ArmyHS.FArmy.FPlayer, ArmyHS.FArmy.FIndependentRelation);
                            if (Side != TCombatSideIndex.csNeutral)
                            {
                                Field = Level.GetField(X, Y);
                                Msg.MsgID = 4387;
                                var levelField = Level.GetField(Walk.X, Walk.Y);
                                Msg.Param[0] = levelField;
                                Msg.Result = 0;
                                Field.SendMapFieldMsg(ref Msg);
                                for (int I = 0, last = ArmyHS.FArmy.Count - 1; I <= last; I++)
                                {
                                    U = ArmyHS.FArmy.GetUnit(I);
                                    if (U.ValidTerrain(Field.TerrainType, Field.OverlayType))
                                    {
                                        AddUnitEx(U, (byte)(int)Side, (byte)((TWallType)Msg.Result.Int != TWallType.wtNone ? 1 : 0));
                                    }
                                }
                            }
                        }
                    }

                    WalkToNextHN(ref Walk);
                }
            }
        }

