        // CombatPredictor.pas:1004
        public int Usefullness(TAbstractUnit AUnit)
        {
            int Result;
            TCombatPredictorUnit Wall;
            TCombatPredictorUnit U;
            TCombatPredictorUnit Target;
            int I;
            bool AllDead;
            bool Useful;
            EnableAllUnits();
            Validate();
            U = new TCombatPredictorUnit();
            U.Setup(AUnit, (TCombatPredictor)(object)this, 0);
            Wall = FWall;
            if (Wall != null && Wall.FHitPoints > 0)
            {
                U.UpdateWallTargets();
                Result = U.FWallCombatValue;
                Useful = false;
                I = U.FWallTargets.Count;
                while (I != 0 && !Useful)
                {
                    I -= 1;
                    if (U.FWallTargets.List[I].B > 0)
                    {
                        Target = U.FWallTargets.List[I].A;
                        Useful = Target == FWall && Target.FHitPoints > 0;
                    }
                }

                if (Useful)
                {
                    Result = Result | 8388608;
                }
            }
            else
            {
                U.UpdateTargets();
                Result = U.FCombatValue;
                I = FSides[0].Count;
                AllDead = true;
                while (I != 0 && AllDead)
                {
                    I -= 1;
                    AllDead = FSides[0].GetUnits(I).FStatus.Contains(TCombatPredictorUnitStatusElement.usDestroyed);
                }

                Useful = false;
                I = U.FTargets.Count;
                while (I != 0 && !Useful)
                {
                    I -= 1;
                    if (U.FTargets.List[I].B > 0)
                    {
                        Target = U.FTargets.List[I].A;
                        Useful = Target != FWall && (Target.FHitPoints > 0 || FResult == 3 || AllDead);
                    }
                }

                if (Useful)
                {
                    Result = Result | 8388608;
                }
            }

            U?.Dispose();
            return Result;
        }

