        public virtual void SetCombatPlayer(byte Player)
        {
            bool ChangedSide;
            TCombat Combat;
            TCombat NewCombat;
            if (FStatus.Contains(TCombatObjectStatusElement.csActivated))
            {
                bool condition = Player != 255;
                if (condition)
                {
                    var players = FCombat.FCombatData.FPlayers.GetPlayers((sbyte)Player);
                    var side = GetSide();
                    condition = (TCombatSideIndex)players.FSideIndex != side;
                }

                ChangedSide = condition;
                if (FCombatPlayer != -1)
                {
                    Combat = FCombat;
                    var players = Combat.FCombatData.FPlayers.GetPlayers(FCombatPlayer);
                    Combat.FSides[(int)(TCombatSideIndex)players.FSideIndex].RemoveChild(this);
                }

                FCombatPlayer = (sbyte)Player;
                if (FCombatPlayer != -1)
                {
                    NewCombat = FCombat;
                    var players = NewCombat.FCombatData.FPlayers.GetPlayers(FCombatPlayer);
                    NewCombat.FSides[(int)(TCombatSideIndex)players.FSideIndex].AddChild(this);
                }

                if (ChangedSide)
                {
                    ResetTargets();
                    SetupTargets();
                    FCombat.ObjectSideChanged(this);
                }
            }
            else
            {
                FCombatPlayer = (sbyte)Player;
            }
        }

