        public virtual int DoDamage(TCombatObject Target, int Damage)
        {
            int Result;
            if (Damage != 0 && Target.GetEnabled())
            {
                Result = Target.ExecuteDamage(Damage);
                if (Target.FStatus.Contains(TCombatObjectStatusElement.csDestroyed) && !Target.GetAbilityEnabled(129) && !Target.GetAbilityEnabled(128))
                {
                    Damage = GetExperience();
                    Damage += Target.GetLevel();
                    SetExperience(Damage);
                }
            }
            else
            {
