        // Combat.pas:5821
        public virtual TDamageType GetOptimalDamageType(TSet<TDamageType> Types)
        {
            TSet<TDamageType> Available;
            TSet<TDamageType> Protection;
            TDamageType Result = TDamageType.dtNone;
            Available = Types - GetImmunityTypes();
            if (Available != TSet<TDamageType>.Of())
            {
                Protection = GetProtectionTypes();
                if (Protection == TSet<TDamageType>.Of() || Available - Protection == TSet<TDamageType>.Of())
                {
                    while (!Available.Contains(Result))
                    {
                        Result = (TDamageType)((int)Result - 1);
                    }
                }
                else
                {
                    while (!Available.Contains(Result) || Protection.Contains(Result))
                    {
                        Result = (TDamageType)((int)Result - 1);
                    }
                }
            }

            return Result;
        }

