        // Combat.pas:5903
        public virtual int ExecuteDamage(int Damage)
        {
            int Result;
            int Hits;
            Assert(Damage >= 0 && Damage < 50, "Invalid Damage Value (TCombatUnit.ExecuteDamage)", "Combat.pas", 5982);
            Hits = GetHitPoints();
            if (Hits < Damage)
            {
                Result = Hits;
            }
            else
            {
                Result = Damage;
            }

            SetHitPoints((byte)(Hits - Result));
            if (Damage != 0)
            {
