        public int FTime;
        public TCombatLogbook FLogbook;

        // Combat2.pas:555
        public virtual void Dispose()
        {
            if (FStatus.Contains(TCombatViewerStatusElement.vsInitialized))
            {
                Finalize();
            }

            FCombat?.Dispose();
        }

        // Combat2.pas:562
        public void Initialize(TCombatLogbook Logbook)
        {
            if (FStatus.Contains(TCombatViewerStatusElement.vsInitialized))
            {
                Finalize();
            }

            FStatus = TSet<TCombatViewerStatusElement>.Of(TCombatViewerStatusElement.vsInitialized);
            FLogbook = Logbook;
            FLogbook.AddRef();
            FPosition = 0;
            FTime = -1;
            FCombat.FCombatData.Assign(Logbook.FInitialData, AoWEUnit.AoWEngine);
            FCombat.Activate();
            FDelay = FSpeed;
        }

        // Combat2.pas:575
        public void Finalize()
        {
            if (FStatus.Contains(TCombatViewerStatusElement.vsInitialized))
            {
                FCombat.Deactivate();
                FCombat.Clear();
                FLogbook.Release();
                FLogbook = null;
                FStatus = FStatus - TSet<TCombatViewerStatusElement>.Of(TCombatViewerStatusElement.vsInitialized);
            }
        }

        // Combat2.pas:587
        public int GetEndPosition() => FLogbook.FActions.Count + 1;

        // Combat2.pas:590
        public void SetSpeed(byte Speed)
        {
            if (Speed == 0)
            {
                Speed = 1;
            }

            FSpeed = Speed;
        }

        // Combat2.pas:593
        public void SetPosition(int Position)
        {
            if (FStatus.Contains(TCombatViewerStatusElement.vsInitialized))
            {
                FTime = -1;
                if (Position > GetEndPosition())
                {
                    Position = GetEndPosition();
                }

                if (Position > 0 && Position <= FLogbook.FActions.Count)
                {
                    FCombat.Deactivate();
                    FCombat.FCombatData.Assign(FLogbook.FInitialData, AoWEUnit.AoWEngine);
                    FCombat.Activate();
                    FPosition = 0;
                    while (Position > FPosition)
                    {
                        FPosition += 1;
                        if (Position != FPosition)
                        {
                            FLogbook.FActions.GetCombatActions(FPosition - 1).Execute(FCombat);
                        }
                    }
                }
                else
                {
                    if (Position == 0)
                    {
                        FPosition = 0;
                        FCombat.Deactivate();
                        FCombat.FCombatData.Assign(FLogbook.FInitialData, AoWEUnit.AoWEngine);
                        FCombat.Activate();
                    }
                    else
                    {
                        FPosition = GetEndPosition();
                        FCombat.Deactivate();
                        FCombat.FCombatData.Assign(FLogbook.FFinalData, AoWEUnit.AoWEngine);
                        FCombat.Activate();
                    }
                }
            }
            else
            {
                FPosition = Position;
            }
        }

        // Combat2.pas:629
        public void Play()
        {
            FStatus = FStatus + TSet<TCombatViewerStatusElement>.Of(TCombatViewerStatusElement.vsPlaying) - TSet<TCombatViewerStatusElement>.Of(TCombatViewerStatusElement.vsPaused);
        }

        // Combat2.pas:632
        public void Pause()
        {
            FStatus = FStatus + TSet<TCombatViewerStatusElement>.Of(TCombatViewerStatusElement.vsPaused);
        }

        // Combat2.pas:635
        public void Update()
        {
            bool Playing;
            if ((FStatus & TSet<TCombatViewerStatusElement>.Of(TCombatViewerStatusElement.vsInitialized, TCombatViewerStatusElement.vsPlaying, TCombatViewerStatusElement.vsPaused)) == TSet<TCombatViewerStatusElement>.Of(TCombatViewerStatusElement.vsInitialized, TCombatViewerStatusElement.vsPlaying) && GetEndPosition() != FPosition)
            {
                Playing = false;
                if (FPosition == 0)
                {
                    FTime += 1;
                    if (FTime >= FDelay)
                    {
                        FPosition = 1;
                        FTime = -1;
                    }
                }

                while (true)
                {
                    bool condition = FPosition > 0;
                    if (condition)
                    {
                        var count = FLogbook.FActions.Count;
                        condition = FPosition <= count;
                    }

                    if (!(condition && !Playing))
                        break;
                    FTime += 1;
                    Playing = FLogbook.FActions.GetCombatActions(FPosition - 1).Play(this);
                    if (!Playing)
                    {
                        FPosition += 1;
                        FDelay = FSpeed;
                        FTime = -1;
                    }
                }

                if (GetEndPosition() == FPosition)
                {
                    SetPosition(GetEndPosition());
                }
            }
        }

