    // FDamage. FDamageTypes. FEffects. FDamageTaken. The two damage sets are deliberately unaligned
    // packed fields
    public partial class TDamageCA : TSingleTargetCA
    {
        // Combat2.pas:774
        public new const int ClassID = 131761;

        public TDamageCA(TECustomNode owner) : base(owner)
        {
        }

        public byte FDamage;
        public Aow.Game.Combat.TP3PackedDamageTypes FDamageTypes;
        public Aow.Game.Combat.TP3PackedDamageTypes FEffects;
        public byte FDamageDone;

        // Combat2.pas:777
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwByte(ref FDamage, 15);
            Stream.rwData(Bytes.Of(ref FEffects, 2), 2, 16);
            Stream.rwData(Bytes.Of(ref FDamageTypes, 2), 2, 17);
        }

        public override void PersistFields(IPersister persister)
        {
            base.PersistFields(persister);
            persister.Byte("Damage", ref FDamage);
            PersistSupport.Record(persister, "Effects", ref FEffects);
            PersistSupport.Record(persister, "DamageTypes", ref FDamageTypes);
        }

        // Combat2.pas:817
        public override void Execute(Aow.Game.Combat.TCombat Combat)
        {
            Aow.Game.Combat.TCombatObject Target;
            Aow.Game.Combat.TCombatObject Source;
            Source = Combat.FCombatData.FindID(FSourceID);
            Target = Combat.FCombatData.FindID(FTargetID);
            if (FDamage != 0)
            {
                FDamageDone = (byte)Source.DoDamage(Target, FDamage);
            }

            if (FEffects.Value != TSet<Aow.Game.Combat.TDamageType>.Of())
            {
                Target.ExecuteDamageEffects(FEffects.Value);
            }
        }

        // Combat2.pas:826
        public override bool Play(Aow.Game.Combat.TCombatViewer Viewer)
        {
            int HitFrame;
            int Duration;
            int EffectFrames;
            Aow.Game.Combat.TCombatObject Target;
            if (Viewer.FDelay < 5)
            {
                HitFrame = Viewer.FDelay;
            }
            else
            {
                HitFrame = 5;
            }

            if (HitFrame == Viewer.FTime)
            {
                Execute(Viewer.FCombat);
                Target = Viewer.FCombat.FCombatData.FindID(FTargetID);
                if (FDamageDone != 0)
                {
                    if (!Target.FStatus.Contains(Aow.Game.Combat.TCombatObjectStatusElement.csDestroyed))
                    {
                        Target.PlaySFX(2);
                    }
                    else
                    {
                        Target.PlaySFX(3);
                    }
                }
            }

            Duration = Viewer.FDelay * 2;
            if (FEffects.Value != TSet<Aow.Game.Combat.TDamageType>.Of())
            {
                EffectFrames = AoWEUnit.DamageEffectsAnimationFrames(FEffects.Value) + Viewer.FDelay;
                HitFrame = Viewer.FDelay * 3;
                if (EffectFrames > HitFrame)
                {
                    EffectFrames = HitFrame;
                }

                if (Duration < EffectFrames)
                {
                    Duration = EffectFrames;
                }
            }

            return Duration > Viewer.FTime;
        }

        // Combat2.pas:848
        public override void ShowObject(Aow.Game.Combat.TCombatViewer Viewer, Aow.Game.Combat.TCombatObject Obj, int Frame, int Direction, int X, int Y, in TSurfaceDesc Surface)
        {
            int HitFrame;
            if (Obj.FID == FSourceID)
            {
                Obj.ShowAttackAnimation(Viewer.FTime, Direction, X, Y, Surface);
            }
            else
            {
                if (Viewer.FDelay < 5)
                {
                    HitFrame = Viewer.FDelay;
                }
                else
                {
                    HitFrame = 5;
                }

                if (Obj.FID == FTargetID && FDamageDone != 0 && HitFrame <= Viewer.FTime)
                {
                    Obj.Show(Frame, Direction, X, Y, Surface);
                    if (FEffects.Value != TSet<Aow.Game.Combat.TDamageType>.Of())
                    {
                        AoWEUnit.ShowDamageEffects(FEffects.Value, X, Y, Viewer.FTime - HitFrame, Surface);
                    }

                    var damageTypesToDamageType = AoWEUnit.DamageTypesToDamageType(FDamageTypes.Value);
                    AoWEUnit.ShowDamageIcon(X, Y, Surface, FDamageDone, damageTypesToDamageType);
                }
                else
                {
                    Obj.Show(Frame, Direction, X, Y, Surface);
                }
            }
        }

        // Combat2.pas:785
        public virtual void Setup(byte SourceID, byte TargetID, byte Damage, TSet<Aow.Game.Combat.TDamageType> Effects, TSet<Aow.Game.Combat.TDamageType> DamageTypes, bool Defensive)
        {
            FSourceID = SourceID;
            FTargetID = TargetID;
            FDamage = Damage;
            FEffects.Value = Effects;
            FDamageTypes.Value = DamageTypes;
            if (Defensive)
            {
                FMode = FMode + TSet<Aow.Game.Combat.TSingleTargetModeElement>.Of(Aow.Game.Combat.TSingleTargetModeElement.smDefensive);
            }
        }

        // Combat2.pas:795
        public virtual void Generate(Aow.Game.Combat.TCombatObject Source, Aow.Game.Combat.TCombatObject Target, sbyte Attack, sbyte Damage, TSet<Aow.Game.Combat.TDamageType> DamageTypes)
        {
            FSourceID = Source.FID;
            FTargetID = Target.FID;
            FDamage = (byte)Target.ExecuteDamageRole(Attack, Damage, DamageTypes);
            if (FDamage != 0)
            {
                var executeDamageEffectsRole = Target.ExecuteDamageEffectsRole(DamageTypes);
                FEffects.Value = executeDamageEffectsRole;
            }
            else
            {
                FEffects.Value = TSet<Aow.Game.Combat.TDamageType>.Of();
            }

            var immunityTypes = Target.GetImmunityTypes();
            FDamageTypes.Value = DamageTypes - immunityTypes;
        }

        // Combat2.pas:806
        public virtual void GenerateEx(Aow.Game.Combat.TCombatObject Source, Aow.Game.Combat.TCombatObject Target, sbyte Attack, sbyte Damage, TSet<Aow.Game.Combat.TDamageType> DamageTypes, byte DamageMode)
        {
            FSourceID = Source.FID;
            FTargetID = Target.FID;
            FDamage = (byte)Target.ExecuteDamageRoleEx(Attack, Damage, DamageTypes, DamageMode);
            if (FDamage != 0)
            {
                var executeDamageEffectsRole = Target.ExecuteDamageEffectsRole(DamageTypes);
                FEffects.Value = executeDamageEffectsRole;
            }
            else
            {
                FEffects.Value = TSet<Aow.Game.Combat.TDamageType>.Of();
            }

            var immunityTypes = Target.GetImmunityTypes();
            FDamageTypes.Value = DamageTypes - immunityTypes;
        }

        // intf_P3_02.inc:38

    }

