        // Combat2.pas:926
        public override void ShowObject(Aow.Game.Combat.TCombatViewer Viewer, Aow.Game.Combat.TCombatObject Obj, int Frame, int Direction, int X, int Y, in TSurfaceDesc Surface)
        {
            if (Obj.FID == FTargetID)
            {
                switch (FDamageType)
                {
                    case Aow.Game.Combat.TDamageType.dtFire:
                        Obj.Show(Frame, Direction, X, Y, Surface);
                        AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(127).FImageSequences.Show(0, X + 32, Y + 32, Viewer.FTime, Surface);
                        break;
                    case Aow.Game.Combat.TDamageType.dtPoison:
                        Obj.Show(Frame, Direction, X, Y, Surface);
                        AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(96).FImageSequences.Show(0, X + 32, Y + 32, Viewer.FTime, Surface);
                        break;
                    case Aow.Game.Combat.TDamageType.dtCold:
                        Obj.Show(Frame, Direction, X, Y, Surface);
                        AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(95).FImageSequences.Show(1, X + 32, Y + 32, Viewer.FTime, Surface);
                        break;
                    case Aow.Game.Combat.TDamageType.dtDeath:
                        Obj.Show(Frame, Direction, X, Y, Surface);
                        AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(93).FImageSequences.Show(0, X + 32, Y + 32, Viewer.FTime, Surface);
                        break;
                    case Aow.Game.Combat.TDamageType.dtHoly:
                        Obj.Show(Frame, Direction, X, Y, Surface);
                        AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(98).FImageSequences.Show(0, X + 32, Y + 32, Viewer.FTime, Surface);
                        break;
                    default:
                        Obj.Show(Frame, Direction, X, Y, Surface);
                        break;
                }
            }
            else
            {
                Obj.Show(Frame, Direction, X, Y, Surface);
            }
        }

