            Attackers = FSides[(int)TCombatSideIndex.csAttacker].GetUndestroyedConquerObjects();
            Defenders = FSides[(int)TCombatSideIndex.csDefender].GetUndestroyedConquerObjects();
            if (Attackers != 0 && Defenders == 0)
            {
                FCombatResult = TCombatResult.crVictory;
            }
            else
            {
                if (Attackers == 0 && Defenders != 0)
                {
                    FCombatResult = TCombatResult.crDefeat;
                }
                else
                {
                    if (Attackers == 0 && Defenders == 0)
                    {
                        FCombatResult = TCombatResult.crBothDefeated;
                    }
                    else
                    {
                        if (Attackers != 0 && Defenders != 0 && FCombatResult != TCombatResult.crUndecided)
                        {
                            FCombatResult = TCombatResult.crCannotInflictDamage;
                        }
                    }
                }
            }

            switch ((int)FCombatResult)
            {
                case >= 4 and <= 5:
                    {
                        for (int I = FCombatData.GetCount() - 1; I >= 0; I--)
                        {
                            if (FCombatData.GetObjects(I).FStatus.Contains(TCombatObjectStatusElement.csFled))
                            {
