            FStatus = FStatus - TSet<TCombatStatusElement>.Of(TCombatStatusElement.cActivated);
            for (int I = FCombatData.GetCount() - 1; I >= 0; I--)
            {
                FCombatData.GetObjects(I).Deactivate();
            }

            FCombatData.FParties.Deactivate(this);
        }

