        // Combat.pas:6303
        public TCombatParty AddArmy(TArmy Army, TCombatSideIndex Side, int X, int Y, int L)
        {
            TCombatParty Party;
            bool Valid;
            bool Transport;
            byte Player;
            byte Position;
            int Index;
            TCombatUnit UnitObj;
            TMapFieldMsg Msg = default;
            TCombatData Data;
            TAbstractUnit Transporter;
            Army.BeginUpdate();
            Player = (byte)FCombatData.FPlayers.IndexOf((byte)Army.FPlayer, (byte)Army.FIndependentRelation);
            if (Player == 255)
            {
                Player = AddCombatPlayer((byte)Army.FPlayer, (byte)Army.FIndependentRelation, Side);
            }

            Position = GetPartyPosition(X, Y, L);
            Party = FCombatData.FParties.CreateParty(this, Position, Player, X, Y, L, Army);
            Transporter = Army.Transporter(255);
            Transport = Transporter != null && Transporter.ValidTerrain((sbyte)FCombatData.F_CombatData_20[0], (sbyte)FCombatData.F_CombatData_20[1]);
            Index = 0;
            for (int I = Army.Count - 1; I >= 0; I--)
            {
                Valid = Army.GetUnit(I).ValidTerrain((sbyte)FCombatData.F_CombatData_20[0], (sbyte)FCombatData.F_CombatData_20[1]);
                if (Valid || Transport)
                {
                    UnitObj = CreateCombatUnit();
                    var unit = Army.GetUnit(I);
                    UnitObj.Setup(CreateUniqueCOID(), (byte)(int)Side, unit, (byte)((Position << 4) + Index), Player);
                    if (!Valid)
                    {
                        UnitObj.FDisabled = true;
                        UnitObj.FControlMode = UnitObj.FControlMode - TSet<TCombatObjectControlModeElement>.Of(TCombatObjectControlModeElement.cmConquerObject);
                    }

                    FCombatData.AddObject(UnitObj);
                    Index += 1;
                }
            }

            if (X != -1)
            {
                Msg.MsgID = 4387;
                var fieldValue = AoWEUnit.AoWHSMap.MapContainer.GetField(X, Y, L);
                Msg.Param[0] = fieldValue;
                Msg.Result = 0;
                Data = FCombatData;
                AoWEUnit.AoWHSMap.MapContainer.GetField(Data.FX, Data.FY, Data.FL).SendMapFieldMsg(ref Msg);
                if (Msg.Result.Int != 0)
                {
                    Party.FWall = (byte)Msg.Result.Int;
                }
            }

            Army.EndUpdate();
            return Party;
        }

        // Combat.pas:6345
        public TCombatParty AddArmyEx(TArmy Army, TCombatSideIndex Side, int X, int Y, int L, byte Position)
        {
            TCombatParty Party;
            byte Player;
            int Index;
            TCombatUnit UnitObj;
            Army.BeginUpdate();
            Player = (byte)FCombatData.FPlayers.IndexOf((byte)Army.FPlayer, (byte)Army.FIndependentRelation);
            if (Player == 255)
            {
                Player = AddCombatPlayer((byte)Army.FPlayer, (byte)Army.FIndependentRelation, Side);
            }

            Party = FCombatData.FParties.CreateParty(this, (byte)(Position << 0), Player, X, Y, L, Army);
            Index = 0;
            for (int I = Army.Count - 1; I >= 0; I--)
            {
                UnitObj = CreateCombatUnit();
                var unit = Army.GetUnit(I);
                UnitObj.Setup(CreateUniqueCOID(), (byte)(int)Side, unit, (byte)((Position << 4) + Index), Player);
                FCombatData.AddObject(UnitObj);
                Index += 1;
            }

            Army.EndUpdate();
            return Party;
        }

