        // Combat.pas:6385
        // { }
        public void InitDefaultArmies(TArmy Army, int X, int Y, int L)
        {
            TCombatData Data;
            TArmyHS ArmyHS;
            Data = FCombatData;
            if (GetPartyPosition(X, Y, L) == 7)
            {
                FExplorationSite = 2;
                AddArmy(Army, TCombatSideIndex.csAttacker, X, Y, L);
                ArmyHS = (TArmyHS)AoWEUnit.AoWHSMap.MapContainer.GetField(Data.FX, Data.FY, Data.FL).FindOwnedChild(131607);
                if (ArmyHS != null)
                {
                    AddArmy(ArmyHS.FArmy, TCombatSideIndex.csDefender, Data.FX, Data.FY, Data.FL);
                }
                else
                {
                    var players = Data.FPlayers.GetPlayers(Data.FDefenderPlayer);
                    AddEmptyArmy((byte)Data.FPlayers.GetPlayers(Data.FDefenderPlayer).FPlayer, players.FIndependentRelation, Data.FX, Data.FY, Data.FL);
                }
            }
            else
            {
                AddAdjacentArmies();
            }
        }

