        // Combat.pas:6642
        // { }
        public string GetCombatResultText()
        {
            var query = new CombatResultQuery();
            ref var Result = ref query.Text;
            TMapFieldMsg Msg = default;
            Result = "";
            Msg.MsgID = 4361;
            Msg.Result = query;
            Msg.Param[0] = this;
            // { direct combat data }
            AoWEUnit.AoWHSMap.MapContainer.GetField(FCombatData.FX, FCombatData.FY, FCombatData.FL).SendMapFieldMsg(ref Msg);
            if (IsEmpty(Result))
            {
                if (FCombatResult == TCombatResult.crVictory)
                {
                    Result = AoWEUnit.TranslateRStr(AoWEUnit.BattleWonRStr);
                }
                else
                {
                    if (FCombatResult == TCombatResult.crDefeat)
                    {
                        Result = AoWEUnit.TranslateRStr(AoWEUnit.BattleLostRStr);
                    }
                    else
                    {
                        if (FCombatResult == TCombatResult.crCannotBreachWall)
                        {
                            Result = AoWEUnit.TranslateRStr(AoWEUnit.CannotBreachWallRStr);
                        }
                        else
                        {
                            if (FCombatResult == TCombatResult.crCannotInflictDamage)
                            {
                                Result = AoWEUnit.TranslateRStr(AoWEUnit.CannotInflictDamageRStr);
                            }
                            else
                            {
                                Result = AoWEUnit.TranslateRStr(AoWEUnit.BattleDrawnRStr);
                            }
                        }
                    }
                }
            }

            return Result;
        }

