        // Combat2.pas:474
        public override bool Execute(bool Mode, TExecuteTrigger Trigger, TExecuteDoneEvent Done)
        {
            bool ShowCombat = default;
            TCombatData Data = default;
            bool Result = false;
            switch (Trigger)
            {
                case TExecuteTrigger.etUser:
                    AoWEUnit.AoWHSMap.TriggerExecuteEventLog(this, false, Done);
                    Result = true;
                    break;
                case TExecuteTrigger.etEvent:
                case TExecuteTrigger.etNewTurn:
                    if (FLogbook.FInitialData.FPlayers.IndexOfPlayer((byte)AoWEUnit.AoWHSMap.FSeatedPlayer) != -1)
                    {
                        Data = FLogbook.FInitialData;
                        ShowCombat = Data.FPlayers.GetPlayers(Data.FAttackerPlayer).FPlayer == AoWEUnit.AoWHSMap.FSeatedPlayer;
                        ShowCombat = ShowCombat || AoWEUnit.AoWHSMap.FRequestCombatType && AoWEUnit.AoWHSMap.FConnectionType == TPlayerConnectionType.pcEmail && FLogbook.FInitialData.FPlayers.GetPlayers(FLogbook.FInitialData.FDefenderPlayer).FPlayer == AoWEUnit.AoWHSMap.FSeatedPlayer;
                        ShowCombat = ShowCombat || Trigger == TExecuteTrigger.etEvent && AoWEUnit.AoWHSMap.FPlayMode == TPlayMode.pmTurn && AoWEUnit.AoWEngine.FRegistry.GetClassicWindowPopupEvents().Contains(TWindowPopupEvent.wpCombat);
                        ShowCombat = ShowCombat || Trigger == TExecuteTrigger.etEvent && AoWEUnit.AoWHSMap.FPlayMode == TPlayMode.pmSimultaneous && AoWEUnit.AoWEngine.FRegistry.GetSimultaneousWindowPopupEvents().Contains(TWindowPopupEvent.wpCombat);
                        ShowCombat = ShowCombat && FLogbook.FCombatResult != TCombatResult.crNoDefenders;
                    }
                    else
                    {
                        ShowCombat = false;
                    }

                    ShowCombat = ShowCombat || FLogbook.F_CombatLogbook_19;
                    if (ShowCombat)
                    {
                        AoWEUnit.AoWHSMap.TriggerExecuteEventLog(this, false, Done);
                        Result = true;
                    }
                    else
                    {
                        Result = false;
                    }

                    break;
            }

            return Result;
        }

