        // AI.pas:213
        public void UpdateSkirmishGroups()
        {
            int SkirmishCount;
            int WantedCount;
            int GroupPriority;
            int UnitPriority;
            TAIGroup Group;
            TAbstractUnit AUnit;
            TDoubleItemList<TAbstractUnit> Units;
            TDoubleItem<TAbstractUnit> Item;
            SkirmishCount = 0;
            for (int I = 0, last = FPlayer.FAIGroups.Count - 1; I <= last; I++)
            {
                if (FPlayer.FAIGroups.GetGroups(I).EClass.ClassID == 136294)
                {
                    SkirmishCount += 1;
                }
            }

            if (AoWEUnit.AoWHSMap.FDay > 5)
            {
                WantedCount = FPlayer.FAIGroups.Count / 6;
                if (WantedCount > 4)
                {
                    WantedCount = 4;
                }

                if (WantedCount == 0 && (AoWEUnit.AoWHSMap.FDay & 16) == 16)
                {
                    WantedCount = 1;
                }
            }
            else
            {
                WantedCount = 2;
            }

            if (SkirmishCount < WantedCount)
            {
                Units = new TDoubleItemList<TAbstractUnit>();
                for (int I = FPlayer.FAIGroups.Count - 1; I >= 0; I--)
                {
                    Group = FPlayer.FAIGroups.GetGroups(I);
                    if (Group.FTargetType != TAIGroupTargetStatus.gtsExecute && Group.EClass.ClassID != 136281 && Group.EClass.ClassID != 136294 && Group.EClass.ClassID != 136273 && Group.EClass.ClassID != 136275 && Group.EClass.ClassID != 136295)
                    {
                        GroupPriority = Group.GetProcessPriority() * -10;
                        for (int J = Group.Count - 1; J >= 0; J--)
                        {
                            AUnit = Group.GetUnit(J);
                            if (!(AUnit is THero))
                            {
                                UnitPriority = AUnit.GetMoves();
                                if (AUnit.GetMoveTypes().Contains(TMoveType.mtFlying))
                                {
                                    UnitPriority += 15;
                                }

                                Units.AddAB(AUnit, UnitPriority + GroupPriority);
                            }
                        }
                    }
                }

                Units.SortDescendingItemB();
                while (SkirmishCount < WantedCount && Units.Count != 0)
                {
                    Group = AoWEUnit.AoWHSMap.FAIGroupManager.CreateGroup(FPlayer.FPlayerIndex, 0, TGroupBehavior.gbSkirmish);
                    Item = Units[0];
                    Group.AddUnit(Item.A);
                    Group.Release();
                    SkirmishCount += 1;
                    Units.Delete(0);
                }

                Units?.Dispose();
            }
        }

