        // AI.pas:290
        public void ListPeaceWarUnknownPlayers(TByteList Peace, TByteList War, TByteList Unknown)
        {
            TDiplomaticRelation Relation;
            Peace.Clear();
            War.Clear();
            Peace.Add((byte)FPlayer.FPlayerIndex);
            for (int I = 1, last = AoWEUnit.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
            {
                if (I != FPlayer.FPlayerIndex)
                {
                    if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FStatus == TPlayerStatus.psPlaying)
                    {
                        Relation = AoWEUnit.AoWHSMap.FPlayers.GetDiplomaticRelation(FPlayer.FPlayerIndex, (sbyte)I);
                        if (TSet<TDiplomaticRelation>.Of(TDiplomaticRelation.drPeace, TDiplomaticRelation.drAlliance).Contains(Relation))
                        {
                            Peace.Add((byte)I);
                        }
                        else
                        {
                            if (Relation == TDiplomaticRelation.drWar)
                            {
                                War.Add((byte)I);
                            }
                            else
                            {
                                if (Relation == TDiplomaticRelation.drUnknown)
                                {
                                    if (FPlayer.GetFirstDaySeen((sbyte)I) != -1)
                                    {
                                        Unknown.Add((byte)I);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        // AI.pas:311
        // The original checks player status. Unknown is not cleared before appending.
        public void ListIdealPeaceWarPlayers(TByteList Peace, TByteList War)
        {
            TDoubleItemList Players;
            TDiplomaticRelation Relation;
            int Priority;
            TStatus RaceRelation;
            int Days;
            int MiddlePlayer;
            TDiplomaticAction Action;
            TDoubleItem Item;
            Peace.Clear();
            War.Clear();
            Players = new TDoubleItemList();
            Players.AddAB(FPlayer.FPlayerIndex, 999);
            for (int I = 1, last = AoWEUnit.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
            {
                if (I != FPlayer.FPlayerIndex && AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FStatus == TPlayerStatus.psPlaying)
                {
                    Priority = 0;
                    Relation = AoWEUnit.AoWHSMap.FPlayers.GetDiplomaticRelation(FPlayer.FPlayerIndex, (sbyte)I);
                    var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I);
                    var fPlayersPlayers = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer.FPlayerIndex);
                    RaceRelation = AoWEUnit.AoWHSMap.FRaces.GetRace(fPlayersPlayers.FPlayerRace).GetDefaultRaceRelation(players.FPlayerRace);
                    Action = FPlayer.FDiplomaticActions.FindLastAction(DeclareWar.Kind, TDiplomaticActionReaction.darNone, (sbyte)I, FPlayer.FPlayerIndex, -1);
                    if (Action != null)
                    {
                        Days = AoWEUnit.AoWHSMap.FDay - Action.FDay;
                        if (Days < 30)
                        {
                            Priority = Days + (Priority - 30);
                        }
                    }

                    switch (RaceRelation)
                    {
                        case TStatus.sHostile:
                        case TStatus.sWary:
                            Priority += 0;
                            break;
                        case TStatus.sNeutral:
                            Priority += 10;
                            break;
                        case TStatus.sPolite:
                        case TStatus.sFriendly:
                            Priority += 20;
                            break;
                    }

                    if (Relation == TDiplomaticRelation.drAlliance)
                    {
                        Priority += 50;
                    }
                    else
                    {
                        if (Relation == TDiplomaticRelation.drPeace)
                        {
                            Priority += 15;
                        }
                    }

                    if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType == TPlayerType.ptHuman && TSet<TPlayerType>.Of(TPlayerType.ptCPU3, TPlayerType.ptCPU4, TPlayerType.ptCPU5).Contains(FPlayer.FPlayerType))
                    {
                        Priority -= 5;
                    }

                    Players.AddAB(I, Priority);
                }
            }

            Players.SortDescendingItemB();
            for (int I = 0, last = Players.Count / 2 - 1; I <= last; I++)
            {
                Item = Players[I];
                Peace.Add((byte)Item.A);
            }

            for (int I = Players.Count - 1, last = (Players.Count + 1) / 2; I >= last; I--)
            {
                Item = Players[I];
                War.Add((byte)Item.A);
            }

            if ((Players.Count & 1) != 0)
            {
                Item = Players[Players.Count / 2];
                MiddlePlayer = Item.A;
                // { The middle player relation is evaluated directly below. }
                var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(MiddlePlayer);
                var fPlayersPlayers = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer.FPlayerIndex);
                var defaultRaceRelation = AoWEUnit.AoWHSMap.FRaces.GetRace(fPlayersPlayers.FPlayerRace).GetDefaultRaceRelation(players.FPlayerRace);
                if (TSet<TStatus>.Of(TStatus.sHostile, TStatus.sWary).Contains(defaultRaceRelation))
                {
                    War.Add((byte)MiddlePlayer);
                }
                else
                {
                    Peace.Add((byte)MiddlePlayer);
                }
            }

            Players?.Dispose();
        }

        // AI.pas:375
        public bool CanOfferPeace(byte Player)
        {
            bool Result;
            TByteList Peace;
            TByteList War;
            TByteList Unknown;
            TByteList IdealPeace;
            TByteList IdealWar;
            int PeaceCount;
            int WarCount;
            int PeaceIndex;
            int WarIndex;
            int Index;
            if (!(FPlayer.FDiplomaticRelations.GetHistory((sbyte)Player).GetRelationOnDay(0) == TDiplomaticRelation.drWar && FPlayer.FDiplomaticRelations.GetDiplomaticRelation((sbyte)Player) == TDiplomaticRelation.drWar))
            {
                IdealPeace = new TByteList();
                IdealWar = new TByteList();
                Peace = new TByteList();
                War = new TByteList();
                Unknown = new TByteList();
                ListPeaceWarUnknownPlayers(Peace, War, Unknown);
                ListIdealPeaceWarPlayers(IdealPeace, IdealWar);
                War.Remove(Player);
                Unknown.Remove(Player);
                Peace.Remove(Player);
                PeaceCount = Peace.Count;
                WarCount = War.Count;
                PeaceIndex = IdealPeace.IndexOf(Player);
                WarIndex = IdealWar.IndexOf(Player);
                for (int I = 0, last = Unknown.Count - 1; I <= last; I++)
                {
                    Index = IdealPeace.IndexOf(Unknown[I]);
                    if (Index != -1)
                    {
                        if (PeaceIndex == -1 || Index < PeaceIndex)
                        {
                            PeaceCount += 1;
                        }
                        else
                        {
                            WarCount += 1;
                        }
                    }

                    Index = IdealWar.IndexOf(Unknown[I]);
                    if (Index != -1)
                    {
                        if (WarIndex == -1 || Index < WarIndex)
                        {
                            WarCount += 1;
                        }
                        else
                        {
                            PeaceCount += 1;
                        }
                    }
                }

                Result = !(PeaceCount > WarCount && !(WarCount == 0 && PeaceCount == 1 && AoWEUnit.AoWHSMap.FPlayers.FActivePlayers.Count > 2));
                if (TSet<TPlayerType>.Of(TPlayerType.ptCPU3, TPlayerType.ptCPU4, TPlayerType.ptCPU5).Contains(FPlayer.FPlayerType))
                {
                    var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers((sbyte)Player);
                    var fPlayersPlayers = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer.FPlayerIndex);
                    var defaultRaceRelation = AoWEUnit.AoWHSMap.FRaces.GetRace(fPlayersPlayers.FPlayerRace).GetDefaultRaceRelation(players.FPlayerRace);
                    if (TSet<TStatus>.Of(TStatus.sHostile, TStatus.sWary).Contains(defaultRaceRelation))
                    {
                        Result = false;
                    }
                }

                Peace?.Dispose();
                War?.Dispose();
                Unknown?.Dispose();
                IdealPeace?.Dispose();
                IdealWar?.Dispose();
            }
            else
            {
                Result = false;
            }

            return Result;
        }

