        // AIGroup.pas:3993
        public bool CalculateTransportGaps(TMovepath Path, FixedArray_Aow_Units_FixedArray_sbyte_16_16 Table)
        {
            bool Result;
            int I;
            int FirstGap;
            int LastGap;
            int Gaps;
            bool InGap;
            TAoWMapField MapF;
            Gaps = 0;
            FirstGap = -1;
            LastGap = -1;
            I = Path.Count - 1;
            InGap = false;
            while (I > 1)
            {
                I -= 1;
                var item = Path[I];
                var pathItem = Path[I];
                var item2 = Path[I];
                MapF = (TAoWMapField)AoWEUnit.AoWHSMap.MapContainer.GetField(item2.X, pathItem.Y, item.L);
                if (Table[MapF.TerrainType][MapF.OverlayType - -1] == -1)
                {
                    if (!InGap)
                    {
                        if (FirstGap == -1)
                        {
                            FirstGap = I;
                        }

                        Gaps += 1;
                        InGap = true;
                    }
                }
                else
                {
                    if (InGap)
                    {
                        LastGap = I + 1;
                        InGap = false;
                    }
                }
            }

            if (InGap)
            {
                LastGap = 1;
            }

            if (Gaps != 0)
            {
                var item = Path[FirstGap + 1];
                FSettings.FBoardingPoint = item;
                var pathItem = Path[FirstGap];
                FSettings.FTransportSource = pathItem;
                var item2 = Path[LastGap - 1];
                FSettings.FArrivalPoint = item2;
                var item3 = Path[LastGap];
                FSettings.FTransportDestination = item3;
                Result = true;
                FMultipleTransportGaps = Gaps > 1;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

