                    }

                    break;
                case 2:
                    FPathSettings.FMovePointsMax = FSettings.FQuickMovePointsMax;
                    Points = AoWEUnit.AoWHSMap.FMoveControl.CanMove(FPathSettings, TSet<TCanMoveModeElement>.Of(TCanMoveModeElement.mmFast));
                    if (Points == -1)
                    {
