        // AIGroup.pas:6467
        public bool ProcessBufferedTransportTargets()
        {
            TXYL Location = default;
            TIntegerList Gaps;
            TMoveTarget Target;
            bool Valid;
            int I;
            if (FBufferedTargets.Count != 0)
            {
                Gaps = new TIntegerList();
                Target = FBufferedTargets.GetTarget(0);
                FTransporter.GetLocation(ref Location.X, ref Location.Y, ref Location.L);
                if (AoWEUnit.ListMovementGaps(AoWEUnit.AoWHSMap, Target.FMovepath, FMovePointTable, Gaps, null) != 0)
                {
                    FSettings.Reset();
                    this.FSettings.FPlayer = FTargetInfo.Player;
                    this.FSettings.FMode = this.FSettings.FMode + TSet<TMoveModeElement>.Of(TMoveModeElement.mmLogProcessedMapFields, TMoveModeElement.mmAI);
                    this.FSettings.SetSourcePos(Location.X, Location.Y, Location.L);

                    FSettings.FMovePointsMax = FMovePointsMax;
                    FSettings.FMovePointTable = FTransportMovePointTable;
                    I = Gaps.Count;
                    Valid = true;
                    while (I != 0 && Valid)
                    {
                        I -= 1;
                        FSettings.ResetState();
                        var item = Gaps[I];
                        var fMovepathItem = Target.FMovepath[item];
                        var gapsItem = Gaps[I];
                        var item2 = Target.FMovepath[gapsItem];
                        var item3 = Gaps[I];
                        var item4 = Target.FMovepath[item3];
                        FSettings.SetDestinationPos(item4.X, item2.Y, fMovepathItem.L);
                        Valid = AoWEUnit.AoWHSMap.FMoveControl.CanMove(FSettings, TSet<TCanMoveModeElement>.Of(TCanMoveModeElement.mmFast)) != -1;
                    }
                }
                else
                {
                    Valid = true;
                }

                if (Valid)
                {
                    TriggerTargetFound(Target);
                    FTargets.AddChild(Target);
                }

                FBufferedTargets.RemoveChild(Target);
                Gaps?.Dispose();
            }

            return FBufferedTargets.Count != 0 && FState != -1;
        }

        // AIGroup.pas:6514
        public bool ProcessStates()
        {
            bool Yield;
            bool Processing;
            bool Found;
            int I;
            TMoveControlSettings Settings;
            TAoWMapField Field;
            TMoveTarget Target;
            Aow.Game.Ai.TAITargetData Data = default;
            Yield = false;
            switch (FState)
            {
                case 0:
                    if (FMovePointsMax != 0)
                    {
                        FBufferedTargets.Clear();
                        FSettings.Reset();
                        this.FSettings.FPlayer = FTargetInfo.Player;
                        this.FSettings.FMode = this.FSettings.FMode + TSet<TMoveModeElement>.Of(TMoveModeElement.mmLogProcessedMapFields, TMoveModeElement.mmAI);
                        this.FSettings.SetSourcePos(FSourceLocation.X, FSourceLocation.Y, FSourceLocation.L);

                        FSettings.FMovePointsMax = FMovePointsMax;
                        FSettings.FMovePointTable = FMovePointTable;
                        FSettings.FUnits.AddUnits(FUnits);
                        FState = 1;
                    }
                    else
                    {
                        FState = 10;
                    }

                    Yield = false;
                    break;
                case 1:
                    AoWEUnit.AoWHSMap.FMoveControl.Activate(FSettings);
                    Processing = true;
                    while (AoWEUnit.AoWHSMap.FAIExecuter.GetProcessTimeLeft() > 0 && Processing)
                    {
                        Processing = AoWEUnit.AoWHSMap.FMoveControl.Process();
                    }

                    Yield = Processing;
                    AoWEUnit.AoWHSMap.FMoveControl.Deactivate();
                    if (FSettings.FStatus != TMoveControlSettingsStatus.mcssProcessing)
                    {
                        FState = 2;
                    }

                    break;
                case 2:
                    Settings = FSettings;
                    Found = false;
                    I = Settings.FProcessedMapFields.Count;
                    while (I > 0 && !Found)
                    {
                        I -= 1;
                        Field = (TAoWMapField)Settings.FProcessedMapFields.List[I];
                        if ((Field.FFieldFlags & 134217728) != 0)
                        {
                            var xyl = Field.GetXYL();
                            if (FTargets.IndexOfXYL(xyl) == -1 && Field.GetAITarget(FControl, FTargetInfo, ref Data))
                            {
                                Target = new TMoveTarget(null);
                                var fieldXYL = Field.GetXYL();
                                Target.FLocation.XYL = fieldXYL;
                                Target.FMovePoints = Settings.GetMovePoints(Field.Xhx, Field.Yhx, Field.Lhx);
                                Target.FTransporterID = -1;
                                Target.FData = Data;
                                if (FMode.Contains(TAIMoveTargetSelectorModeElement.tsmCreateMovepaths))
                                {
                                    Target.FMovepath = new TMovepath();
                                    AoWEUnit.AoWHSMap.FMoveControl.Activate(FSettings);
                                    AoWEUnit.AoWHSMap.FMoveControl.CalculatePathEx(Target.FMovepath, Field.Xhx, Field.Yhx, Field.Lhx);
                                    if (Target.FMovepath.Count != 0)
                                    {
                                        FBufferedTargets.AddChild(Target);
                                    }

                                    AoWEUnit.AoWHSMap.FMoveControl.Deactivate();
                                }
                                else
                                {
                                    FBufferedTargets.AddChild(Target);
                                }

                                Target.Release();
                                Found = true;
                            }
                        }

                        Settings.FProcessedMapFields.Delete(I);
                    }

                    if (FSettings.FProcessedMapFields.Count == 0)
                    {
                        FBufferedTargets.SortOnMovePoints();
                        FState = 3;
                    }

                    Yield = false;
                    break;
                case 3:
                    if (!ProcessBufferedTargets() && FState == 3)
                    {
                        FState = 10;
                    }

                    Yield = false;
                    break;
                case 10:
                    if (FMovePointsMin > 0 && FTransporter != null)
                    {
                        FBufferedTargets.Clear();
                        FSettings.Reset();
                        this.FSettings.FPlayer = FTargetInfo.Player;
                        this.FSettings.FMode = this.FSettings.FMode + TSet<TMoveModeElement>.Of(TMoveModeElement.mmLogProcessedMapFields, TMoveModeElement.mmAI, TMoveModeElement.mmAvoidArmies);
                        this.FSettings.SetSourcePos(FSourceLocation.X, FSourceLocation.Y, FSourceLocation.L);

                        FSettings.FMovePointsMax = FMovePointsMin;
                        FSettings.FMovePointTable = FMovePointTable;
                        FSettings.FUnits.AddUnits(FUnits);
                        FTransporter.CreateMovePointTable(ref FTransportMovePointTable);
                        for (int Terrain = 0; Terrain <= 15; Terrain++)
                        {
                            for (int Overlay = -1; Overlay <= 11; Overlay++)
                            {
                                if (FSettings.FMovePointTable[Terrain][Overlay - -1] == -1 && FTransportMovePointTable[Terrain][Overlay - -1] != -1)
                                {
                                    FSettings.FMovePointTable[Terrain][Overlay - -1] = 8;
                                }
                            }
                        }

                        FState = 11;
                    }
                    else
                    {
                        Done();
                    }

                    Yield = false;
                    break;
                case 11:
                    AoWEUnit.AoWHSMap.FMoveControl.Activate(FSettings);
                    while (AoWEUnit.AoWHSMap.FMoveControl.Process() && AoWEUnit.AoWHSMap.FAIExecuter.GetProcessTimeLeft() > 0)
                    {
                    }

                    AoWEUnit.AoWHSMap.FMoveControl.Deactivate();
                    if (FSettings.FStatus != TMoveControlSettingsStatus.mcssProcessing)
                    {
                        FState = 12;
                    }

                    break;
                case 12:
                    Settings = FSettings;
                    Found = false;
                    I = Settings.FProcessedMapFields.Count;
                    while (I > 0 && !Found)
                    {
                        I -= 1;
                        Field = (TAoWMapField)Settings.FProcessedMapFields.List[I];
                        if ((Field.FFieldFlags & 134217728) != 0)
                        {
                            var xyl = Field.GetXYL();
                            if (FTargets.IndexOfXYL(xyl) == -1 && Field.GetAITarget(FControl, FTargetInfo, ref Data) && FMovePointTable[Field.TerrainType][Field.OverlayType - -1] >= 0)
                            {
                                Target = new TMoveTarget(null);
                                var fieldXYL = Field.GetXYL();
                                Target.FLocation.XYL = fieldXYL;
                                Target.FMovePoints = Settings.GetMovePoints(Field.Xhx, Field.Yhx, Field.Lhx);
                                Target.FTransporterID = FTransporter.FUnitID;
                                Target.FData = Data;
                                Target.FMovepath = new TMovepath();
                                AoWEUnit.AoWHSMap.FMoveControl.Activate(FSettings);
                                AoWEUnit.AoWHSMap.FMoveControl.CalculatePathEx(Target.FMovepath, Field.Xhx, Field.Yhx, Field.Lhx);
                                AoWEUnit.AoWHSMap.FMoveControl.Deactivate();
                                FBufferedTargets.AddChild(Target);
                                Target.Release();
                                Found = true;
                            }
                        }

                        Settings.FProcessedMapFields.Delete(I);
                    }

                    if (FSettings.FProcessedMapFields.Count == 0)
                    {
                        FBufferedTargets.SortOnMovePoints();
                        FState = 13;
                    }

                    Yield = false;
                    break;
                case 13:
                    if (!ProcessBufferedTransportTargets() && FState == 13)
                    {
                        Done();
                    }

                    break;
            }

            return Yield;
        }

        // AIGroup.pas:6677
        public bool Process()
        {
            bool Yield;
            try
            {
                Yield = false;
                while (!Yield && FState != -1 && AoWEUnit.AoWHSMap.FAIExecuter.GetProcessTimeLeft() > 0)
                {
                    Yield = ProcessStates();
                }
            }
            catch
            {
                FState = -1;
            }

            return FState != -1;
        }

        // AIGroup.pas:6690
        public bool Search(TAIGroupControl Control)
        {
            bool Result;
            if (FTargetInfo.Player != -1 && FOnTargetFound != null && FSourceLocation.XYL != 16777215 && (FMovePointsMax > 0 || (FMovePointsMin > 0 && FTransporter != null)))
            {
                if (FMovePointsMax > 0)
                {
                    FState = 0;
                }
                else
                {
                    FState = 10;
                }

                FProcessCycles = 0;
                FControl = Control;
                FStatus = TAIMoveTargetSelectorStatus.atsSearching;
                Result = true;
            }
            else
            {
                Result = false;
            }

