            TAoWMapField MapF;
            TAIMoveExecuterMove Move;
            TArmy ExistingArmy;
            TAIMoveExecuterUnit Transporter;
            UnitCount = 0;
            TransporterCount = 0;
            Capacity = 8;
            Allowed = true;
            MapF = (TAoWMapField)AoWEUnit.AoWHSMap.MapContainer.GetField(X, Y, L);
            ArmyHS = MapF.GetArmyHS();
            byte Result = 0;
            if (ArmyHS != null && ArmyHS.FArmy.FPlayer == Army.FPlayer)
            {
                ExistingArmy = ArmyHS.FArmy;
                I = 0;
