                            }
                        }

                        I += 1;
                    }

                    if (I == Armies.Count)
                    {
                        FState += 1;
                    }

                    Armies?.Dispose();
                    break;
                case 6:
                    if (FExecuter.FTransporter.FStatus == TAIMoveExecuterUnitStatus.esReady)
                    {
                        Armies = FExecuter.CreateArmies(TSet<TAIMoveExecuterUnitStatus>.Of(TAIMoveExecuterUnitStatus.esReady, TAIMoveExecuterUnitStatus.esQueued, TAIMoveExecuterUnitStatus.esDone));
                        Index = Armies.IndexOfTransportStatus(TAIMoveExecuterTransportStatus.mtsBoarding);
                        if (Index != -1)
                        {
                            var aiMoveExecuterArmy = Armies.GetArmies(Index);
                            if (Unsafe.As<TXYL, int>(ref FExecuter.FTransporter.FLocation) != Unsafe.As<TXYL, int>(ref aiMoveExecuterArmy.FTransportSource))
                            {
                                Move = CreateTransporterMove(aiMoveExecuterArmy.FTransportSource.X, aiMoveExecuterArmy.FTransportSource.Y, aiMoveExecuterArmy.FTransportSource.L, true);
                                if (Move == null)
                                {
                                    FExecuter.FTransporter.FStatus = TAIMoveExecuterUnitStatus.esDone;
                                }
                            }
                        }

                        Armies?.Dispose();
                    }

                    FState += 1;
                    break;
                case 7:
                    if (FExecuter.FTransporter.FStatus == TAIMoveExecuterUnitStatus.esReady)
                    {
                        Armies = FExecuter.CreateArmies(TSet<TAIMoveExecuterUnitStatus>.Of(TAIMoveExecuterUnitStatus.esReady, TAIMoveExecuterUnitStatus.esQueued, TAIMoveExecuterUnitStatus.esDone));
                        Index = Armies.IndexOfTransportStatus(TAIMoveExecuterTransportStatus.mtsBoarding);
                        if (Index != -1)
                        {
                            Army = Armies.GetArmies(Index);
                            if (Army.WaitingForTransport() && Unsafe.As<TXYL, int>(ref FExecuter.FTransporter.FLocation) == Unsafe.As<TXYL, int>(ref Army.FTransportSource))
                            {
                                Selection = CanMoveTo(Armies.GetArmies(Index), 255, Army.FTransportSource.X, Army.FTransportSource.Y, Army.FTransportSource.L);
                                if (Selection != 0)
                                {
                                    Move = CreateMove(Armies.GetArmies(Index), Selection, Army.FTransportSource.X, Army.FTransportSource.Y, Army.FTransportSource.L, TSet<TCreateMoveModeElement>.Of());
                                    if (Move == null)
                                    {
                                        FExecuter.FTransporter.FStatus = TAIMoveExecuterUnitStatus.esDone;
                                    }
                                    else
                                    {
                                        Armies.GetArmies(Index).SetTransportStatus(Selection, TAIMoveExecuterTransportStatus.mtsTransporting);
                                    }
                                }
                                else
                                {
                                    FExecuter.FTransporter.FStatus = TAIMoveExecuterUnitStatus.esDone;
                                }
                            }
                        }

                        Armies?.Dispose();
                    }

                    FState += 1;
                    break;
                case 8:
                    if (FExecuter.FMoves.Count == 0)
                    {
                        Done();
                    }
                    else
                    {
                        FState = 1;
                        FExecuter.ExecuteMoves();
                    }

                    break;
            }
        }

        // AIGroup.pas:5543
        public override void Done()
        {
            if (!TransportDone())
            {
                FExecuter.FStatus = TAIMoveExecuterStatus.mesOutOfMovePoints;
            }

            for (int I = FExecuter.FUnits.Count - 1; I >= 0; I--)
            {
                var units = FExecuter.FUnits.GetUnits(I);
                if (TSet<TAIMoveExecuterTransportStatus>.Of(TAIMoveExecuterTransportStatus.mtsGuarding, TAIMoveExecuterTransportStatus.mtsDumped).Contains(units.FTransportStatus))
                {
                    FExecuter.FUnits.GetUnits(I)?.Dispose();
                }
            }

            FState = -1;
        }

        // AIGroup.pas:5465
        public TAIMoveExecuterMove CreateTransporterMove(sbyte X, sbyte Y, sbyte L, bool Queue)
        {
            TAIMoveExecuterMove Move;
            int MovePoints;
            int Pos;
            TAIMoveExecuterArmy Army;
            TAIMoveExecuterUnit UnitEntry;
            TArmyHS ArmyHS;
            TMoveControlSettings Settings;
            Move = null;
            Army = new TAIMoveExecuterArmy(null);
            Army.Setup(FExecuter.FTransporter);
            for (int I = 0, last = FExecuter.FUnits.Count - 1; I <= last; I++)
            {
                UnitEntry = FExecuter.FUnits.GetUnits(I);
                if (Unsafe.As<TXYL, int>(ref UnitEntry.FLocation) == Unsafe.As<TXYL, int>(ref FExecuter.FTransporter.FLocation))
                {
                    Army.AddChild(UnitEntry);
                }
            }

            var aiMoveExecuterUnit = FExecuter.FTransporter;
            ArmyHS = ((TAoWMapField)AoWEUnit.AoWHSMap.MapContainer.GetField(aiMoveExecuterUnit.FLocation.X, aiMoveExecuterUnit.FLocation.Y, aiMoveExecuterUnit.FLocation.L)).GetArmyHS();

            Settings = new TMoveControlSettings(null);
            Settings.SetupArmy(ArmyHS, 255);
            Settings.SetDestinationPos(X, Y, L);
            AoWEUnit.AoWHSMap.FMoveControl.ProcessMove(Settings);
            if (Settings.FPath.Count != 0)
            {
                MovePoints = ArmyHS.FArmy.MovePoints(255);
                Pos = Settings.FPath.MovePointsToPos(MovePoints);
                if (Pos < Settings.FPath.Count - 1)
                {
                    while (true)
                    {
                        bool condition = Pos != Settings.FPath.Count - 1;
                        if (condition)
                        {
                            var item = Settings.FPath[Pos];
                            var fPathItem = Settings.FPath[Pos];
                            condition = CanMoveTo(Army, 255, Settings.FPath[Pos].X, item.Y, fPathItem.L) != 255;
                        }

                        if (!condition)
                            break;
                        Pos += 1;
                    }

                    if (Pos < Settings.FPath.Count - 1)
                    {
                        Move = new TAIMoveExecuterMove(null);
                        Move.AddUnits(Army, 255);
                        for (int I = Pos, last = Settings.FPath.Count - 1; I <= last; I++)
                        {
                            var item = Settings.FPath[I];
                            Move.FPath.Add(item);
                        }

                        Move.FMovePoints = MovePoints;
                        Move.FMoves = ArmyHS.FArmy.Moves(255);
                        Move.FSourceX = ArmyHS.Xhx;
                        Move.FSourceY = ArmyHS.Yhx;
                        Move.FSourceL = ArmyHS.Lhx;
                        Move.FDestinationX = X;
                        Move.FDestinationY = Y;
                        Move.FDestinationL = L;
                        if (Queue)
                        {
                            Move.Owner = FExecuter.FMoves;
                            Move.SetUnitStatus(TAIMoveExecuterUnitStatus.esQueued);
                        }
                    }
                }
            }

            Army?.Dispose();
            Settings.Release();
            return Move;
        }

        // AIGroup.pas:5525
        public bool TransportDone()
        {
            TAIMoveExecuter Executer;
            int I;
            bool Done;
            Executer = FExecuter;
            I = Executer.FUnits.Count;
            Done = true;
            while (I != 0 && Done)
            {
                I -= 1;
                var units = Executer.FUnits.GetUnits(I);
                if (!TSet<TAIMoveExecuterTransportStatus>.Of(TAIMoveExecuterTransportStatus.mtsArriving, TAIMoveExecuterTransportStatus.mtsGuarding, TAIMoveExecuterTransportStatus.mtsDumping, TAIMoveExecuterTransportStatus.mtsDumped, TAIMoveExecuterTransportStatus.mtsDone).Contains(units.FTransportStatus))
                {
                    Done = false;
                }
            }

            return Done;
        }

        // AIGroup.pas:5553
        public void DumpTransportUnits(TAIMoveExecuterArmy Army)
        {
            byte Transporting;
            byte Others;
            TMoveControlSettings Settings;
            byte Selection = default;
            TArmyHS ArmyHS = default;
            TList Fields;
            TList OtherFields;
            int I;
            TAoWMapField Field;
            bool Found;
            Transporting = 0;
            Others = 0;
            I = 0;
            int last = Army.Count - 1;
            for (; I <= last; I += 1)
            {
                if (Army.GetUnits(I).FUnit.GetTransporting())
                {
                    Transporting = (byte)(Transporting | (1 << I));
                }
                else
                {
                    Others = (byte)(Others | (1 << I));
                }
            }

            if (Transporting != 0)
            {
                Settings = new TMoveControlSettings(null);
                Army.RetrieveArmy(Transporting, ref ArmyHS, ref Selection);
                Settings.SetupArmy(ArmyHS, Selection);
                Settings.FMovePointsMax = ArmyHS.FArmy.Moves(Selection);
                Settings.FMode = Settings.FMode + TSet<TMoveModeElement>.Of(TMoveModeElement.mmLogProcessedMapFields);
                AoWEUnit.AoWHSMap.FMoveControl.ProcessMove(Settings);
                Fields = Settings.FProcessedMapFields;
                Found = false;
                I = 0;
                Field = null;
                while (!Found && I != Fields.Count)
                {
                    Field = (TAoWMapField)Fields.List[I];
                    if (Army.FLocation.X != Field.Xhx || Army.FLocation.Y != Field.Yhx || Army.FLocation.L != Field.Lhx)
                    {
                        Found = CanMoveTo(Army, Transporting, Field.Xhx, Field.Yhx, Field.Lhx) == Transporting;
                    }

                    if (!Found)
                    {
                        I += 1;
                    }
                }

                if (Found)
                {
                    if (CreateMove(Army, Transporting, Field.Xhx, Field.Yhx, Field.Lhx, TSet<TCreateMoveModeElement>.Of()) != null)
                    {
                        FExecuter.ExecuteMoves();
                        Army.SetStatus(Transporting, TAIMoveExecuterUnitStatus.esDone);
                        Army.SetTransportStatus(Transporting, TAIMoveExecuterTransportStatus.mtsDumped);
                    }
                    else
                    {
                        FExecuter.FStatus = TAIMoveExecuterStatus.mesOutOfMovePoints;
                    }
                }
                else
                {
                    Army.SetTransportStatus(Transporting, TAIMoveExecuterTransportStatus.mtsGuarding);
                }

                Settings.Release();
            }

            if (Transporting == 0 && Others != 0)
            {
                Settings = new TMoveControlSettings(null);
                Army.RetrieveArmy(Others, ref ArmyHS, ref Selection);
                Settings.SetupArmy(ArmyHS, Selection);
                Settings.FMovePointsMax = ArmyHS.FArmy.Moves(Selection);
                Settings.FMode = Settings.FMode + TSet<TMoveModeElement>.Of(TMoveModeElement.mmLogProcessedMapFields);
                AoWEUnit.AoWHSMap.FMoveControl.ProcessMove(Settings);
                Field = null;
                OtherFields = Settings.FProcessedMapFields;
                Found = false;
                I = 0;
                while (!Found && I != OtherFields.Count)
                {
                    Field = (TAoWMapField)OtherFields.List[I];
                    if (Army.FLocation.X != Field.Xhx || Army.FLocation.Y != Field.Yhx || Army.FLocation.L != Field.Lhx)
                    {
                        Found = CanMoveTo(Army, Others, Field.Xhx, Field.Yhx, Field.Lhx) == Others;
                    }

                    if (!Found)
                    {
                        I += 1;
                    }
                }

                if (Found)
                {
                    if (CreateMove(Army, Others, Field.Xhx, Field.Yhx, Field.Lhx, TSet<TCreateMoveModeElement>.Of()) != null)
                    {
                        FExecuter.ExecuteMoves();
                        Army.SetStatus(Others, TAIMoveExecuterUnitStatus.esDone);
                        Army.SetTransportStatus(Others, TAIMoveExecuterTransportStatus.mtsDumped);
                    }
                    else
                    {
                        FExecuter.FStatus = TAIMoveExecuterStatus.mesOutOfMovePoints;
                    }
                }
                else
                {
                    Army.SetTransportStatus(Others, TAIMoveExecuterTransportStatus.mtsGuarding);
                }

                Settings.Release();
            }
        }

        // AIGroup.pas:5638
        public void UpdateTransportMeetingPoint()
        {
            TAIMoveExecuterArmyList Armies;
            TMoveControlSettings Settings;
            byte Selection = default;
            int I;
            bool Found;
            TArmyHS ArmyHS = default;
            // { Addressability survives elimination of this assignment. }
            Found = false;
            if ((FExecuter.FMode & TSet<TAIMoveExecuterModeElement>.Of(TAIMoveExecuterModeElement.memAdjacent, TAIMoveExecuterModeElement.memAttack)) != TSet<TAIMoveExecuterModeElement>.Of())
            {
                Armies = FExecuter.CreateArmies(TSet<TAIMoveExecuterUnitStatus>.Of(TAIMoveExecuterUnitStatus.esReady));
                I = Armies.Count;
                while (!Found && I != 0)
                {
                    I -= 1;
                    var armies = Armies.GetArmies(I);
                    Found = TSet<TAIMoveExecuterTransportStatus>.Of(TAIMoveExecuterTransportStatus.mtsBoarding, TAIMoveExecuterTransportStatus.mtsTransporting).Contains(armies.FTransportStatus);
                    if (Found)
                    {
                        FMeetingPoint = Armies.GetArmies(I).FArrivalPoint;
                    }
                }

                if (!Found)
                {
                    I = Armies.Count;
                }

                while (!Found && I != 0)
                {
                    I -= 1;
                    var armies = Armies.GetArmies(I);
                    Found = TSet<TAIMoveExecuterTransportStatus>.Of(TAIMoveExecuterTransportStatus.mtsArriving, TAIMoveExecuterTransportStatus.mtsDone).Contains(armies.FTransportStatus);
                    if (Found)
                    {
                        FMeetingPoint = Armies.GetArmies(I).FLocation;
                    }
                }

                if (Found)
                {
                    Settings = new TMoveControlSettings(null);
                    Armies.GetArmies(I).RetrieveArmy(255, ref ArmyHS, ref Selection);
                    Settings.SetupArmy(ArmyHS, Selection);
                    Settings.SetSourcePos(FMeetingPoint.X, FMeetingPoint.Y, FMeetingPoint.L);
                    Settings.SetDestinationPos(FExecuter.FDestination.X, FExecuter.FDestination.Y, FExecuter.FDestination.L);
                    AoWEUnit.AoWHSMap.FMoveControl.ProcessMove(Settings);
                    if (Settings.FPath.Count > 4)
                    {
                        FMeetingPoint = Settings.FPath[Settings.FPath.Count - 2];
                    }

                    I = 0;
                    int limit = Armies.Count - 1;
                    for (; I <= limit; I += 1)
                    {
                        var armies = Armies.GetArmies(I);
                        if (TSet<TAIMoveExecuterTransportStatus>.Of(TAIMoveExecuterTransportStatus.mtsBoarding, TAIMoveExecuterTransportStatus.mtsTransporting, TAIMoveExecuterTransportStatus.mtsArriving, TAIMoveExecuterTransportStatus.mtsDone).Contains(armies.FTransportStatus))
                        {
                            for (int J = 0, last = Armies.GetArmies(I).Count - 1; J <= last; J++)
                            {
                                Armies.GetArmies(I).GetUnits(J).FArrivalPoint = FMeetingPoint;
                            }
                        }
                    }

                    Settings.Release();
                }

                Armies?.Dispose();
            }

            if (!Found)
            {
                FMeetingPoint.X = -1;
                FMeetingPoint.Y = -1;
                FMeetingPoint.L = -1;
            }
        }

        // AIGroup.pas:5691
        public void CalculateTransportPathCallBack(object Sender)
        {
            TAIMoveExecuterArmyList Armies;
            int Index;
            TAIMoveExecuterArmy Army;
            TAIMoveExecuterUnit UnitEntry;
            Armies = FExecuter.CreateArmies(TSet<TAIMoveExecuterUnitStatus>.Of(TAIMoveExecuterUnitStatus.esReady));
            Index = Armies.IndexOf(FMoveControl.FSettings.FArmyHS, (byte)FMoveControl.FSettings.FSelection);
            if (Index != -1)
            {
                Army = Armies.GetArmies(Index);
            }
            else
            {
                Army = null;
            }

            if (Army != null && FMoveControl.FSettings.FMovePoints != -1)
            {
                if (FMoveControl.FSettings.FBoardingPoint.X != -1)
                {
                    var aiMoveControlSettings = FMoveControl.FSettings;
                    Index = aiMoveControlSettings.FTransportPath.IndexOfXYL(aiMoveControlSettings.FBoardingPoint.X, aiMoveControlSettings.FBoardingPoint.Y, aiMoveControlSettings.FBoardingPoint.L);
                    while (true)
                    {
                        bool condition = Index != aiMoveControlSettings.FTransportPath.Count - 1;
                        if (condition)
                        {
                            var item = aiMoveControlSettings.FTransportPath[Index];
                            var fTransportPathItem = aiMoveControlSettings.FTransportPath[Index];
                            condition = CanMoveTo(Army, 255, aiMoveControlSettings.FTransportPath[Index].X, item.Y, fTransportPathItem.L) != 255;
                        }

                        if (!condition)
                            break;
                        Index += 1;
                    }

                    aiMoveControlSettings.FBoardingPoint = aiMoveControlSettings.FTransportPath[Index];
                    Index = aiMoveControlSettings.FTransportPath.IndexOfXYL(aiMoveControlSettings.FArrivalPoint.X, aiMoveControlSettings.FArrivalPoint.Y, aiMoveControlSettings.FArrivalPoint.L);
                    while (true)
                    {
                        bool condition = Index != 0;
                        if (condition)
                        {
                            var item = aiMoveControlSettings.FTransportPath[Index];
                            var fTransportPathItem = aiMoveControlSettings.FTransportPath[Index];
                            condition = CanMoveTo(Army, 255, aiMoveControlSettings.FTransportPath[Index].X, item.Y, fTransportPathItem.L) != 255;
                        }

                        if (!condition)
                            break;
                        Index -= 1;
                    }

                    aiMoveControlSettings.FArrivalPoint = aiMoveControlSettings.FTransportPath[Index];
                    for (int I = 0, last = Army.Count - 1; I <= last; I++)
                    {
                        UnitEntry = Army.GetUnits(I);
                        var units = Army.GetUnits(I);
                        if (Unsafe.As<TXYL, int>(ref units.FLocation) == Unsafe.As<TXYL, int>(ref FExecuter.FTransporter.FLocation))
                        {
                            UnitEntry.FTransportStatus = TAIMoveExecuterTransportStatus.mtsTransporting;
                        }
                        else
                        {
                            UnitEntry.FTransportStatus = TAIMoveExecuterTransportStatus.mtsBoarding;
                        }

                        UnitEntry.FBoardingPoint = FMoveControl.FSettings.FBoardingPoint;
                        UnitEntry.FBoardingPoint.Flag = 0;
                        UnitEntry.FArrivalPoint = FMoveControl.FSettings.FArrivalPoint;
                        UnitEntry.FArrivalPoint.Flag = 0;
                        UnitEntry.FTransportSource = FMoveControl.FSettings.FTransportSource;
                        UnitEntry.FTransportSource.Flag = 0;
                        UnitEntry.FTransportDestination = FMoveControl.FSettings.FTransportDestination;
                        UnitEntry.FTransportDestination.Flag = 0;
                    }
                }
                else
                {
                    for (int I = 0, last = Army.Count - 1; I <= last; I++)
                    {
                        Army.GetUnits(I).FTransportStatus = TAIMoveExecuterTransportStatus.mtsArriving;
                    }
                }
            }
            else
            {
                FExecuter.FStatus = TAIMoveExecuterStatus.mesFailed;
            }

            Armies?.Dispose();
        }
    }
