            if (FTransporter != null)
            {
                throw new InvalidOperationException("Transporter already exists! (TAIMoveExecuter)");
            }

            Index = FUnits.IndexOfUnitID(AUnit.FUnitID);
            if (Index != -1)
            {
                FUnits.GetUnits(Index)?.Dispose();
