        // AIGroup.pas:6095
        public bool Validate()
        {
            bool Valid;
            Valid = true;
            if (FTransporter != null)
            {
                Valid = Valid && FTransporter.Validate();
            }

            for (int I = FUnits.Count - 1; I >= 0; I--)
            {
                Valid = Valid && FUnits.GetUnits(I).Validate();
            }

            return Valid;
