        // AIGroup.pas:6106
        public TAIMoveExecuterArmyList CreateArmies(TSet<TAIMoveExecuterUnitStatus> Status)
        {
            TIntegerList Used;
            TAIMoveExecuterArmyList Armies;
            TAIMoveExecuterUnit UnitEntry;
            TAIMoveExecuterArmy Army;
            Used = new TIntegerList();
            Armies = new TAIMoveExecuterArmyList(null);
            for (int I = 0, last = FUnits.Count - 1; I <= last; I++)
            {
                if (Used.IndexOf(I) == -1)
                {
                    UnitEntry = FUnits.GetUnits(I);
                    if (Status.Contains(UnitEntry.FStatus))
                    {
                        Used.Add(I);
                        Army = new TAIMoveExecuterArmy(null);
                        Army.Setup(UnitEntry);
                        for (int J = 0, lastJ = FUnits.Count - 1; J <= lastJ; J++)
                        {
                            if (Used.IndexOf(J) == -1)
                            {
                                UnitEntry = FUnits.GetUnits(J);
                                if (Status.Contains(UnitEntry.FStatus) && Army.CanAdd(UnitEntry))
                                {
                                    Army.AddChild(UnitEntry);
                                    Used.Add(J);
                                }
                            }
                        }

                        Army.Owner = Armies;
                    }
                }
            }

            Used?.Dispose();
            return Armies;
        }

        // AIGroup.pas:6142
        public void FinishMoves()
        {
            FStatus = TAIMoveExecuterStatus.mesDone;
