        // AIGroup.pas:6147
        public void ExecuteMoves()
        {
            if (FMoves.Count != 0)
            {
                FState = 1;
            }
        }

        // AIGroup.pas:6152
        public void UnitsMoveDone()
        {
            for (int I = FUnits.Count - 1; I >= 0; I--)
            {
                if (FUnits.GetUnits(I).FStatus != TAIMoveExecuterUnitStatus.esLost)
                {
                    var units = FUnits.GetUnits(I);
                    FUnits.GetUnits(I).FUnit.FUnitStatus = units.FUnit.FUnitStatus + TSet<TUnitStatusElement>.Of(TUnitStatusElement.usMoveDone);
                }
            }
        }

        // AIGroup.pas:6161
        public bool GetTransporting()
        {
            bool Transporting;
            int I;
            Transporting = false;
            I = FUnits.Count;
            while (!Transporting && I != 0)
            {
                I -= 1;
                var units = FUnits.GetUnits(I);
                Transporting = TSet<TAIMoveExecuterTransportStatus>.Of(TAIMoveExecuterTransportStatus.mtsBoarding, TAIMoveExecuterTransportStatus.mtsTransporting).Contains(units.FTransportStatus);
            }

            return Transporting;
        }

        // AIGroup.pas:6176
        public void UpdateMoveResult()
        {
            int I;
            if (FStatus == TAIMoveExecuterStatus.mesDone)
            {
                I = 0;
                while (true)
                {
                    bool condition = I != FUnits.Count;
                    if (condition)
                    {
                        var units = FUnits.GetUnits(I);
                        condition = Unsafe.As<TXYL, int>(ref units.FLocation) == Unsafe.As<TXYL, int>(ref FDestination) || FUnits.GetUnits(I).FMoveResult == 2;
                    }

                    if (!condition)
                        break;
                    I += 1;
                }

                if (I != FUnits.Count)
                {
                    FStatus = TAIMoveExecuterStatus.mesOutOfMovePoints;
                }
            }
        }

        // AIGroup.pas:6189
        public void ProcessExecuteMoves()
        {
            TMultiMoveTE MultiMove;
            byte Selection = default;
            TArmyHS Army = default;
            TArmyDefaultMoveTE Move;
            if (FMoves.Count != 0)
            {
                if (FMoves.Count > 1 && FMode.Contains(TAIMoveExecuterModeElement.memSimultaneous))
                {
                    MultiMove = new TMultiMoveTE(null);
                    MultiMove.FSimultaneous = false;
                    for (int I = FMoves.Count - 1; I >= 0; I--)
                    {
                        if (FMoves.GetMoves(I).RetrieveArmy(ref Army, ref Selection))
                        {
                            Move = new TArmyDefaultMoveTE(null);
                            var moves = FMoves.GetMoves(I);
                            if (!Move.Setup(Army, Selection, moves.FPath, TSet<TArmyMoveModeElement>.Of()))
                            {
                                throw new InvalidOperationException("FAILURE: TAIMoveExecuter.ExecuteMoves");
                            }

                            FMoves.GetMoves(I).SetUnitStatus(TAIMoveExecuterUnitStatus.esMoving);
                            MultiMove.FEvents.Add(Move);
                            Move.Release();
                        }
                    }

                    AoWEUnit.AoWHSMap.FTokenManager.GetTokenControl(FPlayer).AddEvent(MultiMove);
                    MultiMove.Release();
                    FMoves.Clear();
                }
                else
                {
                    if (FMoves.GetMoves(0).RetrieveArmy(ref Army, ref Selection))
                    {
                        var moves = FMoves.GetMoves(0);
                        if (!AoWEUnit.MoveArmy(Army, Selection, moves.FPath))
                        {
                            FMoves.GetMoves(0).SetUnitStatus(TAIMoveExecuterUnitStatus.esFailed);
                            FStatus = TAIMoveExecuterStatus.mesFailed;
                        }
                        else
                        {
                            FMoves.GetMoves(0).SetUnitStatus(TAIMoveExecuterUnitStatus.esMoving);
                        }
                    }

                    FMoves.GetMoves(0).Dispose();
                }
            }
            else
            {
                FState = 0;
            }
        }

        // AIGroup.pas:6232
        public void ProcessMECS()
        {
            int TimeLeft = default;
            TimeLeft = 5;
            while (TimeLeft > 0 && (FControl != null || FControlQueue.Count != 0) && FStatus == TAIMoveExecuterStatus.mesBusy && FState == 0)
            {
                if (FControl != null)
                {
                    if (!FControl.Process())
                    {
                        DeactivateMEC();
                    }

                    TimeLeft = AoWEUnit.AoWHSMap.FAIExecuter.GetProcessTimeLeft();
                }

                if (FControl == null && FControlQueue.Count != 0 && FStatus == TAIMoveExecuterStatus.mesBusy)
                {
                    switch (FControlQueue[FControlQueue.Count - 1])
                    {
                        case 0:
                            ActivateMEC(static () => new TDefaultMEC(null));
                            break;
                        case 2:
                            ActivateMEC(static () => new TAdjacentMEC(null));
                            break;
                        case 1:
                            ActivateMEC(static () => new TTransportMEC(null));
                            break;
                    }

                    FControlQueue.Delete(FControlQueue.Count - 1);
                }
            }

            if (FControl == null && FStatus == TAIMoveExecuterStatus.mesBusy && FState == 0)
            {
                FStatus = TAIMoveExecuterStatus.mesDone;
            }
        }

        // AIGroup.pas:6257
        public bool Process()
        {
            bool Busy;
            if (Validate())
            {
                try
                {
                    if (FStatus == TAIMoveExecuterStatus.mesBusy)
                    {
                        FProcessCycles += 1;
                        if (FState == 1)
                        {
                            ProcessExecuteMoves();
                        }

                        if (FState == 0)
                        {
                            ProcessMECS();
                        }
                    }
                }
                catch
                {
                    FStatus = TAIMoveExecuterStatus.mesInvalidated;
                }
            }
            else
            {
                FStatus = TAIMoveExecuterStatus.mesInvalidated;
            }

            Busy = FStatus == TAIMoveExecuterStatus.mesBusy;
            if (!Busy)
            {
                UpdateMoveResult();
                try
                {
                    if (FOnDone != null)
                    {
                        FOnDone(this);
                    }
                }
                catch
                {
                    ShowMessage("MoveExecute.OnDone failed");
                }
            }

            return Busy;
        }

        // AIGroup.pas:6285
        public void SetupTransporter()
        {
            int I;
            int Capacity;
            TArmyHS Army;
            TAbstractUnit AUnit;
            TAIMoveExecuterUnit UnitEntry;
            FControlQueue.Add(1);
            Capacity = FTransporter.FUnit.GetTransportCapacity();
            if (Capacity > 4)
            {
                Capacity = Capacity - 4;
            }
            else
            {
                Capacity = 1;
            }

            Army = ((TAoWMapField)AoWEUnit.AoWHSMap.MapContainer.GetField(this.FTransporter.FLocation.X, this.FTransporter.FLocation.Y, this.FTransporter.FLocation.L)).GetArmyHS();

            I = 0;
            while (Capacity > 0 && I != Army.FArmy.Count)
            {
                AUnit = Army.FArmy.GetUnit(I);
                if (AUnit != FTransporter.FUnit)
                {
                    if (FUnits.IndexOfUnitID(AUnit.FUnitID) == -1 && !AUnit.GetTransporting())
                    {
                        UnitEntry = AddUnit(AUnit);
                        UnitEntry.FTransportStatus = TAIMoveExecuterTransportStatus.mtsGuarding;
                        Capacity -= 1;
                    }
                }

                I += 1;
            }

            I = 0;
            while (I != Army.FArmy.Count)
            {
                AUnit = Army.FArmy.GetUnit(I);
                if (AUnit != FTransporter.FUnit)
                {
                    if (FUnits.IndexOfUnitID(AUnit.FUnitID) == -1)
                    {
                        UnitEntry = AddUnit(AUnit);
                        if (Capacity > 0)
                        {
                            UnitEntry.FTransportStatus = TAIMoveExecuterTransportStatus.mtsGuarding;
                            Capacity -= 1;
                        }
                        else
                        {
                            UnitEntry.FTransportStatus = TAIMoveExecuterTransportStatus.mtsDumping;
                        }

                        // { The original revisits the index after adding a unit to the executer. }
                        I -= 1;
                    }
                }

                I += 1;
            }

            FTransporter.FStatus = TAIMoveExecuterUnitStatus.esReady;
        }

        // AIGroup.pas:6332
        public bool ExecuteMove(sbyte X, sbyte Y, sbyte L)
        {
            TAIMoveExecuterArmyList Armies;
            bool Started;
            if (FStatus != TAIMoveExecuterStatus.mesBusy)
            {
                FState = 0;
                FProcessCycles = 0;
                FDestination.X = X;
                FDestination.Y = Y;
                FDestination.L = L;
                Armies = CreateArmies(TSet<TAIMoveExecuterUnitStatus>.Of(TAIMoveExecuterUnitStatus.esIdle));
                for (int I = 0, last = Armies.Count - 1; I <= last; I++)
                {
                    Armies.GetArmies(I).SetStatus(255, TAIMoveExecuterUnitStatus.esReady);
                }

                if (Armies.Count != 0)
                {
                    bool condition = Armies.Count != 1;
                    if (!condition)
                    {
                        var armies = Armies.GetArmies(0);
                        condition = Unsafe.As<TXYL, int>(ref armies.FLocation) != Unsafe.As<TXYL, int>(ref FDestination);
                    }

                    if (condition)
                    {
                        FStatus = TAIMoveExecuterStatus.mesBusy;
                        if (FMode.Contains(TAIMoveExecuterModeElement.memAdjacent) && Armies.Count > 1)
                        {
                            FControlQueue.Add(2);
                        }
                        else
                        {
                            FControlQueue.Add(0);
                        }

                        if (FTransporter != null)
                        {
                            SetupTransporter();
                        }

                        Process();
                    }
                    else
                    {
                        FStatus = TAIMoveExecuterStatus.mesDone;
                        Process();
                    }

                    Started = true;
                }
                else
                {
                    FStatus = TAIMoveExecuterStatus.mesFailed;
                    Started = false;
                }

                Armies?.Dispose();
            }
            else
            {
                Started = false;
            }

            return Started;
        }

        // intf_P5_06.inc:459

    }
}

