            M = FMana;
            if (Budget != null)
            {
                G += Budget.FGold;
                M += Budget.FMana;
            }

            return (Gold == 0 || G >= Gold) && (Mana == 0 || Mana <= M) && (GoldUpkeep == 0 || FGoldUpkeep >= GoldUpkeep) && (ManaUpkeep == 0 || FManaUpkeep >= ManaUpkeep);
