        // AI.pas:2010
        public bool ProductionExpenseMade(int Gold, int GoldUpkeep, int Mana, int ManaUpkeep)
        {
            bool Result;
            if (RequestProductionExpense(Gold, GoldUpkeep, Mana, ManaUpkeep))
            {
                if (Gold < 0)
                {
                    Gold = 0;
                }

                if (Mana < 0)
                {
                    Mana = 0;
                }

                if (ManaUpkeep < 0)
                {
                    ManaUpkeep = 0;
                }

                if (GoldUpkeep < 0)
                {
                    GoldUpkeep = 0;
                }

                FGold -= Gold;
                FMana -= Mana;
                FGoldUpkeep -= GoldUpkeep;
                FManaUpkeep -= ManaUpkeep;
                FProductionGoldUpkeep += GoldUpkeep;
                FProductionManaUpkeep += ManaUpkeep;
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // AI.pas:2029
        public bool RequestBudgetExpense(int Gold, int Mana, TAIBudget Budget, bool UsePool)
        {
            int G;
            int M;
            G = 0;
            M = 0;
            if (Budget != null)
            {
                G += Budget.FGold;
                M += Budget.FMana;
            }

            if (UsePool)
            {
                G += FGold;
                M += FMana;
            }

            return (Gold == 0 || Gold <= G) && (Mana == 0 || Mana <= M);
        }

        // AI.pas:2049
        public bool BudgetExpenseMade(int Gold, int Mana, TAIBudget Budget, TBudgetExpenseMode Mode)
        {
            bool Result;
            if (RequestBudgetExpense(Gold, Mana, Budget, Mode != TBudgetExpenseMode.bemBudget))
            {
                if (Gold < 0)
                {
                    Gold = 0;
                }

                if (Mana < 0)
                {
                    Mana = 0;
                }

                if (Mode == TBudgetExpenseMode.bemPoolThenBudget)
                {
                    if (Gold < FGold)
                    {
                        FGold -= Gold;
                        Gold = 0;
                    }
                    else
                    {
                        Gold -= FGold;
                        FGold = 0;
                    }

                    if (Mana < FMana)
                    {
                        FMana -= Mana;
                        Mana = 0;
                    }
                    else
                    {
                        Mana -= FMana;
                        FMana = 0;
                    }
                }

                if (Budget != null)
                {
                    if (Gold < Budget.FGold)
                    {
                        Budget.FGold -= Gold;
                        Gold = 0;
                    }
                    else
                    {
                        Gold -= Budget.FGold;
                        Budget.FGold = 0;
                    }

                    if (Mana < Budget.FMana)
                    {
                        Budget.FMana -= Mana;
                        Mana = 0;
                    }
                    else
                    {
                        Mana -= Budget.FMana;
                        Budget.FMana = 0;
                    }
                }

                if (Mode == TBudgetExpenseMode.bemBudgetThenPool)
                {
                    if (Gold < FGold)
                    {
                        FGold -= Gold;
                    }
                    else
                    {
                        FGold = 0;
                    }

                    if (Mana < FMana)
                    {
                        FMana -= Mana;
                    }
                    else
                    {
                        FMana = 0;
                    }
                }

                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

