            OldTransporter = FTransporter;
            if (OldTransporter != AUnit)
            {
                if (OldTransporter != null)
                {
                    OldTransporter.FGroup = null;
                    OldTransporter.FGroupID = 0;
                    OldTransporter.Release();
                }

                Group = AUnit.FGroup;
                if (Group != null)
                {
                    Group.DeleteUnit(AUnit);
                    AUnit.FGroupID = 0;
                }

                FTransporterID = AUnit.FUnitID;
                FTransporter = AUnit;
