        public virtual bool Split()
        {
            int I;
            TAIGroup Group;
            sbyte X = default;
            sbyte Y = default;
            sbyte L = default;
            sbyte UnitX = default;
            sbyte UnitY = default;
            sbyte UnitL = default;
