            bool Result = false;
            Finished = false;
            while (!Finished)
            {
                I = FGroup.Count;
                Found = false;
                while (!Found && I != 0)
                {
                    I -= 1;
                    FGroup.GetUnit(I).GetLocation(ref X, ref Y, ref L);
                    Found = X != FLocation.X || Y != FLocation.Y || L != FLocation.L;
                }

                if (Found)
                {
                    var behavior = FGroup.GroupClass.Behavior;
                    Group = AoWEUnit.AoWHSMap.FAIGroupManager.CreateGroup(FGroup.FPlayer, FGroup.FIndependentRelation, behavior);
                    Group.FStatus = Group.FStatus + TSet<TAIGroupStatusElement>.Of(TAIGroupStatusElement.agsSplit);
                    I = FGroup.Count - 1;
                    for (; I >= 0; I -= 1)
                    {
                        FGroup.GetUnit(I).GetLocation(ref UnitX, ref UnitY, ref UnitL);
                        if (X == UnitX && Y == UnitY && L == UnitL)
                        {
                            Group.AddUnit(FGroup.GetUnit(I));
                        }
                    }

                    if (Group.Count != 0)
                    {
                        FGroup.FStatus = FGroup.FStatus + TSet<TAIGroupStatusElement>.Of(TAIGroupStatusElement.agsSplit);
                        Result = true;
                    }

                    Group.Release();
                }
                else
                {
