            if (Result)
            {
                Result = FRemainingStrength > 0 && AUnit.GetStrengthMax(FDamageTypes) > 0;
                if (!Result)
                {
                    for (int dOrdinal = (int)(TDamageType)0; dOrdinal <= (int)(TDamageType)9; dOrdinal++)
