                Result = Group.FGroup.GetStrengthMax(AoWEUnit.dtAll - TSet<TDamageType>.Of(TDamageType.dtWall)) >= Round((double)Group.FPathStrength * FPathStrengthFactor);
                if (!Result)
                {
                    if (FMode != TAIGroupRecruitControlMode.rcmForceRecruit)
                    {
                        Result = Group.FGroup.GetMovePointsMin() >= Group.FMovePoints;
                    }
                    else
                    {
                        Result = Group.FGroup.GetMovePointsMin() + 20 >= Group.FMovePoints;
                    }
                }
            }
