        // AIGroup.pas:2958
        public bool ValidCooperationGroup(Aow.Game.Ai.TAIRecruitmentGroup Group)
        {
            bool Result;
            int Strength1;
            int Strength2;
            int Strength;
            int[] Location__cell = new int[1];
            ref int Location = ref Location__cell[0];
            int Advantage1;
            int Advantage2;
            int Moves;
            int OtherMoves;
            int Threshold;
            TAIGroup Group1;
            TAIGroup Group2;
            if (Group.FGroup.FTransporterID == -1 && ((Unsafe.As<TXYL, int>(ref Group.FGroup.FTargetXYL) == Unsafe.As<TXYL, int>(ref FTarget.FLocation) && Group.FGroup.FTargetType == TAIGroupTargetStatus.gtsSetup) || TSet<TAIGroupTargetStatus>.Of(TAIGroupTargetStatus.gtsNone, TAIGroupTargetStatus.gtsIdle).Contains(Group.FGroup.FTargetType)) && Group.FGroup.CooperateWithGroup(FControl.FGroup, FTarget))
            {
                if (Group.FPathStrength != 0)
                {
                    Location = Group.FGroup.GetLoc();
                    Strength1 = Group.FGroup.GetStrengthMax(AoWEUnit.dtAll - TSet<TDamageType>.Of(TDamageType.dtWall));
                    Group1 = Group.FGroup;
                    Advantage1 = -AoWEUnit.GetBattleFieldStrengthAdvantage(Location, Group1.FPlayer, Group1.FIndependentRelation, Group1, 1, 10, AoWEUnit.dtAll - TSet<TDamageType>.Of(TDamageType.dtWall));

                    Location = FControl.FGroup.GetLoc();
                    Strength2 = FControl.FGroup.GetStrengthMax(AoWEUnit.dtAll - TSet<TDamageType>.Of(TDamageType.dtWall));
                    Group2 = FControl.FGroup;
                    Advantage2 = -AoWEUnit.GetBattleFieldStrengthAdvantage(Location, Group2.FPlayer, Group2.FIndependentRelation, Group2, 1, 10, AoWEUnit.dtAll - TSet<TDamageType>.Of(TDamageType.dtWall));

                    if (Strength1 < Strength2)
                    {
                        Strength = Strength1;
                    }
                    else
                    {
                        Strength = Strength2;
                    }

                    // { Original bug: compares the first advantage with itself. }
                    if (Advantage1 > Advantage1 + 0)
                    {
                    }
                    else
                    {
                        Advantage1 = Advantage2;
                    }

                    Threshold = Round((double)Group.FPathStrength * FPathStrengthFactor);
                    if (Strength < Threshold && Strength >= Advantage1)
                    {
                        Moves = Group.FGroup.GetMovePointsMin();
                        OtherMoves = FControl.FGroup.GetMovePointsMin();
                        if (OtherMoves < Moves)
                        {
                            Moves = OtherMoves;
                        }

                        Result = Moves >= Group.FMovePoints;
                    }
                    else
                    {
                        Result = true;
                    }
                }
                else
                {
                    Result = true;
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // AIGroup.pas:2998
        public void ExecuteCooperation()
        {
            TAIGroup Group;
            TAbstractUnit Leader;
            for (int I = FGroups.Count - 1; I >= 0; I--)
            {
                Group = FGroups.GetRecruitmentGroups(I).FGroup;
                if (Group.FTargetType == TAIGroupTargetStatus.gtsSetup && FTarget.FMovePoints > Group.FTargetMovePoints)
                {
                    Leader = Group.FLeader;
                }
                else
                {
                    Leader = FControl.FGroup.FLeader;
                }

                for (int J = Group.FProductions.Count - 1; J >= 0; J--)
                {
                    Group.FProductions.ChangeGroup(J, FControl.FGroup);
                }

                FControl.FGroup.AddUnits(Group);
                FControl.FGroup.SetLeader(Leader);
            }
