                                    FGroupControl.SetupME();
                                    FGroupControl.ExecuteME(FGroupControl.FLocation.X, FGroupControl.FLocation.Y, FGroupControl.FLocation.L);
                                    Result = true;
                                    FState = 22;
                                }
                                else
                                {
                                    FGroupControl.SetupME();
                                    var productionLocation = FGroupControl.FProductionLocations.GetProductionLocation(0);
                                    var fProductionLocationsProductionLocation = FGroupControl.FProductionLocations.GetProductionLocation(0);
                                    var productionLocation2 = FGroupControl.FProductionLocations.GetProductionLocation(0);
                                    FGroupControl.ExecuteME(productionLocation2.FLocation.X, fProductionLocationsProductionLocation.FLocation.Y, productionLocation.FLocation.L);
                                    Result = true;
                                    FState = 22;
                                }
                            }
                        }

                        break;
                    case 21:
                        if (FGroupControl.FTargets.FChildren.IndexOf(FTarget) == -1)
                        {
                            FGroupControl.FGroup.ResetTargetExpense();
                            FTargetStatus = TAIGroupTargetSelectorStatus.tssTargetConquered;
                            Done();
                        }
                        else
                        {
                            FTargetStatus = TAIGroupTargetSelectorStatus.tssExecutingTarget;
                            Done();
                        }

                        break;
                    case 22:
                        FGroupControl.FGroup.SetupTarget(FTarget, TAIGroupTargetStatus.gtsSetup, 0);
                        FTargetStatus = TAIGroupTargetSelectorStatus.tssSettingupTarget;
                        Done();
                        break;
                    case 30:
                        ValidateTargetRequirements(FGroupControl.FGroup, FTarget, null, FSpareUnits, FMinimumStrength);
                        if (FSpareUnits.Count != 0)
                        {
                            FTarget.FStatus = FTarget.FStatus - TSet<TAIGroupControlTargetStatusElement>.Of(TAIGroupControlTargetStatusElement.gtsValid);
                            FNextTarget = null;
                            FState = 31;
                        }
                        else
                        {
                            FState = 32;
                        }

                        break;
                    case 31:
                        I = FGroupControl.FTargets.FChildren.IndexOf(FNextTarget);
                        while (I < FGroupControl.FTargets.Count && (I == -1 || FGroupControl.FTargets.GetTargets(I).FTransporterID != -1 || !FGroupControl.FTargets.GetTargets(I).FStatus.Contains(TAIGroupControlTargetStatusElement.gtsValid)))
                        {
                            I += 1;
                        }

                        if (I < FGroupControl.FTargets.Count)
                        {
                            Required = new TUnitUserList(null);
                            Optional = new TUnitUserList(null);
                            FNextTarget = FGroupControl.FTargets.GetTargets(I);
                            if (ValidMultiTarget(FSpareUnits, FNextTarget, Required, Optional))
                            {
                                var group = FGroupControl.FGroup;
                                var behavior = group.GroupClass.Behavior;
                                Group = AoWEUnit.AoWHSMap.FAIGroupManager.CreateGroup(group.FPlayer, group.FIndependentRelation, behavior);

                                Group.AddUnits(Required);
                                Group.SetupTarget(FNextTarget, TAIGroupTargetStatus.gtsExecute, 0);
                                Group.Release();
                                FSpareUnits.Clear();
                                FSpareUnits.AddUnits(Optional);
                                if (FSpareUnits.Count == 0)
                                {
                                    FState = 32;
                                }
                            }

                            FNextTarget.FStatus = FNextTarget.FStatus - TSet<TAIGroupControlTargetStatusElement>.Of(TAIGroupControlTargetStatusElement.gtsValid);
                            Optional?.Dispose();
                            Required?.Dispose();
                        }
                        else
                        {
                            FState = 32;
                        }

                        break;
                    case 32:
                        FGroupControl.FGroup.SetupTarget(FTarget, TAIGroupTargetStatus.gtsExecute, 0);
                        FGroupControl.SetupME();
                        FGroupControl.ExecuteME(FTarget.FLocation.X, FTarget.FLocation.Y, FTarget.FLocation.L);
                        FState = 21;
                        Result = true;
                        break;
                    case 40:
                        NoTargetsFound();
                        Done();
                        break;
                }
            }
            else
            {
                Result = true;
            }

            return Result;
        }

        // AIGroup.pas:3067
        public bool TargetOverlapFound(TAIGroupControlTarget Target, TAIGroup IgnoreGroup)
        {
            TPlayer Player;
            int I;
            TAIGroup Group;
            Player = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FGroupControl.FGroup.FPlayer);
            I = Player.FAIGroups.Count;
            bool Result = false;
            while (I != 0 && !Result)
            {
                I -= 1;
                Group = Player.FAIGroups.GetGroups(I);
                Result = Group != IgnoreGroup && Group.FTargetType == TAIGroupTargetStatus.gtsExecute && Target.FLocation.L == Group.FTargetXYL.L && dHXtoRad(Group.FTargetXYL.X, Group.FTargetXYL.Y, Target.FLocation.X, Target.FLocation.Y) <= 1;
            }

            return Result;
        }

        // AIGroup.pas:3088
        public bool ValidateTargetOverlap(TAIGroup Group, TAIGroupControlTarget Target)
        {
            int I;
            int Moves;
            int Points;
            int OtherDays;
            int Days;
            TPlayer Player;
            TAIGroup Other;
            Player = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FGroupControl.FGroup.FPlayer);
            I = Player.FAIGroups.Count;
            bool Result = true;
            while (I != 0 && Result)
            {
                I -= 1;
                Other = Player.FAIGroups.GetGroups(I);
                if (Other != Group && Other.FTargetType == TAIGroupTargetStatus.gtsExecute && Other.FTargetXYL.L == Target.FLocation.L && dHXtoRad(Other.FTargetXYL.X, Other.FTargetXYL.Y, Target.FLocation.X, Target.FLocation.Y) <= 1)
                {
                    Moves = Other.GetMovesMin();
                    Points = Other.FTargetMovePoints;
                    if (!Other.FStatus.Contains(TAIGroupStatusElement.agsDone))
                    {
                        Points -= Other.GetMovePointsMin();
                    }

                    OtherDays = Points / Moves;
                    if (Points % Moves != 0)
                    {
                        OtherDays += 1;
                    }

                    Moves = Group.GetMovesMin();
                    var movePointsMin = Group.GetMovePointsMin();
                    Points = Target.FMovePoints - movePointsMin;
                    if (Points > 0)
                    {
                        Days = Points / Moves;
                        if (Points % Moves != 0)
                        {
                            Days += 1;
                        }
                    }
                    else
                    {
                        Days = 0;
                    }

                    Result = Days + 1 <= OtherDays;
                }
            }

            return Result;
        }

