            switch ((int)AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Control.FGroup.FPlayer).FPlayerType)
            {
                case (int)TPlayerType.ptCPU1:
                    FValidTargetLimit = 5;
                    break;
                case (int)TPlayerType.ptCPU2:
                    FValidTargetLimit = 7;
                    break;
                case (int)TPlayerType.ptCPU3:
                case (int)TPlayerType.ptCPU4:
                case (int)TPlayerType.ptCPU5:
                    FValidTargetLimit = 10;
                    break;
                default:
                    FValidTargetLimit = 5;
                    break;
            }

            return true;
        }

