        public int GetRequiredTargetStrength(TAIGroupControlTarget Target)
        {
            int Result;
            TDefenseRequirements Strengths = default;
            TBattleFieldInfo Info = default;
            if (Target.FData.TargetType != Aow.Game.Ai.TAITargetType.attNegotiate)
