                AoWEUnit.SetupBattleFieldInfo(ref Info, FGroupControl.FGroup.FPlayer, FGroupControl.FGroup.FIndependentRelation, TSet<TBattleFieldInfoRequestsElement>.Of(), FDamageTypes);
                Info.FriendlyRelations = TSet<byte>.WithBounds(0, 7);
                AoWEUnit.AoWHSMap.RetrieveBattleFieldInfo(Target.FLocation.X, Target.FLocation.Y, Target.FLocation.L, 1, ref Info);
                Result = Round((double)GetRequiredSuperiority(Target) * Info.Strength);
                ((TAoWMapField)AoWEUnit.AoWHSMap.MapContainer.GetFieldXYL(Unsafe.As<TXYL, int>(ref Target.FLocation))).GetDefenseRequirements(FGroupControl.FGroup.FPlayer, ref Strengths);
                Result += AoWEUnit.StrengthInfoMax(Bytes.Of(ref Strengths)) / 2;
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

