        // AIGroup.pas:3325
        public int GetRequiredBattleFieldStrength(TAIGroupControlTarget Target)
        {
            int Result;
            TBattleFieldInfo Info = default;
            int PathStrength;
            if (((double)FBattleFieldFactor > 0 || (double)FCurrentBattleFieldFactor > 0) && Target.FData.TargetType != Aow.Game.Ai.TAITargetType.attNegotiate)
            {
                AoWEUnit.SetupBattleFieldInfo(ref Info, FGroupControl.FGroup.FPlayer, FGroupControl.FGroup.FIndependentRelation, TSet<TBattleFieldInfoRequestsElement>.Of(), FDamageTypes);
                Info.Units = FGroupControl.FGroup;
                Info.Requests = Info.Requests + TSet<TBattleFieldInfoRequestsElement>.Of(TBattleFieldInfoRequestsElement.bfrIgnorePassiveIndependents);
                AoWEUnit.AoWHSMap.RetrieveBattleFieldInfo(Target.FLocation.X, Target.FLocation.Y, Target.FLocation.L, FBattleFieldRadius, ref Info);
                Result = Round((double)GetRequiredBattleFieldSuperiority(Target) * (Info.Strength - Info.FriendlyStrength));
            }
            else
            {
                Result = 0;
            }

            var group = FGroupControl.FGroup;
            if (Unsafe.As<TXYL, int>(ref group.FTargetXYL) == Unsafe.As<TXYL, int>(ref Target.FLocation) && group.FTargetType == TAIGroupTargetStatus.gtsExecute)
            {
                PathStrength = Round((double)Target.FPathStrength * FCurrentPathStrengthFactor);
            }
            else
            {
                PathStrength = Round((double)Target.FPathStrength * FPathStrengthFactor);
            }

            if (Result < PathStrength)
            {
                Result = PathStrength;
            }

            return Result;
        }

