        public void NoTargetsFound()
        {
            FTargetStatus = TAIGroupTargetSelectorStatus.tssNoTargetsFound;
            FGroupControl.FGroup.FTargetXYL.XYL = -1;
            FGroupControl.FGroup.FTargetType = TAIGroupTargetStatus.gtsNone;
