        public sbyte FPlayer;
        public int FDay;
        public TEndTurnMode FMode;

        // MoveT.PAS:1907
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwInteger(ref FDay, 20);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FPlayer), 21);
            Stream.rwData(Bytes.Of(ref FMode, 1), 1, 22);
        }

        // MoveT.PAS:1915
        public override TExecuteResult Execute(TTokenExecuter TE)
        {
            TExecuteResult Result;
            base.Execute(TE);
            if (AoWEUnit.AoWHSMap.FDay == FDay)
            {
                if (FMode == TEndTurnMode.emEndTurn && !AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FSingleProcessCycle)
                {
                    AoWEUnit.AoWHSMap.FPlayerControl.EndTurn(FPlayer);
                    if (AoWEUnit.AoWHSMap.FPlayMode == TPlayMode.pmSimultaneous && AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FPlayerRace != -1)
                    {
                        var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer);
                        var raceNamesPlural = AoWEUnit.TranslateRStr(AoWEUnit.RaceNamesPluralRStr[players.FPlayerRace]);
                        var aoWETranslateRStr = AoWEUnit.TranslateRStr(AoWEUnit.P5FinishedTheirTurnRStr);
                        AoWEUnit.AoWHSMap.ShowMessage(raceNamesPlural + " " + aoWETranslateRStr);
                    }
                }

                if (FMode == TEndTurnMode.emCancelEndTurn)
                {
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).SetEndTurn(false);
                }

                Result = TExecuteResult.erDone;
            }
            else
            {
                Result = TExecuteResult.erDoneHalt;
            }

            return Result;
        }

        // NetworkE.pas:230

