    // status, path, move index
    public partial class TMoveTE : TTokenEvent
    {
        public TMoveTE(TECustomNode owner) : base(owner)
        {
            FPath = new TMovepath();
            FMoveIndex = 0;
            FStatus = TMoveStatus.msIdle;
        }

        public TMoveStatus FStatus;
        public TMovepath FPath;
        public int FMoveIndex;

        // MoveT.PAS:1958
        public override void Dispose()
        {
            FPath?.Dispose();
            base.Dispose();
        }

        // MoveT.PAS:1964
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwStreamProc(20, FPath.LoadFromStream, FPath.SaveToStream);
        }

        // MoveT.PAS:2027
        public override TExecuteResult Execute(TTokenExecuter TE)
        {
            TExecuteResult Result;
            base.Execute(TE);
            if (FStatus == TMoveStatus.msIdle)
            {
                if (Validate())
                {
                    FStatus = TMoveStatus.msMoving;
                    InitializeMove();
                    AoWEUnit.AoWHSMap.Random(1048575);
                    switch (FPath.Count)
                    {
                        case >= 0 and <= 1:
                            FStatus = TMoveStatus.msDone;
                            break;
                        case 2:
                            FStatus = LastMove();
                            break;
                        default:
                            FStatus = DefaultMove();
                            break;
                    }
                }
                else
                {
                    FStatus = TMoveStatus.msFailed;
                }
            }
            else
            {
                if (FStatus == TMoveStatus.msMoving)
                {
                    FStatus = ProcessMove();
                }
            }

            if (FStatus == TMoveStatus.msDone)
            {
                FinishMove();
                Result = TExecuteResult.erDone;
            }
            else
            {
                if (FStatus == TMoveStatus.msFailed)
                {
                    FinishMove();
                    Result = TExecuteResult.erDoneHalt;
                }
                else
                {
                    if (FStatus == TMoveStatus.msFinished)
                    {
                        Result = TExecuteResult.erDone;
                    }
                    else
                    {
                        Result = TExecuteResult.erRetry;
                    }
                }
            }

            return Result;
        }

        // MoveT.PAS:1970
        public virtual TAoWMapField GetMapF(TXYL Location) => (TAoWMapField)AoWEUnit.AoWHSMap.MapContainer.GetField(Location.X, Location.Y, Location.L);

        // MoveT.PAS:2019
        public virtual TMoveStatus ProcessMove()
        {
            TMoveStatus Result;
            if (FMoveIndex == 1)
            {
                Result = LastMove();
            }
            else
            {
                if (FMoveIndex > 1 && FMoveIndex < FPath.Count)
                {
                    Result = DefaultMove();
                }
                else
                {
                    Result = TMoveStatus.msDone;
                }
            }

            return Result;
        }

        // MoveT.PAS:2004
        public virtual bool Validate() => true;

        // MoveT.PAS:2010
        public virtual void FinishMove()
        {
            FStatus = TMoveStatus.msFinished;
        }

        // MoveT.PAS:1997
        public virtual TMoveStatus Move()
        {
            TMoveStatus Result;
            FMoveIndex -= 1;
            if (FMoveIndex == 0)
            {
                Result = TMoveStatus.msDone;
            }
            else
            {
                Result = TMoveStatus.msMoving;
            }

            return Result;
        }

        // MoveT.PAS:2016
        public virtual TMoveStatus LastMove() => DefaultMove();

        // MoveT.PAS:2013
        public virtual TMoveStatus DefaultMove() => Move();

        // MoveT.PAS:1975
        public int GetDirection(int Index)
        {
            int Result;
            if (Index > 0 && Index < FPath.Count)
            {
                var item = FPath[Index];
                var fPathItem = FPath[Index - 1];
                bool condition = item.L == fPathItem.L;
                if (condition)
                {
                    var item2 = FPath[Index - 1];
                    var item3 = FPath[Index - 1];
                    var item4 = FPath[Index];
                    condition = dHXtoRad(FPath[Index].X, item4.Y, item3.X, item2.Y) == 1;
                }

                if (condition)
                {
                    var item2 = FPath[Index - 1];
                    var item3 = FPath[Index - 1];
                    var item4 = FPath[Index];
                    Result = dHXtoHNfast(FPath[Index].X, item4.Y, item3.X, item2.Y);
                }
                else
                {
                    Result = 0;
                }
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // MoveT.PAS:1989
        public int GetHT(int Index)
        {
            int Result;
            if (Index > 0 && Index < FPath.Count)
            {
                var item = FPath[Index - 1];
                var fPathItem = FPath[Index - 1];
                var item2 = FPath[Index];
                Result = dHXtoHT(FPath[Index].X, item2.Y, fPathItem.X, item.Y);
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // intf_P5_07.inc:765

    }

    // events, simultaneous
    public partial class TMultiMoveTE : TTokenEvent
    {
        public new const int ClassID = 135442;

        public TTokenEventList FEvents;
        public bool FSimultaneous;

        // MoveT.PAS:3293
        public override void Dispose()
        {
            FEvents?.Dispose();
            base.Dispose();
        }

        // MoveT.PAS:3302
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwEObject(FEvents, 20);
            Stream.rwBool(ref FSimultaneous, 21);
        }

        // MoveT.PAS:3286
        public TMultiMoveTE(TECustomNode owner) : base(owner)
        {
            FEvents = new TTokenEventList(null);
            FSimultaneous = true;
        }

        // MoveT.PAS:3309
        public override TExecuteResult Execute(TTokenExecuter TE)
        {
            TTokenEventList Events;
            bool Valid;
            TExecuteResult MoveResult;
            int I;
            Events = FEvents;
            if (TE.ExecuteCount == 0)
            {
                I = Events.Count;
                Valid = true;
                while (I != 0)
                {
                    I -= 1;
                    // { The original retains only the final validation result. }
                    Valid = ((TMoveTE)Events[I]).Validate();
                }
            }
            else
            {
                Valid = true;
            }

            if (Valid)
            {
                if (FSimultaneous)
                {
                    I = Events.Count - 1;
                    for (; I >= 0; I -= 1)
                    {
                        MoveResult = Events[I].Execute(TE);
                        if (MoveResult == TExecuteResult.erDone || MoveResult == TExecuteResult.erDoneHalt)
                        {
                            Events.Delete(I);
                        }
                    }
                }
                else
                {
                    MoveResult = TExecuteResult.erDone;
                    while (TSet<TExecuteResult>.Of(TExecuteResult.erDone, TExecuteResult.erDoneHalt).Contains(MoveResult) && FEvents.Count > 0)
                    {
                        MoveResult = Events[0].Execute(TE);
                        if (MoveResult == TExecuteResult.erDone || MoveResult == TExecuteResult.erDoneHalt)
                        {
                            Events.Delete(0);
                        }
                    }
                }
            }

            if (!Valid || FEvents.Count == 0)
            {
                MoveResult = TExecuteResult.erDone;
            }
            else
            {
                MoveResult = TExecuteResult.erRetry;
            }

            return MoveResult;
        }

        // intf_P5_07.inc:788

    }

    // mode, unit IDs, selection, army sprite, moving/target player, target, destination, animate
    public partial class TMoveArmyTE : TMoveTE
    {
        public new const int ClassID = 135424;

        public TSet<TArmyMoveModeElement> FMode;
        public TIntegerList FUnitIDs;
        public byte FSelection;
        public TArmyHS FArmyHS;
        public sbyte FPlayer;
        public sbyte FTargetPlayer;
        public sbyte FTargetX;
        public sbyte FTargetY;
        public sbyte FTargetL;
        public sbyte FDestinationX;
        public sbyte FDestinationY;
        public sbyte FDestinationL;
        public bool FAnimate;

        // MoveT.PAS:2066
        public override void Dispose()
        {
            FUnitIDs?.Dispose();
            base.Dispose();
        }

        // MoveT.PAS:2093
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwStreamProc(30, FUnitIDs.LoadFromStream, FUnitIDs.SaveToStream);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FPlayer), 31);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FTargetX), 32);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FTargetY), 33);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FTargetL), 34);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FTargetPlayer), 35);
            RwSet(ref FMode, 1, 36, Stream.rwData, 0);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FDestinationX), 37);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FDestinationY), 38);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FDestinationL), 39);
        }

        // MoveT.PAS:2060
        public TMoveArmyTE(TECustomNode owner) : base(owner)
        {
            FUnitIDs = new TIntegerList();
        }

        // MoveT.PAS:2137
        public override bool Validate()
        {
            int I;
            int UnitIndex;
            TMoveControlSettings Settings;
            sbyte TargetPlayer;
            I = FPath.Count - 1;
            bool Result = true;
            if (I < 1)
            {
                Result = false;
            }
            else
            {
                FArmyHS = (TArmyHS)GetMapF(FPath[I]).FindOwnedChild(131607);
                if (FArmyHS == null)
                {
                    Result = false;
                }
                else
                {
                    I = FUnitIDs.Count;
                    FSelection = 0;
                    while (I != 0 && Result)
                    {
                        I -= 1;
                        var item = FUnitIDs[I];
                        UnitIndex = FArmyHS.FArmy.IndexOfID(item);
                        if (UnitIndex != -1)
                        {
                            FSelection = (byte)(FSelection | (1 << UnitIndex));
                        }

                        var fUnitIDsItem = FUnitIDs[I];
                        Result = FArmyHS.FArmy.IndexOfID(fUnitIDsItem) != -1;
                    }

                    Settings = new TMoveControlSettings(null);
                    Settings.SetupArmy(FArmyHS, FSelection);
                    Settings.FMode = Settings.FMode.With(TMoveModeElement.mmAI);
                    if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FArmyHS.FArmy.FPlayer).FPlayerType == TPlayerType.ptHuman && AoWEUnit.AoWHSMap.FExplorationEnabled)
                    {
                        Settings.FMode = Settings.FMode.With(TMoveModeElement.mmExploredTerrainOnly);
                    }

                    Result = Result && AoWEUnit.AoWHSMap.FMoveControl.ValidPath(Settings, FPath);
                    Result = Result && FArmyHS.FArmy.FPlayer == FPlayer;
                    TargetPlayer = ((TAoWMapField)AoWEUnit.AoWHSMap.MapContainer.GetField(FTargetX, FTargetY, FTargetL)).GetPlayer();
                    Result = Result && (TargetPlayer == FTargetPlayer || TargetPlayer == FArmyHS.FArmy.FPlayer);
                    if (FMode.Contains(TArmyMoveModeElement.mmBuildRoads))
                    {
                        bool condition = Result;
                        if (condition)
                        {
                            var movePoints = FArmyHS.FArmy.MovePoints(FSelection);
                            condition = AoWEUnit.RoadConstructionCost(FPlayer, FPath, movePoints) <= AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FGems;
                        }

                        Result = condition;
                    }

                    Settings.Release();
                }
            }

            if (!Result && AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FPlayerType != TPlayerType.ptHuman && AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FAIControl.FMoveExecuter.FStatus == TAIMoveExecuterStatus.mesBusy)
            {
                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FAIControl.FMoveExecuter.InvalidateMove(FArmyHS, FSelection);
            }

            return Result;
        }

        // MoveT.PAS:2183
        public override void InitializeMove()
        {
            int Last;
            TArmyHS ArmyHS;
            base.InitializeMove();
            FAnimate = false;
            Last = FPath.Count - 1;
            FSelection = FArmyHS.FArmy.ValidateSelection(FSelection);
            var validateSelection = FArmyHS.FArmy.ValidateSelection(255);
            if (FSelection != validateSelection)
            {
                ArmyHS = new TArmyHS(null);
                ArmyHS.FArmy.SetPlayer(FArmyHS.FArmy.FPlayer);
                ArmyHS.FArmy.AddUnitSelection(FArmyHS.FArmy, FSelection);
                var item = FPath[Last];
                var fPathItem = FPath[Last];
                var item2 = FPath[Last];
                ArmyHS.PlacePrivate(AoWEUnit.AoWHSMap.MapContainer, item2.X, fPathItem.Y, item.L);
                FArmyHS.FArmy.ResetDestinationPos();
                if (FArmyHS.GetSelected())
                {
                    AoWEUnit.AoWHSMap.Selection.UnselectLocation();
                    AoWEUnit.AoWHSMap.Selection.SelectLocationHS(ArmyHS);
                    AoWEUnit.AoWHSMap.FSelectedArmy.DeactivateMoveSelection();
                }

                FArmyHS = ArmyHS;
                FSelection = 255;
            }
            else
            {
                if (FArmyHS.GetSelected())
                {
                    AoWEUnit.AoWHSMap.FSelectedArmy.DeactivateMoveSelection();
                }
            }

            var army = FArmyHS.FArmy;
            army.FMode = army.FMode.With(TArmyModeElement.amMoving);
            army.FDestinationX = this.FDestinationX;
            army.FDestinationY = this.FDestinationY;
            army.FDestinationL = this.FDestinationL;
        }

        // MoveT.PAS:2221
        public override void FinishMove()
        {
            bool Selected;
            TMapField Field;
            TArmyHS ArmyHS;
            base.FinishMove();
            if (FArmyHS != null)
            {
                Selected = FArmyHS.GetSelected();
                Field = (TMapField)FArmyHS.Owner;
                FArmyHS.SetOwner(null);
                ArmyHS = GetNoneMovingArmyHS(Field);
                FArmyHS.SetOwner(Field);
                if (ArmyHS != null)
                {
                    FArmyHS.FArmy.FUserMode = FArmyHS.FArmy.FUserMode & ArmyHS.FArmy.FUserMode;
                    ArmyHS.FArmy.AssignSettings(FArmyHS.FArmy);
                    ArmyHS.FArmy.AddUnitSelection(FArmyHS.FArmy, 255);
                    FArmyHS = ArmyHS;
                    if (Selected)
                    {
                        AoWEUnit.AoWHSMap.FSelectedArmy.Select(ArmyHS);
                        AoWEUnit.AoWHSMap.FSelectedArmy.DeactivateMoveSelection();
                    }
                }

                FArmyHS.FArmy.FMode = FArmyHS.FArmy.FMode - TSet<TArmyModeElement>.Of(TArmyModeElement.amMoving);
                FArmyHS.CancelMove();
                if (Selected)
                {
                    AoWEUnit.AoWHSMap.FSelectedArmy.ActivateMoveSelection();
                    AoWEUnit.AoWHSMap.FSelectedArmy.Update();
                    if (FMode.Contains(TArmyMoveModeElement.mmSelectEndLocation))
                    {
                        var lhx = FArmyHS.GetLhx();
                        var yhx = FArmyHS.GetYhx();
                        var xhx = FArmyHS.GetXhx();
                        AoWEUnit.AoWHSMap.Selection.SelectLocationHX(xhx, yhx, lhx);
                    }
                }
            }
        }

        // MoveT.PAS:2368
        public override TMoveStatus DefaultMove()
        {
            TMoveStatus Result;
            if (!FArmyHS.Moving())
            {
                if (CanMoveNext())
                {
                    SetupNextMove();
                    if (!Animating())
                    {
                        Result = ExecuteMove();
                    }
                    else
                    {
                        Result = TMoveStatus.msMoving;
                    }
                }
                else
                {
                    Result = TMoveStatus.msFailed;
                }
            }
            else
            {
                if (Animating())
                {
                    UpdateAnimation();
                    bool condition = FArmyHS.FArmy.FPlayer == AoWEUnit.AoWHSMap.FSeatedPlayer;
                    if (!condition)
                    {
                        var lhx = FArmyHS.GetLhx();
                        var yhx = FArmyHS.GetYhx();
                        var xhx = FArmyHS.GetXhx();
                        condition = AoWEUnit.AoWHSMap.Watching(xhx, yhx, lhx, 0);
                    }

                    if (condition)
                    {
                        FArmyHS.PlayMoveSFX();
                    }

                    if (!Animating())
                    {
                        Result = ExecuteMove();
                    }
                    else
                    {
                        Result = TMoveStatus.msMoving;
                    }
                }
                else
                {
                    Result = TMoveStatus.msFailed;
                }
            }

            return Result;
        }

        // MoveT.PAS:2304
        public virtual bool Animating() => FArmyHS.GetMoveStatus() < 100 && FArmyHS.GetMoveStatus() != -1;

        // MoveT.PAS:2309
        public virtual void UpdateAnimation()
        {
            FArmyHS.MoveNext();
        }

        // MoveT.PAS:2342
        public virtual void SetupNextMove()
        {
            int Direction;
            bool Instant;
            TAoWMapField Field;
            if ((MoveVisible(FMoveIndex) || FAnimate) && (FPath[FMoveIndex].L == AoWEUnit.AoWHSMap.ViewL || AoWEUnit.AoWHSMap.FShowIndependentMoves))
            {
                FAnimate = true;
                Direction = GetDirection(FMoveIndex);
                if (Direction == 0)
                {
                    Direction = GetHT(FMoveIndex);
                    Instant = true;
                }
                else
                {
                    Instant = false;
                }

                FArmyHS.MoveFirst(Direction, Instant);
                if (ObserveMove(FMoveIndex - 1))
                {
                    Field = GetMapF(FPath[FMoveIndex - 1]);
                    AoWEUnit.AoWHSMap.ValidateObservation(FArmyHS.FArmy.FPlayer, Field.Xhx, Field.Yhx, Field.Lhx, 0);
                }
            }
        }

        // MoveT.PAS:2312
        public virtual bool CanMoveNext()
        {
            bool Stop;
            int I;
            TAoWMapField Field;
            TArmyHS ArmyHS;
            bool Result = false;
            Stop = false;
            I = FMoveIndex;
            while (I != 0 && !(Stop || Result))
            {
                I -= 1;
                Field = GetMapF(FPath[I]);
                Result = Field.GetPlayer() == -1;
                if (!Result)
                {
                    ArmyHS = GetNoneMovingArmyHS(Field);
                    if (ArmyHS != null)
                    {
                        if (ArmyHS.FArmy.FPlayer == FArmyHS.FArmy.FPlayer)
                        {
                            Result = FArmyHS.FArmy.CanCombine(ArmyHS.FArmy, 255);
                        }
                        else
                        {
                            // { Original queries the moving player toward the other army. }
                            if (AoWEUnit.AoWHSMap.FPlayers.GetDiplomaticRelation(FArmyHS.FArmy.FPlayer, ArmyHS.FArmy.FPlayer) != TDiplomaticRelation.drAlliance)
                            {
                                Stop = true;
                            }
                        }
                    }
                    else
                    {
                        Result = Field.GetPlayer() == FArmyHS.FArmy.FPlayer;
                    }
                }
            }

            return Result;
        }

        // MoveT.PAS:2279
        public virtual TMoveStatus ExecuteMove()
        {
            TMoveStatus Result;
            TAoWMapField Field;
            int Direction;
            if (FMode.Contains(TArmyMoveModeElement.mmBuildRoads))
            {
                var mapF = GetMapF(FPath[FMoveIndex]);
                AoWEUnit.ConstructRoad(FArmyHS.FArmy.FPlayer, mapF);
            }

            FMoveIndex -= 1;
            Field = GetMapF(FPath[FMoveIndex]);
            var item = FPath[FMoveIndex];
            FArmyHS.MoveTo(Field, item.Flag);
            if (Field.FindChildIndex(FArmyHS) != -1)
            {
                Direction = GetDirection(FMoveIndex + 1);
                if (Direction == 0)
                {
                    Direction = GetHT(FMoveIndex + 1);
                }

                if (Direction > 0 && Direction <= 6)
                {
                    FArmyHS.SetDirection((byte)Direction);
                }
                else
                {
                    FArmyHS.SetDirection(0);
                }

                if (FMode.Contains(TArmyMoveModeElement.mmBuildRoads))
                {
                    AoWEUnit.ConstructRoad(FArmyHS.FArmy.FPlayer, Field);
                }

                Result = ProcessMove();
            }
            else
            {
                FArmyHS = null;
                Result = TMoveStatus.msDone;
            }

            return Result;
        }

        // MoveT.PAS:2108
        public virtual bool Setup(TArmyHS ArmyHS, byte Selection, TMovepath Path, TSet<TArmyMoveModeElement> Mode)
        {
            bool Result;
            int First;
            int Last;
            FPath.Clear();
            First = Path.MovePointsToPos(ArmyHS.FArmy.MovePoints(Selection));
            Last = Path.Count - 1;
            if (Last > First)
            {
                for (int I = First; I <= Last; I++)
                {
                    var item = Path[I];
                    FPath.Add(item);
                }

                FArmyHS = ArmyHS;
                FPlayer = ArmyHS.FArmy.FPlayer;
                FMode = Mode;
                FTargetPlayer = GetMapF(Path[0]).GetPlayer();
                FTargetX = Path[0].X;
                FTargetY = Path[0].Y;
                FTargetL = Path[0].L;
                FSelection = ArmyHS.FArmy.ValidateSelection(Selection);
                for (int I = 0, last = ArmyHS.FArmy.Count - 1; I <= last; I++)
                {
                    if (((1 << I) & Selection) != 0)
                    {
                        var unit = ArmyHS.FArmy.GetUnit(I);
                        FUnitIDs.Add(unit.FUnitID);
                    }
                }

                FDestinationX = FArmyHS.FArmy.FDestinationX;
                FDestinationY = FArmyHS.FArmy.FDestinationY;
                FDestinationL = FArmyHS.FArmy.FDestinationL;
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // MoveT.PAS:2259
        public bool ObserveMove(int Index)
        {
            bool Visible;
            TMultiMoveTE Event;
            Visible = MoveVisible(Index);
            bool Result = Visible && AoWEUnit.AoWHSMap.FShowIndependentMoves && (AoWEUnit.AoWHSMap.FSeatedPlayer != FArmyHS.FArmy.FPlayer || AoWEUnit.AoWHSMap.FPlayers.GetPlayers((sbyte)(byte)AoWEUnit.AoWHSMap.FSeatedPlayer).FPlayerType != TPlayerType.ptHuman);
            if (Result && AoWEUnit.AoWHSMap.FTokenManager.TokenExecuter.GetExecutingTokenEvent() is TMultiMoveTE && ((TMultiMoveTE)AoWEUnit.AoWHSMap.FTokenManager.TokenExecuter.GetExecutingTokenEvent()).FSimultaneous)
            {
                Event = (TMultiMoveTE)AoWEUnit.AoWHSMap.FTokenManager.TokenExecuter.GetExecutingTokenEvent();
                Visible = this == Event.FEvents[0];
                Result = Visible;
            }

            return Result;
        }

        // MoveT.PAS:2269
        public bool MoveVisible(int Index)
        {
            bool Result;
            if (AoWEUnit.AoWHSMap.FSeatedPlayer != -1)
            {
                var item = FPath[Index];
                var fPathItem = FPath[Index];
                var item2 = FPath[Index];
                Result = AoWEUnit.AoWHSMap.Visible(item2.X, fPathItem.Y, item.L, 0);
                if (Result && FArmyHS.FArmy.FStatus.Contains(TArmyStatusElement.asFullyConcealed))
                {
                    Result = false;
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // intf_P5_07.inc:816
        public TArmyHS GetNoneMovingArmyHS(TMapField field)
        {
            for (int i = field.Count - 1; i >= 0; i--)
            {
                var sprite = field.HSList[i];
                if (sprite.EClass.ClassID == 0x20217 && sprite.Owner == field)
                {
                    var army = (TArmyHS)sprite;
                    if (!army.FArmy.FMode.Contains(TArmyModeElement.amMoving)) return army;
                }
            }
            return null;
        }
    }

