namespace Aow.Game.Commands
{

    // Gold, Offer, X/Y/L, ArmyID, Player, OwnerPlayer, ArmyHS, Object, MovePoints, Selection, Mode,
    // Result, EventLogID, Data1/Data2
    public partial class TNegotiateTE : TTokenEvent
    {
        // Diplomacy.pas:133
        public new const int ClassID = 135431;

        public int FGold;
        public TNegotiateOffer FOffer;
        public byte FX;
        public byte FY;
        public byte FL;
        public TArmyID FArmyID;
        public sbyte FPlayer;
        public byte FOwnerPlayer;
        public TArmyHS FArmyHS;
        public TNegotiateObject FObject;
        public int FMovePoints;
        public byte FSelection;
        public TSet<TNegotiateModeElement> FMode;
        public TNegotiateResult FResult;
        public int FEventLogID;
        public int FData1;
        public int FData2;

        // Diplomacy.pas:124
        public override void Dispose()
        {
            TArmyID ID;
            ID = FArmyID;
            if (ID != null)
            {
                ID?.Dispose();
            }

            base.Dispose();
        }

        // Diplomacy.pas:138
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwInteger(ref FGold, 30);
            Stream.rwData(Bytes.Of(ref FOffer, 1), 1, 31);
            Stream.rwByte(ref FX, 32);
            Stream.rwByte(ref FY, 33);
            Stream.rwByte(ref FL, 34);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FPlayer), 35);
            Stream.rwByte(ref FOwnerPlayer, 36);
            Stream.rwData(Bytes.Of(ref FObject, 1), 1, 37);
            Stream.rwInteger(ref FMovePoints, 38);
            Stream.rwInteger(ref FData1, 39);
            Stream.rwInteger(ref FData2, 40);
            RwSet(ref FMode, 1, 41, Stream.rwData, 0);
            Stream.rwData(Bytes.Of(ref FResult, 1), 1, 42);
            Stream.rwCreateEObject(ref FArmyID, null, 43);
            Stream.rwIntegerEx(ref FEventLogID, -1, 44);
        }

        // Diplomacy.pas:115
        public TNegotiateTE(TECustomNode owner) : base(owner)
        {
            FArmyID = null;
            FMode = TSet<TNegotiateModeElement>.Of(TNegotiateModeElement.nmAttackOnReject, TNegotiateModeElement.nmMoveOnAccept);
            FEventLogID = -1;
            FOwnerPlayer = 0;
        }

        // Diplomacy.pas:247
        public override TExecuteResult Execute(TTokenExecuter TE)
        {
            TMapFieldMsg Msg = default;
            if (Validate())
            {
                Msg.MsgID = 4367;
                Msg.Param[0] = this;
                Msg.Result = 0;
                AoWEUnit.AoWHSMap.MapContainer.GetField((sbyte)FX, (sbyte)FY, (sbyte)FL).SendMapFieldMsg(ref Msg);
            }

            return TExecuteResult.erDone;
        }

        // Diplomacy.pas:158
        public virtual bool Validate()
        {
            bool Result;
            TArmyID ID;
            ID = FArmyID;
            if (ID != null)
            {
                Result = ID.RetrieveArmy(ref FArmyHS, ref FSelection);
            }
            else
            {
                Result = true;
            }

            if (Result && FX != 255)
            {
                Result = (byte)((TAoWMapField)AoWEUnit.AoWHSMap.MapContainer.GetField((sbyte)FX, (sbyte)FY, (sbyte)FL)).GetPlayer() == FOwnerPlayer;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Diplomacy.pas:192
        public virtual void Accept()
        {
            TEventLog Log;
            TMovepath Path;
            TMoveArmyTE Move;
            if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FGems >= FGold)
            {
                var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer);
                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).SetGems(players.FGems - FGold);
                if (FEventLogID != -1)
                {
                    Log = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FEventLogbook.FindID(FEventLogID);
                    if (Log != null)
                    {
                        AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FEventLogbook.RemoveEvent(Log);
                    }
                }

                if (FArmyHS != null && FMode.Contains(TNegotiateModeElement.nmMoveOnAccept))
                {
                    Path = new TMovepath();
                    Path.AddXYL((sbyte)FX, (sbyte)FY, (sbyte)FL);
                    var yhx = FArmyHS.Yhx;
                    Path.AddXYL(FArmyHS.Xhx, yhx, FArmyHS.Lhx);
                    Path.List[0].Flag = (sbyte)FMovePoints;
                    Move = AoWEUnit.CreateArmyMoveTE(FArmyHS, FSelection, Path, (TMoveAction)(byte)3, TSet<TArmyMoveModeElement>.Of(TArmyMoveModeElement.mmSelectEndLocation));
                    AoWEUnit.AoWHSMap.FTokenManager.TokenExecuter.InsertExecuteEvent(Move);
                    // { Original bug: no nil check after CreateArmyMoveTE can return nil. }
                    Move.Release();
                    Path?.Dispose();
                }
            }
        }

        // Diplomacy.pas:226
        public virtual void Reject()
        {
            TMovepath Path;
            TMoveArmyTE Move;
            if (FOffer == TNegotiateOffer.noForceOffer && FArmyHS != null && FMode.Contains(TNegotiateModeElement.nmAttackOnReject))
            {
                Path = new TMovepath();
                Path.AddXYL((sbyte)FX, (sbyte)FY, (sbyte)FL);
                var yhx = FArmyHS.Yhx;
                Path.AddXYL(FArmyHS.Xhx, yhx, FArmyHS.Lhx);
                Path.List[0].Flag = (sbyte)FMovePoints;
                Move = AoWEUnit.CreateArmyMoveTE(FArmyHS, FSelection, Path, (TMoveAction)(byte)1, TSet<TArmyMoveModeElement>.Of(TArmyMoveModeElement.mmSelectEndLocation));
                AoWEUnit.AoWHSMap.FTokenManager.TokenExecuter.InsertExecuteEvent(Move);
                // { Original bug: no nil check after CreateArmyMoveTE can return nil. }
                Move.Release();
                Path?.Dispose();
            }
        }

    }
}

namespace Aow.Game.Events
