    // X/Y/L, MovePoints, ArmyID, Object, Data1/Data2. inherited join fields
    public partial class TNegotiateRequestEventLog : TJoinEventLog
    {
        // Diplomacy.pas:264
        public TNegotiateRequestEventLog(TECustomNode owner) : base(owner)
        {
            FArmyID = null;
        }

        // Diplomacy.pas:279
        public new const int ClassID = 131814;

        public sbyte FX;
        public sbyte FY;
        public sbyte FL;
        public int FMovePoints;
        public TArmyID FArmyID;
        public TNegotiateObject FObject;
        public int FData1;
        public int FData2;

        // Diplomacy.pas:270
        public override void Dispose()
        {
            TArmyID ID;
            ID = FArmyID;
            if (ID != null)
            {
                ID?.Dispose();
            }

            base.Dispose();
        }

        // Diplomacy.pas:284
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FX), 40);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FY), 41);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FL), 42);
            Stream.rwData(Bytes.Of(ref FObject, 1), 1, 43);
            Stream.rwInteger(ref FData1, 44);
            Stream.rwInteger(ref FData2, 45);
