        }

        // Diplomacy.pas:320
        public override bool Accept(ref string ErrorText)
        {
            TNegotiateTE TE;
            bool Result = base.Accept(ref ErrorText);
            if (Result)
            {
                if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FPlayerType == TPlayerType.ptHuman && AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).GetBusy())
                {
                    return Result;
                }

                TE = CreateNegotiateTE();
                TE.FGold = FGold;
                TE.FOffer = TNegotiateOffer.noOfferBribe;
                TE.FResult = TNegotiateResult.nrAccept;
                AoWEUnit.AoWHSMap.FTokenManager.TokenControls[FPlayer].AddEvent(TE);
                TE.Release();
                Result = true;
            }

            return Result;
        }

        // Diplomacy.pas:359
        public override bool Cancel() => true;

        // Diplomacy.pas:339
        public override bool Reject(ref string ErrorText)
        {
            TNegotiateTE TE;
            bool Result = base.Reject(ref ErrorText);
            if (Result)
            {
                if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FPlayerType == TPlayerType.ptHuman && AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).GetBusy())
                {
                    return Result;
                }

                TE = CreateNegotiateTE();
                TE.FGold = 0;
                TE.FOffer = TNegotiateOffer.noForceOffer;
                TE.FResult = TNegotiateResult.nrReject;
                AoWEUnit.AoWHSMap.FTokenManager.TokenControls[FPlayer].AddEvent(TE);
                TE.Release();
                Result = true;
            }

            return Result;
        }

        // Diplomacy.pas:296
        public virtual TNegotiateTE CreateNegotiateTE()
        {
            TNegotiateTE Event;
            TArmyID ID;
            Event = new TNegotiateTE(null);
            Event.FPlayer = FPlayer;
            Event.FObject = FObject;
            Event.FX = (byte)FX;
            Event.FY = (byte)FY;
            Event.FL = (byte)FL;
            Event.FData1 = FData1;
            Event.FData2 = FData2;
            ID = FArmyID;
            if (ID != null)
            {
                Event.FArmyID = (TArmyID)ID.Copy(AoWEUnit.AoWEngine);
                Event.FMovePoints = FMovePoints;
            }
            else
            {
                Event.FArmyID = null;
            }

            return Event;
        }

        public override bool Execute(bool mode, TExecuteTrigger trigger, TExecuteDoneEvent done) => trigger == 0 && AoWEUnit.AoWHSMap.FSeatedPlayer == FPlayer && base.Execute(mode, trigger, done);
    }
}

