    // save filename
    public partial class TSaveGameTE : TTokenEvent
    {
        public TSaveGameTE(TECustomNode owner) : base(owner)
        { }

        public new const int ClassID = 135444;

        public string FFileName = "";

        // MoveT.PAS:1848
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwString(ref FFileName, 15);
        }

        // MoveT.PAS:1854
        public override TExecuteResult Execute(TTokenExecuter TE)
        {
            TExecuteResult Result = default;
            base.Execute(TE);
            if (AoWEUnit.AoWHSMap.FSeatedPlayer == TE.ActiveTCIndex)
            {
                if (TE.ExecuteCount == 0)
                {
                    var fileName = ExtractFileName(FFileName);
                    var format = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.P5SavingGameRStr), [fileName]);
                    AoWEUnit.AoWHSMap.ShowMessage(format);
                    Result = TExecuteResult.erRetry;
                }
                else
                {
                    var fileName = ExtractFileName(FFileName);
                    var format = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.GameSavedRStr), [fileName]);
                    AoWEUnit.AoWHSMap.ShowMessage(format);
                    try
                    {
                        AoWEUnit.AoWHSMap.DisableTurnTimer();
                        if (AoWEUnit.AoWEngine.FCampaign != null)
                        {
                            AoWEUnit.AoWEngine.SaveCampaign(FFileName);
                            AoWEUnit.AoWEngine.FCampaign.FFileName = FFileName;
                        }
                        else
                        {
                            AoWEUnit.AoWEngine.SaveHSM(FFileName, null, Aow.Formats.GameProfile.WorldMap);
                            AoWEUnit.AoWHSMap.FileName = FFileName;
                        }

                        AoWEUnit.AoWHSMap.EnableTurnTimer();
                    }
                    catch
                    {
                        // { Original leaves the turn timer disabled after a save failure. }
                        var aoWEFormat = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.P5ErrorSavingRStr), [FFileName]);
                        AoWEUnit.AoWHSMap.ShowMessage(aoWEFormat);
                    }

                    Result = TExecuteResult.erDone;
                }
            }
            else
            {
                Result = TExecuteResult.erDone;
            }

            return Result;
        }

        // NetworkE.pas:230

    }

    public partial class TCheatTE : TTokenEvent
    {
