            Stream.rwInteger(ref FCheatID, 21);
        }

        // MoveT.PAS:3467
        public override TExecuteResult Execute(TTokenExecuter TE)
        {
            base.Execute(TE);
            switch (FCheatID)
            {
                case 0:
                    {
                        for (int I = 1, last = AoWEUnit.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
                        {
                            var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I);
                            AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).SetGems(players.FGems + 1000);
                        }
                    }

                    break;
                case 1:
                    {
                        for (int I = 1, last = AoWEUnit.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
                        {
                            var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I);
                            AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FMagicControl.SetMana(players.FMagicControl.FMana + 1000);
                        }
                    }

                    break;
                case 2:
                    AoWEUnit.AoWHSMap.SetExplorationEnabled(!AoWEUnit.AoWHSMap.FExplorationEnabled);
                    if (AoWEUnit.AoWHSMap.FExplorationEnabled)
                    {
                        var p5ExplorationEnabled = AoWEUnit.TranslateRStr(AoWEUnit.P5ExplorationEnabledRStr);
                        AoWEUnit.AoWHSMap.ShowMessage(p5ExplorationEnabled);
                    }
                    else
                    {
                        var p5ExplorationDisabled = AoWEUnit.TranslateRStr(AoWEUnit.P5ExplorationDisabledRStr);
                        AoWEUnit.AoWHSMap.ShowMessage(p5ExplorationDisabled);
                    }

                    break;
                case 3:
                    AoWEUnit.AoWHSMap.SetFogEnabled(!AoWEUnit.AoWHSMap.FFogEnabled);
                    if (AoWEUnit.AoWHSMap.FFogEnabled)
                    {
                        var p5FogEnabled = AoWEUnit.TranslateRStr(AoWEUnit.P5FogEnabledRStr);
                        AoWEUnit.AoWHSMap.ShowMessage(p5FogEnabled);
                    }
                    else
                    {
                        var p5FogDisabled = AoWEUnit.TranslateRStr(AoWEUnit.P5FogDisabledRStr);
                        AoWEUnit.AoWHSMap.ShowMessage(p5FogDisabled);
                    }

                    break;
                case 4:
                    var cheatEnabled = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.GetCheatEnabled();
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.FCheatEnabled = !cheatEnabled;
                    if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.GetCheatEnabled())
                    {
                        var p5SpellCheatEnabled = AoWEUnit.TranslateRStr(AoWEUnit.P5SpellCheatEnabledRStr);
                        AoWEUnit.AoWHSMap.ShowMessage(p5SpellCheatEnabled);
                    }
                    else
                    {
                        var p5SpellCheatDisabled = AoWEUnit.TranslateRStr(AoWEUnit.P5SpellCheatDisabledRStr);
                        AoWEUnit.AoWHSMap.ShowMessage(p5SpellCheatDisabled);
                    }

                    {
                        for (int I = 1, last = AoWEUnit.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
                        {
                            var fMagicControlCheatEnabled = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.GetCheatEnabled();
                            AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FMagicControl.FCheatEnabled = fMagicControlCheatEnabled;
                        }
                    }

                    break;
                case 5:
                    AoWEUnit.AoWHSMap.FPlayerControl.GameOver(FPlayer, TGameOverStatus.goWon);
                    break;
                case 6:
                    AoWEUnit.AoWHSMap.FUnlimitedMoves = !AoWEUnit.AoWHSMap.FUnlimitedMoves;
                    if (AoWEUnit.AoWHSMap.FUnlimitedMoves)
                    {
                        var p5FreeMovementEnabled = AoWEUnit.TranslateRStr(AoWEUnit.P5FreeMovementEnabledRStr);
                        AoWEUnit.AoWHSMap.ShowMessage(p5FreeMovementEnabled);
                    }
                    else
                    {
                        var p5FreeMovementDisabled = AoWEUnit.TranslateRStr(AoWEUnit.P5FreeMovementDisabledRStr);
                        AoWEUnit.AoWHSMap.ShowMessage(p5FreeMovementDisabled);
                    }

                    break;
                case 7:
                    {
                        for (int I = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(0).FStructures.Count - 1; I >= 0; I--)
                        {
                            if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(0).FStructures.GetStructure(I).EClass.ClassID == 131336)
                            {
                                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(0).FStructures.GetStructure(I).SetPlayer(FPlayer);
                            }
                        }
                    }

                    break;
                case 8:
                    AoWEUnit.AoWHSMap.FPlayerControl.GameOver(FPlayer, TGameOverStatus.goLost);
                    break;
                case 9:
                    {
                        for (int I = 1, last = AoWEUnit.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
                        {
                            AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FMagicControl.FSpells.Clear();
                            for (int J = 1, lastJ = AoWEUnit.AoWHSSet.FSpellControl.GetCount() - 1; J <= lastJ; J++)
                            {
                                if (AoWEUnit.AoWHSSet.FSpellControl.GetSpell(J) != null)
                                {
                                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FMagicControl.FSpells.Add(J);
                                }
                            }
                        }
                    }

                    break;
            }

            PlaySample("SFX\\ATTACK\\MAGICB01.WAV");
            return TExecuteResult.erDone;
        }

        // NetworkE.pas:230

    }

    // unit ID, player
    public partial class TDisbandUnitTE : TTokenEvent
    {
        public TDisbandUnitTE(TECustomNode owner) : base(owner)
        { }

        public new const int ClassID = 135447;

        public int FUnitID;
        public sbyte FPlayer;

        // MoveT.PAS:3532
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FPlayer), 20);
            Stream.rwInteger(ref FUnitID, 21);
        }

        // MoveT.PAS:3539
        public override TExecuteResult Execute(TTokenExecuter TE)
        {
            TAbstractUnit AUnit;
            TPlayerStructure Structure;
            TArmyHS ArmyHS;
            TGroupBehavior Behavior;
            int I;
            int N;
            sbyte X = default;
            sbyte Y = default;
            sbyte L = default;
            AUnit = AoWEUnit.AoWHSMap.FUnitControl.FindUnit(FUnitID);
            if (AUnit != null && AUnit.FPlayer == FPlayer)
            {
                AUnit.AddRef();
                if (AUnit.GetRace() == 5 && AUnit.FPlayer > 0 && AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AUnit.FPlayer).FPlayerRace == 5 && (AUnit.GetAbilityEnabled(162) || AUnit.GetAbilityEnabled(164) || AUnit.GetAbilityEnabled(165)))
                {
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AUnit.FPlayer).FHeroEmerging = true;
                }

                if (!AUnit.GetAbilityEnabled(155))
                {
                    AUnit.GetLocation(ref X, ref Y, ref L);
                    Structure = (TPlayerStructure)AoWEUnit.AoWHSMap.MapContainer.GetField(X, Y, L).FindNoneTransparentHS(typeof(TPlayerStructure));
                    if (!(AUnit.Owner is TArmy) || AUnit.Owner.Count > 1 || (Structure != null && Structure.FPlayer > 0))
                    {
                        AUnit.GetLocation(ref X, ref Y, ref L);
                        AUnit.SetOwner(null);
                        ArmyHS = AUnit.Place(X, Y, L, 0, TSet<TUnitPlaceModeElement>.Of(TUnitPlaceModeElement.pmScanArea));
                    }
                    else
                    {
                        ((TArmy)AUnit.Owner).SetPlayer(0);
                        ArmyHS = ((TArmy)AUnit.Owner).GetArmyHS();
                    }

                    if (ArmyHS != null)
                    {
                        N = AoWEUnit.AoWHSMap.Random(10);
                        if (N == 0)
                        {
                            Behavior = TGroupBehavior.gbGuardArea;
                        }
                        else
                        {
                            if (N < 7)
                            {
                                Behavior = TGroupBehavior.gbScout;
                            }
                            else
                            {
                                Behavior = TGroupBehavior.gbRaid;
                            }
                        }

                        I = ArmyHS.FArmy.IndexOfBehavior(Behavior);
                        if (I == -1)
                        {
                            var indexOf = ArmyHS.FArmy.IndexOf(AUnit);
                            ArmyHS.FArmy.SetBehavior((byte)(1 << indexOf), Behavior);
                        }
                        else
                        {
                            var unit = ArmyHS.FArmy.GetUnit(I);
                            var indexOf = ArmyHS.FArmy.IndexOf(AUnit);
                            ArmyHS.FArmy.SetGroup((byte)(1 << indexOf), unit.FGroup);
                        }
                    }
                }
                else
                {
                    AUnit.Killed();
                }

                AUnit.RemoveEnchantments();
                AUnit.Release();
                if (AoWEUnit.AoWHSMap.FSeatedPlayer == FPlayer)
                {
                    AoWEUnit.AoWHSMap.FSelectedArmy.Unselect();
                }

                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).UpdateIncome();
            }

            return TExecuteResult.erDone;
        }

        // NetworkE.pas:230

    }

