            if (FMode.Contains(TCombatFlowControlModeElement.cfmEnableTurnTimer))
            {
                AoWEUnit.AoWHSMap.EnableTurnTimer();
            }

            if (FMode.Contains(TCombatFlowControlModeElement.cfmDisableTurnTimer))
