    public partial class TTerminatePlayerTE : TTokenEvent
    {
        public TTerminatePlayerTE(TECustomNode owner) : base(owner)
        { }

        public new const int ClassID = 131836;

        public sbyte FPlayer;
        public TExitGameCallBack FExitCallBack;
        public TExitGameMode FExitMode;

        // MoveT.PAS:3249
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FPlayer), 20);
        }

        // MoveT.PAS:3255
        public override TExecuteResult Execute(TTokenExecuter TE)
        {
            TMessageEventLog Log = default;
            AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FPlayerType = TPlayerType.ptCPU3;
            var remotePCC = (TRemotePCC)AoWEUnit.AoWHSMap.FPlayerCommunicator.PCC;
            remotePCC.SetConnectionMode(FPlayer, TConnectionMode.cmGlobal);
            remotePCC.SetSystemID(FPlayer, 0);

            if (!AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).FSingleProcessCycle)
            {
                AoWEUnit.AoWHSMap.FPlayerControl.EndTurn(FPlayer);
            }

            AoWEUnit.AoWHSMap.FPlayers.Update();
            if (AoWEUnit.AoWHSMap.FSeatedPlayer != FPlayer)
            {
                Log = new TMessageEventLog(null);
                Log.FButtons = TMessageEventLogButtons.mebOk;
                Log.FLayout = TMessageEventLogLayout.melNormal;
                var name = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FPlayer).GetName();
                var format = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.P5XLeftTheGameRStr), [name]);
                Log.FMessage.Add(format);
                // { Append the departure message, as in the original. }
                AoWEUnit.AoWHSMap.TriggerExecuteEventLog(Log, false, null);
                Log.Release();
            }
            else
            {
                AoWEUnit.AoWHSMap.ExecuteExitGame();
                if (FExitCallBack != null)
                {
                    FExitCallBack(FExitMode, true);
                }
            }

            return TExecuteResult.erDone;
        }

        // NetworkE.pas:230

    }
