    // round distance, state
    public partial class TFastCombatUnit : TCombatUnit
    {
        // AIGroup.pas:6778
        public new const int ClassID = 131791;

        // AIGroup.pas:6773
        public TFastCombatUnit(TECustomNode owner) : base(owner)
        {
        }

        public int FRoundDistance;
        public TSet<TFastCombatUnitStateElement> FState;

        // AIGroup.pas:6797
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            RwSet(ref FState, 1, 40, Stream.rwData, 0);
        }

        // AIGroup.pas:6862
        public override void GetTargetCVDV(TCombatObject Target, ref int CV, ref int DV)
        {
            TAbstractUnit AUnit;
            TAbilityTypeList Abilities;
            TAbilityDamageValues Values = default;
            int Value;
            TAbility Ability;
            if (!FStatus.Contains(TCombatObjectStatusElement.csDestroyed))
            {
                AUnit = FUnit;
                CV = 0;
                DV = 0;
                Abilities = AoWEUnit.AoWHSSet.FAbilityControl.FAbilitiesByType[(int)TAbilityType.atCombat];
                for (int I = Abilities.Count - 1; I >= 0; I--)
                {
                    Ability = Abilities.GetAbility(I);
                    if (AUnit.GetAbilityEnabled(Ability.FAbilityID))
                    {
                        Ability.fcGetDamageValueEx(this, Target, TWallSituation.wsNone, ref Values);
                        if (Values.SourceDamage > 0)
                        {
                            Value = Values.SourceDamage * Values.SourceDamage / (Values.TargetDamage + Values.SourceDamage);
                            if (Value <= 0)
                            {
                                Value = 1;
                            }

                            if (Value > CV)
                            {
                                CV = Value;
                            }

                            if (Values.SourceDamage > DV)
                            {
                                DV = Values.SourceDamage;
                            }
                        }
                    }
                }

                if (AUnit.GetAbilityEnabled(52))
                {
                    Ability = AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(52);
                    Ability.tcGetDamageValueEx(this, Target, ref Values);
                    if (Values.SourceDamage > 0)
                    {
                        Value = Values.SourceDamage * Values.SourceDamage / (Values.TargetDamage + Values.SourceDamage);
                        if (Value <= 0)
                        {
                            Value = 1;
                        }

                        if (Value > CV)
                        {
                            CV = Value;
                        }

                        if (Values.SourceDamage > DV)
                        {
                            DV = Values.SourceDamage;
                        }
                    }
                }
            }
            else
            {
                CV = 0;
                DV = 0;
            }
        }

        // AIGroup.pas:6913
        public override int GetTargetWallCV(TCombatObject Target)
        {
            int Best;
            TWallSituation Wall;
            TAbstractUnit AUnit;
            TAbilityTypeList Abilities;
            int Value;
            TAbility Ability;
            TAbilityDamageValues Values = default;
            AUnit = FUnit;
            Best = 0;
            if (FCombat.FCombatData.FPlayers.GetPlayers(FCombatPlayer).FSideIndex == 1)
            {
                Wall = TWallSituation.wsSource;
            }
            else
            {
                Wall = TWallSituation.wsTarget;
            }

            Abilities = AoWEUnit.AoWHSSet.FAbilityControl.FAbilitiesByType[(int)TAbilityType.atCombat];
            for (int I = Abilities.Count - 1; I >= 0; I--)
            {
                Ability = Abilities.GetAbility(I);
                if (AUnit.GetAbilityEnabled(Ability.FAbilityID))
                {
                    Ability.fcGetDamageValueEx(this, Target, Wall, ref Values);
                    if (Values.SourceDamage > 0)
                    {
                        Value = Values.SourceDamage * Values.SourceDamage / (Values.TargetDamage + Values.SourceDamage);
                        if (Value <= 0)
                        {
                            Value = 1;
                        }

                        if (Value > Best)
                        {
                            Best = Value;
                        }
                    }
                }
            }

            return Best;
        }

        // AIGroup.pas:6946
        public override int GetTargetPriority()
        {
            int I;
            int CV;
            TCombatObject Target;
            int Count;
            if (FTargetPriorityInvalid)
            {
                try
                {
                    if (FCombat.FCombatData.FWallType == 0 || FCombat.FCombatData.FWallBreached)
                    {
                        FTargetPriority = 0;
                        Count = 0;
                        I = FTargetedBy.Count - 1;
                        for (; I >= 0; I -= 1)
                        {
                            if (FTargetedBy.List[I].B == 0)
                            {
                                Count += 1;
                            }
                        }

                        I = FTargets.Count - 1;
                        for (; I >= 0; I -= 1)
                        {
                            CV = FTargets.List[I].B;
                            if (CV != 0)
                            {
                                Target = FTargets.List[I].A;
                                CV = Round((double)(CV * CV) / Target.FIncomingCombatValue);
                                FTargetPriority += CV;
                            }
                        }

                        FTargetPriority = FTargetPriority * (Count + 2);
                        I = FTargetedBy.Count;
                        // { The original stores normalized priority in the target-strength field. }
                        if (I != 0)
                        {
                            FTargetStrength = FTargetPriority / I;
                        }
                        else
                        {
                            FTargetStrength = 0;
                        }
                    }
                    else
                    {
                        FTargetPriority = 0;
                        Count = 0;
                        I = FTargetedBy.Count - 1;
                        for (; I >= 0; I -= 1)
                        {
                            if (FTargetedBy.List[I].C == 0)
                            {
                                Count += 1;
                            }
                        }

                        I = FTargets.Count - 1;
                        for (; I >= 0; I -= 1)
                        {
                            CV = FTargets.List[I].C;
                            if (CV != 0)
                            {
