                        for (int I = AUnit.GetAbilityCount() - 1; I >= 0; I--)
                        {
                            if (AUnit.GetAbilityEnabled(I))
                            {
                                var ability = AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(I);
                                Ability[0] = ability;
                                Ability[0].fcPrefetchCombatCommands(Commands);
                            }
                        }

                        FState = FState - TSet<TFastCombatUnitStateElement>.Of(TFastCombatUnitStateElement.fsOutsideWall);
                    }
                }
            }

            if (GetSide() == TCombatSideIndex.csDefender && FAttackerCount == 0 && !FCombat.FCombatData.GetSideLeaderInvolved(1))
            {
                for (int I = Commands.GetCount() - 1; I >= 0; I--)
                {
                    var commands = Commands.GetCommands(I);
                    var hitPoints = GetHitPoints();
                    if (commands.FTargetDV >= hitPoints * 75)
                    {
                        Commands.Delete(I);
                    }
                }
            }

            if (Commands.GetCount() != 0)
            {
                Commands.Sort();
                if (Commands.GetCommands(0).FMoveCost <= MoveCost)
                {
                    var commands = Commands.GetCommands(0);
                    var commandsCommands = Commands.GetCommands(0);
                    Executed = AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(commandsCommands.FAbilityID).fcExecuteCombatCommand(this, commands);
                    if (Commands.GetCommands(0).FAbilityID == 52)
                    {
                        UpdateWallSiegeObjectRegistration();
                    }

                    TurnDone();
                }
                else
                {
                    Executed = false;
                }
            }
            else
            {
                if (MoveCost == 2)
                {
                    if (FCombatValue == 0 && FIncomingCombatValue != 0 && GetSide() == TCombatSideIndex.csAttacker && !GetLocked())
                    {
                        Action = new TFleeCA(null);
                        Action.FObjectID = FID;
                        FCombat.ExecuteCombatAction(Action);
                        Action.Release();
                        Executed = true;
                    }
                    else
                    {
                        Executed = false;
                    }
                }
                else
                {
                    Executed = false;
                }
            }

            Commands?.Dispose();
            return Executed;
        }

