        public int GetAttackerBalisticCV()
        {
            int CV;
            TCombatSide Side;
            CV = 0;
            Side = FSides[(int)TCombatSideIndex.csAttacker];
            for (int I = 0, last = Side.Count - 1; I <= last; I++)
            {
                if (!Side.GetObjects(I).FStatus.Contains(TCombatObjectStatusElement.csDestroyed) && Side.GetObjects(I).SupportCombatMode(TSet<TCombatMode>.Of(TCombatMode.cmMediumRange, TCombatMode.cmLongRange)))
                {
                    CV += Side.GetObjects(I).FCombatValue;
                }
