namespace Aow.Game.Combat.Actions
{

    // (strike mode)
    public partial class TStrikeCA : TDamageCA
    {
        public new const int ClassID = 131754;

        public TStrikeCA(TECustomNode owner) : base(owner)
        { }

        public TSet<Aow.Game.Combat.TStrikeModeElement> FStrikeMode;

        // AoWAb.PAS:1157
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            RwSet(ref FStrikeMode, 1, 20, Stream.rwData, 0);
        }

        // AoWAb.PAS:1163
        public override void Execute(Aow.Game.Combat.TCombat Combat)
        {
            Aow.Game.Combat.TCombatObject Source;
            Aow.Game.Combat.TCombatObject Target;
            TUnitEnchantmentAbilityData Data;
            Source = Combat.FCombatData.FindID(FSourceID);
            Target = Combat.FCombatData.FindID(FTargetID);
            FDamageDone = (byte)Source.DoDamage(Target, FDamage);
            if (FEffects.Value != TSet<Aow.Game.Combat.TDamageType>.Of())
            {
                Target.ExecuteDamageEffects(FEffects.Value);
            }

            if (FDamageDone != 0 && FStrikeMode.Contains(Aow.Game.Combat.TStrikeModeElement.smLifeStealing) && Target is Aow.Game.Combat.TCombatUnit && ((Aow.Game.Combat.TCombatUnit)Target).FUnit.GetUnitType() != TUnitType.utMachine)
            {
                Source.SetHitPoints((byte)(Source.GetHitPoints() + 1));
            }

            if (FStrikeMode.Contains(Aow.Game.Combat.TStrikeModeElement.smCausedFear) && Target is Aow.Game.Combat.TCombatUnit)
            {
                AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(108).Expand(((Aow.Game.Combat.TCombatUnit)Target).FUnit);
            }

            if (FStrikeMode.Contains(Aow.Game.Combat.TStrikeModeElement.smEntangled) && Target is Aow.Game.Combat.TCombatUnit)
            {
                AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(94).Expand(((Aow.Game.Combat.TCombatUnit)Target).FUnit);
                Data = (TUnitEnchantmentAbilityData)((Aow.Game.Combat.TCombatUnit)Target).FUnit.GetAbilityData(94);
                if (Data != null)
                {
                    Data.FEnchantmentPlayerIndex = Source.FCombatPlayer;
                }
            }
        }

        // AoWAb.PAS:1187
        public override bool Play(Aow.Game.Combat.TCombatViewer Viewer)
        {
            if (Viewer.FTime == 1)
            {
                if (FDamage == 0)
                {
                    Viewer.FCombat.FCombatData.FindID(FSourceID).PlaySFX(1);
                }
                else
                {
                    Viewer.FCombat.FCombatData.FindID(FSourceID).PlaySFX(0);
                }
            }

            return base.Play(Viewer);
        }

        // AoWAb.PAS:1197
        public override void Generate(Aow.Game.Combat.TCombatObject Source, Aow.Game.Combat.TCombatObject Target, sbyte Attack, sbyte Damage, TSet<Aow.Game.Combat.TDamageType> DamageTypes)
        {
            base.Generate(Source, Target, Attack, Damage, DamageTypes);
            if (FDamage != 0)
            {
                if (Source.GetAbilityEnabled(51) && !Target.GetAbilityEnabled(67) && AoWEUnit.HitRole(3 - Target.GetResistance()))
                {
                    FStrikeMode = FStrikeMode + TSet<Aow.Game.Combat.TStrikeModeElement>.Of(Aow.Game.Combat.TStrikeModeElement.smCausedFear);
                }

                if (Source.GetAbilityEnabled(119) && AoWEUnit.HitRole(7 - Target.GetResistance()))
                {
                    FStrikeMode = FStrikeMode + TSet<Aow.Game.Combat.TStrikeModeElement>.Of(Aow.Game.Combat.TStrikeModeElement.smEntangled);
                }
            }
        }

        // intf_P3_02.inc:38

    }
}

