    [LegacyObject]
    // count, capacity, strikes, combat objects, cached damage values, units, strike counts,
    // attacker/defender damage types
    public partial class TMeleeRound : IDisposable
    {
        // AoWAb.PAS:1487
        public TMeleeRound()
        {
            CaptureAddress.Assign(this);
        }

        public int FCount;
        public int FCapacity;
        public TMeleeStrike[] FStrikes = [];
        public TCombatObject FAttacker;
        public TCombatObject FDefender;
        public int FAttackerDV;
        public int FDefenderDV;
        public TAbstractUnit FAttackerUnit;
        public TAbstractUnit FDefenderUnit;
        public int FAttackerStrikes;
        public int FDefenderStrikes;
        public TSet<TDamageType> FAttackerDamageTypes;
        public TSet<TDamageType> FDefenderDamageTypes;

        // AoWAb.PAS:1492
        public virtual void Dispose()
        {
            SetCapacity(0);
        }

        // AoWAb.PAS:1498
        public void SetCapacity(int NewCapacity)
        {
            FCapacity = NewCapacity;
            if (FCapacity < FCount)
            {
                FCount = FCapacity;
            }

            Array.Resize(ref FStrikes, NewCapacity);
        }

        // AoWAb.PAS:1505
        public void SetCount(int NewCount)
        {
            if (NewCount > FCapacity)
            {
                SetCapacity(NewCount);
            }

            if (NewCount > FCount)
            {
                FStrikes.AsSpan(FCount, NewCount - FCount).Clear();
            }

            FCount = NewCount;
        }

        // AoWAb.PAS:1513
        public void GetMeleeStrike(int Index, ref TMeleeStrike Strike)
        {
            Strike = FStrikes[Index];
        }

        // AoWAb.PAS:1518
        public void Reset()
        {
            SetCount(0);
            FAttacker = null;
            FDefender = null;
            FAttackerUnit = null;
            FDefenderUnit = null;
            FAttackerDV = -1;
            FDefenderDV = -1;
            FAttackerStrikes = 0;
            FDefenderStrikes = 0;
        }

        // AoWAb.PAS:1531
        public void CalculateUnitStrikes(TCombatSideIndex FirstSide)
        {
            int AttackerCount;
            int DefenderCount;
            TCombatSideIndex Side;
            TAbstractUnit Source;
            TAbstractUnit Target;
            Side = FirstSide;
            AttackerCount = 0;
            DefenderCount = 0;
            SetCount(FAttackerStrikes + FDefenderStrikes);
            for (int I = 0, last = FCount - 1; I <= last; I++)
            {
                if (Side == TCombatSideIndex.csAttacker)
                {
                    Source = FAttackerUnit;
                    Target = FDefenderUnit;
                }
                else
                {
                    Source = FDefenderUnit;
                    Target = FAttackerUnit;
                }

                ref var Strike = ref FStrikes[I];
                Strike.Side = Side;
                if (I == 0 || (I == 1 && Side != FirstSide))
                {
                    if (Side == TCombatSideIndex.csAttacker && I == 0 && Source.GetAbilityEnabled(111))
                    {
                        Strike.DamageBonus += 2;
                    }

                    if (Target.GetAbilityEnabled(113))
                    {
                        Strike.AttackBonus -= 2;
                    }
                }

                bool condition = Source.GetAbilityEnabled(146) || Source.GetAbilityEnabled(160);
                if (condition)
                {
                    var alignment = Target.GetAlignment();
                    condition = TSet<TAlignment>.Of(TAlignment.alEvil, TAlignment.alPureEvil).Contains(alignment);
                }

                if (condition)
                {
                    Strike.DamageBonus += 2;
                    Strike.AttackBonus += 2;
                }

                bool test = Source.GetAbilityEnabled(147) || Source.GetAbilityEnabled(161);
                if (test)
                {
                    var alignment = Target.GetAlignment();
                    test = TSet<TAlignment>.Of(TAlignment.alPureGood, TAlignment.alGood).Contains(alignment);
                }

                if (test)
                {
                    Strike.DamageBonus += 2;
                    Strike.AttackBonus += 2;
                }

                if (Source.GetAbilityEnabled(112) && Target.GetAbilityEnabled(63))
                {
                    Strike.AttackBonus += 3;
                    Strike.DamageBonus += 3;
                }

                // { Original uses the attacker's damage types for both sides. }
                var defense = Target.GetDefense();
                var resistance = Target.GetResistance();
                var immunityTypes = Target.GetImmunityTypes();
                var protectionTypes = Target.GetProtectionTypes();
                var damage = Source.GetDamage();
                var statisticsToDV = AoWEUnit.StatisticsToDV(Source.GetAttack() + Strike.AttackBonus, damage + Strike.DamageBonus, FAttackerDamageTypes, defense, resistance, immunityTypes, protectionTypes);
                Strike.DamageValue = statisticsToDV;
                switch (Side)
                {
                    case TCombatSideIndex.csAttacker:
                        AttackerCount += 1;
                        if (FDefenderStrikes != DefenderCount)
                        {
                            Side = TCombatSideIndex.csDefender;
                        }

                        break;
                    case TCombatSideIndex.csDefender:
                        DefenderCount += 1;
                        if (FAttackerStrikes != AttackerCount)
                        {
                            Side = TCombatSideIndex.csAttacker;
                        }

                        break;
                }
            }
        }

        // AoWAb.PAS:1600
        public void CalculateFreeUnitSwing(TAbstractUnit Attacker, TAbstractUnit Defender)
        {
            Reset();
            FAttackerUnit = Attacker;
            FDefenderUnit = Defender;
            FAttackerDamageTypes = ((TStrikeAbility)AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(21)).GetDamageTypes(Attacker);
            FDefenderDamageTypes = TSet<TDamageType>.Of();
            if (FAttackerDamageTypes != TSet<TDamageType>.Of())
            {
                FAttackerStrikes = 1;
                CalculateUnitStrikes(TCombatSideIndex.csAttacker);
            }
        }

        // AoWAb.PAS:1614
        public void CalculateUnit(TAbstractUnit Attacker, TAbstractUnit Defender)
        {
            TCombatSideIndex Side;
            Reset();
            FAttackerUnit = Attacker;
            FDefenderUnit = Defender;
            FAttackerDamageTypes = ((TStrikeAbility)AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(21)).GetDamageTypes(Attacker);
            if (FAttackerDamageTypes != TSet<TDamageType>.Of())
            {
                FAttackerStrikes = 2;
                if (FAttackerUnit.GetAbilityEnabled(115))
                {
                    FAttackerStrikes += 1;
                }
            }
            else
            {
                FAttackerStrikes = 0;
            }

            FDefenderDamageTypes = ((TStrikeAbility)AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(21)).GetDamageTypes(Defender);
            if (FDefenderDamageTypes != TSet<TDamageType>.Of())
            {
                FDefenderStrikes = 2;
            }
            else
            {
                FDefenderStrikes = 0;
            }

            if (FDefenderUnit.GetAbilityEnabled(116) && !FAttackerUnit.GetAbilityEnabled(116) && FDefenderStrikes != 0)
            {
                Side = TCombatSideIndex.csDefender;
            }
            else
            {
                Side = TCombatSideIndex.csAttacker;
            }

            CalculateUnitStrikes(Side);
        }

        // AoWAb.PAS:1642
        public void CalculateStrikes(TCombatSideIndex FirstSide)
        {
            int AttackerCount;
            int DefenderCount;
            TCombatSideIndex Side;
            TCombatObject Source;
            TCombatObject Target;
            Side = FirstSide;
            AttackerCount = 0;
            DefenderCount = 0;
            SetCount(FAttackerStrikes + FDefenderStrikes);
            for (int I = 0, last = FCount - 1; I <= last; I++)
            {
                if (Side == TCombatSideIndex.csAttacker)
                {
                    Source = FAttacker;
                    Target = FDefender;
                }
                else
                {
                    Source = FDefender;
                    Target = FAttacker;
                }

                ref var Strike = ref FStrikes[I];
                Strike.Side = Side;
                if (I == 0 || (I == 1 && Side != FirstSide))
                {
                    if (Side == TCombatSideIndex.csAttacker && I == 0 && Source.GetAbilityEnabled(111))
                    {
                        Strike.DamageBonus += 2;
                    }

                    if (Target.GetAbilityEnabled(113))
                    {
                        Strike.AttackBonus -= 2;
                    }
                }

                bool condition = Source.GetAbilityEnabled(146) || Source.GetAbilityEnabled(160);
                if (condition)
                {
                    var alignment = Target.GetAlignment();
                    condition = TSet<TAlignment>.Of(TAlignment.alEvil, TAlignment.alPureEvil).Contains(alignment);
                }

                if (condition)
                {
                    Strike.AttackBonus += 2;
                    Strike.DamageBonus += 2;
                }

                bool test = Source.GetAbilityEnabled(147) || Source.GetAbilityEnabled(161);
                if (test)
                {
                    var alignment = Target.GetAlignment();
                    test = TSet<TAlignment>.Of(TAlignment.alPureGood, TAlignment.alGood).Contains(alignment);
                }

                if (test)
                {
                    Strike.AttackBonus += 2;
                    Strike.DamageBonus += 2;
                }

                if (Source.GetAbilityEnabled(112) && Target.GetAbilityEnabled(63))
                {
                    Strike.AttackBonus += 3;
                    Strike.DamageBonus += 3;
                }

                // { Original uses the attacker's damage types for both sides. }
                var defense = Target.GetDefense();
                var resistance = Target.GetResistance();
                var immunityTypes = Target.GetImmunityTypes();
                var protectionTypes = Target.GetProtectionTypes();
                var damage = Source.GetDamage();
                var statisticsToDV = AoWEUnit.StatisticsToDV(Source.GetAttack() + Strike.AttackBonus, damage + Strike.DamageBonus, FAttackerDamageTypes, defense, resistance, immunityTypes, protectionTypes);
                Strike.DamageValue = statisticsToDV;
                switch (Side)
                {
                    case TCombatSideIndex.csAttacker:
                        AttackerCount += 1;
                        if (FDefenderStrikes != DefenderCount)
                        {
                            Side = TCombatSideIndex.csDefender;
                        }

                        break;
                    case TCombatSideIndex.csDefender:
                        DefenderCount += 1;
                        if (FAttackerStrikes != AttackerCount)
                        {
                            Side = TCombatSideIndex.csAttacker;
                        }

                        break;
                }
            }
        }

        // AoWAb.PAS:1711
        public void Calculate(TCombatObject Attacker, TCombatObject Defender)
        {
            TCombatSideIndex Side;
            Reset();
            FAttacker = Attacker;
            FDefender = Defender;
            FAttackerDamageTypes = AoWEUnit.MeleeDamageTypes(Attacker);
            if (FAttackerDamageTypes != TSet<TDamageType>.Of() && !Attacker.GetLocked())
            {
                FAttackerStrikes = 2;
                if (FAttacker.GetAbilityEnabled(115))
                {
                    FAttackerStrikes += 1;
                }
            }
            else
            {
                FAttackerStrikes = 0;
            }

            FDefenderDamageTypes = AoWEUnit.MeleeDamageTypes(Defender);
            if (FDefenderDamageTypes != TSet<TDamageType>.Of() && !Defender.GetLocked())
            {
                FDefenderStrikes = 2;
            }
            else
            {
                FDefenderStrikes = 0;
            }

            if (Defender.GetAbilityEnabled(116) && !Attacker.GetAbilityEnabled(116) && FDefenderStrikes != 0)
            {
                Side = TCombatSideIndex.csDefender;
            }
            else
            {
                Side = TCombatSideIndex.csAttacker;
            }

            CalculateStrikes(Side);
        }

        // AoWAb.PAS:1739
        public void CalculateSingleSide(TCombatObject Attacker, TCombatObject Defender)
        {
            Reset();
            FAttacker = Attacker;
            FDefender = Defender;
            FAttackerDamageTypes = AoWEUnit.MeleeDamageTypes(Attacker);
            FDefenderDamageTypes = TSet<TDamageType>.Of();
            if (FAttackerDamageTypes != TSet<TDamageType>.Of() && !FAttacker.GetLocked())
            {
                FAttackerStrikes = 2;
                if (FAttacker.GetAbilityEnabled(115))
                {
                    FAttackerStrikes += 1;
                }
            }

            CalculateStrikes(TCombatSideIndex.csAttacker);
        }

        // AoWAb.PAS:1754
        public TStrikeCA CreateStrikeCA(int Index)
        {
            TStrikeCA Result = null;
            if (Index < FCount)
            {
                ref var Strike = ref FStrikes[Index];
                switch (Strike.Side)
                {
                    case TCombatSideIndex.csAttacker:
                        if (!FAttacker.GetLocked())
                        {
                            Result = new TStrikeCA(null);
                            var damage = FAttacker.GetDamage();
                            var attack = FAttacker.GetAttack();
                            Result.Generate(FAttacker, FDefender, (sbyte)(attack + Strike.AttackBonus), (sbyte)(damage + Strike.DamageBonus), FAttackerDamageTypes);
                            if (FAttacker.GetAbilityEnabled(118))
                            {
                                Result.FStrikeMode = Result.FStrikeMode + TSet<TStrikeModeElement>.Of(TStrikeModeElement.smLifeStealing);
                            }
                        }

                        break;
                    case TCombatSideIndex.csDefender:
                        if (!FDefender.GetLocked())
                        {
                            Result = new TStrikeCA(null);
                            Result.SetDefensive(true);
                            var damage = FDefender.GetDamage();
                            var attack = FDefender.GetAttack();
                            Result.Generate(FDefender, FAttacker, (sbyte)(attack + Strike.AttackBonus), (sbyte)(damage + Strike.DamageBonus), FDefenderDamageTypes);
                        }

                        break;
                }
            }

            return Result;
        }

        // AoWAb.PAS:1786
        public void CalculateDV()
        {
            int I;
            int LifeStealingDV;
            bool LifeStealing;
            TCombatObject Source;
            FAttackerDV = 0;
            FDefenderDV = 0;
            I = 0;
            LifeStealingDV = 0;
            Source = FAttacker;
            if (Source != null)
            {
                LifeStealing = Source.GetAbilityEnabled(118);
                if (LifeStealing && FDefender is TCombatUnit && ((TCombatUnit)FDefender).FUnit.GetUnitType() == TUnitType.utMachine)
                {
                    LifeStealing = false;
                }
            }
            else
            {
                LifeStealing = FAttackerUnit.GetAbilityEnabled(118);
                if (LifeStealing && FDefenderUnit.GetUnitType() == TUnitType.utMachine)
                {
                    LifeStealing = false;
                }
            }

            while (I != FCount)
            {
                if (FStrikes[I].Side == TCombatSideIndex.csAttacker)
                {
                    FAttackerDV += FStrikes[I].DamageValue;
                    if (FStrikes[I].DamageValue > 100)
                    {
                        LifeStealingDV += 100;
                    }
                    else
                    {
                        LifeStealingDV += FStrikes[I].DamageValue;
                    }
                }
                else
                {
                    FDefenderDV += FStrikes[I].DamageValue;
                }

                I += 1;
            }

            if (LifeStealing && FDefenderDV > 0)
            {
                FDefenderDV -= LifeStealingDV;
                if (FDefenderDV <= 0)
                {
                    FDefenderDV = 1;
                }
            }
        }

        // AoWAb.PAS:1831
        public int GetAttackerDV()
        {
            if (FAttackerDV == -1)
            {
                CalculateDV();
            }

            return FAttackerDV;
        }

        // AoWAb.PAS:1837
        public int GetDefenderDV()
        {
            if (FDefenderDV == -1)
            {
                CalculateDV();
            }

            return FDefenderDV;
        }

        // intf_P4_02.inc:123

    }
}

