            FSelectionTypes = TSet<TAbilitySelectionType>.Of(TAbilitySelectionType.astUnit, TAbilitySelectionType.astAttackItem);
            FAbilityType = TAbilityType.atCombat;
            FAbilityID = 21;
            FAbilityName = AoWEUnit.TranslateRStr(AoWEUnit.StrikeRStr);
