        // AoWAb.PAS:1226
        public override TSet<TAbilityControlTypeElement> GetControlType(TAbilityOwner Owner) => TSet<TAbilityControlTypeElement>.Of();

        // AoWAb.PAS:1445
        public override void fcPrefetchCombatCommands(TFastCombatCommandList Commands)
        {
            TCombatObject Target;
            TFastCombatCommand Command;
            TAbilityDamageValues Values = default;
            for (int I = 0, last = Commands.FTargetSide.GetCount() - 1; I <= last; I++)
            {
                Target = Commands.FTargetSide.GetObjects(I);
                if (Target.GetEnabled() && fcValidRoundDistance(Commands.FSource, Target) && CanExecuteMelee(Commands.FSource, Target))
                {
                    fcGetDamageValueEx(Commands.FSource, Target, TWallSituation.wsNone, ref Values);
                    if (Values.SourceDamage != 0)
                    {
                        Command = new TFastCombatCommand(FAbilityID);
                        Command.FTarget = Target;
                        Command.FSourceDV = Values.SourceDamage;
                        Command.FTargetDV = Values.TargetDamage;
                        Command.FExpectedDV = AoWEUnit.DVtoDEV(Values.SourceDamage, Values.TargetDamage, Commands.FSource, Target);
                        // { Both original branches assign the same move cost. }
                        if (Values.TargetDamage == 0)
                        {
                            Command.FMoveCost = 2;
                        }
                        else
                        {
                            Command.FMoveCost = 2;
                        }

                        Commands.Add(Command);
                    }
                }
            }
        }

        // AoWAb.PAS:1399
        public override bool fcExecuteCombatCommand(TCombatObject Source, TFastCombatCommand Command)
        {
            TMeleeRound Round;
            int I;
            bool Stop;
            TCombatObject Target;
            TCombatAction Action;
            TMoveWallCA MoveCA;
            TMeleeStrike Strike = default;
            Target = Command.FTarget;
            Round = new TMeleeRound();
            Round.Calculate(Source, Target);
            Stop = false;
            I = 0;
            if (Source is TFastCombatUnit)
            {
                ((TFastCombatUnit)Source).FState = ((TFastCombatUnit)Source).FState + TSet<TFastCombatUnitStateElement>.Of(TFastCombatUnitStateElement.fsVulnerable);
                if (Source.fcBehindWall() && Source.fcWallInBetween(Target.FPosition) && !Target.WallCombatFeatures().Contains(TWallCombatFeaturesElement.wcWallPassing))
                {
                    MoveCA = new TMoveWallCA(null);
                    MoveCA.F_MoveWallCA_0C = Source.FID;

                    MoveCA.F_MoveWallCA_0D = 0;

                    Source.FCombat.ExecuteCombatAction(MoveCA);
                    MoveCA.Release();
                }
            }

            while (I < Round.FCount && !Stop)
            {
                Action = Round.CreateStrikeCA(I);
                if (Action != null)
                {
                    Source.FCombat.ExecuteCombatAction(Action);
                    Round.GetMeleeStrike(I, ref Strike);
                    switch (Strike.Side)
                    {
                        case TCombatSideIndex.csAttacker:
                            Stop = !Target.GetEnabled();
                            break;
                        case TCombatSideIndex.csDefender:
                            Stop = !Source.GetEnabled();
                            break;
                    }

                    Action.Release();
                }

                I += 1;
            }

            bool Result = Round.FCount != 0;
            Round?.Dispose();
            return Result;
        }

        // AoWAb.PAS:1297
        public override int GetDamageValue(TAbstractUnit Attacker, TAbstractUnit Defender)
        {
