            if (Owner is TAbstractUnit)
            {
                var unit = (TAbstractUnit)Owner;
                var attack = unit.GetAttack();
                Info.Attack = attack;
                var damage = unit.GetDamage();
                Info.Damage = damage;

                var damageTypes = GetDamageTypes(Owner);
                Info.DamageTypes = damageTypes;
                Info.RepeatCount = 2;
            }
            else
            {
                Info.Attack = -1;
                Info.Damage = -1;
                Info.DamageTypes = TSet<TDamageType>.Of(TDamageType.dtPhysical);
                Info.RepeatCount = 2;
            }
        }

        // AoWAb.PAS:1248
        public bool CanExecuteMelee(TCombatObject Source, TCombatObject Target)
        {
            bool Result;
            if (Source.GetSide() == TCombatSideIndex.csDefender)
            {
                if (Source.fcBehindWall() && Source.fcWallInBetween(Target.FPosition))
                {
                    Result = Target.WallCombatFeatures().Contains(TWallCombatFeaturesElement.wcWallPassing);
                }
                else
                {
                    Result = true;
                }
            }
            else
            {
                if (Target.fcBehindWall() && Source.fcWallInBetween(Target.FPosition) && !Source.WallCombatFeatures().Contains(TWallCombatFeaturesElement.wcWallPassing))
                {
                    Result = false;
                }
                else
                {
                    Result = true;
                }
            }

            return Result && (!Target.GetAbilityEnabled(1) || Source.GetAbilityEnabled(1));
        }

        // AoWAb.PAS:1354
        public TSet<TDamageType> GetDamageTypes(TAbilityOwner Owner)
        {
            TSet<TDamageType> Result;
            if (Owner is TAbstractUnit && ((TAbstractUnit)Owner).GetAbilityEnabled(21))
            {
                Result = TSet<TDamageType>.Of(TDamageType.dtPhysical);
                var unit = (TAbstractUnit)Owner;
                if (unit.GetAbilityEnabled(14) || unit.GetAbilityEnabled(163))
                {
                    Result = Result + TSet<TDamageType>.Of(TDamageType.dtFire);
                }

                if (unit.GetAbilityEnabled(15))
                {
                    Result = Result + TSet<TDamageType>.Of(TDamageType.dtCold);
                }

                if (unit.GetAbilityEnabled(16))
                {
                    Result = Result + TSet<TDamageType>.Of(TDamageType.dtLightning);
                }

                if (unit.GetAbilityEnabled(17))
                {
                    Result = Result + TSet<TDamageType>.Of(TDamageType.dtPoison);
                }

                var unit2 = (TAbstractUnit)Owner;
                if (unit2.GetAbilityEnabled(18) || unit2.GetAbilityEnabled(169))
                {
                    Result = Result + TSet<TDamageType>.Of(TDamageType.dtDeath);
                }

                if (unit2.GetAbilityEnabled(19))
                {
                    Result = Result + TSet<TDamageType>.Of(TDamageType.dtHoly);
                }

                var unit3 = (TAbstractUnit)Owner;
                if (unit3.GetAbilityEnabled(20) || unit3.GetAbilityEnabled(154))
                {
                    Result = Result + TSet<TDamageType>.Of(TDamageType.dtMagic);
                }
            }
            else
            {
                Result = TSet<TDamageType>.Of();
            }

            return Result;
        }

        public override bool Remove(TAbilityOwner owner)
        {
            if (!owner.GetAbEnabled(21)) return false;
            base.Remove(owner);
            for (int i = owner.GetAbCount() - 1; i >= 0; --i)
                if (owner.GetAbEnabled(i) && AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(i) is TStrikeEnhancementAbility)
                    while (AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(i).Remove(owner)) { }
            return true;
        }
    }
}

