            TSet<TDamageType> ImmunityTypes;
            int Damage;
            int Defense;
            int Value;
            int Repeats;
            TCombatRange Range;
            Range = GetRangeRA(Attacker.GetAbilityOwner());
            if (WallSituation == TWallSituation.wsNone || TSet<TCombatRange>.Of(TCombatRange.crMedium, TCombatRange.crLong).Contains(Range) || Attacker.GetAbilityEnabled(1))
            {
