    public partial class TBreathAbility : TRangedAttackAbility
    {
        // AoWAb.PAS:4852
        public TBreathAbility(TECustomNode owner) : base(owner)
        {
            FRangeRA = TCombatRange.crShort;
            FAttackRepeatRA = 1;
            FAttackRA = 7;
            FDamageRA = 5;
        }

        // AoWAb.PAS:4894
        public override bool fcExecuteCombatCommand(TCombatObject Source, TFastCombatCommand Command)
        {
            TCombat Combat;
            TList Targets;
            TCombatObject Target;
            TCombatObject Other;
            int Count;
            TRangedAttackCA Action;
            bool Result = base.fcExecuteCombatCommand(Source, Command);
            if (Result)
            {
                Combat = Source.FCombat;
                Targets = new TList();
                Target = Command.FTarget;
                for (int I = Combat.FSides[(int)Target.GetSide()].GetCount() - 1; I >= 0; I--)
                {
                    var side = Target.GetSide();
                    Other = Combat.FSides[(int)side].GetObjects(I);
                    bool condition = Other != Target && Other.GetEnabled() && (int)(((uint)Other.FPosition) >> 4) == (int)(((uint)Target.FPosition) >> 4) && Other.fcRoundDistance() <= Combat.GetRoundDistance();
                    if (condition)
                    {
                        var immunityTypes = Other.GetImmunityTypes();
                        condition = FDamageTypesRA.Value - immunityTypes != TSet<TDamageType>.Of();
                    }

                    if (condition)
                    {
                        Targets.Add(Other);
                    }
                }

                Count = AoWEUnit.AoWHSMap.Random(2) + 1;
                while (Count != 0 && Targets.Count != 0)
                {
                    Other = (TCombatObject)Targets[AoWEUnit.AoWHSMap.Random(Targets.Count)];
                    Action = CreateRangedAttackCA(Source, Other, 2);
                    Source.FCombat.ExecuteCombatAction(Action);
                    Action.Release();
                    Targets.Remove(Other);
                    Count -= 1;
                }

                Targets?.Dispose();
            }

            return Result;
        }

        // AoWAb.PAS:4860
        public override void GetOffensiveStrength(TAbilityOwner Owner, ref int Strength, ref TSet<TDamageType> Types)
        {
            var attackRepeatRA = GetAttackRepeatRA(Owner);
            var damageRA = GetDamageRA(Owner);
            Strength = AoWEUnit.P3LimitedDamage(GetAttackRA(Owner), damageRA, attackRepeatRA);
            Strength = Strength * 2;
            Types = GetDamageTypesRA(Owner);
        }

        // AoWAb.PAS:4866
        public override void fcGetDamageValueEx(TCombatObject Attacker, TCombatObject Defender, TWallSituation WallSituation, ref TAbilityDamageValues DamageValues)
        {
            int Count;
            TCombat Combat;
            TCombatObject Target;
            base.fcGetDamageValueEx(Attacker, Defender, WallSituation, ref DamageValues);
            if (DamageValues.SourceDamage != 0)
            {
                Combat = Attacker.FCombat;
                Count = 0;
                for (int I = Combat.FSides[(int)Defender.GetSide()].GetCount() - 1; I >= 0; I--)
                {
                    var side = Defender.GetSide();
                    Target = Combat.FSides[(int)side].GetObjects(I);
                    bool condition = Target != Defender && Target.GetEnabled() && (int)(((uint)Target.FPosition) >> 4) == (int)(((uint)Defender.FPosition) >> 4) && Target.fcRoundDistance() <= Combat.GetRoundDistance();
                    if (condition)
                    {
                        var immunityTypes = Target.GetImmunityTypes();
                        condition = FDamageTypesRA.Value - immunityTypes != TSet<TDamageType>.Of();
                    }

                    if (condition)
                    {
                        Count += 1;
                    }
                }

                if (Count != 0)
                {
                    if (Count > 3)
                    {
                        Count = 3;
                    }

                    DamageValues.SourceDamage += Round((double)(DamageValues.SourceDamage * Count) / 3);
                }
            }
        }

        // AoWAb.PAS:4930
        public override void tcGetDamageValueEx(TCombatObject Attacker, TCombatObject Defender, ref TAbilityDamageValues DamageValues)
        {
            base.fcGetDamageValueEx(Attacker, Defender, TWallSituation.wsNone, ref DamageValues);
        }
    }

