    public partial class TTouchAbility : TAdjustableAbility
    {
        // AoWAb.PAS:1843
        public TTouchAbility(TECustomNode owner) : base(owner)
        {
            FSelectionTypes = FSelectionTypes + TSet<TAbilitySelectionType>.Of(TAbilitySelectionType.astUseItem);
            FAbilityType = TAbilityType.atCombat;
        }

        // AoWAb.PAS:1875
        public override TCombatMode GetCombatMode(TAbilityOwner Owner) => TCombatMode.cmTouch;

        // AoWAb.PAS:1850
        public override TSet<TAbilityControlTypeElement> GetControlType(TAbilityOwner Owner) => TSet<TAbilityControlTypeElement>.Of(TAbilityControlTypeElement.acCombatAction);

        // AoWAb.PAS:1962
        public override void fcPrefetchCombatCommands(TFastCombatCommandList Commands)
        {
            TCombatObject Target;
            TFastCombatCommand Command;
            TAbilityDamageValues Values = default;
            for (int I = 0, last = Commands.FTargetSide.GetCount() - 1; I <= last; I++)
            {
                Target = Commands.FTargetSide.GetObjects(I);
                if (Target.GetEnabled() && CanTouch(Commands.FSource, Target) && fcValidRoundDistance(Commands.FSource, Target))
                {
                    fcGetDamageValueEx(Commands.FSource, Target, TWallSituation.wsNone, ref Values);
                    if (Values.SourceDamage != 0)
                    {
                        Command = new TFastCombatCommand(FAbilityID);
                        Command.FTarget = Commands.FTargetSide.GetObjects(I);
                        Command.FSourceDV = Values.SourceDamage;
                        Command.FTargetDV = Values.TargetDamage;
                        Command.FExpectedDV = AoWEUnit.DVtoDEV(Values.SourceDamage, Values.TargetDamage, Commands.FSource, Target);
                        if (Values.TargetDamage == 0)
                        {
                            Command.FMoveCost = 1;
                        }
                        else
                        {
                            Command.FMoveCost = 2;
                        }

                        Commands.Add(Command);
                    }
                }
            }
        }

        // AoWAb.PAS:1860
        public override void GetCombatInfo(TAbilityOwner Owner, ref TAbilityCombatInfo Info)
        {
            sbyte Attack;
            int Level;
            Level = GetLevel(Owner);
            Attack = GetTouchAttack(Level);
            Info.Attack = Attack;
            if (Attack < 0)
            {
                Info.Attack = 0;
            }

            Info.Damage = -1;
            Info.DamageTypes = TSet<TDamageType>.Of();
            Info.RepeatCount = 1;
            Info.TargetTypes = TSet<TCombatTargetTypeElement>.Of(TCombatTargetTypeElement.cttEnemy);
        }

        // AoWAb.PAS:1855
        public virtual sbyte GetTouchAttack(int Level) => -10;

        // AoWAb.PAS:1892
        public virtual bool CombatTouchRole(TCombatUnit Source, TCombatObject Target)
        {
            int Attack;
            bool Result = AoWEUnit.HitRole(Source.GetAttack() - Target.GetDefense());
            Attack = GetTouchAttack(GetLevel(Source.FUnit));
            if (Result && Attack != -10)
            {
                Result = Result && AoWEUnit.HitRole(Attack - Target.GetResistance());
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // AoWAb.PAS:1904
        public virtual float CombatTouchRoleProbability(TCombatUnit Source, TCombatObject Target)
        {
            int Attack;
            float Result = AoWEUnit.HitRoleProbability(Source.GetAttack() - Target.GetDefense());
            Attack = GetTouchAttack(GetLevel(Source.FUnit));
            if (Attack != -10)
            {
                Result = (float)((double)Result * AoWEUnit.HitRoleProbability(Attack - Target.GetResistance()));
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // AoWAb.PAS:1880
        public virtual float TouchRoleProbability(TAbstractUnit Source, TAbstractUnit Target)
        {
            int Attack;
            float Result = AoWEUnit.HitRoleProbability(Source.GetAttack() - Target.GetDefense());
            Attack = GetTouchAttack(GetLevel(Source));
            if (Attack != -10)
            {
                Result = (float)((double)Result * AoWEUnit.HitRoleProbability(Attack - Target.GetResistance()));
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // AoWAb.PAS:1916
        public virtual bool CanTouch(TCombatObject Source, TCombatObject Target)
        {
            bool Result;
            if (Source.GetSide() == TCombatSideIndex.csDefender)
            {
                if (Source.fcBehindWall() && Source.fcWallInBetween(Target.FPosition))
                {
                    Result = Target.WallCombatFeatures().Contains(TWallCombatFeaturesElement.wcWallPassing);
                }
                else
                {
                    Result = true;
                }
            }
            else
            {
                if (Target.fcBehindWall() && Source.fcWallInBetween(Target.FPosition) && !Source.WallCombatFeatures().Contains(TWallCombatFeaturesElement.wcWallPassing))
                {
                    Result = false;
                }
                else
                {
                    Result = true;
                }
            }

            if (Source.GetSide() != Target.GetSide())
            {
                Result = Result && (!Target.GetAbilityEnabled(1) || Source.GetAbilityEnabled(1));
            }

            return Result;
        }

        // AoWAb.PAS:1937
        public virtual bool CanTouchUnit(TAbstractUnit Source, TAbstractUnit Target)
        {
            if (Target.GetAbilityEnabled(1) && !Source.GetAbilityEnabled(1))
            {
                return false;
            }

            return true;
        }

        // AoWAb.PAS:1947
        public void fcValidateMoveOutsideWall(TCombatObject Source, TCombatObject Target)
        {
            TMoveWallCA Action;
            if (Source.fcBehindWall() && Source.fcWallInBetween(Target.FPosition) && !Target.WallCombatFeatures().Contains(TWallCombatFeaturesElement.wcWallPassing))
            {
                Action = new TMoveWallCA(null);
                Action.F_MoveWallCA_0C = Source.FID;
                Action.F_MoveWallCA_0D = 0;
                Source.FCombat.ExecuteCombatAction(Action);
                Action.Release();
            }
        }
    }
}

namespace Aow.Game.Combat.Actions
{

    // (possession succeeded)
    public partial class TPossessCA : TSingleTargetCA
    {
        public new const int ClassID = 131765;

        public TPossessCA(TECustomNode owner) : base(owner)
        { }

        public bool FSuccessful;

        // AoWAb.PAS:2471
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwBool(ref FSuccessful, 20);
        }

        // AoWAb.PAS:2484
        public override void Execute(Aow.Game.Combat.TCombat Combat)
        {
            Aow.Game.Combat.TCombatUnit Source;
            Aow.Game.Combat.TCombatUnit Target;
            TAbstractUnit NewUnit;
            TAbstractUnit OldUnit;
            TPossessedAbilityData Data;
            int Experience;
            if (FSuccessful)
            {
                Source = (Aow.Game.Combat.TCombatUnit)Combat.FCombatData.FindID(FSourceID);
                Target = (Aow.Game.Combat.TCombatUnit)Combat.FCombatData.FindID(FTargetID);
                for (int I = 0; I <= 2; I++)
                {
                    ((TCommandAbility)AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(AoWEUnit.CommandAbilityIDs[I])).ResetCommandedUnits(Target);
                }

                for (int I = 0; I <= 2; I++)
                {
                    ((TCommandAbility)AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(AoWEUnit.CommandAbilityIDs[I])).Uncommand(Target);
                }

                NewUnit = Target.FUnit;
                NewUnit.AddRef();
                Target.SetUnit(null);
                Target.DestroyObject();
                OldUnit = Source.FUnit;
                OldUnit.AddRef();
                OldUnit.Killed();
                OldUnit.SetOwner(null);
                Source.SetUnit(NewUnit);
                if (OldUnit.FUnitStatus.Contains(TUnitStatusElement.usMoving))
                {
                    Source.FUnit.FUnitStatus = Source.FUnit.FUnitStatus + TSet<TUnitStatusElement>.Of(TUnitStatusElement.usMoving);
                }

                AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(107).Expand(Source.FUnit);
                if (OldUnit.GetAbilityEnabled(107))
                {
                    Data = (TPossessedAbilityData)OldUnit.GetAbilityData(107);
                    if (Data != null)
                    {
                        Experience = Data.FSourceExperience;
                    }
                    else
                    {
                        Experience = 0;
                    }
                }
                else
                {
                    Experience = OldUnit.GetExperience();
                }

                Data = (TPossessedAbilityData)Source.FUnit.GetAbilityData(107);
                if (Data != null)
                {
                    Data.FSourceExperience = Source.FUnit.GetUnitLevel() + Experience;
                }

                NewUnit.Release();
                OldUnit.Release();
            }
        }

        // AoWAb.PAS:2537
        public override bool Play(Aow.Game.Combat.TCombatViewer Viewer)
        {
            if (Viewer.FTime == 0)
            {
                AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(106).FSFXLibrary.Play(0);
            }

            if (Viewer.FDelay == Viewer.FTime)
            {
                Execute(Viewer.FCombat);
            }

            return Viewer.FDelay * 2 > Viewer.FTime;
        }

        // AoWAb.PAS:2529
        public override void ShowObject(Aow.Game.Combat.TCombatViewer Viewer, Aow.Game.Combat.TCombatObject Obj, int Frame, int Direction, int X, int Y, in TSurfaceDesc Surface)
        {
            base.ShowObject(Viewer, Obj, Frame, Direction, X, Y, Surface);
            if (Obj.FID == FSourceID || Obj.FID == FTargetID)
            {
                AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(106).FImageSequences.Show(0, X + 32, Y + 32, Viewer.FTime, Surface);
            }
        }

        // AoWAb.PAS:2477
        public void Initialize(byte SourceID, byte TargetID, bool Successful)
        {
            FSourceID = SourceID;
            FTargetID = TargetID;
            FSuccessful = Successful;
        }

        // intf_P3_02.inc:38

    }
}

