    public partial class TPossessAbility : TTouchAbility
    {
        // AoWAb.PAS:2627
        public TPossessAbility(TECustomNode owner) : base(owner)
        {
            FAbilityID = 106;
            FAbilityName = AoWEUnit.TranslateRStr(AoWEUnit.PossessRStr);
            FSelectionTypes = TSet<TAbilitySelectionType>.Of(TAbilitySelectionType.astUnit);
        }

        // AoWAb.PAS:2737
        public override bool fcExecuteCombatCommand(TCombatObject Source, TFastCombatCommand Command)
        {
            TCombatObject Target;
            TPossessCA Action;
            TStrikeCA Strike;
            Target = Command.FTarget;
            fcValidateMoveOutsideWall(Source, Target);
            Action = CreatePossessCA(Source, Target);
            Source.FCombat.ExecuteCombatAction(Action);
            if (!Action.FSuccessful)
            {
                Strike = AoWEUnit.CreateStrikeCA(Target, Source, true);
                if (Strike != null)
                {
                    Source.FCombat.ExecuteCombatAction(Strike);
                    Strike.Release();
                }
            }

            Action.Release();
            return true;
        }

        // AoWAb.PAS:2673
        public override int GetDamageValue(TAbstractUnit Attacker, TAbstractUnit Defender)
        {
            int Result;
            float Probability;
            if (CanTouchUnit(Attacker, Defender) && !Defender.GetImmunityTypes().Contains(TDamageType.dtNone))
            {
                Probability = TouchRoleProbability(Attacker, Defender);
                Result = Round((double)((double)Defender.GetHitPoints() * Probability) * 200);
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // AoWAb.PAS:2686
        public override void GetDamageValueEx(TAbstractUnit Attacker, TAbstractUnit Defender, TWallSituation WallSituation, ref TAbilityDamageValues DamageValues)
        {
            float Probability;
            if (WallSituation == TWallSituation.wsNone && CanTouchUnit(Attacker, Defender) && !Defender.GetImmunityTypes().Contains(TDamageType.dtNone))
            {
                Probability = TouchRoleProbability(Attacker, Defender);
                var hitPoints = Defender.GetHitPoints();
                DamageValues.SourceDamage = Round((double)((double)hitPoints * Probability) * 200);
                if (Attacker.GetAbilityEnabled(106))
                {
                    DamageValues.TargetDamage = 0;
                }
                else
                {
                    var attackerHitPoints = Attacker.GetHitPoints();
                    DamageValues.TargetDamage = Round((double)((double)attackerHitPoints * Probability) * 100);
                }

                // { Original leaves both cost fields untouched on success. }
                DamageValues.DamageTypes = TSet<TDamageType>.Of();
            }
            else
            {
                DamageValues.SourceDamage = 0;
                DamageValues.SourceCost = 0;
                DamageValues.TargetDamage = 0;
                DamageValues.TargetCost = 0;
                DamageValues.DamageTypes = TSet<TDamageType>.Of();
            }
        }

        // AoWAb.PAS:2664
        public override void GetOffensiveStrength(TAbilityOwner Owner, ref int Strength, ref TSet<TDamageType> Types)
        {
            if (Owner is TAbstractUnit unit)
            {
                Strength = Round((double)(unit.GetAttack() * 25) * 0.1);
                Types = TSet<TDamageType>.Of(TDamageType.dtNone);
            }
        }

        // AoWAb.PAS:2711
        public override void fcGetDamageValueEx(TCombatObject Attacker, TCombatObject Defender, TWallSituation WallSituation, ref TAbilityDamageValues DamageValues)
        {
            float Probability;
            if (WallSituation == TWallSituation.wsNone && CanTouch(Attacker, Defender))
            {
                Probability = CombatTouchRoleProbability((TCombatUnit)Attacker, Defender);
                var hitPoints = Defender.GetHitPoints();
                DamageValues.SourceDamage = Round((double)((double)hitPoints * Probability) * 200);
                var defenderHitPoints = Defender.GetHitPoints();
                DamageValues.SourceCost = defenderHitPoints * 2;
                if (Attacker.GetAbilityEnabled(106))
                {
                    DamageValues.TargetDamage = 0;
                }
                else
                {
                    var attackerHitPoints = Attacker.GetHitPoints();
                    DamageValues.TargetDamage = Round((double)((double)attackerHitPoints * Probability) * 100);
                }

                var damage = Defender.GetDamage();
                DamageValues.TargetCost = damage;
                DamageValues.DamageTypes = TSet<TDamageType>.Of();
            }
            else
            {
                DamageValues.SourceDamage = 0;
                DamageValues.SourceCost = 0;
                DamageValues.TargetDamage = 0;
                DamageValues.TargetCost = 0;
                DamageValues.DamageTypes = TSet<TDamageType>.Of();
            }
        }

        // AoWAb.PAS:2635
        public override sbyte GetTouchAttack(int Level) => 5;

        // AoWAb.PAS:2646
        public override bool CanTouch(TCombatObject Source, TCombatObject Target) => base.CanTouch(Source, Target) && (Source is TCombatUnit && Target is TCombatUnit && !Target.GetAbilityEnabled(106) && ((TCombatUnit)Target).FUnit.GetUnitType() != TUnitType.utMachine && !(((TCombatUnit)Target).FUnit is TLeader));

        // AoWAb.PAS:2656
        public override bool CanTouchUnit(TAbstractUnit Source, TAbstractUnit Target)
        {
            bool Result = base.CanTouchUnit(Source, Target);
            // { Original excludes humanoids here, but machines in CanTouch. }
            return Result && !Target.GetAbilityEnabled(106) && Target.GetUnitType() != TUnitType.utHumanoid && !(Target is TLeader);
        }

        // AoWAb.PAS:2640
        public TPossessCA CreatePossessCA(TCombatObject Source, TCombatObject Target)
        {
            TPossessCA Result = new TPossessCA(null);
            var combatTouchRole = CombatTouchRole((TCombatUnit)Source, Target);
            Result.Initialize(Source.FID, Target.FID, combatTouchRole);
            return Result;
        }
    }

