        public override bool Expand(TAbilityOwner Owner)
        {
            TPossessedAbilityData Data;
            bool Result = false;
            Data = (TPossessedAbilityData)Owner.GetAbilityData(FAbilityID);
            if (Data == null)
            {
                Data = new TPossessedAbilityData(null);
                SetAb(Owner, FAbilityID, 1);
                Owner.AddAbilityData(Data);
                Result = true;
