            Data = (TPossessedAbilityData)owner.GetAbilityData(FAbilityID);
            if (Data != null)
            {
                SetAb(owner, FAbilityID, 0);
                owner.RemoveAbilityData(Data);
            }
            else
            {
                SetAb(owner, FAbilityID, 0);
            }

