        // AoWAb.PAS:2571
        public override void CombatObjectDestroyed(TCombatObject CombatObject)
        {
            TUnit NewUnit;
            TPossessedAbilityData Data;
            var combatUnit = (TCombatUnit)CombatObject;
            combatUnit.SetStatus(combatUnit.FStatus - TSet<TCombatObjectStatusElement>.Of(TCombatObjectStatusElement.csDestroyed));
            NewUnit = new TUnit(null);
            NewUnit.SetUnitResource(AoWEUnit.AoWHSSet.FUnitResources.GetUnitResource(152));
            Data = (TPossessedAbilityData)combatUnit.FUnit.GetAbilityData(107);
            if (Data != null)
            {
                NewUnit.SetExperience(Data.FSourceExperience);
            }

            if (combatUnit.FUnit.FUnitStatus.Contains(TUnitStatusElement.usMoving))
            {
                NewUnit.FUnitStatus = TSet<TUnitStatusElement>.Of(TUnitStatusElement.usMoving) + NewUnit.FUnitStatus;
            }

            combatUnit.FUnit.Killed();
            combatUnit.SetUnit(NewUnit);
            NewUnit.Release();
        }

