        public override bool Expand(TAbilityOwner Owner)
        {
            TMultiLevelAbilityData Data;
            bool Result = false;
            Data = (TMultiLevelAbilityData)Owner.GetAbilityData(FAbilityID);
            if (Data == null)
            {
                Data = new TMultiLevelAbilityData(null);
                Data.FLevelAbilityID = (ushort)FAbilityID;
                Data.FLevel = 1;
                SetAb(Owner, FAbilityID, 1);
                Owner.AddAbilityData(Data);
                Result = true;
            }
            else
            {
                if (Data.FLevel != 4)
                {
                    Result = true;
                    Data.FLevel = (byte)(Data.FLevel + 1);
                }
            }

            return Result;
        }

        // AoWAb.PAS:3238
        public override bool Remove(TAbilityOwner owner)
        {
            TMultiLevelAbilityData Data;
            bool Result = true;
            Data = (TMultiLevelAbilityData)owner.GetAbilityData(FAbilityID);
            if (Data != null)
            {
                if (Data.FLevel == 1)
                {
                    SetAb(owner, FAbilityID, 0);
                    owner.RemoveAbilityData(Data);
                }
                else
                {
                    Data.FLevel = (byte)(Data.FLevel - 1);
                }
            }
            else
            {
                SetAb(owner, FAbilityID, 0);
                Result = false;
            }

            return Result;
        }

        // AoWAb.PAS:3293
        public override int GetDamageValue(TAbstractUnit Attacker, TAbstractUnit Defender)
        {
            int Result;
            float Probability;
            if (CanTouchUnit(Attacker, Defender) && !Defender.GetImmunityTypes().Contains(TDamageType.dtNone))
            {
                Probability = TouchRoleProbability(Attacker, Defender);
                Result = Round((double)((double)Defender.GetHitPoints() * Probability) * 100);
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // AoWAb.PAS:3305
        public override void GetDamageValueEx(TAbstractUnit Attacker, TAbstractUnit Defender, TWallSituation WallSituation, ref TAbilityDamageValues DamageValues)
        {
            float Probability;
            int HitPoints;
            if (WallSituation == TWallSituation.wsNone && CanTouchUnit(Attacker, Defender) && !Defender.GetImmunityTypes().Contains(TDamageType.dtNone))
            {
                Probability = TouchRoleProbability(Attacker, Defender);
                HitPoints = Defender.GetHitPoints();
                DamageValues.SourceCost = HitPoints;
                DamageValues.SourceDamage = Round((double)((double)HitPoints * Probability) * 100);
                var p4UnitStrikeDV = AoWEUnit.P4UnitStrikeDV(Defender, Attacker);
                DamageValues.TargetDamage = Round((double)p4UnitStrikeDV * ((double)1 - Probability));
                var protectionTypes = Attacker.GetProtectionTypes();
                var damageTypes = ((TStrikeAbility)AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(21)).GetDamageTypes(Defender);
                var immunityTypes = Attacker.GetImmunityTypes();
                var statisticsToMaxDamage = AoWEUnit.StatisticsToMaxDamage(Defender.GetDamage(), damageTypes, immunityTypes, protectionTypes);
                DamageValues.TargetCost = statisticsToMaxDamage;
                DamageValues.DamageTypes = TSet<TDamageType>.Of(TDamageType.dtHoly);
            }
            else
            {
                DamageValues.SourceDamage = 0;
                DamageValues.SourceCost = 0;
                DamageValues.TargetDamage = 0;
                DamageValues.TargetCost = 0;
                DamageValues.DamageTypes = TSet<TDamageType>.Of();
            }
        }

        // AoWAb.PAS:3168
