        // AoWAb.PAS:3137
        public override bool CanTouch(TCombatObject Source, TCombatObject Target)
        {
            bool Result = base.CanTouch(Source, Target);
            if (Result)
            {
                bool condition = Source is TCombatUnit && Target is TCombatUnit;
                if (condition)
                {
                    var unitType = ((TCombatUnit)Target).FUnit.GetUnitType();
                    condition = TSet<TUnitType>.Of(TUnitType.utHumanoid, TUnitType.utCreature).Contains(unitType);
                }

                Result = condition && ((ushort)((TCombatUnit)Target).FUnit.GetRace() == 11 || ((TCombatUnit)Target).FUnit.GetAbilityEnabled(129));
            }

            return Result;
        }

        // AoWAb.PAS:3130
        public override bool CanTouchUnit(TAbstractUnit Source, TAbstractUnit Target)
        {
            bool Result = base.CanTouchUnit(Source, Target);
            if (Result)
            {
                var unitType = Target.GetUnitType();
                Result = TSet<TUnitType>.Of(TUnitType.utHumanoid, TUnitType.utCreature).Contains(unitType) && ((ushort)Target.GetRace() == 11 || Target.GetAbilityEnabled(129));
            }

            return Result;
        }

