        // AoWAb.PAS:3356
        public TTurnUndeadCA CreateTurnUndeadCA(TCombatObject Source, TCombatObject Target)
        {
            TTurnUndeadCA Action;
            int Level;
            // { These eliminated copies preserve the original saved registers. }
            Action = new TTurnUndeadCA(null);
            if (AoWEUnit.HitRole(Source.GetAttack() - Target.GetDefense()))
            {
                Level = Source.GetAbilityLevel(FAbilityID);
                var turnUndeadDamage = GetTurnUndeadDamage(Level);
                Action.GenerateEx(Source, Target, GetTouchAttack(Level), turnUndeadDamage, TSet<TDamageType>.Of(TDamageType.dtHoly), 1);
            }
            else
            {
                Action.FSourceID = Source.FID;
                Action.FTargetID = Target.FID;
            }

            return Action;
        }

