    public partial class TRoundAttackAbility : TTouchAbility
    {
        // AoWAb.PAS:2262
        public TRoundAttackAbility(TECustomNode owner) : base(owner)
        {
            FAbilityID = 114;
            FAbilityType = TAbilityType.atCombat;
            FAbilityName = AoWEUnit.TranslateRStr(AoWEUnit.RoundAttackRStr);
        }

        // AoWAb.PAS:2404
        public override bool fcExecuteCombatCommand(TCombatObject Source, TFastCombatCommand Command)
        {
            TSet<TDamageType> DamageTypes;
            int Count;
            TStrikeCA Action;
            TCombat Combat;
            TList Targets;
            TCombatObject Target;
            TCombatObject Other;
            TMoveWallCA MoveAction;
            Combat = Source.FCombat;
            Targets = new TList();
            DamageTypes = AoWEUnit.MeleeDamageTypes(Source);
            Target = Command.FTarget;
            fcValidateMoveOutsideWall(Source, Target);
            if (Source is TFastCombatUnit)
            {
                ((TFastCombatUnit)Source).FRoundDistance = 0;
                if (Source.fcBehindWall() && Source.fcWallInBetween(Target.FPosition) && !Target.WallCombatFeatures().Contains(TWallCombatFeaturesElement.wcWallPassing))
                {
                    MoveAction = new TMoveWallCA(null);
                    MoveAction.F_MoveWallCA_0C = Source.FID;
                    MoveAction.F_MoveWallCA_0D = 0;
                    Source.FCombat.ExecuteCombatAction(MoveAction);
                    MoveAction.Release();
                }
            }

            Action = AoWEUnit.CreateStrikeCA(Source, Target, false);
            if (Action != null)
            {
                Combat.ExecuteCombatAction(Action);
                Action.Release();
            }

            for (int I = Combat.FSides[(int)Target.GetSide()].GetCount() - 1; I >= 0; I--)
            {
                var side = Target.GetSide();
                Other = Combat.FSides[(int)side].GetObjects(I);
                if (Other != Target && Other.GetEnabled() && (int)(((uint)Other.FPosition) >> 4) == (int)(((uint)Target.FPosition) >> 4) && (!Other.GetAbilityEnabled(1) || Source.GetAbilityEnabled(1)) && !Source.fcWallInBetween(Other.FPosition) && Other.fcRoundDistance() <= Combat.GetRound() - 1 && DamageTypes - Other.GetImmunityTypes() != TSet<TDamageType>.Of())
                {
                    Targets.Add(Other);
                }
            }

            Count = AoWEUnit.AoWHSMap.Random(2) + 1;
            while (Count != 0 && Targets.Count != 0)
            {
                Other = (TCombatObject)Targets[AoWEUnit.AoWHSMap.Random(Targets.Count)];
                Action = AoWEUnit.CreateStrikeCA(Source, Other, false);
                if (Action != null)
                {
                    Combat.ExecuteCombatAction(Action);
                    Action.Release();
                }

                Targets.Remove(Other);
                Count -= 1;
            }

            Targets?.Dispose();
            return true;
        }

        // AoWAb.PAS:2286
        public override int GetDamageValue(TAbstractUnit Attacker, TAbstractUnit Defender)
        {
            int Result;
            if (CanTouchUnit(Attacker, Defender))
            {
                Result = AoWEUnit.P4UnitStrikeDV(Attacker, Defender) * 2;
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // AoWAb.PAS:2318
        public override void GetDamageValueEx(TAbstractUnit Attacker, TAbstractUnit Defender, TWallSituation WallSituation, ref TAbilityDamageValues DamageValues)
        {
            if (WallSituation == TWallSituation.wsNone && CanTouchUnit(Attacker, Defender))
            {
                var p4UnitStrikeDV = AoWEUnit.P4UnitStrikeDV(Attacker, Defender);
                DamageValues.SourceDamage = p4UnitStrikeDV * 2;
                DamageValues.SourceCost = 0;
                var aoWEP4UnitStrikeDV = AoWEUnit.P4UnitStrikeDV(Attacker, Defender);
                DamageValues.TargetDamage = aoWEP4UnitStrikeDV;
                DamageValues.TargetCost = 0;
                var damageTypes = ((TStrikeAbility)AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(21)).GetDamageTypes(Attacker);
                var immunityTypes = Defender.GetImmunityTypes();
                DamageValues.DamageTypes = damageTypes - immunityTypes;
            }
            else
            {
                DamageValues.SourceDamage = 0;
                DamageValues.SourceCost = 0;
                DamageValues.TargetDamage = 0;
                DamageValues.TargetCost = 0;
                DamageValues.DamageTypes = TSet<TDamageType>.Of();
            }
        }

        // AoWAb.PAS:2270
        public override void GetOffensiveStrength(TAbilityOwner Owner, ref int Strength, ref TSet<TDamageType> Types)
        {
            int Attack;
            int Damage;
            if (Owner is TAbstractUnit unit)
            {
                Attack = unit.GetAttack();
                Damage = unit.GetDamage();

                Strength = AoWEUnit.P3LimitedDamage(Attack, Damage, 1) * 3;
                Types = ((TStrikeAbility)AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(21)).GetDamageTypes(Owner);
            }
        }

        // AoWAb.PAS:2338
        public override void fcGetDamageValueEx(TCombatObject Attacker, TCombatObject Defender, TWallSituation WallSituation, ref TAbilityDamageValues DamageValues)
        {
            int Count;
            TSet<TDamageType> DamageTypes;
            TCombat Combat;
            TCombatObject Target;
            if (WallSituation == TWallSituation.wsNone && CanTouch(Attacker, Defender))
            {
                DamageTypes = AoWEUnit.MeleeDamageTypes(Attacker);
                var strikeDV = AoWEUnit.StrikeDV(Attacker, Defender);
                DamageValues.SourceDamage = strikeDV;
                var damage = Attacker.GetDamage();
                DamageValues.SourceCost = damage;
                var aoWEStrikeDV = AoWEUnit.StrikeDV(Defender, Attacker);
                DamageValues.TargetDamage = aoWEStrikeDV;
                var defenderDamage = Defender.GetDamage();
                DamageValues.TargetCost = defenderDamage;
                var immunityTypes = Defender.GetImmunityTypes();
                DamageValues.DamageTypes = DamageTypes - immunityTypes;
                Combat = Attacker.FCombat;
                Count = 0;
                for (int I = Combat.FSides[(int)Defender.GetSide()].GetCount() - 1; I >= 0; I--)
                {
                    // { Preserve the original saved registers. }
                    var side = Defender.GetSide();
                    Target = Combat.FSides[(int)side].GetObjects(I);
                    // { Original tests Defender's flying ability here, rather than Target's. }
                    if (Target != Defender && Target.GetEnabled() && (int)(((uint)Target.FPosition) >> 4) == (int)(((uint)Defender.FPosition) >> 4) && (!Defender.GetAbilityEnabled(1) || Attacker.GetAbilityEnabled(1)) && !Attacker.fcWallInBetween(Target.FPosition) && Target.fcRoundDistance() <= Combat.GetRoundDistance() && DamageTypes - Target.GetImmunityTypes() != TSet<TDamageType>.Of())
                    {
                        Count += 1;
                    }
                }

                if (Count != 0)
                {
                    if (Count > 3)
                    {
                        Count = 3;
                    }

                    DamageValues.SourceDamage += Round((double)(DamageValues.SourceDamage * Count) / 3);
                }
            }
            else
            {
                DamageValues.SourceDamage = 0;
                DamageValues.SourceCost = 0;
                DamageValues.TargetDamage = 0;
                DamageValues.TargetCost = 0;
                DamageValues.DamageTypes = TSet<TDamageType>.Of();
            }
        }

        // AoWAb.PAS:2383
        public override void tcGetDamageValueEx(TCombatObject Attacker, TCombatObject Defender, ref TAbilityDamageValues DamageValues)
        {
            if (CanTouch(Attacker, Defender))
            {
                var strikeDV = AoWEUnit.StrikeDV(Attacker, Defender);
                DamageValues.SourceDamage = strikeDV * 2;
                var damage = Attacker.GetDamage();
                DamageValues.SourceCost = damage * 2;
                // { Original repeats the forward strike instead of reversing the arguments. }
                var aoWEStrikeDV = AoWEUnit.StrikeDV(Attacker, Defender);
                DamageValues.TargetDamage = aoWEStrikeDV;
                var defenderDamage = Defender.GetDamage();
                DamageValues.TargetCost = defenderDamage;
                var meleeDamageTypes = AoWEUnit.MeleeDamageTypes(Attacker);
                var immunityTypes = Defender.GetImmunityTypes();
                DamageValues.DamageTypes = meleeDamageTypes - immunityTypes;
            }
            else
            {
                DamageValues.SourceDamage = 0;
                DamageValues.SourceCost = 0;
                DamageValues.TargetDamage = 0;
                DamageValues.TargetCost = 0;
                DamageValues.DamageTypes = TSet<TDamageType>.Of();
            }
        }

        // AoWAb.PAS:2294
        public override void GetCombatInfo(TAbilityOwner Owner, ref TAbilityCombatInfo Info)
        {
            TAbstractUnit Source;
            if (Owner is TAbstractUnit)
            {
                Source = (TAbstractUnit)Owner;
                var attack = Source.GetAttack();
                Info.Attack = attack;
                var damage = Source.GetDamage();
                Info.Damage = damage;
                var damageTypes = ((TStrikeAbility)AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(21)).GetDamageTypes(Source);
                Info.DamageTypes = damageTypes;
                Info.RepeatCount = 2;
                Info.TargetTypes = TSet<TCombatTargetTypeElement>.Of(TCombatTargetTypeElement.cttEnemy);
                return;
            }
            else
            {
                Info.Attack = -1;
                Info.Damage = -1;
                Info.DamageTypes = TSet<TDamageType>.Of(TDamageType.dtPhysical);
                Info.RepeatCount = 2;
                Info.TargetTypes = TSet<TCombatTargetTypeElement>.Of(TCombatTargetTypeElement.cttEnemy);
            }
        }
    }

