namespace Aow.Game.Combat.Actions
{

    // (ability ID, success)
    public partial class TCommandCA : TSingleTargetCA
    {
        public new const int ClassID = 131763;

        public TCommandCA(TECustomNode owner) : base(owner)
        { }

        public int FAbilityID;
        public bool FSuccessful;

        // AoWAb.PAS:5044
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwInteger(ref FAbilityID, 20);
            Stream.rwBool(ref FSuccessful, 21);
        }

        // AoWAb.PAS:5063
        public override void Execute(Aow.Game.Combat.TCombat Combat)
        {
            Aow.Game.Combat.TCombatUnit Source;
            Aow.Game.Combat.TCombatUnit Target;
            if (FSuccessful)
            {
                Source = (Aow.Game.Combat.TCombatUnit)Combat.FCombatData.FindID(FSourceID);
                Target = (Aow.Game.Combat.TCombatUnit)Combat.FCombatData.FindID(FTargetID);
                Source.SetExperience(Source.GetExperience() + Target.GetLevel());
                for (int I = 0; I <= 2; I++)
                {
                    ((TCommandAbility)AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(AoWEUnit.CommandAbilityIDs[I])).ResetCommandedUnits(Target);
                }

                for (int I = 0; I <= 2; I++)
                {
                    ((TCommandAbility)AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(AoWEUnit.CommandAbilityIDs[I])).Uncommand(Target);
                }

                if (Source.GetSide() != Target.GetSide())
                {
                    ((TCommandAbility)AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(FAbilityID)).Command(Source, Target);
                }
            }
        }

        // AoWAb.PAS:5081
        public override bool Play(Aow.Game.Combat.TCombatViewer Viewer)
        {
            if (Viewer.FTime == 0)
            {
                AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(FAbilityID).FSFXLibrary.Play(0);
            }

            if (Viewer.FDelay == Viewer.FTime)
            {
                Execute(Viewer.FCombat);
            }

            return Viewer.FDelay * 2 > Viewer.FTime;
        }

        // AoWAb.PAS:5056
        public override void ShowObject(Aow.Game.Combat.TCombatViewer Viewer, Aow.Game.Combat.TCombatObject Obj, int Frame, int Direction, int X, int Y, in TSurfaceDesc Surface)
        {
