            if (Obj.FID == FSourceID)
            {
                AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(FAbilityID).FImageSequences.Show(0, X + 32, Y + 32, Viewer.FTime, Surface);
            }
        }

