        }

        public int FCommandedAbilityID;

        // AoWAb.PAS:5190
        public override TAbilityType GetAbilityType() => TAbilityType.atCombat;

        // AoWAb.PAS:5288
        public override void fcPrefetchCombatCommands(TFastCombatCommandList Commands)
        {
            int Distance;
            TCombatObject Target;
            TAbilityDamageValues Values = default;
            TFastCombatCommand Command;
            Distance = Commands.FCombat.GetRoundDistance();
            if (Commands.FSource.GetMoves() >= 32)
            {
                Distance += 2;
            }

            for (int I = 0, last = Commands.FTargetSide.GetCount() - 1; I <= last; I++)
            {
                Target = Commands.FTargetSide.GetObjects(I);
                if (Target.GetEnabled() && Target.fcRoundDistance() <= Distance && CanTouch(Commands.FSource, Target))
                {
                    fcGetDamageValueEx(Commands.FSource, Target, TWallSituation.wsNone, ref Values);
                    if (Values.SourceDamage != 0)
                    {
                        Command = new TFastCombatCommand(FAbilityID);
                        Command.FTarget = Commands.FTargetSide.GetObjects(I);
                        Command.FExpectedDV = AoWEUnit.DVtoDEV(Values.SourceDamage, Values.TargetDamage, Commands.FSource, Target);
                        Command.FMoveCost = 0;
                        Commands.Add(Command);
                    }
                }
            }
        }

        // AoWAb.PAS:5266
        public override bool fcExecuteCombatCommand(TCombatObject Source, TFastCombatCommand Command)
        {
            TCombatObject Target;
            TCommandCA Action;
            TStrikeCA Strike;
            Target = Command.FTarget;
            fcValidateMoveOutsideWall(Source, Target);
            Action = CreateCommandCA((TCombatUnit)Source, (TCombatUnit)Target);
            Source.FCombat.ExecuteCombatAction(Action);
            if (!Action.FSuccessful)
            {
                Strike = AoWEUnit.CreateStrikeCA(Target, Source, true);
                if (Strike != null)
                {
                    Source.FCombat.ExecuteCombatAction(Strike);
                    Strike.Release();
                }
            }

            Action.Release();
            return true;
        }

        // AoWAb.PAS:5097
        public override bool Remove(TAbilityOwner owner)
        {
            bool Result = base.Remove(owner);
            if (Result)
            {
                owner.RemoveAbilityDataID(FAbilityID);
            }

            return Result;
        }

        // AoWAb.PAS:5194
        public override int GetDamageValue(TAbstractUnit Attacker, TAbstractUnit Defender)
        {
            int Result;
            float Probability;
            if (CanTouchUnit(Attacker, Defender))
            {
                Probability = TouchRoleProbability(Attacker, Defender);
                Result = Round((double)(Defender.GetHitPoints() * 200) * Probability);
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // AoWAb.PAS:5213
        public override void GetDamageValueEx(TAbstractUnit Attacker, TAbstractUnit Defender, TWallSituation WallSituation, ref TAbilityDamageValues DamageValues)
        {
            float Probability;
            if (WallSituation == TWallSituation.wsNone && (!Defender.GetAbilityEnabled(1) || Attacker.GetAbilityEnabled(1)) && Defender.GetUnitType() != TUnitType.utMachine)
            {
                Probability = TouchRoleProbability(Attacker, Defender);
                var hitPoints = Defender.GetHitPoints();
                DamageValues.SourceDamage = Round((double)(hitPoints * 200) * Probability);
                var defenderHitPoints = Defender.GetHitPoints();
                DamageValues.SourceCost = defenderHitPoints * 2;
                var p4UnitStrikeDV = AoWEUnit.P4UnitStrikeDV(Defender, Attacker);
                DamageValues.TargetDamage = Round((double)p4UnitStrikeDV * ((double)1 - Probability));
                var damage = Defender.GetDamage();
                DamageValues.TargetCost = damage;
            }
            else
            {
                // { Original leaves DamageTypes unchanged on this path. }
                DamageValues.SourceDamage = 0;
                DamageValues.SourceCost = 0;
                DamageValues.TargetDamage = 0;
                DamageValues.TargetCost = 0;
                DamageValues.DamageTypes = TSet<TDamageType>.Of();
            }
        }

        // AoWAb.PAS:5205
        public override void GetOffensiveStrength(TAbilityOwner Owner, ref int Strength, ref TSet<TDamageType> Types)
        {
            if (Owner is TAbstractUnit unit)
            {
                Strength = Round((double)(GetTouchAttack(GetLevel(unit)) * (unit.GetAttack() * 5)) * 0.1);
                Types = TSet<TDamageType>.Of(TDamageType.dtNone);
            }
        }

        // AoWAb.PAS:5237
        public override void fcGetDamageValueEx(TCombatObject Attacker, TCombatObject Defender, TWallSituation WallSituation, ref TAbilityDamageValues DamageValues)
        {
            float Probability;
            if (CanTouch(Attacker, Defender) && !(((TCombatUnit)Defender).FUnit is TLeader))
            {
                Probability = CombatTouchRoleProbability((TCombatUnit)Attacker, Defender);
                var hitPoints = Defender.GetHitPoints();
                DamageValues.SourceDamage = Round((double)(hitPoints * 200) * Probability);
                var defenderHitPoints = Defender.GetHitPoints();
                DamageValues.SourceCost = defenderHitPoints * 2;
                var strikeDV = AoWEUnit.StrikeDV(Defender, Attacker);
                DamageValues.TargetDamage = Round((double)strikeDV * ((double)1 - Probability));
                var damage = Defender.GetDamage();
                DamageValues.TargetCost = damage;
            }
            else
            {
                // { Original leaves DamageTypes unchanged on this path. }
                DamageValues.SourceDamage = 0;
                DamageValues.SourceCost = 0;
                DamageValues.TargetDamage = 0;
                DamageValues.TargetCost = 0;
                DamageValues.DamageTypes = TSet<TDamageType>.Of();
            }
        }

