        }

        // AoWAb.PAS:5176
        public override bool CanTouch(TCombatObject Source, TCombatObject Target) => base.CanTouch(Source, Target) && (Source is TCombatUnit && Target is TCombatUnit && ((TCombatUnit)Target).FUnit.GetUnitType() != TUnitType.utMachine && !Target.GetAbilityEnabled(107));

        // AoWAb.PAS:5184
        public override bool CanTouchUnit(TAbstractUnit Source, TAbstractUnit Target)
        {
            bool Result;
            if (base.CanTouchUnit(Source, Target))
            {
                Result = Target.GetUnitType() != TUnitType.utMachine;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // AoWAb.PAS:5110
        public virtual void Command(TCombatUnit Source, TCombatUnit Target)
        {
            TCommandedAbilityData TargetData;
            TCommandAbilityData SourceData;
            // { The returned class is consumed by its constructor. }
            Uncommand(Target);
            // { Inline the returned class receiver. }
            TargetData = (TCommandedAbilityData)AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(FCommandedAbilityID).AbilityDataClass().Create(null);
            TargetData.FAbilityID = FCommandedAbilityID;
            TargetData.FCommandAbilityID = FAbilityID;
            TargetData.FSourceID = Source.FID;
            TargetData.FOriginalCombatPlayer = (byte)Target.FCombatPlayer;
            SetAb(Target.FUnit, FCommandedAbilityID, 1);
            Target.FUnit.AddAbilityData(TargetData);
            Target.SetCombatPlayer((byte)Source.FCombatPlayer);
            SourceData = (TCommandAbilityData)Source.FUnit.GetAbilityData(FAbilityID);
            if (SourceData == null)
            {
                SourceData = new TCommandAbilityData(null);
                SourceData.FAbilityID = FAbilityID;
                Source.FUnit.AddAbilityData(SourceData);
            }

            SourceData.FCommandedUnits.Add(Target.FID);
        }

        // AoWAb.PAS:5259
        public virtual TCommandCA CreateCommandCA(TCombatUnit Source, TCombatUnit Target)
        {
            TCommandCA Result = new TCommandCA(null);
            bool condition = !(Target.FUnit is TLeader) && CombatTouchRole(Source, Target);
            Result.Initialize(Source.FID, Target.FID, condition);
            Result.FAbilityID = FAbilityID;
            return Result;
        }

        // AoWAb.PAS:5157
        public virtual void ResetCommandedUnits(TCombatUnit Source)
        {
            TAbstractUnit UnitOwner;
            TCommandAbilityData Data;
            TCombatUnit Target;
            UnitOwner = Source.FUnit;
            if (UnitOwner.GetAbilityEnabled(FAbilityID))
            {
                Data = (TCommandAbilityData)Source.FUnit.GetAbilityData(FAbilityID);
                if (Data != null)
                {
                    for (int I = Data.FCommandedUnits.Count - 1; I >= 0; I--)
                    {
                        Target = (TCombatUnit)Source.FCombat.FCombatData.FindID(Data.FCommandedUnits.List[I]);
                        if (Target != null)
                        {
                            Uncommand(Target);
                        }
                    }
                }
            }
        }

        // AoWAb.PAS:5135
        public virtual void Uncommand(TCombatUnit Target)
        {
            TAbstractUnit UnitOwner;
            TCommandedAbilityData Data;
            TCombatUnit Source;
            TCommandAbilityData SourceData;
            UnitOwner = Target.FUnit;
            if (UnitOwner.GetAbilityEnabled(FCommandedAbilityID))
            {
                Data = (TCommandedAbilityData)UnitOwner.GetAbilityData(FCommandedAbilityID);
                // { Original reads Data before checking it for nil. }
                Source = (TCombatUnit)Target.FCombat.FCombatData.FindID(Data.FSourceID);
                if (Data != null)
                {
                    Target.SetCombatPlayer(Data.FOriginalCombatPlayer);
                }

                AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(FCommandedAbilityID).Remove(Target.FUnit);
                if (Source != null)
                {
                    SourceData = (TCommandAbilityData)Source.FUnit.GetAbilityData(FAbilityID);
                    if (SourceData != null)
                    {
                        SourceData.FCommandedUnits.Remove(Target.FID);
                    }
                }
            }
        }

