        { }

        // AoWAb.PAS:3894
        public override bool CanSelectUnit(TAbstractUnit AUnit)
        {
            var unitType = AUnit.GetUnitType();
            if (!(TSet<TUnitType>.Of(TUnitType.utHumanoid, TUnitType.utCreature).Contains(unitType) && AUnit.GetHits() != AUnit.GetHitPoints()))
            {
                return false;
            }

            return true;
        }

        // AoWAb.PAS:3904
        public override bool Select()
        {
            bool Result;
            TAbstractUnit Source;
            TAbstractUnit Target;
            string Error = "";
            int I;
            THealingTE Event;
            Source = AoWEUnit.AoWHSMap.FUnitControl.FindUnit(FSourceUnitID);
            if (CanSelect(ref Error) && !AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Source.FPlayer).GetBusy())
            {
                I = 0;
                Target = null;
                while (Target == null && I != FUnits.GetCount())
                {
                    if ((FSelection & (1 << I)) != 0)
                    {
                        Target = FUnits.GetUnit(I);
                    }

                    I += 1;
                }

                if (Target != null)
                {
                    Event = new THealingTE(null);
                    Event.FSourceID = Source.FUnitID;
                    Event.FSourcePlayer = (byte)Source.FPlayer;
                    Event.FTargetID = Target.FUnitID;
                    Event.FTargetPlayer = (byte)Target.FPlayer;
                    AoWEUnit.AoWHSMap.FTokenManager.GetTokenControl(Source.FPlayer).AddEvent(Event);
                    Event.Release();
                    Result = true;
                }
                else
                {
                    Result = false;
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // intf_P1_08.inc:65

    }
