namespace Aow.Game.Combat.Actions
{

    // (dispelled enchantment IDs)
    public partial class TDispelMagicCA : TSingleTargetCA
    {

        // AoWAb.PAS:3936
        public TDispelMagicCA(TECustomNode owner) : base(owner)
        {
            FEnchantmentIDs = new TIntegerList();
        }

        public TIntegerList FEnchantmentIDs;

        // AoWAb.PAS:3941
        public override void Dispose()
        {
            FEnchantmentIDs?.Dispose();
            base.Dispose();
        }

        // AoWAb.PAS:3946
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwStreamProc(50, FEnchantmentIDs.LoadFromStream, FEnchantmentIDs.SaveToStream);
        }

        // AoWAb.PAS:3951
        public override void Execute(Aow.Game.Combat.TCombat Combat)
        {
            TEnchantmentList Enchantments;
            Aow.Game.Combat.TCombatObject Source;
            Aow.Game.Combat.TCombatObject Target;
            TEnchantment Enchantment;
            bool WasSummoned;
            Source = Combat.FCombatData.FindID(FSourceID);
            Target = Combat.FCombatData.FindID(FTargetID);
            if (Source is Aow.Game.Combat.TCombatUnit && Target is Aow.Game.Combat.TCombatUnit)
            {
                Enchantments = new TEnchantmentList(null);
                var combatUnit = (Aow.Game.Combat.TCombatUnit)Target;
                combatUnit.FUnit.ListEnchantments(Enchantments);
                WasSummoned = combatUnit.FUnit.GetAbilityEnabled(155);

                for (int I = FEnchantmentIDs.Count - 1; I >= 0; I--)
                {
                    Enchantment = Enchantments.FindID(FEnchantmentIDs[I]);
                    if (Enchantment != null)
                    {
                        Enchantment.Dispel();
                    }
                }

                if (WasSummoned && !((Aow.Game.Combat.TCombatUnit)Target).FUnit.GetAbilityEnabled(155))
                {
                    Source.DoDamage(Target, Target.GetHitPoints());
                }

                Enchantments?.Dispose();
            }
        }

        // AoWAb.PAS:3986
        public override bool Play(Aow.Game.Combat.TCombatViewer Viewer)
        {
            if (Viewer.FTime == 0)
            {
                AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(60).FSFXLibrary.Play(0);
            }

            if (Viewer.FDelay == Viewer.FTime)
            {
                Execute(Viewer.FCombat);
            }

            return Viewer.FDelay * 2 > Viewer.FTime;
        }

        // AoWAb.PAS:3979
        public override void ShowObject(Aow.Game.Combat.TCombatViewer Viewer, Aow.Game.Combat.TCombatObject Obj, int Frame, int Direction, int X, int Y, in TSurfaceDesc Surface)
        {
            base.ShowObject(Viewer, Obj, Frame, Direction, X, Y, Surface);
            if (Obj.FID == FTargetID)
            {
                AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(60).FImageSequences.Show(0, X + 32, Y + 32, Viewer.FTime, Surface);
            }
        }

        // AoWAb.PAS:3994
        public void Generate(Aow.Game.Combat.TCombatObject Source, Aow.Game.Combat.TCombatObject Target, int DispelMana)
        {
            TEnchantmentList Enchantments;
            int Chance;
            FSourceID = Source.FID;
            FTargetID = Target.FID;
            if (Source is Aow.Game.Combat.TCombatUnit && Target is Aow.Game.Combat.TCombatUnit)
            {
                Enchantments = new TEnchantmentList(null);
                ((Aow.Game.Combat.TCombatUnit)Target).FUnit.ListEnchantments(Enchantments);
                for (int I = Enchantments.GetCount() - 1; I >= 0; I--)
                {
                    Chance = Enchantments.GetEnchantments(I).DispelChance(DispelMana);
                    if (Chance > AoWEUnit.AoWHSMap.Random(100))
                    {
                        var enchantments = Enchantments.GetEnchantments(I);
                        FEnchantmentIDs.Add(enchantments.FEnchantmentID);
                    }
                }

                Enchantments?.Dispose();
            }
        }

        // intf_P4_02.inc:660

    }

