namespace Aow.Game.Commands
{

    // (source unit ID/player, target unit ID/player)
    public partial class TDispelMagicAbilityTE : TTokenEvent
    {
        public TDispelMagicAbilityTE(TECustomNode owner) : base(owner)
        { }

        public new const int ClassID = 131827;

        public int FSourceID;
        public byte FSourcePlayer;
        public int FTargetID;
        public byte FTargetPlayer;

        // AoWAb.PAS:4337
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwInteger(ref FSourceID, 25);
            Stream.rwByte(ref FSourcePlayer, 26);
            Stream.rwInteger(ref FTargetID, 27);
            Stream.rwByte(ref FTargetPlayer, 28);
        }

        // AoWAb.PAS:4345
        public override TExecuteResult Execute(TTokenExecuter TE)
        {
            TExecuteResult Result;
            int Count;
            int Mana;
            TDispelMagicAbility Ability;
            TEnchantmentList Enchantments;
            TAbstractUnit Source;
            TAbstractUnit Target;
            sbyte X = default;
            sbyte Y = default;
            sbyte L = default;
            bool Success;
            int Chance;
            TImageSequenceAnimation Anim;
            base.Execute(TE);
            Enchantments = new TEnchantmentList(null);
            Source = AoWEUnit.AoWHSMap.FUnitControl.FindUnit(FSourceID);
            Target = AoWEUnit.AoWHSMap.FUnitControl.FindUnit(FTargetID);
            Ability = (TDispelMagicAbility)AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(60);
            Success = Source != null && (byte)Source.FPlayer == FSourcePlayer && Target != null && (byte)Target.FPlayer == FTargetPlayer;
            Success = Success && Ability.GetEnabled(Source);
            if (Success)
            {
                Target.ListEnchantments(Enchantments);
                Success = Enchantments.GetCount() > 0;
            }

            if (Success)
            {
                Count = 0;
                Mana = ((TDispelMagicAbility)AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(60)).GetDispelMana(Source);
                for (int I = Enchantments.GetCount() - 1; I >= 0; I--)
                {
                    Chance = Enchantments.GetEnchantments(I).DispelChance(Mana);
                    if (Chance > AoWEUnit.AoWHSMap.Random(100))
                    {
                        Count += 1;
                        Enchantments.GetEnchantments(I).Dispel();
                    }
                }

                if (Source.FPlayer == AoWEUnit.AoWHSMap.FSeatedPlayer)
                {
                    if (Count > 0)
                    {
                        var format = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.XSpellsSuccessfullyDispelledRStr), [IntToStr(Count)]);
                        AoWEUnit.AoWHSMap.ShowMessage(format);
                    }
                    else
                    {
                        var dispelMagicFailed = AoWEUnit.TranslateRStr(AoWEUnit.DispelMagicFailedRStr);
                        AoWEUnit.AoWHSMap.ShowMessage(dispelMagicFailed);
                    }
                }

                Ability.SetEnabled(Source, false);
                Target.GetLocation(ref X, ref Y, ref L);
                AoWEUnit.AoWHSMap.ValidateObservation((sbyte)FSourcePlayer, X, Y, L, 0);
                if (AoWEUnit.AoWHSMap.Visible(X, Y, L, 0))
                {
                    Anim = new TImageSequenceAnimation(null);
                    Anim.SetImageSequence(Ability.FImageSequences.GetImageSequence(0));
                    AoWEUnit.AoWHSMap.PlaceHX(Anim, X, Y, L);
                }

                if ((byte)AoWEUnit.AoWHSMap.FSeatedPlayer == FSourcePlayer || AoWEUnit.AoWHSMap.Watching(X, Y, L, 0))
                {
                    Ability.FSFXLibrary.Play(0);
                }

                Result = TExecuteResult.erDone;
            }
            else
            {
                Result = TExecuteResult.erDoneHalt;
            }

            Enchantments?.Dispose();
            return Result;
        }

        // NetworkE.pas:230

    }
}

