        // AoWAb.PAS:4275
        public override void fcPrefetchCombatCommands(TFastCombatCommandList Commands)
        {
            TCombatObject Target;
            TFastCombatCommand Command;
            TAbilityDamageValues Values = default;
            for (int I = 0, last = Commands.FSourceSide.GetCount() - 1; I <= last; I++)
            {
                Target = Commands.FSourceSide.GetObjects(I);
                if (Target.GetEnabled() && CanTouch(Commands.FSource, Target))
                {
                    fcGetDamageValueEx(Commands.FSource, Target, TWallSituation.wsNone, ref Values);
                    if (Values.SourceDamage != 0)
                    {
                        Command = new TFastCombatCommand(FAbilityID);
                        Command.FTarget = Target;
                        Command.FSourceDV = Values.SourceDamage;
                        Command.FTargetDV = 0;
                        Command.FExpectedDV = AoWEUnit.DVtoDEV(Values.SourceDamage, 0, Commands.FSource, Target);
                        Command.FMoveCost = 0;
                        Commands.Add(Command);
                    }
                }
            }
        }

