        // AoWAb.PAS:4311
        public override bool Activate(TAbilityOwner Owner, ref string Reason)
        {
            bool Result;
            TUnitSelectorAAI Info;
            TDispelMagicAbilityUnitSelector Selector;
            if (CanActivate(Owner, ref Reason))
            {
                var unit = Owner as TAbstractUnit;
                Info = new TUnitSelectorAAI(null);
                Info.FAbilityID = FAbilityID;
                if (unit != null)
                {
                    Info.FUnitID = unit.FUnitID;
                }
                else
                {
                    Info.FUnitID = 0;
                }

                Selector = new TDispelMagicAbilityUnitSelector();
                var dispelMagic = AoWEUnit.TranslateRStr(AoWEUnit.DispelMagicRStr);
                Selector.FCaption = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.SelectUnitForXRStr), [dispelMagic]);
                if (unit != null)
                {
                    Selector.Setup(unit, (TUnitList)unit.Owner);
                }

                Info.SetUnitSelector(Selector);
                Selector.Release();
                AoWEUnit.AoWHSMap.FOnActivateAbilityStore.Raise(Info);
                Info.Release();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // AoWAb.PAS:4139
        public override bool CanExpand(TAbilityOwner owner)
        {
            if ((owner.GetAbilitySelectionTypes() & FSelectionTypes) == TSet<TAbilitySelectionType>.Of() || GetLevel(owner) >= 3)
            {
                return false;
            }

            return true;
        }

        // AoWAb.PAS:4135
        public override int ExpandCost(TAbilityOwner owner) => 5;

        // AoWAb.PAS:4125
        public override string ExpandName(TAbilityOwner Owner) => GetLevelName(GetLevel(Owner) + 1);

        // AoWAb.PAS:4152
        public override bool Expand(TAbilityOwner Owner)
        {
            TDispelMagicAbilityData Data;
            bool Result = false;
            Data = (TDispelMagicAbilityData)Owner.GetAbilityData(FAbilityID);
            if (Data == null)
            {
                Data = new TDispelMagicAbilityData(null);
                Data.FLevel = 1;
                Data.FEnabled = true;
                SetAb(Owner, FAbilityID, 1);
                Owner.AddAbilityData(Data);
                Result = true;
            }
            else
            {
                if (Data.FLevel != 3)
                {
                    Result = true;
                    Data.FLevel = (byte)(Data.FLevel + 1);
                    // { Original skips level one when upgrading data created by SetEnabled. }
                    if (Data.FLevel == 1)
                    {
                        Data.FLevel = 2;
                    }
                }
            }

            return Result;
        }

        // AoWAb.PAS:4175
        public override bool Remove(TAbilityOwner owner)
        {
            TDispelMagicAbilityData Data;
            bool Result = true;
            Data = (TDispelMagicAbilityData)owner.GetAbilityData(FAbilityID);
            if (Data != null)
            {
                if (Data.FLevel == 1)
                {
                    SetAb(owner, FAbilityID, 0);
                    owner.RemoveAbilityData(Data);
                }
                else
                {
                    Data.FLevel = (byte)(Data.FLevel - 1);
                }
            }
            else
            {
                SetAb(owner, FAbilityID, 0);
                Result = false;
            }

            return Result;
        }

        // AoWAb.PAS:4209
        public override int GetDamageValue(TAbstractUnit Attacker, TAbstractUnit Defender)
        {
            int Result;
            // { Original evaluates dispelling with the healing hit-point formula. }
            if (!Defender.GetImmunityTypes().Contains(TDamageType.dtNone))
            {
                Result = Defender.GetHits() - Defender.GetHitPoints();
                if (Result > 5)
                {
                    Result = 5;
                }

                return Result * 100;
            }

            return 0;
        }

        // AoWAb.PAS:4221
        public override void GetDamageValueEx(TAbstractUnit Attacker, TAbstractUnit Defender, TWallSituation WallSituation, ref TAbilityDamageValues DamageValues)
        {
            // { Original evaluates dispelling with the healing hit-point formula. }
            if (WallSituation == TWallSituation.wsNone && !Defender.GetImmunityTypes().Contains(TDamageType.dtNone))
            {
                var hits = Defender.GetHits();
                var hitPoints = Defender.GetHitPoints();
                DamageValues.SourceCost = hits - hitPoints;
                if (DamageValues.SourceCost > 5)
                {
                    DamageValues.SourceCost = 5;
                }

                DamageValues.SourceDamage = DamageValues.SourceCost * 100;
                DamageValues.TargetDamage = 0;
                DamageValues.TargetCost = 0;
                DamageValues.DamageTypes = TSet<TDamageType>.Of(TDamageType.dtNone);
            }
            else
            {
                DamageValues.SourceDamage = 0;
                DamageValues.SourceCost = 0;
                DamageValues.TargetDamage = 0;
                DamageValues.TargetCost = 0;
                DamageValues.DamageTypes = TSet<TDamageType>.Of();
            }
        }

        // AoWAb.PAS:4242
        public override void fcGetDamageValueEx(TCombatObject Attacker, TCombatObject Defender, TWallSituation WallSituation, ref TAbilityDamageValues DamageValues)
        {
            if (WallSituation == TWallSituation.wsNone && CanTouch(Attacker, Defender))
            {
                // { Original assigns zero benefit, so its prefetch loop emits no commands. }
                DamageValues.SourceCost = 0;
                DamageValues.SourceDamage = DamageValues.SourceCost * 100;
                DamageValues.TargetDamage = 0;
                DamageValues.TargetCost = 0;
                DamageValues.DamageTypes = TSet<TDamageType>.Of(TDamageType.dtNone);
            }
            else
            {
                DamageValues.SourceDamage = 0;
                DamageValues.SourceCost = 0;
                DamageValues.TargetDamage = 0;
                DamageValues.TargetCost = 0;
                DamageValues.DamageTypes = TSet<TDamageType>.Of();
            }
        }

