            Info.TargetTypes = TSet<TCombatTargetTypeElement>.Of(TCombatTargetTypeElement.cttFriend, TCombatTargetTypeElement.cttEnemy);
        }

        // AoWAb.PAS:4202
        public override bool CanTouch(TCombatObject Source, TCombatObject Target)
        {
            bool Result = base.CanTouch(Source, Target);
            if (Result)
            {
                bool condition = Source is TCombatUnit && Target is TCombatUnit;
                if (condition)
                {
                    var player = Source.GetPlayer();
                    condition = ((TCombatUnit)Target).FUnit.CanDispelEnchantment(player);
                }

                Result = condition;
            }

            return Result;
        }

        // AoWAb.PAS:4197
