        // AoWAb.PAS:4116
        public string GetLevelName(int Level)
        {
            string Result = "";
            switch (Level)
            {
                case 0:
                    Result = AoWEUnit.TranslateRStr(AoWEUnit.DispelMagicRStr);
                    break;
                case 1:
                    Result = AoWEUnit.TranslateRStr(AoWEUnit.DispelMagicRStr) + " I";
                    break;
                case 2:
                    Result = AoWEUnit.TranslateRStr(AoWEUnit.DispelMagicRStr) + " II";
                    break;
                case 3:
