        {
            FMaxLevel = 1;
            FAbilityID = 46;
            FLevelCosts[1] = 10;
        }

        // AoWAb.PAS:1002
        public override sbyte GetAttack(TAbilityOwner Owner)
        {
            sbyte Result;
            int Level;
            Level = GetLevel(Owner);
            if (Level != 0)
            {
                Result = AoWEUnit.P4LeadershipAttack[Level];
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // AoWAb.PAS:1013
        public override sbyte GetDefense(TAbilityOwner Owner)
        {
            sbyte Result;
            int Level;
            Level = GetLevel(Owner);
            if (Level != 0)
            {
                Result = AoWEUnit.P4LeadershipDefense[Level];
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // AoWAb.PAS:978
        public override int GetLevel(TAbilityOwner owner)
        {
            int Result;
            TLeadershipAbilityData Data;
            if (owner != null)
            {
                Data = (TLeadershipAbilityData)owner.GetAbilityData(FAbilityID);
                if (Data != null)
                {
                    if (Data.FExternalLevel > Data.FLevel)
                    {
                        Result = Data.FExternalLevel;
                    }
                    else
                    {
                        Result = Data.FLevel;
                    }
                }
                else
                {
                    return 0;
                }
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // AoWAb.PAS:1067
        public override string GetSourceName(TAbilityOwner Owner)
        {
            string Result;
            TLeadershipAbilityData Data;
            Data = (TLeadershipAbilityData)Owner.GetAbilityData(FAbilityID);
            if (Data != null && Data.FExternalLevel > Data.FLevel)
            {
                Result = Data.FExternalSource;
            }
            else
            {
                Result = Owner.GetOwnerName();
            }

            return Result;
        }

        // AoWAb.PAS:1078
        public override bool GetInherent(TAbilityOwner owner)
        {
            TLeadershipAbilityData Data;
            Data = (TLeadershipAbilityData)owner.GetAbilityData(FAbilityID);
            return Data != null && Data.FLevel > 0;
        }

        // AoWAb.PAS:1086
        public override bool CanExpand(TAbilityOwner owner)
        {
            bool Result;
            TLeadershipAbilityData Data;
            Data = (TLeadershipAbilityData)owner.GetAbilityData(FAbilityID);
            if (Data != null)
            {
                Result = Data.FLevel < FMaxLevel;
            }
            else
            {
                Result = true;
            }

            return Result;
        }

        // AoWAb.PAS:1097
        public override string GetLevelName(int Level) => AoWEUnit.TranslateRStr(AoWEUnit.LeadershipRStr);

        // AoWAb.PAS:1024
        public void SetExternalSource(TAbilityOwner Owner, byte Level, string SourceName)
        {
            TLeadershipAbilityData Data;
            Data = (TLeadershipAbilityData)Owner.GetAbilityData(FAbilityID);
            if (Data == null)
            {
                SetAb(Owner, FAbilityID, 1);
                Data = new TLeadershipAbilityData(null);
                Data.FLevelAbilityID = (ushort)FAbilityID;
                Data.FLevel = 0;
                Owner.AddAbilityData(Data);
            }

            // { Original compares with the inherent level, even if an external level is higher. }
            if (Data.FLevel < Level)
            {
                Data.FExternalSource = SourceName;
                Data.FExternalLevel = Level;
            }

            if (Owner is TAbstractUnit)
            {
                Owner.Changed();
            }
        }

        // AoWAb.PAS:1047
        public void ResetExternalSource(TAbilityOwner Owner)
        {
            TLeadershipAbilityData Data;
            Data = (TLeadershipAbilityData)Owner.GetAbilityData(FAbilityID);
            if (Data != null)
            {
                if (Data.FLevel != 0)
                {
                    Data.FExternalSource = "";
                    Data.FExternalLevel = 0;
                }
                else
                {
                    SetAb(Owner, FAbilityID, 0);
                    Owner.RemoveAbilityData(Data);
                }
            }

            if (Owner is TAbstractUnit)
            {
                Owner.Changed();
            }
        }

        // AoWAb.PAS:973
        public override EClass AbilityDataClass() => EClass.Of<TLeadershipAbilityData>();

    }
}

