    public partial class TUnitEnchantmentAbility : TAdjustableAbility
    {

        // AoWAb.PAS:601
        public TUnitEnchantmentAbility(TECustomNode owner) : base(owner)
        {
            FAbilityType = TAbilityType.atEnchantment;
            FSelectionTypes = TSet<TAbilitySelectionType>.Of();
        }

        // AoWAb.PAS:613
        public override string GetName(TAbilityOwner Owner)
        {
            string Result;
            if (Owner != null)
            {
                switch (GetDurationMode())
                {
                    case TDurationMode.dmDay:
                        Result = base.GetName(Owner);
                        if (GetDuration(Owner) != 0)
                        {
                            var duration = GetDuration(Owner);
                            var totalDuration = GetTotalDuration();
                            var format = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.DurationDaysRStr), [IntToStr(duration), IntToStr(totalDuration)]);
                            Result = Result + " " + format;
                        }

                        break;
                    case TDurationMode.dmCombatTurn:
                        var duration2 = GetDuration(Owner);
                        var totalDuration2 = GetTotalDuration();
                        var aoWEFormat = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.DurationCombatTurnRStr), [IntToStr(duration2), IntToStr(totalDuration2)]);
                        Result = base.GetName(Owner) + " " + aoWEFormat;
                        break;
                    case TDurationMode.dmEntireCombat:
                        var name = base.GetName(Owner);
                        var durationEntireCombat = AoWEUnit.TranslateRStr(AoWEUnit.DurationEntireCombatRStr);
                        Result = name + " " + durationEntireCombat;
                        break;
                    default:
                        Result = base.GetName(Owner);
                        break;
                }
            }
            else
            {
                Result = base.GetName(Owner);
            }

            return Result;
        }

        // AoWAb.PAS:637
        public override string GetSourceName(TAbilityOwner Owner)
        {
            string Result;
            TUnitEnchantmentAbilityData Data;
            TAbstractUnit Source;
            if (AoWEUnit.AoWHSMap != null)
            {
                Data = (TUnitEnchantmentAbilityData)Owner.GetAbilityData(FAbilityID);
                Source = AoWEUnit.AoWHSMap.FUnitControl.FindUnit(Data.FEnchantment.FUnitID);
                // { Original also reports player zero as unknown. }
                if (Data.FEnchantment.FSource <= 0)
                {
                    Result = AoWEUnit.TranslateRStr(AoWEUnit.UnknownRStr);
                }
                else
                {
                    if (Source != null && Source.FPlayer == Data.FEnchantment.FSource)
                    {
                        Result = AoWEUnit.TranslateRStr(AoWEUnit.P4ManaRStr);
                    }
                    else
                    {
                        Result = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Data.FEnchantment.FSource).FLeader.FHeroName;
                    }
                }
            }
            else
            {
                Result = AoWEUnit.TranslateRStr(AoWEUnit.UnknownRStr);
            }

            return Result;
        }

        // AoWAb.PAS:735
        public override void NewTurn(TAbilityOwner Owner, sbyte Player)
        {
            TUnitEnchantmentAbilityData Data;
            if (GetDurationMode() == TDurationMode.dmDay)
            {
                Data = (TUnitEnchantmentAbilityData)Owner.GetAbilityData(FAbilityID);
                if (Data != null)
                {
                    if (Data.FEnchantmentDuration > 0 && Player == Data.FEnchantmentPlayerIndex)
                    {
                        Data.FEnchantmentDuration = (sbyte)(Data.FEnchantmentDuration - 1);
                        if (Data.FEnchantmentDuration == 0)
                        {
                            Owner.RemoveAbility(FAbilityID);
                        }
                    }
                }
                else
                {
                    Owner.RemoveAbility(FAbilityID);
                }
            }
        }

        // AoWAb.PAS:668
        public override bool Expand(TAbilityOwner Owner)
        {
            TUnitEnchantmentAbilityData Data;
            TUnitEnchantment Enchantment;
            if (Owner is not TAbstractUnit unit)
            {
                // { Preserve the original assertion diagnostic. }
                Assert(false, "Assertion failure", "D:\\AoWDev\\AoWE\\inc\\AoWAb.PAS", 46175);
                return false;
            }

            bool Result = false;
            Data = (TUnitEnchantmentAbilityData)Owner.GetAbilityData(FAbilityID);
            if (Data == null)
            {
                if (unit.FUnitID <= 0)
                {
                    // { Preserve the original assertion diagnostic. }
                    Assert(false, "Assertion failure", "D:\\AoWDev\\AoWE\\inc\\AoWAb.PAS", 46181);
                }

                Data = new TUnitEnchantmentAbilityData(null);
                Data.FEnchantmentAbilityID = (ushort)FAbilityID;
                Data.FEnchantmentDuration = GetTotalDuration();
                Enchantment = CreateEnchantment();
                Data.FEnchantment = Enchantment;
                Enchantment.FEnchantmentAbilityID = FAbilityID;
                Enchantment.FUnitID = unit.FUnitID;
                SetAb(Owner, FAbilityID, 1);
                Owner.AddAbilityData(Data);
                Result = true;
            }
            else
            {
                Data.FEnchantmentDuration = GetTotalDuration();
            }

            return Result;
        }

        // AoWAb.PAS:694
        public override bool Remove(TAbilityOwner owner)
        {
            TUnitEnchantmentAbilityData Data;
            bool Result = true;
            Data = (TUnitEnchantmentAbilityData)owner.GetAbilityData(FAbilityID);
            if (Data != null)
            {
                if (AoWEUnit.AoWHSMap != null && Data.FEnchantment.FSource > -1)
                {
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Data.FEnchantment.FSource).FMagicControl.UnregisterEnchantment(Data.FEnchantment);
                }

                SetAb(owner, FAbilityID, 0);
                owner.RemoveAbilityData(Data);
            }
            else
            {
                SetAb(owner, FAbilityID, 0);
                Result = false;
            }

            return Result;
        }

        // AoWAb.PAS:756
        public override void NewCombatTurn(TCombatObject CombatObject, sbyte Player)
        {
            TUnitEnchantmentAbilityData Data;
            if (GetDurationMode() == TDurationMode.dmCombatTurn)
            {
                Data = (TUnitEnchantmentAbilityData)CombatObject.GetAbilityOwner().GetAbilityData(FAbilityID);
                if (Data != null)
                {
                    if (Data.FEnchantmentDuration > 0 && Player == Data.FEnchantmentPlayerIndex)
                    {
                        Data.FEnchantmentDuration = (sbyte)(Data.FEnchantmentDuration - 1);
                        if (Data.FEnchantmentDuration == 0)
                        {
                            CombatObject.GetAbilityOwner().RemoveAbility(FAbilityID);
                        }
                    }
                }
                else
                {
                    CombatObject.GetAbilityOwner().RemoveAbility(FAbilityID);
                }
            }
        }

        // AoWAb.PAS:777
        public override void CombatDone(TCombatObject CombatObject)
        {
            switch (GetDurationMode())
            {
                case TDurationMode.dmCombatTurn:
                case TDurationMode.dmEntireCombat:
                    CombatObject.GetAbilityOwner().RemoveAbility(FAbilityID);
                    break;
            }
        }

        // AoWAb.PAS:714
        public virtual TDurationMode GetDurationMode() => TDurationMode.dmNone;

        // AoWAb.PAS:719
        public virtual byte GetDuration(TAbilityOwner Owner)
        {
            byte Result;
            TUnitEnchantmentAbilityData Data;
            Data = (TUnitEnchantmentAbilityData)Owner.GetAbilityData(FAbilityID);
            if (Data != null)
            {
                Result = (byte)Data.FEnchantmentDuration;
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // AoWAb.PAS:608
        public virtual int GetAIUpkeepPriority(TAbilityOwner Owner) => 0;

        // AoWAb.PAS:730
        public virtual sbyte GetTotalDuration() => -1;

        // AoWAb.PAS:663
        public virtual TUnitEnchantment CreateEnchantment() => new TUnitEnchantment(null);

        // AoWAb.PAS:658
        public override EClass AbilityDataClass() => EClass.Of<TUnitEnchantmentAbilityData>();

    }
}

