        // AoWAb.PAS:4588
        public override void fcPrefetchCombatCommands(TFastCombatCommandList Commands)
        {
            TFastCombat Combat;
            TCombatObject Source;
            string Error = "";
            TPlayerMagicControl Magic;
            TSpell Spell;
            Combat = Commands.FCombat;
            Source = Commands.FSource;
            if (Source is TCombatUnit)
            {
                var players = Combat.FCombatData.FPlayers.GetPlayers(Source.FCombatPlayer);
                if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(players.FPlayer).FPlayerType != TPlayerType.ptHuman || ((THero)((TCombatUnit)Source).FUnit).FCastingSpellID == 0)
                {
                    var side = Source.GetSide();
                    var opponentSide = Source.GetOpponentSide();
                    if (Combat.FSides[(int)side].FStrength < Combat.FSides[(int)opponentSide].FStrength * 2 || Source.GetHitPoints() < 10 || Combat.FCombatData.FWallType != 0 && !Combat.FCombatData.FWallBreached && CanCastBreachWallSpell(((TCombatUnit)Source).FUnit))
                    {
                        var player = Commands.FSource.GetPlayer();
                        Magic = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(player).FMagicControl;
                        if (!Magic.GetCheatEnabled())
                        {
                            for (int I = Magic.FSpells.Count - 1; I >= 0; I--)
                            {
                                var item = Magic.FSpells[I];
                                Spell = AoWEUnit.AoWHSSet.FSpellControl.GetSpell(item);
                                if (Spell != null && Spell.FSpellControlTypes.Contains(TSpellControlTypeElement.sctCombat))
                                {
                                    if (((TCombatUnit)Commands.FSource).FUnit is THero)
                                    {
                                        if (((THero)((TCombatUnit)Commands.FSource).FUnit).CanCastSpellInstantly(Spell.FSpellID, Spell.FBaseManaCost, ref Error))
                                        {
                                            Spell.fcPrefetchCombatCommands(Commands);
                                        }
                                    }
                                }
                            }
                        }
                        else
                        {
                            for (int I = 0, last = AoWEUnit.AoWHSSet.FSpellControl.GetCount() - 1; I <= last; I++)
                            {
                                Spell = AoWEUnit.AoWHSSet.FSpellControl.GetSpell(I);
                                if (Spell != null && Spell.FSpellControlTypes.Contains(TSpellControlTypeElement.sctCombat))
                                {
                                    Spell.fcPrefetchCombatCommands(Commands);
                                }
                            }
                        }
                    }
                }
            }
        }

