        // AoWAb.PAS:4488
        public bool CanCastBreachWallSpell(TAbstractUnit AUnit)
        {
            bool Result;
            int I;
            TSpell Spell;
            TSpellCombatInfo Info = default;
            string Error = "";
            TPlayerMagicControl Magic;
            if (AUnit is THero)
            {
                Magic = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AUnit.FPlayer).FMagicControl;
                Result = Magic.GetCheatEnabled();
                I = Magic.FSpells.Count;
                while (!Result && I != 0)
                {
                    I -= 1;
                    var item = Magic.FSpells[I];
                    Spell = AoWEUnit.AoWHSSet.FSpellControl.GetSpell(item);
                    if (Spell != null && Spell.FSpellType == TSpellType.stCombat)
                    {
                        Spell.GetCombatInfo(AUnit, ref Info);
                        bool condition = Info.DamageTypes.Contains(TDamageType.dtWall);
                        if (condition)
                        {
                            var fSpellsItem = Magic.FSpells[I];
                            condition = ((THero)AUnit).CanCastCombatSpell(fSpellsItem, ref Error);
                        }

                        Result = condition;
                    }
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // AoWAb.PAS:4515
        public bool AICanCastCombatSpell(TCombatUnit Source)
        {
            THero Hero;
            int SourceStrength;
            int TargetStrength;
            float Ratio;
            Hero = (THero)Source.FUnit;
            bool Result = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Hero.FPlayer).FPlayerType != TPlayerType.ptHuman || Hero.FCastingSpellID == 0;
            if (Result)
            {
                var side = Source.GetSide();
                SourceStrength = Source.FCombat.FSides[(int)side].FStrength;
                if (SourceStrength <= 0)
                {
                    SourceStrength = 0;
                }

                var opponentSide = Source.GetOpponentSide();
                TargetStrength = Source.FCombat.FSides[(int)opponentSide].FStrength;
                if (TargetStrength <= 0)
                {
                    TargetStrength = 0;
                }

                // { Original divides by zero when the opponent strength is zero. }
                Ratio = (float)((double)SourceStrength / TargetStrength);
                if (((double)Ratio >= 1.5 || Hero.FCastingSpellID != 0) && (double)Ratio >= 1 && (double)((double)Source.GetHitPoints() * Ratio) >= 7)
                {
                    Result = false;
                }
                else
                {
                    Result = true;
                }
            }

            return Result;
        }
    }
}

