            {
                Mana -= AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Source.FPlayer).FMagicControl.AIRequestOverrideUpkeep(Round((double)Upkeep * 0.8));
                if (Mana < 0)
                {
                    Mana = 0;
