            {
                UnregisterSpell((TSpell)FRegisteredSpells.List[SpellID]);
            }
        }

        // Spells.PAS:651
        public void UnregisterAll()
        {
            for (int I = FRegisteredSpells.Count - 1; I >= 0; I--)
