                {
                    UnregisterSpell((TSpell)FRegisteredSpells[I]);
                }
            }
        }

        // Spells.PAS:659
        public void ListSpells(TStrings SpellStrings, TSet<Aow.Game.Magic.TMagicSphere> Spheres)
        {
            SpellStrings.Clear();
            for (int I = 0, last = this.FRegisteredSpells.Count - 1; I <= last; I++)
            {
                if (this.FRegisteredSpells.List[I] != null && Spheres.Contains(((TSpell)this.FRegisteredSpells.List[I]).FMagicSphere))
                {
                    SpellStrings.AddObject(((TSpell)this.FRegisteredSpells.List[I]).FSpellName, IntToObject(I));
