        {
            sbyte x = 0, y = 0, l = 0;
            GetSource().GetLocation(ref x, ref y, ref l);
            var spell = AoWEUnit.AoWHSSet.FSpellControl.GetSpell(FEventSpellID);
            spell.PlayDefaultCastEffects(GetSource().FPlayer, x, y, l);
        }

        public override TExecuteResult Execute(TTokenExecuter executer)
        {
            base.Execute(executer);
            var source = AoWEUnit.AoWHSMap.FUnitControl.FindUnit(FEventSourceID);
            if (source == null || executer.ExecuteCount == 0 && !Validate((THero)source)) return TExecuteResult.erDoneHalt;
