namespace Aow.Game.Units
{

    // (target-unit users, selection bits)
    public partial class TUnitSpellCaster : TSpellCaster
    {
        // Spells.PAS:859
        public TUnitSpellCaster(TECustomNode owner) : base(owner)
        {
            FTargetUnits = new TUnitUserList(null);
        }

        public TUnitUserList FTargetUnits;
        public byte FSelectionMask;
        public bool FAllowMultipleTargets;
        public byte FValidSelection;

        // Spells.PAS:864
        public override void Dispose()
        {
            FTargetUnits?.Dispose();
            base.Dispose();
        }

        // Spells.PAS:947
        public override bool CanCast(ref string Reason)
        {
            bool Result;
            THero Hero;
            int Mana;
            Hero = AoWEUnit.AoWHSMap.FUnitControl.FindUnit<THero>(FCasterSourceID);
            if (Hero != null && !Hero.FUnitStatus.Contains(TUnitStatusElement.usKilled))
            {
                if (FSelectionMask != 0)
                {
                    if (!AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Hero.FPlayer).FMagicControl.GetCheatEnabled())
                    {
                        Mana = GetRequiredMana();
                        if (Hero.CastingReady() && Hero.FCastingSpellID == FCasterSpellID)
                        {
                            Mana -= AoWEUnit.AoWHSSet.FSpellControl.GetSpell(FCasterSpellID).FBaseManaCost;
                        }

                        if (Mana <= Hero.GetCastingPoints())
                        {
                            if (Mana <= AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Hero.FPlayer).FMagicControl.FMana)
                            {
                                Result = true;
                            }
                            else
                            {
                                Result = false;
                                Reason = AoWEUnit.TranslateRStr(AoWEUnit.NotEnoughManaRStr);
                            }
                        }
                        else
                        {
                            Result = false;
                            Reason = AoWEUnit.TranslateRStr(AoWEUnit.P2NotEnoughCastingPointsRStr);
                        }
                    }
                    else
                    {
                        Result = true;
                    }
                }
                else
                {
                    Result = false;
                    Reason = AoWEUnit.TranslateRStr(AoWEUnit.NoUnitSelectedRStr);
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Spells.PAS:981
        public override bool Cast()
        {
            bool Result;
            TUnitUserList Targets;
            string Reason = "";
            TAbstractUnit Source;
            if (CanCast(ref Reason))
            {
                Source = AoWEUnit.AoWHSMap.FUnitControl.FindUnit(FCasterSourceID);
                if (Source != null)
                {
                    Targets = new TUnitUserList(null);
                    for (int I = 0, last = FTargetUnits.Count - 1; I <= last; I++)
                    {
                        if (((1 << I) & FSelectionMask) != 0)
                        {
                            Targets.AddUnit(FTargetUnits.GetUnit(I));
                        }
                    }

                    Result = ((TUnitSpell)AoWEUnit.AoWHSSet.FSpellControl.GetSpell(FCasterSpellID)).CastSpell(Source, Targets);
                    Targets?.Dispose();
                }
                else
                {
                    Result = true;
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Spells.PAS:896
        public int GetSelectionCount()
        {
            int Bits;
            int Result = 0;
            Bits = FSelectionMask;
            while (Bits != 0)
            {
                if ((Bits & 1) != 0)
                {
                    Result += 1;
                }

                Bits = (int)(((uint)Bits) >> 1);
            }

            return Result;
        }

        // Spells.PAS:1085
        public bool Valid()
        {
            bool Result;
            TAbstractUnit Source;
            Source = AoWEUnit.AoWHSMap.FUnitControl.FindUnit<TAbstractUnit>(FCasterSourceID);
            if (Source == null || (((byte)Source.FUnitStatus.Image) & 16) != 0)
            {
                Result = false;
            }
            else
            {
                Result = true;
            }

            return Result;
        }

        // intf_P4_02.inc:1038
        public void SetSelection(byte selection)
        {
            byte value = selection;
            var source = AoWEUnit.AoWHSMap.FUnitControl.FindUnit(FCasterSourceID);
            ((TUnitSpell)AoWEUnit.AoWHSSet.FSpellControl.GetSpell(FCasterSpellID)).ValidateUnitSelection(source, FTargetUnits, ref value);
            FSelectionMask = value;
        }
    }
}

