        {
            TAICastSpellAction Action;
            string Reason = "";
            int Priority = default;
            TAbstractUnit Target = default;
            bool Valid;
            if (FAIValue != -1 && Source.Owner is TArmy)
            {
                Valid = AIRequestCastSpellExpense(Source, FBaseManaCost, FManaUpkeep, 0);
                Valid = Valid && Source.Owner is TArmy;
                Valid = Valid && ((THero)Source).CanCastSpell(FSpellID, ref Reason);
                if (Valid && AIRetrieveOptimalTargetUnit(Source, (TUnitList)Source.Owner, ref Target, ref Priority))
                {
                    Action = CreateCastSpellAction();
                    SetupCastSpellAction(Source, Action);
                    Action.FPriority = Priority;
                    Action.SetOwner(Actions);
                }
            }
        }

        // Spells.PAS:1466
        public override bool AIExecuteCastSpellAction(TAbstractUnit Source)
        {
            bool Result;
            string Reason = "";
            int Priority = default;
            TAbstractUnit Target = default;
            TUnitList Targets;
            TUnitSpellTE Event;
            if (((THero)Source).CanCastSpell(FSpellID, ref Reason))
            {
                AICastSpellExpenseMade(Source, FBaseManaCost, FManaUpkeep, 0);
                if (((THero)Source).CanCastSpellInstantly(FSpellID, FBaseManaCost, ref Reason))
                {
                    Targets = (TUnitList)Source.Owner;
                    if (AIRetrieveOptimalTargetUnit(Source, Targets, ref Target, ref Priority))
                    {
                        Event = new TUnitSpellTE(null);
                        Event.Initialize(FSpellID, Source, null, FBaseManaCost);
                        Event.FTargetPlayer = (byte)Source.FPlayer;
                        Event.FTargetUnitIDs.Add(Target.FUnitID);
                        AoWEUnit.AoWHSMap.FTokenManager.GetTokenControl(Source.FPlayer).AddEvent(Event);
                        Event.Release();
                        Result = true;
                    }
                    else
                    {
                        Result = false;
                    }
                }
                else
                {
                    if (((THero)Source).FCastingSpellID != FSpellID)
                    {
                        ((THero)Source).ExecuteStartCasting(FSpellID);
                        Result = true;
                    }
                    else
                    {
                        Result = true;
                    }
