        {
            bool Result;
            if (!FSpellControlTypes.Contains(Aow.Game.Magic.Spells.TSpellControlTypeElement.sctCombat) || !base.CanActivateCombat(source, ref reason))
            {
                Result = false;
            }
            else
            {
                Result = true;
            }

            return Result;
        }

