        // Spells.PAS:1228
        public virtual void ValidateUnitSelection(TAbstractUnit Source, TUnitList Targets, ref byte Selection)
        {
            var count = Targets.GetCount();
            Selection = (byte)(Selection & AoWEUnit.P4SelectionMasks[count]);
            for (int I = 0, last = Targets.GetCount() - 1; I <= last; I++)
            {
                if ((Selection & (1 << I)) != 0)
                {
                    if (!ValidTargetUnit(Source, Targets.GetUnit(I)))
                    {
                        Selection = (byte)(Selection & ~(1 << I));
                    }
                }
            }
        }

        // Spells.PAS:1238
        public virtual void SetupUSC(TUnitSpellCaster Caster, TAbstractUnit Source, TUnitList Targets)
        {
            Caster.FCasterSourceID = Source.FUnitID;
            Caster.FCasterSpellID = FSpellID;
            for (int I = 0, last = Targets.GetCount() - 1; I <= last; I++)
            {
                if (!((TArmy)Targets).GetUnitConcealedForPlayer(I, Source.FPlayer))
                {
                    var unit = Targets.GetUnit(I);
                    Caster.FTargetUnits.AddUnit(unit);
                }
            }

            Caster.FTargetUnits.SortUnits();
            Caster.FAllowMultipleTargets = FAllowMultipleTargets;
            Caster.FValidSelection = 0;
            for (int I = Caster.FTargetUnits.GetCount() - 1; I >= 0; I--)
            {
                if (ValidTargetUnit(Source, Caster.FTargetUnits.GetUnit(I)))
                {
                    Caster.FValidSelection = (byte)(Caster.FValidSelection | (1 << I));
                }
            }
        }

        // Spells.PAS:1254
        public virtual bool CastSpell(TAbstractUnit Source, TUnitList Targets)
        {
            bool Result;
            TUnitSpellTE Event;
            ResetTargetSelection();
            if (!AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Source.FPlayer).GetBusy())
            {
                Event = new TUnitSpellTE(null);
                var castingMana = ((THero)Source).CastingMana(this);
                Event.Initialize(FSpellID, Source, Targets, castingMana);
                AoWEUnit.AoWHSMap.FTokenManager.GetTokenControl(Source.FPlayer).AddEvent(Event);
                Event.Release();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

