        // Spells.PAS:1411
        public virtual void ExecuteCA(TCombat Combat, TUnitSpellCA Action)
        {
            TCombatObject Source;
            TCombatObject Target;
            Source = Combat.FCombatData.FindID(Action.FSourceID);
            Target = Combat.FCombatData.FindID(Action.FTargetID);
            if (Source is TCombatUnit && Target is TCombatUnit)
            {
                if (ExecuteSpell(((TCombatUnit)Source).FUnit, ((TCombatUnit)Target).FUnit, Action.FMana, ref Action.FSpellData))
                {
                    if (Action.FMana != 0 && (((byte)Combat.FStatus.Image) & 1) != 0)
                    {
                        AoWEUnit.AoWHSSet.FSpellControl.GetSpell(FSpellID).CombatCastingDone(Source, Action.FMana);
                    }
                }
            }
        }

        // Spells.PAS:1422
        public virtual bool AIRetrieveOptimalTargetUnit(TAbstractUnit Source, TUnitList Targets, ref TAbstractUnit Target, ref int Priority)
        {
            bool Result;
            TDoubleItemList<TAbstractUnit> List;
            int Value;
            List = new TDoubleItemList<TAbstractUnit>();
            for (int I = 0, last = Targets.GetCount() - 1; I <= last; I++)
            {
                if (ValidTargetUnit(Source, Targets.GetUnit(I)) && Targets.GetUnit(I).GetUnitType() != TUnitType.utMachine)
                {
                    Value = Targets.GetUnit(I).GetUnitLevel() + FAIValue;
                    List.AddAB(Targets.GetUnit(I), Value);
                }
            }

            if (List.Count != 0)
            {
                List.SortDescendingItemB();
                Target = List[0].A;
                Priority = List[0].B;
                Result = true;
            }
            else
            {
                Result = false;
            }

            List?.Dispose();
            return Result;
        }

        // Spells.PAS:1269
        public void OnValidateTarget(TTargetSelectionControl Control, sbyte X, sbyte Y, sbyte L, ref bool Valid)
        {
            TAbstractUnit Source;
            TArmyHS Party;
            Source = AoWEUnit.AoWHSMap.FUnitControl.FindUnit(Control.FSourceUnitID);
            if (Source != null)
            {
                if (AoWEUnit.AoWHSMap.Visible(X, Y, L, 0))
                {
                    Party = ((TAoWMapField)AoWEUnit.AoWHSMap.MapContainer.GetField(X, Y, L)).GetArmyHS();
                    if (Party != null && (Party.FArmy.FPlayer == Source.FPlayer || !((TAoWMapField)AoWEUnit.AoWHSMap.MapContainer.GetField(X, Y, L)).GetMagicShieldActive()))
                    {
                        Valid = ValidTargetParty(Source, Party);
                    }
                    else
                    {
                        Valid = false;
                    }
                }
                else
                {
                    Valid = false;
                }
            }
            else
            {
                ResetTargetSelection();
            }
        }

        // Spells.PAS:1289
        public void OnTargetSelectionChange(TTargetSelectionControl Control)
        {
            TAbstractUnit Source;
            TArmyHS Party;
            Source = AoWEUnit.AoWHSMap.FUnitControl.FindUnit(Control.FSourceUnitID);
            if (Source != null)
            {
                switch (Control.FChange)
                {
                    case TTargetSelectionChange.tscDeactivated:
                        ResetTargetSelection();
                        break;
                    case TTargetSelectionChange.tscSelected:
                        if (Control.FTargetX != -1)
                        {
                            Party = ((TAoWMapField)AoWEUnit.AoWHSMap.MapContainer.GetField(Control.FTargetX, Control.FTargetY, Control.FTargetL)).GetArmyHS();
                            if (Party != null && ValidTargetParty(Source, Party))
                            {
                                TargetPartySelected(Source, Party);
                            }
                        }

                        break;
                }
            }
            else
            {
                ResetTargetSelection();
            }
        }

        // Spells.PAS:1310
        public void ResetTargetSelection()
        {
            var targetSelectionControl = AoWEUnit.AoWHSMap.FTargetSelection;
            targetSelectionControl.FOnChange -= OnTargetSelectionChange;
            targetSelectionControl.Deactivate();
        }

        // Spells.PAS:1318
        public void SetupTargetSelection(TAbstractUnit Source, TTargetSelectionControl Control)
        {
            sbyte X = default;
            sbyte Y = default;
            sbyte L = default;
            Control.Initialize(Source);
            Control.FTargetMode = Control.FTargetMode + TSet<TTargetSelectionModeElement>.Of(TTargetSelectionModeElement.tmExternalFloater);
            if (FTargetRange != -1)
            {
                Control.FTargetMode = Control.FTargetMode + TSet<TTargetSelectionModeElement>.Of(TTargetSelectionModeElement.tmValidateDistance);
                Control.FRange = FTargetRange;
            }
            else
            {
                Control.FRange = 0;
            }

            Source.GetLocation(ref X, ref Y, ref L);
            Control.FSourceX = X;
            Control.FSourceY = Y;
            Control.FSourceL = L;
            Control.FOnChange += OnTargetSelectionChange;
            Control.FOnValidateTarget = OnValidateTarget;
            var format = AoWEUnit.Format(AoWEUnit.TranslateRStr(AoWEUnit.P4SelectTargetPartyForXRStr), [FSpellName]);
            Control.FText.Text = format;
            Control.FTitle = FSpellName;
            Control.FCancelText = AoWEUnit.TranslateRStr(AoWEUnit.CancelRStr);
            Control.FSourceUnitID = Source.FUnitID;
            Control.FSourceImage = AoWEUnit.AoWHSSet.FSpellControl.GetSpell(FSpellID).FCastImages.GetImageSequence(20).GetPreviewImage();
            Control.FValidTargetImage = AoWEUnit.AoWHSSet.FSpellControl.GetSpell(FSpellID).FCastImages.GetImageSequence(21).GetPreviewImage();
            Control.FInvalidTargetImage = AoWEUnit.AoWHSSet.FSpellControl.GetSpell(FSpellID).FCastImages.GetImageSequence(22).GetPreviewImage();
        }
    }
}

