        // Diplomacy.pas:1804
        public void GenerateTransferUnits(TUnitList Units)
        {
            int Index;
            int MaxUnits;
            FixedArray_int_4 LevelCounts = default;
            TList Candidates;
            TAbstractUnit AUnit;
            FUnits.Clear();
            Candidates = new TList();
            MaxUnits = 10;
            LevelCounts[1 - 1] = 8;
            LevelCounts[2 - 1] = 4;
            LevelCounts[3 - 1] = 1;
            if (AoWEUnit.AoWEngine.FCampaign.FRaceHistory.Count > 2)
            {
                LevelCounts[4 - 1] = 1;
            }
            else
            {
                LevelCounts[4 - 1] = 0;
            }

            for (int Level = 4; Level >= 1; Level--)
            {
                if (LevelCounts[Level - 1] != 0)
                {
                    Candidates.Clear();
                    for (int I = 0, last = Units.Count - 1; I <= last; I++)
                    {
                        AUnit = Units.GetUnit(I);
                        if (AUnit.GetUnitLevel() == Level && FUnits.IndexOf(AUnit) == -1)
                        {
                            Candidates.Add(AUnit);
                        }
                    }

                    // { Original bug: the per-level quota is tested but never decremented. }
                    while (LevelCounts[Level - 1] != 0 && Candidates.Count != 0 && FUnits.Count != MaxUnits)
                    {
                        Index = Random(Candidates.Count);
                        var abstractUnit = Candidates[Index];
                        FUnits.AddUnit((TAbstractUnit)abstractUnit);
                        Candidates.Delete(Index);
                    }
                }
            }

            Candidates?.Dispose();
        }

        // Diplomacy.pas:1842
        public void Retrieve()
        {
            TUnitUserList Units;
            sbyte Player;
            TAbstractUnit AUnit;
            TAbstractUnit NewUnit;
            THero Hero;
            TItem Item;
            TItem CopyItem;
            Clear();
            if (AoWEUnit.AoWHSMap != null)
            {
                Units = new TUnitUserList(null);
                Player = (sbyte)AoWEUnit.AoWHSMap.FPlayers.FLocalPlayers[0];
                FLeader = (TLeader)AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FLeader.Copy(AoWEUnit.AoWEngine);
                FLeader.RemoveEnchantments();
                FLeader.RemoveHandicaps();
                FLeader.ExecuteCancelCasting();
                for (int J = FLeader.FInventory.Count - 1; J >= 0; J--)
                {
                    Item = FLeader.FInventory.GetItem(J);
                    if (Item != null)
                    {
                        CopyItem = (TItem)Item.Copy(AoWEUnit.AoWEngine);
                        CopyItem.SetOwner(FItems);
                        CopyItem.FItemID = FLeader.FUnitID;
                        CopyItem.Release();
                    }
                }

                FLeader.FInventory.Clear();
                for (int J = FLeader.FHeroItems.Count - 1; J >= 0; J--)
                {
                    Item = FLeader.FHeroItems.GetItem(J);
                    if (Item != null)
                    {
                        CopyItem = (TItem)Item.Copy(AoWEUnit.AoWEngine);
                        CopyItem.SetOwner(FItems);
                        CopyItem.FItemID = FLeader.FUnitID;
                        CopyItem.Release();
                    }
                }

                FLeader.FHeroItems.Clear();
                for (int I = 0, last = AoWEUnit.AoWHSMap.FUnitControl.GetCount() - 1; I <= last; I++)
                {
                    AUnit = AoWEUnit.AoWHSMap.FUnitControl.GetUnit(I);
                    if (AUnit.FPlayer == Player && AUnit.GetUnitType() != TUnitType.utMachine && (AUnit.GetMoveTypes() & TSet<TMoveType>.Of(TMoveType.mtWalking, TMoveType.mtFlying)) != TSet<TMoveType>.Of() && !(AUnit is TLeader) && !AUnit.GetAbilityEnabled(155))
                    {
                        if (AUnit is THero)
                        {
                            Hero = (THero)AUnit.Copy(AoWEUnit.AoWEngine);
                            Hero.SetOwner(FHeroes);
                            Hero.RemoveEnchantments();
                            Hero.RemoveHandicaps();
                            Hero.ExecuteCancelCasting();
                            for (int J = Hero.FInventory.Count - 1; J >= 0; J--)
                            {
                                Item = Hero.FInventory.GetItem(J);
                                if (Item != null)
                                {
                                    CopyItem = (TItem)Item.Copy(AoWEUnit.AoWEngine);
                                    CopyItem.SetOwner(FItems);
                                    CopyItem.FItemID = Hero.FUnitID;
                                    CopyItem.Release();
                                }
                            }

                            Hero.FInventory.Clear();
                            for (int J = Hero.FHeroItems.Count - 1; J >= 0; J--)
                            {
                                Item = Hero.FHeroItems.GetItem(J);
                                if (Item != null)
                                {
                                    CopyItem = (TItem)Item.Copy(AoWEUnit.AoWEngine);
                                    CopyItem.SetOwner(FItems);
                                    CopyItem.FItemID = Hero.FUnitID;
                                    CopyItem.Release();
                                }
                            }

                            Hero.FHeroItems.Clear();
                            Hero.Release();
                        }
                        else
                        {
                            NewUnit = (TAbstractUnit)AUnit.Copy(AoWEUnit.AoWEngine);
                            NewUnit.RemoveEnchantments();
                            NewUnit.RemoveHandicaps();
                            Units.AddUnit(NewUnit);
                            NewUnit.Release();
                        }
                    }
                }

                FResearchPercentage = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FMagicControl.FResearchPercentage;
                var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
                FSpells.Assign(players.FMagicControl.FSpells);
                FResearchSpellID = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FMagicControl.FResearchSpellID;
                FResearchPointsLeft = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FMagicControl.FResearchPointsLeft;
                RandSeed = AoWEUnit.AoWHSMap.Random(16777215);
                GenerateTransferUnits(Units);
                Units?.Dispose();
            }
        }

