            Map = (TAoWHSMap)AoWEUnit.AoWEngine.CreatePreviewHSM(FileName, Aow.Formats.GameProfile.WorldMap);
            FTransferPointsMax = Map.FCampaignSettings.FTransferPointsMax;
            if (AoWEUnit.AoWEngine.FCampaign.FDifficultyLevel == TCampaignDifficultyLevel.cdlEasy)
            {
                FTransferPointsMax = Round((double)FTransferPointsMax * 1.5);
            }

            if (AoWEUnit.AoWEngine.FCampaign.FDifficultyLevel == TCampaignDifficultyLevel.cdlHard)
            {
                FTransferPointsMax = Round((double)FTransferPointsMax * 0.5);
            }

            FTransferGoldMax = Map.FCampaignSettings.FTransferGoldMax;
            FTransferManaMax = Map.FCampaignSettings.FTransferManaMax;
            FTransferPointsLeft = FTransferPointsMax;
            Map?.Dispose();
        }

        // Diplomacy.pas:2065
        public void AutoSelect()
        {
            int Points = default;
            bool Done = default;
            TQuadItemList Candidates = default;
            ClearSelection();
            Candidates = new TQuadItemList();
            Done = false;
            while (!Done)
            {
                Candidates.Clear();
                for (int I = 0, last = FHeroes.Count - 1; I <= last; I++)
                {
                    if (FSelectedHeroes.IndexOf(I) == -1)
                    {
                        Points = FHeroes.GetHero(I).GetCampaignTransferPoints();
                        if (Points <= FTransferPointsLeft)
                        {
                            Candidates.AddABCD(0, I, Points, 0);
                        }
                    }
                }

                for (int I = 0, last = FItems.Count - 1; I <= last; I++)
                {
                    if (FSelectedItems.IndexOf(I) == -1)
                    {
                        Points = FItems.GetItem(I).GetCampaignTransferPoints();
                        if (Points <= FTransferPointsLeft)
                        {
                            Candidates.AddABCD(1, I, Points, 0);
                        }
                    }
                }

                for (int I = 0, last = FUnits.Count - 1; I <= last; I++)
                {
                    if (FSelectedUnits.IndexOf(I) == -1)
                    {
                        Points = FUnits.GetUnit(I).GetCampaignTransferPoints();
                        if (Points <= FTransferPointsLeft)
                        {
                            Candidates.AddABCD(2, I, Points, 0);
                        }
                    }
                }

                Candidates.Sort(AoWEUnit.CompareCampaignTransfer);
                if (Candidates.Count != 0)
                {
                    switch (Candidates[0].A)
                    {
                        case 0:
                            AddHero(Candidates[0].B);
                            break;
                        case 1:
                            AddItem(Candidates[0].B);
                            break;
                        case 2:
                            AddUnit(Candidates[0].B);
                            break;
                    }
                }
                else
                {
                    Done = true;
                }
            }

            SetSelectedTransferGold(FTransferPointsMax);
            SetSelectedTransferMana(FTransferPointsMax);
            Candidates?.Dispose();
        }

        // Diplomacy.pas:2109
        public void ExecuteSelection()
        {
            sbyte Player;
            sbyte X = default;
            sbyte Y = default;
            sbyte L = default;
            TLeader Leader;
            TAbstractUnit AUnit;
            THero Hero;
            TItem Item;
            if (AoWEUnit.AoWHSMap != null)
            {
                AoWEUnit.AoWHSMap.SynchroniseBegin();
                AoWEUnit.AoWHSMap.FPlayers.Update();
                Player = (sbyte)(AoWEUnit.AoWHSMap.FPlayers.Count - 1);
                while (Player > 1 && AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType != TPlayerType.ptHuman)
                {
                    Player = (sbyte)(Player - 1);
                }

                if (AoWEUnit.AoWEngine.FCampaign.FCompletedScenarios.Count != 0)
                {
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FMagicControl.FResearchPercentage = FResearchPercentage;
                }

                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FMagicControl.FResearchSpellID = FResearchSpellID;
                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FMagicControl.FResearchPointsLeft = FResearchPointsLeft;
                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FMagicControl.FSpells.Assign(FSpells);
                var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
                players.FInitialGold += FSelectedTransferGold;
                var fPlayersPlayers = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
                fPlayersPlayers.FMagicControl.FExternalMana += FSelectedTransferMana;
                Leader = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FLeader;
                Leader.GetLocation(ref X, ref Y, ref L);
                if (FLeader != null)
                {
                    Leader.Deactivate();
                    Leader.Assign(FLeader, AoWEUnit.AoWEngine);
                    Leader.SetSpherePicksMax((byte)(Leader.GetSphereCount() + FSelectedSpheres.Count));
                    for (int I = 0, last = FSelectedSpheres.Count - 1; I <= last; I++)
                    {
                        Leader.AddSphere((TMagicSphere)FSelectedSpheres[I]);
                    }

                    for (int J = FSelectedItems.Count - 1; J >= 0; J--)
                    {
                        var item = FSelectedItems[J];
                        Item = FItems.GetItem(item);
                        if (Leader.FUnitID == Item.FItemID)
                        {
                            var fSelectedItemsItem = FSelectedItems[J];
                            Item = (TItem)FItems.GetItem(fSelectedItemsItem).Copy(AoWEUnit.AoWEngine);
                            if (Leader.AutoPlaceItem(Item))
                            {
                                FSelectedItems.Delete(J);
                            }

                            Item.Release();
                        }
                    }

                    Leader.FUnitID = -1;
                    Leader.SetPlayer(Player);
                    Leader.Activate();
                }

                for (int I = FSelectedUnits.Count - 1; I >= 0; I--)
                {
                    var item = FSelectedUnits[I];
                    AUnit = (TAbstractUnit)FUnits.GetUnit(item).Copy(AoWEUnit.AoWEngine);
                    AUnit.FUnitID = -1;
                    AUnit.Place(X, Y, L, Player, TSet<TUnitPlaceModeElement>.Of(TUnitPlaceModeElement.pmScanArea));
                    AUnit.Release();
                }

                for (int I = FSelectedHeroes.Count - 1; I >= 0; I--)
                {
                    var item = FSelectedHeroes[I];
                    Hero = (THero)FHeroes.GetHero(item).Copy(AoWEUnit.AoWEngine);
                    for (int J = FSelectedItems.Count - 1; J >= 0; J--)
                    {
                        var fSelectedItemsItem = FSelectedItems[J];
                        Item = FItems.GetItem(fSelectedItemsItem);
                        if (Hero.FUnitID == Item.FItemID)
                        {
                            var item2 = FSelectedItems[J];
                            Item = (TItem)FItems.GetItem(item2).Copy(AoWEUnit.AoWEngine);
                            if (Hero.AutoPlaceItem(Item))
                            {
                                FSelectedItems.Delete(J);
                            }

                            Item.Release();
                        }
                    }

                    Hero.FUnitID = -1;
                    Hero.FMode = Hero.FMode + TSet<THeroModeElement>.Of(THeroModeElement.hmSkipLibraryUpdate);
                    Hero.Place(X, Y, L, Player, TSet<TUnitPlaceModeElement>.Of(TUnitPlaceModeElement.pmScanArea));
                    Hero.FMode = Hero.FMode - TSet<THeroModeElement>.Of(THeroModeElement.hmSkipLibraryUpdate);
                    Hero.Release();
                }

                for (int I = FSelectedItems.Count - 1; I >= 0; I--)
                {
                    var item = FSelectedItems[I];
                    Item = (TItem)FItems.GetItem(item).Copy(AoWEUnit.AoWEngine);
                    AoWEUnit.AoWHSMap.FItemControl.RegisterItem(Item);
                    Item.PlaceOnMap(AoWEUnit.AoWHSMap, X, Y, L);
                    Item.Release();
                }

                AoWEUnit.AoWHSMap.SynchroniseEnd();
            }
        }

