        // Diplomacy.pas:2343
        public virtual void SetupScenario()
        {
            sbyte Player;
            int Level;
            TSpell Spell;
            TRace Race;
            byte Relation;
            Player = (sbyte)(AoWEUnit.AoWHSMap.FPlayers.Count - 1);
            while (Player > 1 && AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType != TPlayerType.ptHuman)
            {
                Player = (sbyte)(Player - 1);
            }

            Level = 1 + FCompletedScenarios.Count / 4;
            for (int I = 1, last = AoWEUnit.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
            {
                if (I != Player)
                {
                    for (int J = 0, lastJ = AoWEUnit.AoWHSSet.FSpellControl.GetCount() - 1; J <= lastJ; J++)
                    {
                        Spell = AoWEUnit.AoWHSSet.FSpellControl.GetSpell(J);
                        bool condition = Spell != null && Spell.FSpellLevel <= Level;
                        if (condition)
                        {
                            var spherePicks = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FLeader.GetSpherePicks(Spell.FMagicSphere);
                            condition = Spell.FSpellLevel <= spherePicks;
                        }

                        if (condition)
                        {
                            if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FMagicControl.FSpells.IndexOf(J) == -1)
                            {
                                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FMagicControl.FSpells.Add(J);
                            }
                        }
                    }
                }
            }

            for (int I = 1, last = AoWEUnit.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
            {
                if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType != TPlayerType.ptHuman && AoWEUnit.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)I, Player) != TDiplomaticRelation.drAlliance)
                {
                    if (FDifficultyLevel == TCampaignDifficultyLevel.cdlEasy)
                    {
                        switch (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType)
                        {
                            case TPlayerType.ptCPU2:
                                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType = TPlayerType.ptCPU1;
                                break;
                            case TPlayerType.ptCPU3:
                                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType = TPlayerType.ptCPU2;
                                break;
                            case TPlayerType.ptCPU4:
                                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType = TPlayerType.ptCPU3;
                                break;
                            case TPlayerType.ptCPU5:
                                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType = TPlayerType.ptCPU3;
                                break;
                        }
                    }

                    if (FDifficultyLevel == TCampaignDifficultyLevel.cdlHard)
                    {
                        switch (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType)
                        {
                            case TPlayerType.ptCPU1:
                                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType = TPlayerType.ptCPU3;
                                break;
                            case TPlayerType.ptCPU2:
                                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType = TPlayerType.ptCPU4;
                                break;
                            case TPlayerType.ptCPU3:
                                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType = TPlayerType.ptCPU5;
                                break;
                            case TPlayerType.ptCPU4:
                                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType = TPlayerType.ptCPU5;
                                break;
                        }
                    }
                }
            }

            AoWEUnit.AoWHSMap.SetupPlayerControl(FPlayMode, TPlayerConnectionType.pcLocal);
            for (int R = 0, last = AoWEUnit.AoWHSMap.FRaces.Count - 1; R <= last; R++)
            {
                if (AoWEUnit.AoWHSMap.FRaces.GetRace(R) != null)
                {
                    Race = AoWEUnit.AoWHSMap.FRaces.GetRace(R);
                    if (Race != null)
                    {
                        for (int I = 0; I <= 11; I++)
                        {
                            if ((FRaceHistory.IndexOf((byte)I) != -1 || I == AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerRace) && AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerRace == R || (FRaceHistory.IndexOf((byte)R) != -1 || AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerRace == R) && I == AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerRace)
                            {
                                Relation = Race.FDefaultRelations[I];
                                switch (Relation)
                                {
                                    case 0:
                                        Relation = 3;
                                        break;
                                    case 1:
                                        Relation = 3;
                                        break;
                                    case 2:
                                        Relation = 4;
                                        break;
                                    case 3:
                                        Relation = 4;
                                        break;
                                }

                                Race.FDefaultRelations[I] = Relation;
                            }
                        }
                    }
                }
            }

            AoWEUnit.AoWHSMap.FAlliedVictory = AoWEUnit.AoWHSMap.FCampaignSettings.FAlliedVictory;
            FTransferSettings.ExecuteSelection();
            FScenarioStarted = true;
        }

        // Diplomacy.pas:2416
        public virtual void FinishScenario()
        {
            sbyte Player;
            string FileName;
            FScenarioStarted = false;
            FCompletedScenarios.Add(FCurrentScenarioID);
            FTransferSettings.Retrieve();
            FStream.Clear();
            Player = (sbyte)(AoWEUnit.AoWHSMap.FPlayers.Count - 1);
            while (Player > 1 && AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType != TPlayerType.ptHuman)
            {
                Player = (sbyte)(Player - 1);
            }

            var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
            if (FRaceHistory.IndexOf((byte)players.FPlayerRace) == -1)
            {
                var fPlayersPlayers = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
                FRaceHistory.Add((byte)fPlayersPlayers.FPlayerRace);
            }

            FileName = GetAutoSaveFileName(TCampaignAutoSaveType.casScenarioFinished);
            AoWEUnit.AoWEngine.SaveCampaign(AoWEUnit.AoWEngine.StartupDirectory + "Save\\" + FileName);
        }

        // Diplomacy.pas:2432
        public virtual void RestartScenario()
        {
            if (FCompletedScenarios.Count != 0)
            {
                FCurrentScenarioID = FCompletedScenarios[FCompletedScenarios.Count - 1];
            }
            else
            {
                FCurrentScenarioID = 0;
            }

            FScenarioStarted = false;
            FStream.Clear();
        }

        // Diplomacy.pas:2285
        public virtual TAoWCampaignScenario AddScenario()
        {
            TAoWCampaignScenario Result = CreateScenario();
            Result.FID = FScenarios.CreateUniqueID();
            Result.SetOwner(FScenarios);
            return Result;
        }

        // Diplomacy.pas:2292
        public bool GetContainsMap() => FStream.Length != 0;

        // intf_P5_08.inc:107

    }

    // RefCount, Day, Source, Target, OtherPlayer, Reaction, EscrowGold, EscrowMana, EventLogID and the
    // proposal (AoWE.DiplomaticProposals.cs), stored as ActionType, Gold, Mana and Message
    public partial class TDiplomaticAction : TEObject
    {
        // Diplomacy.pas:495
        public new const int ClassID = 131666;

        // Diplomacy.pas:482
        public TDiplomaticAction(TECustomNode owner) : base(owner)
        {
            FRefCount = 1;
        }

        public int FRefCount;
        public int FDay;
        public sbyte FSource;
        public sbyte FTarget;
        // The census finds it written for every kind, 255 for the kinds that name no other player.
        public sbyte FOtherPlayer;
        public TDiplomaticActionReaction FReaction;
        public DiplomaticProposal Proposal = new DeclareWar();
        public int FEscrowGold;
        public int FEscrowMana;
        public int FEventLogID;

        // Diplomacy.pas:596
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            var (kind, gold, mana) = Proposal.ToFields();
            var message = new TStringList();
            foreach (var line in Proposal.Message)
            {
                message.Add(line);
            }

            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FSource), 20);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FTarget), 21);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FOtherPlayer), 22);
            Stream.rwInteger(ref gold, 23);
            Stream.rwInteger(ref mana, 24);
            Stream.rwData(Bytes.Of(ref kind, 1), 1, 25);
            Stream.rwData(Bytes.Of(ref FReaction, 1), 1, 26);
            Stream.rwStrings(message, 27);
            if (Stream.StorageMode().Contains(TStorageModeElement.smRead))
            {
                Proposal = DiplomaticProposal.FromFields(kind, gold, mana) with { Message = DiplomaticProposal.Lines(message) };
            }

            message?.Dispose();
            Stream.rwInteger(ref FEscrowGold, 28);
            Stream.rwInteger(ref FEscrowMana, 29);
            Stream.rwInteger(ref FEventLogID, 30);
            Stream.rwInteger(ref FDay, 31);
        }

        // Diplomacy.pas:586
        public override int AddRef()
        {
            FRefCount += 1;
            return FRefCount;
        }

        // Diplomacy.pas:589
        public override int Release()
        {
            FRefCount -= 1;
            int Result = FRefCount;
            if (FRefCount == 0)
            {
                Dispose();
            }

            return Result;
        }

        // Diplomacy.pas:613
        public override void MsgProc(ref TEMsg Msg, TEObject Sender)
        {
            bool Ignore;
            TEventLog Log;
            base.MsgProc(ref Msg, Sender);
            if (Msg.MsgID == 537001986 && Msg.Payload.Int == FSource && FReaction == TDiplomaticActionReaction.darNone)
            {
                Ignore = Proposal.LapsesUnanswered(this);
                if (Ignore && (AoWEUnit.AoWHSMap.FPlayMode != TPlayMode.pmSimultaneous || AoWEUnit.AoWHSMap.FDay > FDay + 1))
                {
                    FReaction = TDiplomaticActionReaction.darIgnore;
                    Log = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FTarget).FEventLogbook.FindID(FEventLogID);
                    Assert(Log is TDiplomaticActionEventLog, "", "Diplomacy.pas", 697);
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FSource).FEventLogbook.AddEvent(Log);
                    var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FSource);
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FSource).SetGems(players.FGems + FEscrowGold);
                    var fPlayersPlayers = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FSource);
                    AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FSource).FMagicControl.SetMana(fPlayersPlayers.FMagicControl.FMana + FEscrowMana);
                    FEscrowGold = 0;
                    FEscrowMana = 0;
                }
            }
        }

        // Diplomacy.pas:992
        public virtual void ExecuteSend(TDiplomaticActionTE TE)
        {
            if (FReaction == TDiplomaticActionReaction.darNone)
            {
                var (_, gold, mana) = Proposal.ToFields();
                FEscrowGold = gold;
                var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FSource);
                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FSource).SetGems(players.FGems - gold);
                FEscrowMana = mana;
                var fPlayersPlayers = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FSource);
                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FSource).FMagicControl.SetMana(fPlayersPlayers.FMagicControl.FMana - mana);
                Proposal.Sent(this);
            }
        }

        // Diplomacy.pas:826
        public virtual void ExecuteAccept(TDiplomaticActionTE TE)
        {
            FReaction = TDiplomaticActionReaction.darAccept;
            RetrieveDefaultMessage(FSource, FTarget, FOtherPlayer, FReaction);
            var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FTarget);
            AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FTarget).SetGems(players.FGems + FEscrowGold);
            FEscrowGold = 0;
            var fPlayersPlayers = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FTarget);
            AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FTarget).FMagicControl.SetMana(fPlayersPlayers.FMagicControl.FMana + FEscrowMana);
            FEscrowMana = 0;
            ApplyRelationModifiers();
            Proposal.Accepted(this);
        }

        // Diplomacy.pas:950
        public virtual void ExecuteReject(TDiplomaticActionTE TE)
        {
            TDiplomaticActionEventLog Log;
            FReaction = Proposal.RejectReaction(this);
            var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FSource);
            AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FSource).SetGems(players.FGems + FEscrowGold);
            FEscrowGold = 0;
            var fPlayersPlayers = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FSource);
            AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FSource).FMagicControl.SetMana(fPlayersPlayers.FMagicControl.FMana + FEscrowMana);
            FEscrowMana = 0;
            RetrieveDefaultMessage(FSource, FTarget, FOtherPlayer, FReaction);
            Log = (TDiplomaticActionEventLog)AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FTarget).FEventLogbook.FindID(FEventLogID);
            Log.SetDiplomaticAction(this);
            AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FSource).FEventLogbook.AddEvent(Log);
        }

        // Diplomacy.pas:722
        public virtual void ExecuteAI(sbyte Player)
        {
            TByteList Peace;
            TByteList War;
            TByteList Unknown;
            TByteList IdealPeace;
            TByteList IdealWar;
            TDiplomaticRelation Relation;
            TDiplomaticActionReaction Reaction;
            Reaction = FReaction;
            if (Reaction == TDiplomaticActionReaction.darNone)
            {
                Relation = AoWEUnit.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FSource, (sbyte)(byte)FTarget);
                IdealPeace = new TByteList();
                IdealWar = new TByteList();
                Peace = new TByteList();
                War = new TByteList();
                Unknown = new TByteList();
                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FTarget).FAIControl.ListPeaceWarUnknownPlayers(Peace, War, Unknown);
                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FTarget).FAIControl.ListIdealPeaceWarPlayers(IdealPeace, IdealWar);
                Proposal.AnswerAI(this, Player, Relation, IdealPeace, IdealWar);
                Peace?.Dispose();
                War?.Dispose();
                Unknown?.Dispose();
                IdealPeace?.Dispose();
                IdealWar?.Dispose();
            }
            else
            {
                if (TSet<TDiplomaticActionReaction>.Of(TDiplomaticActionReaction.darReject, TDiplomaticActionReaction.darIgnore).Contains(Reaction))
                {
                    Proposal.RefusedAI(this);
                }
            }
        }

        // Diplomacy.pas:1055
        public virtual bool CanSend(ref string ErrorText)
        {
            bool Result;
            var (_, gold, mana) = Proposal.ToFields();
            if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FSource).FGems >= gold)
            {
                if (AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FSource).FMagicControl.FMana >= mana)
                {
                    Result = Proposal.CanSend(this, ref ErrorText);
                }
                else
                {
                    Result = false;
                    ErrorText = AoWEUnit.TranslateRStr(AoWEUnit.P5NotEnoughManaRStr);
                }
            }
            else
            {
                Result = false;
                ErrorText = AoWEUnit.TranslateRStr(AoWEUnit.P5NotEnoughGoldRStr);
            }

            return Result;
        }

        // Diplomacy.pas:1081
        public virtual bool Send(ref string ErrorText)
        {
            bool Result;
            TDiplomaticActionTE TE;
            if (CanSend(ref ErrorText) && !AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FSource).GetBusy())
            {
                FDay = AoWEUnit.AoWHSMap.FDay;
                TE = new TDiplomaticActionTE(null);
                TE.SetDiplomaticAction(this);
                TE.FOperation = 0;
                AoWEUnit.AoWHSMap.FTokenManager.TokenControls[FSource].AddEvent(TE);
                TE.Release();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Diplomacy.pas:920
        public virtual bool CanAccept(ref string ErrorText) => true;

        // Diplomacy.pas:923
        public virtual bool Accept(ref string ErrorText)
        {
            bool Result;
            TDiplomaticActionTE TE;
            if (CanAccept(ref ErrorText) && !AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FTarget).GetBusy())
            {
                TE = new TDiplomaticActionTE(null);
                TE.SetDiplomaticAction(this);
                TE.FOperation = 1;
                AoWEUnit.AoWHSMap.FTokenManager.TokenControls[FTarget].AddEvent(TE);
                TE.Release();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Diplomacy.pas:974
        public virtual bool CanReject(ref string ErrorText) => true;

        // Diplomacy.pas:977
        public virtual bool Reject(ref string ErrorText)
        {
            bool Result;
            TDiplomaticActionTE TE;
            if (CanReject(ref ErrorText) && !AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FTarget).GetBusy())
            {
                TE = new TDiplomaticActionTE(null);
                TE.SetDiplomaticAction(this);
                TE.FOperation = 2;
                AoWEUnit.AoWHSMap.FTokenManager.TokenControls[FTarget].AddEvent(TE);
                TE.Release();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Diplomacy.pas:505
        public string GetName(sbyte Player) => Proposal.Name(this);

        // Diplomacy.pas:527
        public int GetRelationModifier(sbyte Player, sbyte Race) => Proposal.RelationModifier(this, Player, Race);

        // Diplomacy.pas:707
        public TDiplomaticActionEventLog CreateEventLog()
        {
            TDiplomaticActionEventLog Log;
            Log = new TDiplomaticActionEventLog(null);
            Log.FDay = AoWEUnit.AoWHSMap.FDay;
            Log.SetDiplomaticAction(this);
            return Log;
        }

        // Diplomacy.pas:938
        public void UpdateAIDiplomaticActionsLog(sbyte Player)
        {
            TDiplomaticAction Action;
            var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
            if (TSet<TPlayerType>.Of().WithRange(TPlayerType.ptCPU1, TPlayerType.ptCPU3).WithRange(TPlayerType.ptCPU4, TPlayerType.ptCPU5).Contains(players.FPlayerType))
            {
                Action = (TDiplomaticAction)Copy(AoWEUnit.AoWEngine);
                Action.Proposal = Action.Proposal with { Message = [] };
                AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FDiplomaticActions.AddChild(Action);
                Action.Release();
            }
        }

