namespace Aow.Game.Commands
{

    // Operation, Action
    public partial class TDiplomaticActionTE : TTokenEvent
    {
        public TDiplomaticActionTE(TECustomNode owner) : base(owner)
        { }

        // Diplomacy.pas:1125
        public new const int ClassID = 135432;

        public int FOperation;
        public TDiplomaticAction FAction;

        // Diplomacy.pas:1117
        public override void Dispose()
        {
            TDiplomaticAction Action;
            base.Dispose();
            Action = FAction;
            if (Action != null)
            {
                Action.Release();
            }
        }

        // Diplomacy.pas:1140
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwCreateEObject(ref FAction, null, 20);
            Stream.rwInteger(ref FOperation, 21);
        }

        // Diplomacy.pas:1147
        public override TExecuteResult Execute(TTokenExecuter TE)
        {
            string ErrorText = "";
            switch (FOperation)
            {
                case 0:
                    if (FAction.CanSend(ref ErrorText))
                    {
                        FAction.ExecuteSend(this);
                        FAction.UpdateAIDiplomaticActionsLog(FAction.FSource);
                    }

                    break;
                case 1:
                    if (FAction.CanAccept(ref ErrorText))
                    {
                        FAction.ExecuteAccept(this);
                        FAction.UpdateAIDiplomaticActionsLog(FAction.FTarget);
                    }

                    break;
                case 2:
                    if (FAction.CanReject(ref ErrorText))
                    {
                        FAction.ExecuteReject(this);
                        FAction.UpdateAIDiplomaticActionsLog(FAction.FTarget);
                    }

                    break;
            }

            return TExecuteResult.erDone;
        }

        // Diplomacy.pas:1128
        public void SetDiplomaticAction(TDiplomaticAction Action)
        {
            TDiplomaticAction Old;
            Old = FAction;
            if (Old != Action)
            {
                if (Old != null)
                {
                    Old.Release();
                }

                FAction = Action;
                if (FAction != null)
                {
                    FAction.AddRef();
                }
            }
        }

        // NetworkE.pas:230

    }
}

