        // Diplomacy.pas:1265
        public override string GetText() => FAction.Proposal.LogText(FAction);

        // Diplomacy.pas:1228
        public override int GetTextColor()
        {
            int Result;
            int Race;
            if (FAction.Proposal.SignedAsOtherPlayer)
            {
                bool condition = FAction.FOtherPlayer > 0;
                if (condition)
                {
                    var count = AoWEUnit.AoWHSMap.FPlayers.Count;
                    condition = FAction.FOtherPlayer < count;
                }

                if (condition)
                {
                    Race = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FAction.FOtherPlayer).FPlayerRace;
                }
                else
                {
                    Race = 12;
                }

                Result = AoWEUnit.P5RaceColors[Race];
            }
            else
            {
                if (FAction.FReaction == TDiplomaticActionReaction.darAccept)
                {
                    bool condition = FAction.FTarget > 0;
                    if (condition)
                    {
                        var count = AoWEUnit.AoWHSMap.FPlayers.Count;
                        condition = FAction.FTarget < count;
                    }

                    if (condition)
                    {
                        Race = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FAction.FTarget).FPlayerRace;
                    }
                    else
                    {
                        Race = 12;
                    }

                    Result = AoWEUnit.P5RaceColors[Race];
                }
                else
                {
                    if (AoWEUnit.AoWHSMap.FSeatedPlayer != FAction.FSource)
                    {
                        bool condition = FAction.FSource > 0;
                        if (condition)
                        {
                            var count = AoWEUnit.AoWHSMap.FPlayers.Count;
                            condition = FAction.FSource < count;
                        }

                        if (condition)
                        {
                            Race = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FAction.FSource).FPlayerRace;
                        }
                        else
                        {
                            Race = 12;
                        }

                        Result = AoWEUnit.P5RaceColors[Race];
                    }
                    else
                    {
                        bool condition = FAction.FTarget > 0;
                        if (condition)
                        {
                            var count = AoWEUnit.AoWHSMap.FPlayers.Count;
                            condition = FAction.FTarget < count;
                        }

                        if (condition)
                        {
                            Race = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(FAction.FTarget).FPlayerRace;
                        }
                        else
                        {
                            Race = 12;
                        }

                        Result = AoWEUnit.P5RaceColors[Race];
                    }
                }
            }

            return Result;
        }

        // Diplomacy.pas:1333
        public override int GetLeftIcon()
        {
            int Result;
            TDiplomaticAction Action;
            Action = FAction;
            if (!Action.Proposal.SignedAsOtherPlayer)
            {
                bool condition = Action.FSource > 0;
                if (condition)
                {
                    var count = AoWEUnit.AoWHSMap.FPlayers.Count;
                    condition = Action.FSource < count;
                }

                if (condition)
                {
                    Result = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Action.FSource).FPlayerRace;
                }
                else
                {
                    Result = -1;
                }
            }
            else
            {
                bool condition = Action.FOtherPlayer > 0;
                if (condition)
                {
                    var count = AoWEUnit.AoWHSMap.FPlayers.Count;
                    condition = Action.FOtherPlayer < count;
                }

                if (condition)
                {
                    Result = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Action.FOtherPlayer).FPlayerRace;
                }
                else
                {
                    Result = -1;
                }
            }

            return Result;
        }

        // Diplomacy.pas:1379
        // { DCC32 folds JMP-to-RET; keep the original branch over the 11-byte arms. }
        public override int GetRightIcon()
        {
            int Result;
            TDiplomaticAction Action;
            Action = FAction;
            bool condition = Action.FTarget > 0;
            if (condition)
            {
                var count = AoWEUnit.AoWHSMap.FPlayers.Count;
                condition = Action.FTarget < count;
            }

            if (condition)
            {
                Result = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Action.FTarget).FPlayerRace;
            }
            else
            {
                Result = -1;
            }

            return Result;
        }

        // Diplomacy.pas:1225
        public override bool GetVisible() => true;

        // Diplomacy.pas:1208
        public override void PlayLoggedSFX(TEventLogbook Logbook) => PlaySample(FAction.Proposal.LoggedSample);

        // Diplomacy.pas:1217
        public override void NotifyLogged(TEventLogbook Logbook)
        {
            TDiplomaticAction Action;
            base.NotifyLogged(Logbook);
            Action = FAction;
            if (Action != null)
            {
                Action.FEventLogID = FID;
            }
        }

        // Diplomacy.pas:1414
        public override bool Execute(bool Mode, TExecuteTrigger Trigger, TExecuteDoneEvent Done)
        {
            bool Result = default;
            bool Show;
            Show = Trigger == TExecuteTrigger.etUser;
            if (AoWEUnit.AoWHSMap.FSeatedPlayer == FAction.FTarget || AoWEUnit.AoWHSMap.FSeatedPlayer == FAction.FSource)
            {
                Show = Show || AoWEUnit.AoWHSMap.FPlayMode == TPlayMode.pmTurn && AoWEUnit.AoWEngine.FRegistry.GetClassicWindowPopupEvents().Contains(TWindowPopupEvent.wpDiplomacy) && Trigger == TExecuteTrigger.etNewTurn;
                Show = Show || AoWEUnit.AoWHSMap.FPlayMode == TPlayMode.pmSimultaneous && AoWEUnit.AoWEngine.FRegistry.GetSimultaneousWindowPopupEvents().Contains(TWindowPopupEvent.wpDiplomacy);
            }

            Show = Show && (Trigger == TExecuteTrigger.etUser || FAction.FReaction != TDiplomaticActionReaction.darIgnore);
            if (Show)
            {
                AoWEUnit.AoWHSMap.TriggerExecuteEventLog(this, Mode, Done);
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Diplomacy.pas:1188
        public void SetDiplomaticAction(TDiplomaticAction Action)
        {
            TDiplomaticAction Old;
            Old = FAction;
            if (Old != Action)
            {
                if (Old != null)
                {
                    Old.Release();
                }

                if (Action != null)
                {
                    FAction = (TDiplomaticAction)Action.Copy(AoWEUnit.AoWEngine);
                }
                else
                {
                    FAction = null;
                }
            }
        }

        public override int GetMiddleIcon() => FAction.Proposal.MiddleIcon(FAction);
    }
}

namespace Aow.Game.Ai
{

    public partial class TDiplomacyAIPA : TAIPlayerAction, IAIPlayerActionClass
    {
        // Diplomacy.pas:1540
        public TDiplomacyAIPA(TECustomNode owner) : base(owner)
        {
        }

        public sbyte FNextPlayer;

        // Diplomacy.pas:1549
        public override bool Activate()
        {
            bool Result = base.Activate();
            FNextPlayer = 0;
            return Result;
        }

        // Diplomacy.pas:1699
        public override bool Process()
        {
            bool Result;
            base.Process();
            if (FControl.FPlayer.FPlayerIndex != 0)
            {
                while (true)
                {
                    var count = AoWEUnit.AoWHSMap.FPlayers.Count;
                    if (!(FNextPlayer < count && !FControl.FPlayer.GetBusy()))
                        break;
                    FNextPlayer = (sbyte)(FNextPlayer + 1);
                    while (true)
                    {
                        var fPlayersCount = AoWEUnit.AoWHSMap.FPlayers.Count;
                        if (!(FNextPlayer < fPlayersCount && (FControl.FPlayer.GetFirstDaySeen((sbyte)(byte)FNextPlayer) == -1 || FControl.FPlayer.FPlayerIndex == FNextPlayer)))
                            break;
                        FNextPlayer = (sbyte)(FNextPlayer + 1);
                    }

                    var count2 = AoWEUnit.AoWHSMap.FPlayers.Count;
                    if (FNextPlayer < count2)
                    {
                        ExecuteDiplomacy(FNextPlayer);
                    }
                }

                var count3 = AoWEUnit.AoWHSMap.FPlayers.Count;
                Result = FNextPlayer < count3;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Diplomacy.pas:1552
        public TDiplomaticAction CreateDA(DiplomaticProposal Action, sbyte Target, sbyte Other, int MinDays)
        {
            TDiplomaticAction Result;
            sbyte Player;
            TDiplomaticAction Last;
            Player = FControl.FPlayer.FPlayerIndex;
            Last = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).FDiplomaticActions.FindLastAction(Action.ToFields().Kind, TDiplomaticActionReaction.darNone, Player, Target, Other);
            if (Last == null || AoWEUnit.AoWHSMap.FDay - Last.FDay >= MinDays)
            {
                Result = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).CreateDiplomaticAction(Action, Target, Other);
            }
            else
            {
                Result = null;
            }

            return Result;
        }

        // Diplomacy.pas:1563
        public bool ExecuteDiplomacy(sbyte Player)
        {
            TDiplomaticAction Action;
            TByteList Peace;
            TByteList War;
            TByteList Unknown;
            TByteList IdealPeace;
            TByteList IdealWar;
            TDoubleItemList Candidates;
            int Index;
            int Score;
            sbyte Source;
            sbyte Candidate;
            string ErrorText = "";
            // { Original bug: the result remains False even when an action is sent. }
            bool Result = false;
            Action = null;
            Source = FControl.FPlayer.FPlayerIndex;
            IdealPeace = new TByteList();
            IdealWar = new TByteList();
            Peace = new TByteList();
            War = new TByteList();
            Unknown = new TByteList();
            FControl.ListPeaceWarUnknownPlayers(Peace, War, Unknown);
            FControl.ListIdealPeaceWarPlayers(IdealPeace, IdealWar);
            switch (AoWEUnit.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)Source, (sbyte)(byte)Player))
            {
                case TDiplomaticRelation.drUnknown:
                    if (IdealPeace.IndexOf((byte)Player) != -1)
                    {
                        if (FControl.CanOfferPeace((byte)Player))
                        {
                            Action = CreateDA(new OfferPeace(), Player, -1, 10);
                        }
                        else
                        {
                            Action = CreateDA(new DeclareWar(), Player, -1, -1);
                        }
                    }

                    if (IdealWar.IndexOf((byte)Player) != -1)
                    {
                        if (FControl.CanDeclareWar((byte)Player))
                        {
                            Action = CreateDA(new DeclareWar(), Player, -1, -1);
                        }
                        else
                        {
                            Action = CreateDA(new OfferPeace(), Player, -1, 10);
                        }
                    }

                    break;
                case TDiplomaticRelation.drPeace:
                    if (!FControl.CanOfferPeace((byte)Player) && IdealWar.IndexOf((byte)Player) != -1)
                    {
                        RandSeed = AoWEUnit.AoWHSMap.FInitialRandomSeed + AoWEUnit.AoWHSMap.FDay + Source;
                        Index = Random(IdealWar.Count);
                        if (IdealWar[Index] == Player)
                        {
                            Action = CreateDA(new DeclareWar(), Player, -1, -1);
                        }
                    }
                    else
                    {
                        if (FControl.CanProposeAlliance((byte)Player))
                        {
                            RandSeed = (int)(((uint)(AoWEUnit.AoWHSMap.FInitialRandomSeed + AoWEUnit.AoWHSMap.FDay + Source)) >> 2);
                            if (Random(100) < 30)
                            {
                                Action = CreateDA(new ProposeAlliance(), Player, -1, 10);
                            }
                        }
                    }

                    break;
                case TDiplomaticRelation.drAlliance:
                    if (!FControl.CanOfferPeace((byte)Player) && IdealWar.IndexOf((byte)Player) != -1)
                    {
                        RandSeed = AoWEUnit.AoWHSMap.FInitialRandomSeed + AoWEUnit.AoWHSMap.FDay + Source + 1;
                        Index = Random(IdealWar.Count);
                        if (IdealWar[Index] == Player)
                        {
                            Action = CreateDA(new BreakAlliance(), Player, -1, -1);
                        }
                    }

                    break;
                case TDiplomaticRelation.drWar:
                    if (!FControl.CanDeclareWar((byte)Player))
                    {
                        Candidates = new TDoubleItemList();
                        for (int I = 0, last = IdealPeace.Count - 1; I <= last; I++)
                        {
                            Candidate = (sbyte)IdealPeace[I];
                            if (War.IndexOf((byte)Candidate) != -1 && FControl.CanOfferPeace((byte)Candidate))
                            {
                                Action = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Source).FDiplomaticActions.FindLastAction(OfferPeace.Kind, TDiplomaticActionReaction.darNone, Source, Candidate, -1);
                                if (Action == null || AoWEUnit.AoWHSMap.FDay - Action.FDay > 12)
                                {
                                    Score = -I;
                                    Score -= AoWEUnit.AoWHSMap.FPlayers.GetDiplomaticRelationCount((sbyte)(byte)Candidate, TSet<TDiplomaticRelation>.Of(TDiplomaticRelation.drPeace)) * 5;
                                    Score -= AoWEUnit.AoWHSMap.FPlayers.GetDiplomaticRelationCount((sbyte)(byte)Candidate, TSet<TDiplomaticRelation>.Of(TDiplomaticRelation.drAlliance)) * 10;
                                    Candidates.AddAB(Candidate, Score);
                                }

                                Action = null;
                            }
                        }

                        if (Candidates.Count == 0 && War.Count - Peace.Count > 2)
                        {
                            for (int J = 0, last = IdealWar.Count - 1; J <= last; J++)
                            {
                                Candidate = (sbyte)IdealWar[J];
                                if (War.IndexOf((byte)Candidate) != -1)
                                {
                                    Action = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Source).FDiplomaticActions.FindLastAction(OfferPeace.Kind, TDiplomaticActionReaction.darNone, Source, Candidate, -1);
                                    if (Action == null || AoWEUnit.AoWHSMap.FDay - Action.FDay > 12)
                                    {
                                        Score = J;
                                        Score -= AoWEUnit.AoWHSMap.FPlayers.GetDiplomaticRelationCount((sbyte)(byte)Candidate, TSet<TDiplomaticRelation>.Of(TDiplomaticRelation.drPeace)) * 5;
                                        Score -= AoWEUnit.AoWHSMap.FPlayers.GetDiplomaticRelationCount((sbyte)(byte)Candidate, TSet<TDiplomaticRelation>.Of(TDiplomaticRelation.drAlliance)) * 10;
                                        Candidates.AddAB(Candidate, Score);
                                    }

                                    Action = null;
                                }
                            }
                        }

                        if (Candidates.Count != 0)
                        {
                            Candidates.SortDescendingItemB();
                            if (Candidates[0].A == Player)
                            {
                                Action = CreateDA(new OfferPeace(), (sbyte)Candidates[0].A, -1, -1);
                            }
                        }

                        Candidates?.Dispose();
                    }

                    break;
            }

            if (Action != null)
            {
                Action.Send(ref ErrorText);
                Action.Release();
            }

            Peace?.Dispose();
            War?.Dispose();
            Unknown?.Dispose();
            IdealPeace?.Dispose();
            IdealWar?.Dispose();
            return Result;
        }

        // Diplomacy.pas:1670
        public void ListDebugInfo()
        {
            TByteList IdealPeace;
            TByteList IdealWar;
            int Player;
            string S;
            IdealPeace = new TByteList();
            IdealWar = new TByteList();
            FControl.ListIdealPeaceWarPlayers(IdealPeace, IdealWar);
            Player = FControl.FPlayer.FPlayerIndex;
            var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player);
            S = AoWEUnit.TranslateRStr(AoWEUnit.RaceNamesPluralRStr[players.FPlayerRace]);
            var name = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(Player).GetName();
            S = S + "/" + name;
            AoWEUnit.AoWEngine.OutputDebugMessage(AoWEUnit.AIDID, "DIPLOMACY (" + S + ")");
            AoWEUnit.AoWEngine.OutputDebugMessage(AoWEUnit.AIDID, "IDEAL PEACE PLAYERS");
            for (int I = 0, last = IdealPeace.Count - 1; I <= last; I++)
            {
                var item = IdealPeace[I];
                var fPlayersPlayers = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(item);
                S = AoWEUnit.TranslateRStr(AoWEUnit.RaceNamesPluralRStr[fPlayersPlayers.FPlayerRace]);
                var idealPeaceItem = IdealPeace[I];
                var name2 = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(idealPeaceItem).GetName();
                S = S + "/" + name2;
                AoWEUnit.AoWEngine.OutputDebugMessage(AoWEUnit.AIDID, S);
            }

            AoWEUnit.AoWEngine.OutputDebugMessage(AoWEUnit.AIDID, "IDEAL WAR PLAYERS");
            for (int I = 0, last = IdealWar.Count - 1; I <= last; I++)
            {
                var item = IdealWar[I];
                var name2 = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(item).GetName();
                AoWEUnit.AoWEngine.OutputDebugMessage(AoWEUnit.AIDID, name2);
            }

            IdealPeace?.Dispose();
            IdealWar?.Dispose();
        }

        // intf_P5_08.inc:209

        // Diplomacy.pas:1546
        public static new int Priority => 14;

    }
