        // Army.PAS:5648
        public void TranslateEObject(TEObject Obj, TIvDictionary Dictionary)
        {
            TTranslateTextStream Stream;
            Stream = new TTranslateTextStream(this);
            Stream.FDictionary = Dictionary;
            try
            {
                Stream.rwEObject(Obj, 0);
            }
            finally
            {
                Stream?.Dispose();
            }
        }

        // Army.PAS:5660
        public void TranslateEObjectFromFile(TEObject Obj, string FileName)
        {
            TAoWDictionary Dictionary;
            if (FileExists(FileName))
            {
                Dictionary = new TAoWDictionary(null);
                try
                {
                    Dictionary.FFileName = FileName;
                    Dictionary.Open();
                    switch (FRegistry.GetLanguage())
                    {
                        case TAoWLanguage.alAuto:
                            Dictionary.SetLanguage(-1);
                            break;
                        case TAoWLanguage.alEnglish:
                            Dictionary.SetLanguage(1);
                            break;
                        case TAoWLanguage.alGerman:
                            Dictionary.SetLanguage(2);
                            break;
                        case TAoWLanguage.alFrench:
                            Dictionary.SetLanguage(3);
                            break;
                        case TAoWLanguage.alItalian:
                            Dictionary.SetLanguage(4);
                            break;
                        case TAoWLanguage.alSpanish:
                            Dictionary.SetLanguage(5);
                            break;
                    }

                    TranslateEObject(Obj, Dictionary);
                    Dictionary.Close();
                }
                finally
                {
                    Dictionary?.Dispose();
                }
            }
        }

        // Army.PAS:5725
        public void ExportTextToFile(string FileName, TEObject Obj)
        {
            TExportTextStream Stream;
            Stream FileStream;
            FileStream = OpenFile(FileName, 65535);
            try
            {
                Stream = new TExportTextStream(FileStream, this);
                try
                {
                    Stream.rwEObject(Obj, 0);
                }
                finally
                {
                    Stream?.Dispose();
                }
            }
            finally
            {
                FileStream?.Dispose();
            }
        }

        // Army.PAS:5741
        public string TranslateRStr(string S)
        {
            string Result;
            if (FDictionary.FLanguage > 0)
            {
                Result = FDictionary.Translate(S);
            }
            else
            {
                if (CompareText(S, AoWEUnit.P2UndeadPluralRStr) == 0)
                {
                    Result = AoWEUnit.P2UndeadRStr;
                }
                else
                {
                    Result = S;
                }
            }

            return Result;
        }

        // Army.PAS:5915
        public int GetMajorVersion() => ((int)(((uint)FVersion) >> 24)) & 255;

        // Army.PAS:5918
        public int GetMinorVersion()
        {
            int Result = ((int)(((uint)FVersion) >> 16)) & 255;
            if (Result > 99)
            {
                Result = 99;
            }

            return Result;
        }

        // Army.PAS:5924
        public int GetBuildNumber()
        {
            int Result = FVersion & 65535;
            if (Result > 9999)
            {
                Result = 9999;
            }

            return Result;
        }

        // Army.PAS:5930
        public void SetVersion(int Major, int Minor, int Build)
        {
            if (Major < 0)
            {
                Major = 0;
            }

            if (Major > 99)
            {
                Major = 99;
            }

            if (Minor < 0)
            {
                Minor = 0;
            }

            if (Minor > 99)
            {
                Minor = 99;
            }

            if (Build < 0)
            {
                Build = 0;
            }

            if (Build > 9999)
            {
                Build = 9999;
            }

            FVersion = (Major << 24) + (Minor << 16) + Build;
        }

        // Army.PAS:5941
        public string GetVersionStr()
        {
            int Version;
            string Result = IntToStr(GetMajorVersion()) + ".";
            Version = GetMinorVersion();
            if (Version < 10)
            {
                Result = Result + "0" + IntToStr(Version) + ".";
            }
            else
            {
                Result = Result + IntToStr(Version) + ".";
            }

            Version = GetBuildNumber();
            if (Version < 1000)
            {
                Result = Result + "0";
            }

            if (Version < 100)
            {
                Result = Result + "0";
            }

            if (Version < 10)
            {
                Result = Result + "0";
            }

            return Result + IntToStr(Version);
        }

        // Army.PAS:5983
        public bool RegisteredVersion()
        {
            bool Result = default;
            bool Registered = default;
            MemoryStream Mem;
            Stream FileStream;
            string Name = "";
            try
            {
                Mem = new MemoryStream();
                // { Original leaks Mem if opening or loading the file raises. }
                FileStream = OpenFile(AoWEUnit.AoWEngine.StartupDirectory + "RELEASE\\GENERAL.PFS", 0 | 32);
                try
                {
                    Mem.LoadFromStream(FileStream);
                }
                finally
                {
                    FileStream?.Dispose();
                }

                try
                {
                    Mem.Position = 0;
                    Mem.Read(Bytes.Of(ref Registered, 1));
                    StringFromStream(ref Name, Mem);
                    Result = Registered;
                }
                finally
                {
                    Mem?.Dispose();
                }
            }
            catch
            {
                Result = true;
            }

            return Result;
        }

        // Army.PAS:6008
        public string RegisteredTo()
        {
            string Result = "";
            bool Registered = default;
            MemoryStream Mem;
            string Name = "";
            try
            {
                Mem = new MemoryStream();
                try
                {
                    Mem.LoadFromFile(AoWEUnit.AoWEngine.StartupDirectory + "RELEASE\\GENERAL.PFS");
                    Mem.Read(Bytes.Of(ref Registered, 1));
                    StringFromStream(ref Name, Mem);
                    Result = AoWEUnit.Encode(Name, 0);
                }
                finally
                {
                    Mem?.Dispose();
                }
            }
            catch
            {
                Result = "";
            }

            return Result;
        }

        // Army.PAS:6026
        public bool RequestAccess(string Name, string Code)
        {
            string RegistrationCode(string Text)
            {
                int Value;
                string Hex;
                string Result = "";
                if (Text.Length >= 4)
                {
                    Value = 0;
                    for (int I = 1; I <= Text.Length; I++)
                    {
                        Value += Cp1252.Byte(Text[I - 1]);
                    }

                    for (int I = 1; I <= 4; I++)
                    {
                        Hex = IntToHex(Cp1252.Byte(Text[I - 1]) * Value + I, 6);
                        Result = Result + Hex[Hex.Length - 1].ToString();
                        Value += Cp1252.Byte(Hex[Hex.Length - 1]) + Cp1252.Byte(Hex[0]);
                    }
                }

                return Result;
            }

            return RegisteredTo() == Name && !IsEmpty(Name) && Code == RegistrationCode(Name);
        }

