namespace Aow.Game.World.Structures
{

    // { Interface declaration run owned by P1. }
    public partial class TStructureConstructionControl : TConstructionControl
    {

        public TStructureConstructionControl(TECustomNode owner) : base(owner)
        { }

        // Structur.PAS:3195
        public override bool CanConstruct(TAbstractUnit AUnit, ref string Reason) => ValidateLocation(AUnit, ref Reason) && (base.CanConstruct(AUnit, ref Reason) && StructureResource(AUnit) != null);

        // Structur.PAS:3201
        public override bool Construct(TAbstractUnit AUnit)
        {
            bool Result;
            TConstructStructureTE Event;
            string Reason = "";
            if (CanConstruct(AUnit, ref Reason) && !AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AUnit.FPlayer).GetBusy())
            {
                Event = new TConstructStructureTE(null);
                Event.FUnitID = AUnit.FUnitID;
                Event.FPlayer = AUnit.FPlayer;
                Event.FControlID = ID();
                AoWEUnit.AoWHSMap.FTokenManager.GetTokenControl(AUnit.FPlayer).AddEvent(Event);
                Event.Release();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Structur.PAS:3162
        public virtual bool ValidateLocation(TAbstractUnit AUnit, ref string Reason)
        {
            TStructureResource Resource;
            sbyte X = default;
            sbyte Y = default;
            sbyte L = default;
            TMapLevel Level;
            TAoWMapField MapField;
            THNWalkData Walk = default;
            bool Result = true;
            Resource = StructureResource(AUnit);
            AUnit.GetLocation(ref X, ref Y, ref L);
            Level = AoWEUnit.AoWHSMap.MapContainer.GetMapLevel(L);
            InitHNWalk(ref Walk, X, Y, 0);
            while (Resource.TerrainList.Count > Walk.HN && Result)
            {
                if (Walk.X >= 0 && Walk.Y >= 0 && Walk.X < Level.Width && Walk.Y < Level.Height)
                {
                    if (Resource.TerrainList.GetUsed(Walk.HN))
                    {
                        MapField = (TAoWMapField)Level.GetField(Walk.X, Walk.Y);
                        Result = MapField.GetPlayer() == -1 || MapField.GetPlayer() == AUnit.FPlayer;
                        Result = Result && MapField.FindNoneTransparentHS(typeof(TStructure)) == null;
                        Result = Result && !TSet<byte>.WithBounds(0, 255).With(0).With(2).Contains((byte)MapField.OverlayType);
                        Result = Result && TSet<byte>.WithBounds(0, 255).With(12).WithRange(1, 5).Contains((byte)MapField.TerrainType);
                    }
                }
                else
                {
                    Result = false;
                }

                WalkToNextHN(ref Walk);
            }

            if (!Result)
            {
                Reason = AoWEUnit.TranslateRStr(AoWEUnit.CannotBuildOnCurrentLocationRStr);
            }

            return Result;
        }

        // Structur.PAS:3158
        public virtual TStructureResource StructureResource(TAbstractUnit AUnit) => null;
    }
}

namespace Aow.Game.Commands
{

    public partial class TConstructStructureTE : TTokenEvent
    {
        public TConstructStructureTE(TECustomNode owner) : base(owner)
        { }

        public new const int ClassID = 135962;

        public int FUnitID;
        public sbyte FPlayer;
        public int FControlID;

        // Structur.PAS:3098
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwInteger(ref FControlID, 20);
            Stream.rwInteger(ref FUnitID, 21);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FPlayer), 22);
        }

        // Structur.PAS:3106
        public override TExecuteResult Execute(TTokenExecuter TE)
        {
            TAbstractUnit AUnit;
            TStructureConstructionControl Control;
            TStructureResource Resource;
            TStructure Structure;
            string Reason = "";
            string Text = "";
            int Gold = default;
            int Days = default;
            TEChangeNotifyNode Owner;
            sbyte X = default;
            sbyte Y = default;
            sbyte L = default;
            TMapLevel Level;
            THNWalkData Walk = default;
            TExecuteResult Result = TExecuteResult.erDoneHalt;
            base.Execute(TE);
            AUnit = AoWEUnit.AoWHSMap.FUnitControl.FindUnit(FUnitID);
            Control = (TStructureConstructionControl)((TConstructAbility)AoWEUnit.AoWHSSet.FAbilityControl.GetAbility(125)).FConstructionControls.FindID(FControlID);
            if (Control != null && AUnit != null && AUnit.FPlayer == FPlayer && Control.CanConstruct(AUnit, ref Reason))
            {
                Resource = Control.StructureResource(AUnit);
                if (Resource != null)
                {
                    AUnit.GetLocation(ref X, ref Y, ref L);
                    Level = AoWEUnit.AoWHSMap.MapContainer.GetMapLevel(L);
                    InitHNWalk(ref Walk, X, Y, 0);
                    while (Walk.HN < Resource.TerrainList.Count)
                    {
                        if (Walk.X >= 0 && Walk.Y >= 0 && Level.Width > Walk.X && Level.Height > Walk.Y && Resource.TerrainList.GetUsed(Walk.HN))
                        {
                            AoWEUnit.AoWHSMap.ClearTerrain(Walk.X, Walk.Y, L, 0, -1);
                        }

                        WalkToNextHN(ref Walk);
                    }

                    Owner = (TEChangeNotifyNode)AUnit.Owner;
                    Owner.BeginUpdate();
                    Structure = (TStructure)Resource.PlaceResourceUser(AoWEUnit.AoWHSMap, X, Y, L);
                    if (Structure != null)
                    {
                        Control.GetInfo(AUnit, ref Text, ref Gold, ref Days);
                        Structure.ExecuteBuild(AUnit, Days);
                        var players = AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AUnit.FPlayer);
                        AoWEUnit.AoWHSMap.FPlayers.GetPlayers(AUnit.FPlayer).SetGems(players.FGems - Gold);
                        AUnit.Killed();
                        Result = TExecuteResult.erDone;
                    }

                    Owner.EndUpdate();
                }
            }

            return Result;
        }

        // NetworkE.pas:230

    }
}

namespace Aow.Game.Engine.Storage
