    // { Interface declaration run owned by P2. }
    public partial class TExportTextStream : TEWriteTextStorageStream
    {
        // Army.PAS:5685
        public override void rwString(ref string S, int ID)
        {
            string Buffer;
            if (!PropertyTable.PropertyExist(ID))
            {
                if (!IsEmpty(S))
                {
                    Buffer = "[" + IntToStr(ID) + "]=" + "|" + S + "|" + "\r" + "\n";
                    FBuffer.Write(Cp1252.Encode(Buffer).AsSpan().Slice(1 - 1, Buffer.Length));
                    PropertyTable.Add(ID, 0);
                }
            }
            else
            {
                throw new Aow.Game.Engine.EDoublePrioriyID("Double priorityID found");
            }
        }

        // Army.PAS:5700
        public override void rwStrings(TStrings Strings, int ID)
        {
            string S = "";
            string Buffer;
            if (!PropertyTable.PropertyExist(ID))
            {
                if (Strings.Count != 0)
                {
                    for (int I = 0, last = Strings.Count - 1; I <= last; I++)
                    {
                        S = S + Strings[I];
                        if (I != Strings.Count - 1)
                        {
                            S = S + "<eol>";
                        }
                    }
                    {
                        Buffer = "[" + IntToStr(ID) + "]=";
                        if (!IsEmpty(S))
                        {
                            Buffer = Buffer + "|" + S + "|" + "\r" + "\n";
                        }
                        else
                        {
                            Buffer = Buffer + "\r" + "\n";
                        }

                        FBuffer.Write(Cp1252.Encode(Buffer).AsSpan().Slice(1 - 1, Buffer.Length));
                        PropertyTable.Add(ID, 0);
                    }
                }
            }
            else
            {
                throw new Aow.Game.Engine.EDoublePrioriyID("Double priorityID found");
            }
        }

        // Engine.pas:1327
        public TExportTextStream(Stream AStream, Aow.Game.Engine.TEngine AEngine) : base(AStream, AEngine)
        { }
    }

    public partial class TTranslateTextStream : TTranslateStorageStream
    {
        public TIvDictionary FDictionary;

        // Army.PAS:5614
        public override void TranslateStrings(ref TStrings Strings)
        {
            string S;
            int EndOfLine;
            int LineFeed;
            if (Strings.Count != 0)
            {
                S = "";
                for (int I = 0, last = Strings.Count - 1; I <= last; I++)
                {
                    S = S + Strings[I];
                    if (I != Strings.Count - 1)
                    {
                        S = S + "<eol>";
                    }
                }

                S = FDictionary.Translate(S);
                Strings.Clear();
                do
                {
                    EndOfLine = Pos("<eol>", S);
                    LineFeed = Pos("\n", S);
                    if ((EndOfLine < LineFeed || LineFeed == 0) && EndOfLine != 0)
                    {
                        Strings.Add(Copy(S, 1, EndOfLine - 1));
                        S = Copy(S, EndOfLine + 5, S.Length - EndOfLine - 4);
                    }
                    else
                    {
                        if ((LineFeed < EndOfLine || EndOfLine == 0) && LineFeed != 0)
                        {
                            Strings.Add(Copy(S, 1, LineFeed - 1));
                            // { Original reverses the length comparison before reading the following CR. }
                            if (S.Length < LineFeed + 1 && S[LineFeed] == 13)
                            {
                                LineFeed += 1;
                            }

                            S = Copy(S, LineFeed + 1, S.Length - LineFeed);
                        }
                        else
                        {
                            Strings.Add(S);
                            S = "";
                        }
                    }
                }
                while (!IsEmpty(S));
            }
        }

        // Army.PAS:5609
        public override void TranslateString(ref string S)
        {
            S = FDictionary.Translate(S);
        }

        // Engine.pas:1343
        public TTranslateTextStream(Aow.Game.Engine.TEngine AEngine) : base(AEngine)
        { }
    }
}

