        // Diplomacy.pas:1420
        public static void RetrieveDefaultDiplomaticActionMessage(sbyte Source, sbyte Target, sbyte Other, DiplomaticProposal Proposal, TDiplomaticActionReaction Reaction, TStrings Text)
        {
            string SourceRace;
            string TargetRace;
            string OtherRace;
            TDiplomaticRelation Relation;
            TTextControl TextControl;
            int Alignment;
            Text.Clear();
            TextControl = AoWHSSet.FTextControl;
            Relation = AoWHSMap.FPlayers.GetDiplomaticRelation(Source, Target);
            var players = AoWHSMap.FPlayers.GetPlayers(Source);
            SourceRace = TranslateRStr(RaceNamesPluralRStr[players.FPlayerRace]);
            var fPlayersPlayers = AoWHSMap.FPlayers.GetPlayers(Target);
            TargetRace = TranslateRStr(RaceNamesPluralRStr[fPlayersPlayers.FPlayerRace]);
            if (Other > 0)
            {
                var players2 = AoWHSMap.FPlayers.GetPlayers(Other);
                OtherRace = TranslateRStr(RaceNamesPluralRStr[players2.FPlayerRace]);
            }
            else
            {
                OtherRace = "";
            }

            var players3 = AoWHSMap.FPlayers.GetPlayers(Source);
            var alignment = AoWHSSet.FRaceResources.GetRaceResource(players3.FPlayerRace).GetAlignment();
            if (TSet<TAlignment>.Of(TAlignment.alPureGood, TAlignment.alGood).Contains(alignment))
            {
                Alignment = 0;
            }
            else
            {
                if (TSet<TAlignment>.Of(TAlignment.alEvil, TAlignment.alPureEvil).Contains(alignment))
                {
                    Alignment = 2;
                }
                else
                {
                    Alignment = 1;
                }
            }

            Proposal.DefaultMessage(new DiplomaticMessageText(TextControl, Alignment, SourceRace, TargetRace, OtherRace, Text), Reaction, Relation);
        }

