        // PlayerC.PAS:2225
        public static int PlaceRandomUnits(int X, int Y, int L, sbyte Player, TUnitIndexList Units, int Level, int Value, TSet<TUnitType> Types)
        {
            int Index;
            int Tries;
            int Difference;
            int BestIndex;
            int I;
            int Delta;
            TUnit Unit_;
            int Result = 0;
            Tries = 50;
            if (Units.Count != 0)
            {
                while (Result < Value && Tries != 0)
                {
                    Tries -= 1;
                    Index = Units[Random(Units.Count)];
                    if (Index != -1 && Types.Contains(AoWHSSet.FUnitResources.GetUnitResource(Index).FUnitType) && AoWHSSet.FUnitResources.GetUnitResource(Index).GetObtainValue() + Result > Value && AoWHSSet.FUnitResources.GetUnitResource(Index).FLevel <= Level)
                    {
                        BestIndex = Index;
                        I = 20;
                        Difference = Math.Abs(AoWHSSet.FUnitResources.GetUnitResource(Index).GetObtainValue() - (Value - Result));
                        do
                        {
                            Index = Units[Random(Units.Count)];
                            if (Index != -1 && Types.Contains(AoWHSSet.FUnitResources.GetUnitResource(Index).FUnitType))
                            {
                                Delta = Math.Abs(AoWHSSet.FUnitResources.GetUnitResource(Index).GetObtainValue() - (Value - Result));
                                if (Delta < Difference)
                                {
                                    Difference = Delta;
                                    BestIndex = Index;
                                }
                            }

                            I -= 1;
                        }
                        while (!(I == 0));
                        Index = BestIndex;
                    }

                    if (Index != -1 && Types.Contains(AoWHSSet.FUnitResources.GetUnitResource(Index).FUnitType) && AoWHSSet.FUnitResources.GetUnitResource(Index).FLevel <= Level)
                    {
                        Unit_ = new TUnit(null);
                        Unit_.SetUnitResource(AoWHSSet.FUnitResources.GetUnitResource(Index));
                        if (Unit_.Place(X, Y, L, Player, TSet<TUnitPlaceModeElement>.Of()) != null)
                        {
                            Result += Unit_.GetObtainValue();
                            Tries = 50;
                        }

                        Unit_.Release();
                    }
                }
            }

            return Result;
        }

        // PlayerC.PAS:2263
        public static int FillWithRandomUnits(TIntegerList Indexes, TUnitList Units, int Level, int Value, TSet<TUnitType> Types)
        {
            TUnit TestUnit;
            int Index;
            int Tries;
            int I;
            int Difference;
            int BestIndex;
            int Delta;
            TUnit Unit_;
            bool CanUse(TUnit Unit_)
            {
                bool condition = Unit_.FUnitResource != null;
                if (condition)
                {
                    var unitType = Unit_.GetUnitType();
                    condition = Types.Contains(unitType);
                }

                return condition && Unit_.GetUnitLevel() <= Level && Units.CanAddUnit(Unit_);
            }

            TestUnit = new TUnit(null);
            int Result = 0;
            Tries = 50;
            Units.BeginUpdate();
            while (Result < Value && Tries != 0)
            {
                Tries -= 1;
                Index = Indexes[Random(Indexes.Count)];
                if (Index != -1)
                {
                    TestUnit.SetUnitResource(AoWHSSet.FUnitResources.GetUnitResource(Index));
                    if (CanUse(TestUnit))
                    {
                        if (TestUnit.GetObtainValue() + Result > Value)
                        {
                            BestIndex = Index;
                            I = 20;
                            Difference = Math.Abs(TestUnit.GetObtainValue() - (Value - Result));
                            do
                            {
                                Index = Indexes[Random(Indexes.Count)];
                                if (Index != -1 && Index != BestIndex)
                                {
                                    TestUnit.SetUnitResource(AoWHSSet.FUnitResources.GetUnitResource(Index));
                                    if (CanUse(TestUnit))
                                    {
                                        Delta = Math.Abs(TestUnit.GetObtainValue() - (Value - Result));
                                        if (Delta < Difference)
                                        {
                                            BestIndex = Index;
                                            Difference = Delta;
                                        }
                                    }
                                }

                                I -= 1;
                            }
                            while (!(I == 0));
                            Index = BestIndex;
                        }

                        Unit_ = new TUnit(null);
                        Unit_.SetUnitResource(AoWHSSet.FUnitResources.GetUnitResource(Index));
                        Units.AddUnit(Unit_);
                        Result += Unit_.GetObtainValue();
                        Tries = 50;
                        Unit_.Release();
                    }
                }
            }

            Units.EndUpdate();
            TestUnit.Release();
            return Result;
        }

