            Level = AoWHSMap.MapContainer.MapLevels[L];
            Msg.MsgID = 4432;
            Msg.Param[0] = (int)Storm;
            Msg.Param[2] = Player;
            InitHNWalk(ref Walk, X, Y, InnerRadius);
            while (Walk.Radius <= OuterRadius)
            {
                if (Walk.X >= 0 && Walk.Y >= 0 && Walk.X < Level.Width && Walk.Y < Level.Height)
                {
                    Msg.Param[1] = Walk.Radius;
                    Level.Field[Walk.X, Walk.Y].SendMapFieldMsg(ref Msg);
                }

                WalkToNextHN(ref Walk);
            }
        }

        // PlayerC.PAS:2406
        public static TDiplomaticRelation dAlignmentToDiplomaticRelation(TAlignment A, TAlignment B)
        {
            TDiplomaticRelation Result;
            if (TSet<TAlignment>.Of(TAlignment.alPureGood, TAlignment.alGood).Contains(A))
            {
                if (TSet<TAlignment>.Of(TAlignment.alPureGood, TAlignment.alGood).Contains(B))
                {
                    Result = TDiplomaticRelation.drPeace;
                }
                else
                {
                    if (TSet<TAlignment>.Of(TAlignment.alPureNeutral, TAlignment.alNeutral, TAlignment.alNone).Contains(B))
                    {
                        Result = TDiplomaticRelation.drUnknown;
                    }
                    else
                    {
                        Result = TDiplomaticRelation.drWar;
                    }
                }
            }
            else
            {
                if (TSet<TAlignment>.Of(TAlignment.alEvil, TAlignment.alPureEvil).Contains(A))
                {
                    if (TSet<TAlignment>.Of(TAlignment.alEvil, TAlignment.alPureEvil).Contains(B))
                    {
                        Result = TDiplomaticRelation.drPeace;
                    }
                    else
                    {
                        if (TSet<TAlignment>.Of(TAlignment.alPureNeutral, TAlignment.alNeutral, TAlignment.alNone).Contains(B))
                        {
                            Result = TDiplomaticRelation.drUnknown;
                        }
                        else
                        {
                            Result = TDiplomaticRelation.drWar;
                        }
                    }
                }
                else
                {
                    if (A == TAlignment.alPureNeutral && B == TAlignment.alPureNeutral)
                    {
                        Result = TDiplomaticRelation.drPeace;
                    }
                    else
                    {
                        Result = TDiplomaticRelation.drUnknown;
                    }
                }
            }

            return Result;
        }

        // PlayerC.PAS:2421
        public static TDiplomaticRelation StatusToDiplomaticRelation(TStatus Status)
        {
            TDiplomaticRelation Result;
            switch (Status)
            {
                case TStatus.sPolite:
                case TStatus.sFriendly:
                    Result = TDiplomaticRelation.drPeace;
                    break;
                case TStatus.sNeutral:
                    Result = TDiplomaticRelation.drUnknown;
                    break;
                case TStatus.sHostile:
                case TStatus.sWary:
                    Result = TDiplomaticRelation.drWar;
                    break;
                default:
                    Result = TDiplomaticRelation.drUnknown;
                    break;
            }

            return Result;
        }

        // PlayerC.PAS:2430
        public static TCombatSideIndex GetCombatSide(sbyte Attacker, sbyte AttackerRelation, sbyte Defender, sbyte DefenderRelation, sbyte Player, sbyte Relation)
        {
            TCombatSideIndex Result;
            if (Player != 0 && Attacker == 0 && Defender == 0)
            {
                Result = TCombatSideIndex.csNeutral;
            }
            else
            {
                if (Player == Attacker && (Player != 0 || AttackerRelation == Relation))
                {
                    Result = TCombatSideIndex.csAttacker;
                }
                else
                {
                    if (Player == Defender && (Player != 0 || DefenderRelation == Relation))
                    {
                        Result = TCombatSideIndex.csDefender;
                    }
                    else
                    {
                        if (Player == 0)
                        {
                            if (Attacker != 0 && DiplomaticRelation(Attacker, AttackerRelation, Player, Relation) == TDiplomaticRelation.drPeace && DiplomaticRelation(Defender, DefenderRelation, Player, Relation) != TDiplomaticRelation.drPeace)
                            {
                                Result = TCombatSideIndex.csAttacker;
                            }
                            else
                            {
                                if (Defender != 0 && DiplomaticRelation(Defender, DefenderRelation, Player, Relation) == TDiplomaticRelation.drPeace && DiplomaticRelation(Attacker, AttackerRelation, Player, Relation) != TDiplomaticRelation.drPeace)
                                {
                                    Result = TCombatSideIndex.csDefender;
                                }
                                else
                                {
                                    Result = TCombatSideIndex.csNeutral;
                                }
                            }
                        }
                        else
                        {
                            if (Attacker != 0 && DiplomaticRelation(Attacker, AttackerRelation, Player, Relation) == TDiplomaticRelation.drAlliance && DiplomaticRelation(Defender, DefenderRelation, Player, Relation) != TDiplomaticRelation.drAlliance)
                            {
                                Result = TCombatSideIndex.csAttacker;
                            }
                            else
                            {
                                if (Defender != 0 && DiplomaticRelation(Defender, DefenderRelation, Player, Relation) == TDiplomaticRelation.drAlliance && DiplomaticRelation(Attacker, AttackerRelation, Player, Relation) != TDiplomaticRelation.drAlliance)
                                {
                                    Result = TCombatSideIndex.csDefender;
                                }
                                else
                                {
                                    Result = TCombatSideIndex.csNeutral;
                                }
                            }
                        }
                    }
                }
            }

            return Result;
        }

        // PlayerC.PAS:2453
        public static sbyte AlignmentToIR(TAlignment Alignment)
        {
            sbyte Result;
            switch (Alignment)
            {
                case TAlignment.alPureGood:
                case TAlignment.alGood:
                    Result = -2;
                    break;
                case TAlignment.alEvil:
                case TAlignment.alPureEvil:
                    Result = -4;
                    break;
                case TAlignment.alPureNeutral:
                case TAlignment.alNeutral:
                    Result = -3;
                    break;
                default:
                    Result = -1;
                    break;
            }

            return Result;
        }

        // PlayerC.PAS:2462
        public static TAlignment IRtoAlignment(sbyte Relation)
        {
            TAlignment Result;
            if (Relation < 0)
            {
                switch (Relation)
                {
                    case -2:
                        Result = TAlignment.alGood;
                        break;
                    case -4:
                        Result = TAlignment.alEvil;
                        break;
                    case -3:
                        Result = TAlignment.alNeutral;
                        break;
                    default:
                        Result = TAlignment.alNeutral;
                        break;
                }
            }
            else
            {
                Result = AoWHSSet.FRaceResources.GetRaceResource(Relation).GetAlignment();
            }

            return Result;
        }

        // PlayerC.PAS:2473
        public static TDiplomaticRelation DiplomaticRelation(sbyte Player, sbyte IndependentRelation, sbyte OtherPlayer, sbyte OtherIndependentRelation)
        {
            TDiplomaticRelation Result;
            sbyte Race;
            sbyte OtherRace;
            TAlignment Alignment;
            TAlignment OtherAlignment;
            if (Player == 0 || OtherPlayer == 0)
            {
                if (Player != 0)
                {
                    Race = AoWHSMap.FPlayers.GetPlayers(Player).FPlayerRace;
                }
                else
                {
                    if (IndependentRelation >= 0)
                    {
                        Race = IndependentRelation;
                    }
                    else
                    {
                        Race = -1;
                    }
                }

                if (OtherPlayer != 0)
                {
                    OtherRace = AoWHSMap.FPlayers.GetPlayers(OtherPlayer).FPlayerRace;
                }
                else
                {
                    if (OtherIndependentRelation >= 0)
                    {
                        OtherRace = OtherIndependentRelation;
                    }
                    else
                    {
                        OtherRace = -1;
                    }
                }

                if (Race == -1 || OtherRace == -1)
                {
                    if (Race != -1)
                    {
                        Alignment = AoWHSSet.FRaceResources.GetRaceResource(Race).GetAlignment();
                    }
                    else
                    {
                        Alignment = IRtoAlignment(IndependentRelation);
                    }

                    if (OtherRace != -1)
                    {
                        OtherAlignment = AoWHSSet.FRaceResources.GetRaceResource(OtherRace).GetAlignment();
                    }
                    else
                    {
                        OtherAlignment = IRtoAlignment(OtherIndependentRelation);
                    }

                    Result = dAlignmentToDiplomaticRelation(Alignment, OtherAlignment);
                }
                else
                {
                    Result = StatusToDiplomaticRelation(AoWHSMap.FRaces.GetRace(Race).GetRelation(OtherRace));
                }
            }
            else
            {
                if (Player != OtherPlayer)
                {
                    Result = AoWHSMap.FPlayers.GetDiplomaticRelation(Player, OtherPlayer);
                }
                else
                {
                    Result = TDiplomaticRelation.drAlliance;
                }
            }

            return Result;
        }

        // PlayerC.PAS:2496
        public static bool ValidAttackRelation(sbyte Player, sbyte IndependentRelation, sbyte TargetPlayer, sbyte TargetRace)
        {
            bool Result;
            TDiplomaticRelation Relation;
            if (Player == 0)
            {
                if (TargetPlayer != 0)
                {
                    Relation = DiplomaticRelation(Player, IndependentRelation, TargetPlayer, TargetRace);
                    Result = TSet<TDiplomaticRelation>.Of(TDiplomaticRelation.drWar, TDiplomaticRelation.drUnknown).Contains(Relation);
                }
                else
                {
                    Result = false;
                }
            }
            else
            {
                Result = AoWHSMap.FPlayers.GetPlayers(Player).ValidAttackRelation(TargetPlayer, TargetRace);
            }

            return Result;
        }

