                            Result = 10;
                        }
                        else
                        {
                            if (MapField.TerrainType == 2)
                            {
                                Result = 30;
                            }
                            else
                            {
                                Result = 20;
                            }
                        }
                    }
                    else
                    {
                        if (MapField.TerrainType == 3)
                        {
                            Result = 1;
                        }
                        else
                        {
                            Result = 5;
                        }
                    }
                }

                if (MapField.FindNoneTransparentHS(typeof(TStructure)) != null)
                {
                    Result += 5;
                    if (AoWHSMap != null && AoWHSMap.FGlobalMagicControl.FActiveEnchantments.Contains(Aow.Game.Magic.TGlobalEnchantmentType.getFireMastery))
                    {
                        Result += 5;
                    }
                }

                if (Result < 0)
                {
                    Result = 0;
                }
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

