        public static TSet<TDamageType> MeleeDamageTypes(TCombatObject Source)
        {
            TSet<TDamageType> Result;
            if (Source is TCombatUnit)
            {
                Result = ((TStrikeAbility)AoWHSSet.FAbilityControl.GetAbility(21)).GetDamageTypes(((TCombatUnit)Source).FUnit);
            }
            else
            {
