            }

            return Result;
        }

        // AoWAb.PAS:1116
        public static int StrikeDV(TCombatObject Source, TCombatObject Target)
        {
            int Result;
            sbyte Attack;
            sbyte Damage;
            TSet<TDamageType> Types;
            if (Source.GetAbilityEnabled(21))
            {
                Attack = Source.GetAttack();
                Damage = Source.GetDamage();
                Types = MeleeDamageTypes(Source);
                bool condition = Source.GetAbilityEnabled(146) || Source.GetAbilityEnabled(160);
                if (condition)
                {
                    var alignment = Target.GetAlignment();
                    condition = TSet<TAlignment>.Of(TAlignment.alEvil, TAlignment.alPureEvil).Contains(alignment);
                }

                if (condition)
                {
                    Attack = (sbyte)(Attack + 2);
                    Damage = (sbyte)(Damage + 2);
                }

                bool test = Source.GetAbilityEnabled(147) || Source.GetAbilityEnabled(161);
                if (test)
                {
                    var alignment = Target.GetAlignment();
                    test = TSet<TAlignment>.Of(TAlignment.alPureGood, TAlignment.alGood).Contains(alignment);
                }

                if (test)
                {
                    Attack = (sbyte)(Attack + 2);
                    Damage = (sbyte)(Damage + 2);
                }

                if (Source.GetAbilityEnabled(112) && Target.GetAbilityEnabled(63))
                {
                    Attack = (sbyte)(Attack + 3);
                    Damage = (sbyte)(Damage + 3);
                }

                Result = StatisticsToLimitedDV(Attack, Damage, Types, Target.GetHitPoints(), Target.GetDefense(), Target.GetResistance(), Target.GetImmunityTypes(), Target.GetProtectionTypes());
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

