        // Original unnamed helper, following TNegotiateRequestEventLog
        // { P5 unnamed helper declarations; these must follow the forward class block. }
        public static void NegotiateArmy(sbyte Player, TArmyHS ArmyHS, byte Selection, sbyte X, sbyte Y, sbyte L, int MovePoints)
        {
            TNegotiateRequestEventLog Log;
            string ErrorText = "";
            TMapFieldMsg Msg = default;
            if (AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType == TPlayerType.ptHuman)
            {
                // Use the map's seated player.
                if (Player == AoWHSMap.FSeatedPlayer)
                {
                    Log = new TNegotiateRequestEventLog(null);
                    Log.FArmyID = ArmyHS.FArmy.CreateID(Selection);
                    Log.FMovePoints = MovePoints;
                    Log.FX = (sbyte)(byte)X;
                    Log.FY = (sbyte)(byte)Y;
                    Log.FL = (sbyte)(byte)L;
                    Log.FPlayer = (sbyte)(byte)Player;
                    Msg.MsgID = 4366;
                    Msg.Param[0] = Log;
                    Msg.Param[1] = 0;
                    Msg.Result = 0;
                    AoWHSMap.MapContainer.GetField(X, Y, L).SendMapFieldMsg(ref Msg);
                    if (Msg.Param[1].Int != 0)
                    {
                        Log.Execute(true, TExecuteTrigger.etEvent, null);
                    }

                    Log.Release();
                }
            }
            else
            {
                if (AoWHSMap.FPlayers.GetPlayers(Player).GetLocal())
                {
                    Log = new TNegotiateRequestEventLog(null);
                    Log.FArmyID = ArmyHS.FArmy.CreateID(Selection);
                    Log.FMovePoints = MovePoints;
                    Log.FX = (sbyte)(byte)X;
                    Log.FY = (sbyte)(byte)Y;
                    Log.FL = (sbyte)(byte)L;
                    Log.FPlayer = (sbyte)(byte)Player;
                    Msg.MsgID = 4366;
                    Msg.Param[0] = Log;
                    Msg.Param[1] = 0;
                    Msg.Result = 0;
                    AoWHSMap.MapContainer.GetField(X, Y, L).SendMapFieldMsg(ref Msg);
                    if (Msg.Param[1].Int != 0 && AoWHSMap.FPlayers.GetPlayers(Player).FGems >= Log.FGold)
                    {
                        Log.Accept(ref ErrorText);
                    }
                    else
                    {
                        Log.Reject(ref ErrorText);
                    }

                    Log.Release();
                }
            }
        }

        // Diplomacy.pas:458
        // Original unnamed helper: copy a diplomatic event to eligible players
        public static void BroadcastDiplomaticEvent(TDiplomaticActionEventLog Log, sbyte Exclude)
        {
            TEventLog CopyLog;
            TPlayer Player;
            for (int I = 0, last = AoWHSMap.FPlayers.Count - 1; I <= last; I++)
            {
                Player = AoWHSMap.FPlayers.GetPlayers(I);
                if (Player.FStatus == TPlayerStatus.psPlaying && I != Exclude && (I == Log.FAction.FSource || I == Log.FAction.FTarget || AoWHSMap.FPlayers.GetPlayers(I).GetFirstDaySeen((sbyte)(byte)Log.FAction.FSource) != -1 && AoWHSMap.FPlayers.GetPlayers(I).GetFirstDaySeen((sbyte)(byte)Log.FAction.FTarget) != -1))
                {
                    CopyLog = (TEventLog)Log.Copy(AoWEngine);
                    Player.FEventLogbook.AddEvent(CopyLog);
                    CopyLog.Release();
                }
            }
        }

