        // MoveT.PAS:3353
        public static bool ValidateMultiArmyMove(TMoveSettingsList Moves, int Index)
        {
            int UnitCount;
            int Transporters;
            int Capacity;
            sbyte Player;
            TMoveSettings Settings;
            int I;
            TAoWMapField Field;
            sbyte OwnerPlayer;
            TXYL Location;
            TArmyHS ArmyHS;
            void AddArmy(TArmyHS ArmyHS, byte Selection)
            {
                TAbstractUnit Transporter;
                var selectionCount = ArmyHS.FArmy.SelectionCount(Selection);
                UnitCount += selectionCount;
                Transporter = ArmyHS.FArmy.Transporter(Selection);
                if (Transporter != null)
                {
                    Transporters += 1;
                    if (Transporter.GetTransportCapacity() + 1 < Capacity)
                    {
                        Capacity = Transporter.GetTransportCapacity() + 1;
                    }
                }
            }

            bool Result = true;
            Player = ((TArmyHS)Moves.GetMoveSettings(Index).FMoveObject).FArmy.FPlayer;
            Settings = Moves.GetMoveSettings(Index);
            I = Settings.FMovePos;
            while (Result && I != Settings.FPath.Count)
            {
                var item = Settings.FPath[I];
                var fPathItem = Settings.FPath[I];
                var item2 = Settings.FPath[I];
                Field = (TAoWMapField)AoWHSMap.MapContainer.GetField(item2.X, fPathItem.Y, item.L);
                OwnerPlayer = Field.GetPlayer();
                Result = OwnerPlayer == -1 || OwnerPlayer == Player;
                I += 1;
            }

            if (Result)
            {
                UnitCount = 0;
                Transporters = 0;
                Capacity = 8;
                var moveSettings = Moves.GetMoveSettings(Index);
                AddArmy((TArmyHS)Moves.GetMoveSettings(Index).FMoveObject, (byte)moveSettings.FSelection);
                Location = Moves.GetMoveSettings(Index).GetMoveLoc();
                Field = (TAoWMapField)AoWHSMap.MapContainer.GetField(Location.X, Location.Y, Location.L);
                ArmyHS = (TArmyHS)Field.FindOwnedChild(131607);
                if (ArmyHS != null)
                {
                    AddArmy(ArmyHS, 255);
                }

                I = Moves.Count - 1;
                for (; I >= 0; I -= 1)
                {
                    if (I != Index)
                    {
                        Settings = Moves.GetMoveSettings(I);
                        bool condition = Settings.FValid && Moves.GetMoveSettings(Index).GetMovePrio() >= Settings.GetMovePrio();
                        if (condition)
                        {
                            var moveLoc = Moves.GetMoveSettings(Index).GetMoveLoc();
                            condition = Unsafe.BitCast<TXYL, int>(Settings.GetMoveLoc()) == Unsafe.BitCast<TXYL, int>(moveLoc);
                        }

                        if (condition)
                        {
                            AddArmy((TArmyHS)Settings.FMoveObject, (byte)Settings.FSelection);
                        }
                    }
                }

                Result = UnitCount <= Capacity && Transporters <= 1;
            }

            return Result;
        }

