        public static bool TryEndPlayerTurn(sbyte Player)
        {
            bool Result;
            if (Player != -1 && !AoWHSMap.FPlayers.GetPlayers(Player).GetBusy() && !AoWHSMap.FPlayers.GetPlayers(Player).FSingleProcessCycle)
            {
                Result = EndPlayerTurn(Player);
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // AoWHSMap.PAS:2758
        public static bool CancelPlayerTurn(sbyte Player)
        {
            bool Result;
            TEndTurnTE Event;
            if (!AoWHSMap.FPlayers.GetPlayers(Player).GetBusy() && AoWHSMap.FPlayers.GetPlayers(Player).FSingleProcessCycle)
            {
                Event = new TEndTurnTE(null);
                Event.FPlayer = Player;
                Event.FDay = AoWHSMap.FDay;
                Event.FMode = TEndTurnMode.emCancelEndTurn;
                AoWHSMap.FTokenManager.GetTokenControl(Player).AddEvent(Event);
                Event.Release();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

