        // Unit.PAS:2301
        public static int P2CompareUnits(object Item1, object Item2)
        {
            int S1;
            int S2;
            var unit = (TAbstractUnit)Item1;
            S1 = unit.GetUnitLevel();
            if (unit.GetTransporter())
            {
                S1 += 500;
            }

            if ((TAbstractUnit)Item1 is THero)
            {
                S1 += 50;
                if ((TAbstractUnit)Item1 is TLeader)
                {
                    S1 += 100;
                }
            }

            var unit2 = (TAbstractUnit)Item2;
            S2 = unit2.GetUnitLevel();
            if (unit2.GetTransporter())
            {
                S2 += 500;
            }

            if ((TAbstractUnit)Item2 is THero)
            {
                S2 += 50;
                if ((TAbstractUnit)Item2 is TLeader)
                {
                    S2 += 100;
                }
            }

            int Result = S2 - S1;
            if (Result == 0)
            {
                if (((TAbstractUnit)Item1).FUnitStatus.Contains(TUnitStatusElement.usEnchanted))
                {
                    S1 = 1;
                }
                else
                {
                    S1 = 0;
                }

                if (((TAbstractUnit)Item2).FUnitStatus.Contains(TUnitStatusElement.usEnchanted))
                {
                    S2 = 1;
                }
                else
                {
                    S2 = 0;
                }

                Result = S2 - S1;
            }

            if (Result == 0)
            {
                Result = ((TAbstractUnit)Item2).GetUnitGFXResourceIndex() - ((TAbstractUnit)Item1).GetUnitGFXResourceIndex();
                if (Result == 0)
                {
                    Result = ((TAbstractUnit)Item2).FUnitID - ((TAbstractUnit)Item1).FUnitID;
                }
            }

            return Result;
        }

